window.COLLECTION = [{"number": "0001", "file": "0001 - Capella Bangkok - River Suite Premier - bedroom with king bed and river window daybed.jpg", "resort": "Capella Bangkok", "space": "River Suite Premier", "description": "The bedroom is arranged for the river, with a king bed dressed in plain white Egyptian cotton and a low upholstered daybed set along the glazing at its foot, so the view is taken lying down as much as sitting up. Walls and joinery are blonde timber with a fabric shaded wall sconce beside the bedhead, and oatmeal linen Roman blinds soften the black framed floor to ceiling windows and balcony sliders. A black arc floor lamp marks the window corner. To recreate it, keep the palette to warm white, sand and pale oak, furniture low and horizontal, and textiles unpatterned.", "src": "images/Capella Bangkok/0001 - Capella Bangkok - River Suite Premier - bedroom with king bed and river window daybed.jpg", "source": "https://capellahotels.com/en/capella-bangkok/accommodation/river-premier-suite", "dimensions": "1296x723", "size": 159483}, {"number": "0002", "file": "0002 - Capella Bangkok - River Suite Premier - corner living room with sofa and barrel chairs.jpg", "resort": "Capella Bangkok", "space": "River Suite Premier", "description": "The separate living room wraps two walls of glass around a corner sofa in oatmeal weave with cushions in sage green and taupe. Two barrel back armchairs in pale leather on dark timber legs face the river, paired with a dark round side table carrying an oversized drum shaded lamp in cream silk on a faceted bronze base. A dark stained desk or console repeats the lamp at smaller scale. Pale carpet, linen Roman blinds and blonde panelling keep the room light. Recreation notes: overscale one lamp, keep upholstery plain, and let green cushions be the only colour accent.", "src": "images/Capella Bangkok/0002 - Capella Bangkok - River Suite Premier - corner living room with sofa and barrel chairs.jpg", "source": "https://capellahotels.com/en/capella-bangkok/accommodation/river-premier-suite", "dimensions": "1296x723", "size": 214806}, {"number": "0005", "file": "0005 - Capella Bangkok - Private Villa - living room looking through to bedroom.jpg", "resort": "Capella Bangkok", "space": "Private Villa", "description": "From the living area, sliding pocket doors open to the bedroom in one enfilade. Foreground pieces include a dark timber display cabinet with blue and white porcelain jars, art books and a sculptural knot object, a tall floor lamp with a cream drum shade, and a marble topped round table. The bedroom has a king bed in white linen, a striped upholstered bench at its foot, and a geometric gridded fabric panel behind the bedhead flanked by mirrored niches and pendant shades. A dressing area with robes and a stool is visible at right. Keep joinery dark against pale walls and repeat grid patterns quietly.", "src": "images/Capella Bangkok/0005 - Capella Bangkok - Private Villa - living room looking through to bedroom.jpg", "source": "https://capellahotels.com/en/capella-bangkok/accommodation/villa", "dimensions": "1296x723", "size": 289259}, {"number": "0006", "file": "0006 - Capella Bangkok - Private Villa - dining room with marble table and shell pendant.jpg", "resort": "Capella Bangkok", "space": "Private Villa", "description": "The combined living and dining room is anchored by an oval marble dining table with cream leather barrel chairs on dark timber frames, lit by a pair of sculptural hammered metal shell pendants. Behind the sofa, a long dark timber console carries a bonsai and an art book, facing a media wall with open shelving and ceramics. Whitewashed boarded ceilings, a ceiling fan, pale oak floors and full height linen curtains frame folding doors to the garden and plunge pool. Recreation notes: one statement pendant group, low horizontal consoles, and indoor planting at architectural scale, including the large potted palm by the doors.", "src": "images/Capella Bangkok/0006 - Capella Bangkok - Private Villa - dining room with marble table and shell pendant.jpg", "source": "https://capellahotels.com/en/capella-bangkok/private-villa", "dimensions": "1920x1282", "size": 309966}, {"number": "0007", "file": "0007 - Capella Bangkok - Private Villa - bedroom with striped chaises and pool doors.jpg", "resort": "Capella Bangkok", "space": "Private Villa", "description": "The villa bedroom keeps furniture low and textile led, with two striped chaise longues in beige and brown weave angled towards the garden, small round black side tables between them, and the king bed in plain white in the foreground. Full width sliding doors open to the plunge pool, sun loungers and lawn, while the inner wall is lined with woven grasscloth panels in a pale sand tone that catch raking sunlight. A white ceiling fan, taupe curtains and a muted flatweave rug finish the room. Recreate with natural fibre wallcovering, striped upholstery as the only pattern, and nothing above waist height.", "src": "images/Capella Bangkok/0007 - Capella Bangkok - Private Villa - bedroom with striped chaises and pool doors.jpg", "source": "https://capellahotels.com/en/capella-bangkok/private-villa", "dimensions": "1280x853", "size": 107422}, {"number": "0011", "file": "0011 - Capella Bangkok - Tea Lounge - rattan armchairs and lattice screens by the lily pond.jpg", "resort": "Capella Bangkok", "space": "Tea Lounge", "description": "The signature Tea Lounge view pairs two woven rattan armchairs with rolled spiral arms and sage cushions against low dark timber tables and upholstered stools, arranged symmetrically on a patterned carpet over polished stone. Behind them, full height windows look onto the lily pond, divided by dark timber lattice screens in a Thai diamond fretwork, with oversized black ceramic planters holding tall palms at each bay. Arched floor lamps with pink silk shades and a coffered ceiling clad in silk complete the room. This is the clearest statement of the hotel lobby look. [below 1200px - best available]", "src": "images/Capella Bangkok/0011 - Capella Bangkok - Tea Lounge - rattan armchairs and lattice screens by the lily pond.jpg", "source": "https://capellahotels.com/en/capella-bangkok/dining", "dimensions": "968x646", "size": 162644}, {"number": "0012", "file": "0012 - Capella Bangkok - Tea Lounge - lobby lounge sofas and Ming style chairs.jpg", "resort": "Capella Bangkok", "space": "Tea Lounge", "description": "This angle of the lobby Tea Lounge shows the deeper seating groups: cream sofas and striped upholstered armchairs around a dark timber coffee table, plus Chinese inspired dark wood armchairs with stone top tables in honey onyx in the foreground. A black lacquer side table with a floral arrangement, drum shaded floor lamps and a display shelf holding a bronze horse sculpture and lacquer boxes add the collected, residential layer. Bronze tinted mirror panels and diamond fretwork screens line the walls, and the lily pond runs outside the glazing. Palette is cream, charcoal, bronze and stone throughout.", "src": "images/Capella Bangkok/0012 - Capella Bangkok - Tea Lounge - lobby lounge sofas and Ming style chairs.jpg", "source": "https://bradajohnson.net/2023/12/16/oltre-review-one-day-in-bangkok-two-worlds-apart/", "dimensions": "2560x1707", "size": 729305}, {"number": "0014", "file": "0014 - Capella Bangkok - Tea Lounge - window armchairs overlooking the lily pond.jpg", "resort": "Capella Bangkok", "space": "Tea Lounge", "description": "Along the Tea Lounge windows, low taupe armchairs with loose cushions are grouped in pairs around small round tables with white cloths, facing the lily pond and the low rise buildings across it. A dark fretwork screen divides the seating from the passage, and a flatweave carpet in mottled grey and cream unifies the groups. Daylight does most of the work, with one shaded lamp for evening. To recreate the feel, set every seat towards water or garden, keep chair backs low so sightlines stay open, and use upholstery in a single warm greige family with cushions a shade darker.", "src": "images/Capella Bangkok/0014 - Capella Bangkok - Tea Lounge - window armchairs overlooking the lily pond.jpg", "source": "https://suiteverdict.com/en/thailand/bangkok/capella-bangkok-verdict", "dimensions": "2560x1707", "size": 731213}, {"number": "0016", "file": "0016 - Capella Bangkok - Phra Nakhon - conservatory dining room with skylight and banquettes.jpg", "resort": "Capella Bangkok", "space": "Phra Nakhon", "description": "Inside Phra Nakhon, the conservatory dining room runs between glass walls under a coffered ceiling with a central skylight screened by woven cane panels. A long grey upholstered banquette with botanical print cushions faces cane backed chairs with dark timber frames at square marble tables set with green glassware and brass cutlery. Herringbone timber floors, a woven screen divider and a large floral arrangement on a pedestal table structure the depth of the room. Recreation notes: cane, marble and grey upholstery are the three materials, repeated without variation, and planting inside should be oversized and sculptural. Image extracted at native resolution from the official Capella press release PDF.", "src": "images/Capella Bangkok/0016 - Capella Bangkok - Phra Nakhon - conservatory dining room with skylight and banquettes.jpg", "source": "https://capellahotels.com/assets/docs/bangkok/10-2020_Capella_Bangkoks_Phra_Nakhon_Restaurant_ENG.pdf", "dimensions": "1276x852", "size": 188429}, {"number": "0018", "file": "0018 - Capella Bangkok - Phra Nakhon - indoor marble table setting with green glassware.jpg", "resort": "Capella Bangkok", "space": "Phra Nakhon", "description": "This close view of an indoor Phra Nakhon table shows the material palette at full size: a beige marble top with a dark stained timber edge and frame, white paper placemats, black ceramic plates, folded white napkins, green glass tumblers and brass cutlery, lit by a small brass table lamp with a posy of white flowers. The chairs are dark framed with woven backs, glimpsed at the edges. For a home version, the formula is a stone top, black plate, green glass and brass metalwork, with joinery kept dark enough to anchor the pale surfaces around it.", "src": "images/Capella Bangkok/0018 - Capella Bangkok - Phra Nakhon - indoor marble table setting with green glassware.jpg", "source": "https://suiteverdict.com/en/thailand/bangkok/capella-bangkok-verdict", "dimensions": "2560x1707", "size": 623979}, {"number": "0019", "file": "0019 - Capella Bangkok - Phra Nakhon - terrace at dusk with marble tables.jpg", "resort": "Capella Bangkok", "space": "Phra Nakhon", "description": "At dusk the Phra Nakhon terrace reads differently, with rows of white marble tables and black rattan chairs lit by small table lamps and the last light on the river, under a heavy tree canopy. The setting is the same furniture as the daytime terrace views but the mood depends on low warm light, dark silhouettes and the reflective water behind the rail. The source review describes vintage style table lamps, gold tinted glasses and brass cutlery in vintage Thai style at these tables. Keep outdoor lighting low, warm and at table height only. [below 1200px - best available]", "src": "images/Capella Bangkok/0019 - Capella Bangkok - Phra Nakhon - terrace at dusk with marble tables.jpg", "source": "https://happyhourasia.com/phra-nakhon-serves-authentic-cuisine-in-capella-bangkoks-relaxing-riverfront-setting/", "dimensions": "1170x780", "size": 490826}, {"number": "0020", "file": "0020 - Joali Maldives - Luxury Water Villa with Pool - bedroom with canopy net and turquoise pendant.jpg", "resort": "Joali Maldives", "space": "Luxury Water Villa with Pool", "description": "A king bed dressed in white linen with a taupe throw sits under a sheer canopy net, facing a wall of dark stained timber panels hand carved with palm frond reliefs. A turquoise glass disc pendant and matching wall disc act as the single colour accent, echoed in the ocean beyond the sliding doors. Note the blush toned flatweave rug with a faded botanical pattern, the woven drum pouf at the bed foot, open shelving with ceramics and books, a television panel painted with a wave motif, wall sconces in aged bronze, and full height sheer curtains softening the vaulted thatch lined ceiling.", "src": "images/Joali Maldives/0020 - Joali Maldives - Luxury Water Villa with Pool - bedroom with canopy net and turquoise pendant.jpg", "source": "https://www.joali.com/joali-maldives/villas-and-residences/luxury-water-villa-with-pool/", "dimensions": "2000x1126", "size": 309301}, {"number": "0021", "file": "0021 - Joali Maldives - Luxury Water Villa with Pool - living room with blush woven armchairs and library bar.jpg", "resort": "Joali Maldives", "space": "Luxury Water Villa with Pool", "description": "The separate living room pairs two blush pink woven swivel armchairs with a low grey sofa dressed in pink and dove cushions, arranged around a glossy dark wood drum coffee table on a monochrome patterned rug. Behind, a dark timber bar and library unit with brass framing holds glassware, books and small sculptures, flanked by carved palm relief panels and a large turquoise glass disc artwork. Recreating the look needs cane and rattan textures kept tonal, one saturated teal art piece per room, potted palms in woven baskets, and a wall of hat hooks and curated objects by the entry.", "src": "images/Joali Maldives/0021 - Joali Maldives - Luxury Water Villa with Pool - living room with blush woven armchairs and library bar.jpg", "source": "https://www.joali.com/joali-maldives/villas-and-residences/luxury-water-villa-with-pool/", "dimensions": "2000x1126", "size": 324286}, {"number": "0027", "file": "0027 - Joali Maldives - Four Bedroom Beach Residence with Pool - bedroom opening to garden terrace.jpg", "resort": "Joali Maldives", "space": "Four Bedroom Beach Residence with Pool", "description": "A ground floor bedroom opens fully to a shaded garden terrace through sliding glass doors with sheer and taupe curtains. The bed carries white linen and a blush throw, matched by a woven blush swivel chair with a slate cushion and two cane terrace armchairs outside around a small table. Two black lattice lantern pendants hang from the thatched terrace roof, and a dark minibar cabinet with brass shelving stands by the wall. The scheme layers cream walls, pale stone floors, woven cane and rattan in honey tones, and soft pink textiles against dense green planting.", "src": "images/Joali Maldives/0027 - Joali Maldives - Four Bedroom Beach Residence with Pool - bedroom opening to garden terrace.jpg", "source": "https://www.joali.com/joali-maldives/villas-and-residences/four-bedroom-beach-residence-with-pool/", "dimensions": "2000x1126", "size": 306820}, {"number": "0031", "file": "0031 - Joali Maldives - Four Bedroom Beach Residence with Pool - dressing room with vanity and green marble panels.jpg", "resort": "Joali Maldives", "space": "Four Bedroom Beach Residence with Pool", "description": "The dressing room combines open wardrobe shelving in pale oak with a dark stained vanity desk and woven stool, lit by a mirror framed with globe bulbs in theatrical style. A stained glass door panel of green palm leaves and a full height panel of swirling green marble effect glass carry the bathroom motif through the suite, and a cylindrical rattan stool holds a woven tote. Brass shelf edging and black accessories keep the pale palette grounded. The design lesson is continuity: one coloured glass language links bath, dressing and bedroom, while storage stays open, shallow and hotel style.", "src": "images/Joali Maldives/0031 - Joali Maldives - Four Bedroom Beach Residence with Pool - dressing room with vanity and green marble panels.jpg", "source": "https://www.joali.com/joali-maldives/villas-and-residences/four-bedroom-beach-residence-with-pool/", "dimensions": "2000x1126", "size": 299706}, {"number": "0032", "file": "0032 - Joali Maldives - Four Bedroom Beach Residence with Pool - living room with shelving wall and blue sofa.jpg", "resort": "Joali Maldives", "space": "Four Bedroom Beach Residence with Pool", "description": "A double height living room is organised around a full wall of dark timber shelving divided into square compartments displaying ceramics, books and sculpture, with a wave painted television panel at its centre and carved palm relief panels behind. Seating mixes a long blue grey sofa with exposed dark wood frame, woven swivel chairs and a pair of charcoal dining chairs on a blue patterned rug over banded stone floors. Tall sliding doors open to the pool terrace. To recreate, build the shelving as the artwork, keep upholstery in dusty blue and blush, and let one large plant soften the grid.", "src": "images/Joali Maldives/0032 - Joali Maldives - Four Bedroom Beach Residence with Pool - living room with shelving wall and blue sofa.jpg", "source": "https://www.joali.com/joali-maldives/villas-and-residences/four-bedroom-beach-residence-with-pool/", "dimensions": "2000x1126", "size": 316898}, {"number": "0034", "file": "0034 - Joali Maldives - Four Bedroom Beach Residence with Pool - outdoor shower with emerald tile wall.jpg", "resort": "Joali Maldives", "space": "Four Bedroom Beach Residence with Pool", "description": "The garden shower court is walled in vertically stacked emerald green glazed ceramic tiles with strong colour variation, set between blush plaster pillars and a slatted bamboo privacy screen. A black rain shower on a dark pole, a carved wooden stump side table holding flowers and folded towels, and dense tropical planting in greens complete the space, over pale gravel and stone paving. This is the boldest colour moment in the residence: one saturated tile wall, everything else natural. Recreating it needs handmade look tiles with tonal movement, not flat green, and timber screens left untreated.", "src": "images/Joali Maldives/0034 - Joali Maldives - Four Bedroom Beach Residence with Pool - outdoor shower with emerald tile wall.jpg", "source": "https://www.joali.com/joali-maldives/villas-and-residences/four-bedroom-beach-residence-with-pool/", "dimensions": "2000x1126", "size": 422974}, {"number": "0035", "file": "0035 - Joali Maldives - Four Bedroom Beach Residence with Pool - library with open shelving and woven chairs.jpg", "resort": "Joali Maldives", "space": "Four Bedroom Beach Residence with Pool", "description": "The residence library lines one wall with open dark timber and brass shelving filled with books, coral, ceramics and framed pieces, above a long dark wood desk with bamboo style legs and a brass lamp. Two woven armchairs in blush and cream with pink cushions are grouped with a turned dark wood side table, and carved timber panels and a patterned stair rail close the view. Lighting is warm and low from sconces and desk lamps. For recreation, treat the library as a lived in cabinet of curiosities: mixed natural specimens and books, no matching sets, upholstery kept pale.", "src": "images/Joali Maldives/0035 - Joali Maldives - Four Bedroom Beach Residence with Pool - library with open shelving and woven chairs.jpg", "source": "https://www.joali.com/joali-maldives/villas-and-residences/four-bedroom-beach-residence-with-pool/", "dimensions": "2000x1126", "size": 323834}, {"number": "0041", "file": "0041 - One&Only Reethi Rah - Lobby - wide view of reception pavilion.jpg", "resort": "One&Only Reethi Rah", "space": "Lobby", "description": "The reception pavilion is a vast open sided hall under a steeply pitched thatched roof with exposed dark timber trusses. Massive carved wooden columns stand on black polished terrazzo floors inlaid with teak strips. Low lounge sofas in white canvas with crimson red cushions line both sides, paired with woven rattan tub chairs and low wooden coffee tables on pale rugs. Oversized black wire cage drum pendants with cream shades hang at intervals. Geometric timber lattice screens filter daylight and garden views. A single timber reception desk sits on axis beneath a carved gable panel and patterned feature wall. [below 1200px - best available]", "src": "images/One&Only Reethi Rah/0041 - One&Only Reethi Rah - Lobby - wide view of reception pavilion.jpg", "source": "https://theluxurytravelexpert.com/review-one-only-reethi-rah-maldives/", "dimensions": "1000x750", "size": 361590}, {"number": "0049", "file": "0049 - One&Only Reethi Rah - Botanica restaurant - orchid house dining room.jpg", "resort": "One&Only Reethi Rah", "space": "Botanica restaurant", "description": "Dinner inside the Botanica orchid house is served under a high pitched glasshouse roof of black steel trusses and translucent shade panels, with ceiling fans and small star like downlights. Dark stained timber dining tables are paired with formal carved chairs whose shaped splat backs and tan seats recall colonial plantation furniture. Both long walls are tiered planting benches dense with flowering orchids, each tier edged with tiny fairy lights, so guests dine between two banks of blooms. The floor is raked pale sand. Palette: black framework, dark wood, white and magenta orchid flowers, warm pinpoint lighting. [below 1200px - best available]", "src": "images/One&Only Reethi Rah/0049 - One&Only Reethi Rah - Botanica restaurant - orchid house dining room.jpg", "source": "https://www.purelymaldives.co.uk/resorts/view/one-only-reethi-rah", "dimensions": "850x638", "size": 335958}, {"number": "0050", "file": "0050 - One&Only Reethi Rah - Beach Villas - living room with lattice ceiling.jpg", "resort": "One&Only Reethi Rah", "space": "Beach Villas", "description": "The villa living room runs under a soaring pitched ceiling of dark timber boards crossed by lashed bamboo poles in a diamond lattice. Freestanding screen walls alternate cream panels with dark woven coconut shell mosaic, separating living, sleeping and bathing zones without doors. A long oatmeal linen sofa and chaise carry cushions in cream, sage and a red medallion print, arranged around a round white coffee table and timber armchairs with woven backs. Polished terrazzo floors with dark inlay bands, a patterned rust toned rug, and full height sliding doors open to a canopied daybed, plunge pool and beach beyond.", "src": "images/One&Only Reethi Rah/0050 - One&Only Reethi Rah - Beach Villas - living room with lattice ceiling.jpg", "source": "https://www.travoh.com/stays/oneonly-reethi-rah-resort-north-male-atoll-maldives/", "dimensions": "1840x1324", "size": 583154}, {"number": "0051", "file": "0051 - One&Only Reethi Rah - Beach Villas - master bedroom with ocean view.jpg", "resort": "One&Only Reethi Rah", "space": "Beach Villas", "description": "The master bedroom is arranged symmetrically on the ocean view, the king bed centred on a wide timber framed window with white linen, taupe cushions and a mustard yellow bolster. At its foot, two pale upholstered timber armchairs with red medallion print cushions flank a round drum pedestal table in warm wood with a dark woven top. Round timber bedside cabinets carry square white pendant lamps. To one side, a black framed minibar cabinet combines mirror, glass shelves and drawers faced in coconut shell and woven fibre; opposite stands a matching luggage cabinet on X frame legs. Woven mosaic wall panels and lashed bamboo ceiling beams complete the scheme.", "src": "images/One&Only Reethi Rah/0051 - One&Only Reethi Rah - Beach Villas - master bedroom with ocean view.jpg", "source": "https://www.travoh.com/stays/oneonly-reethi-rah-resort-north-male-atoll-maldives/", "dimensions": "1840x1150", "size": 758992}, {"number": "0055", "file": "0055 - One&Only Reethi Rah - Beach Villas - veranda lounge with teal daybed.jpg", "resort": "One&Only Reethi Rah", "space": "Beach Villas", "description": "The covered veranda lounge is furnished as an outdoor living room: a very long low bench daybed in dark timber with a taupe mattress and a continuous teal bolster back, dressed with teal cushions and leaf patterned pillows in aqua and white. Two barrel back chairs woven in grey cord sit at a round white dining table with a wooden bowl of fruit. Above, the open gable shows thatch laid over bamboo laths and lashed bamboo trusses, framing a wall of tropical planting that acts as the room backdrop. Terrazzo flooring with dark inlay continues outside, blurring the indoor outdoor boundary.", "src": "images/One&Only Reethi Rah/0055 - One&Only Reethi Rah - Beach Villas - veranda lounge with teal daybed.jpg", "source": "https://www.travoh.com/stays/oneonly-reethi-rah-resort-north-male-atoll-maldives/", "dimensions": "1840x1551", "size": 706415}, {"number": "0056", "file": "0056 - One&Only Reethi Rah - Beach Villas - dining room with coconut shell table.jpg", "resort": "One&Only Reethi Rah", "space": "Beach Villas", "description": "The villa dining area centres on a rectangular table whose top is a mosaic of coconut shell pieces in variegated browns, carried on splayed timber legs. Six sculpted dining chairs in warm mid tone wood have curved crest rails, padded grey seats and slender tapered legs. Behind, a pale grey sofa faces the beach through wide sliding doors beneath a thatched veranda. Black metal framed consoles with timber tops hold books, a star sculpture and flowers, and two framed black and white photographs hang above. Polished terrazzo with dark border inlay, woven screen panels and bamboo lashed ceiling beams maintain the villa material palette.", "src": "images/One&Only Reethi Rah/0056 - One&Only Reethi Rah - Beach Villas - dining room with coconut shell table.jpg", "source": "https://www.travoh.com/stays/oneonly-reethi-rah-resort-north-male-atoll-maldives/", "dimensions": "1840x1510", "size": 659432}, {"number": "0059", "file": "0059 - The Nautilus Maldives - Beach Residence with Private Pool - curved living room with orange ikat cushions.jpg", "resort": "The Nautilus Maldives", "space": "Beach Residence with Private Pool", "description": "Ground floor living room planned on a curve, with a long low sofa in natural linen following the wall, piled with solid orange cushions and orange and gold ikat cushions. Two round coral orange coffee tables with dark turned legs and patterned tops sit on an orange and ochre abstract rug over pale parquet. Beyond are a slatted timber television console, a table lamp with a stacked openwork rattan base, a woven chandelier over the dining table, and sage woven dining chairs. A cream macrame hanging against a round orange wall disc anchors the bohemian layering, and full height glazing opens to the deck, pool and ocean.", "src": "images/The Nautilus Maldives/0059 - The Nautilus Maldives - Beach Residence with Private Pool - curved living room with orange ikat cushions.jpg", "source": "https://www.thenautilusmaldives.com/houses/beach-residence", "dimensions": "1920x900", "size": 183062}, {"number": "0060", "file": "0060 - The Nautilus Maldives - Beach Residence with Private Pool - wet bar and dining detail with woven stools.jpg", "resort": "The Nautilus Maldives", "space": "Beach Residence with Private Pool", "description": "Close view of the ground floor wet bar and dining corner. Two high stools pair sage green woven wrap around backs with pale timber legs and foot rails, set at a counter fronted in fine vertical strips with a floating shelf holding dark glass vessels above. Matching woven dining chairs with grey seat pads surround a round pale wood table set with turquoise glassware. Oversized ribbed rattan urns, a chevron grooved timber door and a table lamp with three stacked rattan spheres on a round side table complete the scheme, over basketweave parquet in warm oak tones.", "src": "images/The Nautilus Maldives/0060 - The Nautilus Maldives - Beach Residence with Private Pool - wet bar and dining detail with woven stools.jpg", "source": "https://www.thenautilusmaldives.com/houses/beach-residence", "dimensions": "1920x900", "size": 179464}, {"number": "0062", "file": "0062 - The Nautilus Maldives - Beach Residence with Private Pool - upstairs king bedroom opening to ocean balcony.jpg", "resort": "The Nautilus Maldives", "space": "Beach Residence with Private Pool", "description": "Upstairs king bedroom in white linen, dressed with a central bolster, patterned cushions piped in orange and a painterly bed runner in orange, ochre and taupe stripes. A buttoned grey bench at the foot holds two white and gold lattice cushions, and a round orange and yellow rug softens pale geometric tiled flooring. Timber framed folding doors open to a balcony with wicker armchairs and a round pedestal table under the thatch, facing the ocean. Through the rear doorway, the bathroom shows a round patterned pouffe, a glass shower enclosure and a white robe, linking the sleep and bath zones.", "src": "images/The Nautilus Maldives/0062 - The Nautilus Maldives - Beach Residence with Private Pool - upstairs king bedroom opening to ocean balcony.jpg", "source": "https://www.thenautilusmaldives.com/houses/beach-residence", "dimensions": "1920x900", "size": 197986}, {"number": "0069", "file": "0069 - The Nautilus Maldives - Nautilus Retreat with Private Pool - living room under domed thatch ceiling with macrame chandelier.jpg", "resort": "The Nautilus Maldives", "space": "Nautilus Retreat with Private Pool", "description": "Reverse view of the circular living room, taken for its ceiling: a high domed roof of woven panels and exposed rafters, hung with a large hand knotted macrame chandelier with a beaded drop. Below, a high backed mustard wing chair and the curved cream sofa with yellow floral cushions sit around the round yellow coffee table, beside a drum side table carrying the stacked sphere rattan lamp. A cream macrame hanging is mounted on a round yellow wall disc, echoing the motif used in the beach residence, and a chevron grooved timber door closes the wall. Glazed doors run the length of the deck side.", "src": "images/The Nautilus Maldives/0069 - The Nautilus Maldives - Nautilus Retreat with Private Pool - living room under domed thatch ceiling with macrame chandelier.jpg", "source": "https://www.thenautilusmaldives.com/houses/the-nautilus-retreat", "dimensions": "1920x980", "size": 211128}, {"number": "0070", "file": "0070 - The Nautilus Maldives - Nautilus Retreat with Private Pool - curved bedroom in yellow scheme with deck doors.jpg", "resort": "The Nautilus Maldives", "space": "Nautilus Retreat with Private Pool", "description": "Curved bedroom in the yellow colourway, the king bed in white linen with a yellow and taupe painterly runner, lattice patterned cushions and a cylindrical bolster, backed by a pale timber headboard shelf with arched reading lamps. A buttoned cream bench stands at the foot, and a long low slatted timber console holds a turquoise glass bowl. Three tall glazed openings frame the deck and ocean, the middle one open. Through folding doors, the living room shows a rounded mustard chair, yellow tables and a sunburst mirror. Pale parquet in a chevron layout and a yellow abstract rug unify both rooms.", "src": "images/The Nautilus Maldives/0070 - The Nautilus Maldives - Nautilus Retreat with Private Pool - curved bedroom in yellow scheme with deck doors.jpg", "source": "https://www.thenautilusmaldives.com/houses/the-nautilus-retreat", "dimensions": "1920x900", "size": 233722}, {"number": "0076", "file": "0076 - Raffles Bali - Residence - master bedroom with bed bench and balcony.jpg", "resort": "Raffles Bali", "space": "Residence", "description": "Master bedroom with a coffered, high pitched ceiling in rich teak toned timber and walls panelled in fluted wood and soft taupe fabric. The king bed is dressed in crisp white linen with navy and terracotta cushions, and a dark wood bed bench with navy bolster cushions sits at its foot, a signature Raffles touch. Beside the bed, marble effect stone panels back floating nightstands with box frame lamps. A lounge chair and ottoman sit by full height sliding doors opening to a balcony with garden views. Polished hardwood floors are softened by a plain cream rug.", "src": "images/Raffles Bali/0076 - Raffles Bali - Residence - master bedroom with bed bench and balcony.jpg", "source": "https://www.raffles.com/bali/residence/", "dimensions": "2560x1707", "size": 630516}, {"number": "0077", "file": "0077 - Raffles Bali - Residence - bedroom suite with sitting area and carved screen.jpg", "resort": "Raffles Bali", "space": "Residence", "description": "Second bedroom suite arranged as a private apartment, with its own sitting area in the foreground. A cream sofa with navy and woven tan cushions faces a low stone topped coffee table on a blue patterned rug, while the bed sits beyond a carved timber screen panel with a traditional Balinese motif, which zones sleep from sitting without a wall. Fitted wardrobes in warm wood line the far wall, and glazed doors on both sides bring in garden light. The lesson is zoning with screens, rugs and ceiling coffers in one continuous timber and cream scheme.", "src": "images/Raffles Bali/0077 - Raffles Bali - Residence - bedroom suite with sitting area and carved screen.jpg", "source": "https://www.raffles.com/bali/residence/", "dimensions": "2560x1707", "size": 587788}, {"number": "0078", "file": "0078 - Raffles Bali - Residence - dining room with long dark table and rattan chairs.jpg", "resort": "Raffles Bali", "space": "Residence", "description": "Formal dining room for twelve under a soaring pitched ceiling of warm timber boards. One very long, dark stained plank table runs the length of the room, set with white napkins, glassware and a low floral centrepiece. The chairs are the focal craft piece, high backed woven rattan with curved crest rails and plump patterned seat cushions, light in colour against the dark table. Walls of glass on three sides frame jungle and ocean, a carved dark wood screen closes one end, and a single long pendant hangs over the table. Hardwood floors run throughout.", "src": "images/Raffles Bali/0078 - Raffles Bali - Residence - dining room with long dark table and rattan chairs.jpg", "source": "https://www.raffles.com/bali/residence/", "dimensions": "2560x1707", "size": 703277}, {"number": "0079", "file": "0079 - Raffles Bali - Residence - open plan living room and stone kitchen island.jpg", "resort": "Raffles Bali", "space": "Residence", "description": "Open plan living and show kitchen in one double height space, designed for entertaining. A long island in warm wood cabinetry with a thick grey veined stone top anchors the room, lit by a cluster of slim black pendant rods at different heights. Beyond it, low cream sofas and armchairs with dark frames group around coffee tables on a pale rug, with a television console against the glass wall. Ceiling fans, cove lit timber ceilings and full height glazing keep the large volume intimate. The scheme mixes stone, teak toned joinery and black metal accents.", "src": "images/Raffles Bali/0079 - Raffles Bali - Residence - open plan living room and stone kitchen island.jpg", "source": "https://www.raffles.com/bali/residence/", "dimensions": "2560x1707", "size": 721087}, {"number": "0080", "file": "0080 - Raffles Bali - Residence - study with marble desk and display shelving.jpg", "resort": "Raffles Bali", "space": "Residence", "description": "Private study and entertainment room with a dramatic black marble desk slab in the foreground, paired with sculptural grey upholstered desk chairs. Behind, a full wall of open display shelving in warm timber is backlit and styled with Balinese artefacts, a carved gold toned plaque, masks, ceramics, books and framed photographs, with a wall mounted television at its centre. A black multi disc chandelier adds a modern note against a dark woven ceiling panel. Glazed doors open to the pool terrace. The takeaway is museum style shelving, objects in ones and twos, and generous spacing.", "src": "images/Raffles Bali/0080 - Raffles Bali - Residence - study with marble desk and display shelving.jpg", "source": "https://www.raffles.com/bali/residence/", "dimensions": "2560x1707", "size": 654096}, {"number": "0083", "file": "0083 - Mandapa - Riverfront Pool Villa - living room with hand painted panels.jpg", "resort": "Mandapa", "space": "Riverfront Pool Villa", "description": "Open sided living room in dark stained timber centred on a woven rattan sofa dressed with ivory cushions and patterned throw pillows in grey, gold and cream. A round black pedestal coffee table carries a tea set and a small floral arrangement, balanced by a cylindrical dark wood cabinet at the side. Behind the sofa, tall hand painted wall panels in muted gold and sage show delicate botanical motifs, the signature art treatment of the villas. Full height glass doors open to a planted terrace, and a pale woven rug softens the polished timber floor.", "src": "images/Mandapa/0083 - Mandapa - Riverfront Pool Villa - living room with hand painted panels.jpg", "source": "https://www.ritzcarlton.com/en/hotels/dpsub-mandapa-a-ritz-carlton-reserve/photos/", "dimensions": "2560x1440", "size": 771740}, {"number": "0085", "file": "0085 - Mandapa - Riverfront Pool Villa - bedroom with murals and terrace doors.jpg", "resort": "Mandapa", "space": "Riverfront Pool Villa", "description": "Wide bedroom view showing how the villa layers art, textile and timber. Large hand painted murals of Balinese landscape and flora cover the wall panels around a window seat dressed in cream with ochre cushions. A green upholstered lounge chair and small black side table sit beside folding glass doors that open to a furnished terrace. The bed, partly seen, carries a vivid floral patterned throw in coral and blue over white linen. A woven ceiling pendant, natural fibre rug and dark wood framing complete a rich but restful scheme.", "src": "images/Mandapa/0085 - Mandapa - Riverfront Pool Villa - bedroom with murals and terrace doors.jpg", "source": "https://www.ritzcarlton.com/en/hotels/dpsub-mandapa-a-ritz-carlton-reserve/photos/", "dimensions": "2560x1440", "size": 928792}, {"number": "0086", "file": "0086 - Mandapa - Riverfront Pool Villa - king bedroom with mural panel and daybed.jpg", "resort": "Mandapa", "space": "Riverfront Pool Villa", "description": "King bedroom arranged symmetrically in dark stained wood, the bed dressed in crisp white linen with a low black bench at its foot holding folded books. Behind the bed, a tall window frames tropical planting, flanked by a large colourful mural panel with peacock and floral detailing. To the left, a built in daybed with cream cushions and a coral throw sits under a second garden window, with a small round black table in front. Stone sculpture on a floating shelf, hanging lantern pendants and a pale woven rug finish the composition.", "src": "images/Mandapa/0086 - Mandapa - Riverfront Pool Villa - king bedroom with mural panel and daybed.jpg", "source": "https://www.ritzcarlton.com/en/hotels/dpsub-mandapa-a-ritz-carlton-reserve/photos/", "dimensions": "2560x1440", "size": 953519}, {"number": "0091", "file": "0091 - Mandapa - Mandapa Spa - relaxation lounge with river view.jpg", "resort": "Mandapa", "space": "Mandapa Spa", "description": "Spa relaxation lounge arranged along a glass wall above the Ayung River. A curved low sofa in pale upholstery carries cushions in leaf green and terracotta, facing the water through full height sliding glass. Beside it stands a sculptural round side table in dark turned wood, set with a tea service and a bowl of fruit. Polished timber floors reflect the daylight, and carved wooden screens partly divide the seating bays. The recipe to copy is simple: one strong sculptural table, plain upholstery, two saturated cushion colours and an uninterrupted view.", "src": "images/Mandapa/0091 - Mandapa - Mandapa Spa - relaxation lounge with river view.jpg", "source": "https://www.ritzcarlton.com/en/hotels/dpsub-mandapa-a-ritz-carlton-reserve/photos/", "dimensions": "2560x1440", "size": 872199}, {"number": "0093", "file": "0093 - Mandapa - Mandapa Spa - reception and retail gallery.jpg", "resort": "Mandapa", "space": "Mandapa Spa", "description": "Long reception and retail gallery in the spa, lined on one side with dark timber display shelving holding ceramics, oils and treatment products under warm picture lighting. A central stone topped consultation table with a carved geometric base is paired with leather and wood chairs, while a low credenza in matching dark wood carries table lamps and a tall arrangement of red tropical flowers. Coffered ceilings, travertine style stone floors and brass pendants give the space a calm, residential formality quite different from a typical hotel spa desk.", "src": "images/Mandapa/0093 - Mandapa - Mandapa Spa - reception and retail gallery.jpg", "source": "https://www.ritzcarlton.com/en/hotels/dpsub-mandapa-a-ritz-carlton-reserve/photos/", "dimensions": "1920x1302", "size": 368899}, {"number": "0100", "file": "0100 - Mandapa - Library - open pavilion lounge with woven pendants.jpg", "resort": "Mandapa", "space": "Library", "description": "The Library is an open sided timber pavilion lounge beside the main pool, furnished for afternoon tea and quiet reading. Round dark wood tables are paired with armchairs that combine curved timber frames with woven cane style backs and patterned upholstery. Large woven rattan pendants hang from the high pitched, raftered ceiling, and patterned stone tiles in grey and terracotta run across the floor. Dark wood bookcases and cabinets line the inner wall, while the open sides frame the pool, rice fields and forest. Official resort photograph, the only Library image the resort itself publishes.", "src": "images/Mandapa/0100 - Mandapa - Library - open pavilion lounge with woven pendants.jpg", "source": "https://www.ritzcarlton.com/en/hotels/dpsub-mandapa-a-ritz-carlton-reserve/dining/", "dimensions": "1920x1280", "size": 472846}, {"number": "0101", "file": "0101 - Mandapa - Library - afternoon tea setting with framed deity painting.jpg", "resort": "Mandapa", "space": "Library", "description": "Second verified view of The Library, captioned as The Library in the gallery of a UK luxury travel specialist. A large gilt framed Balinese painting of a multi armed deity dominates the dark timber wall above a painted storage chest with gold detailing and a row of small candles. In front, steam bent style wooden armchairs with navy cushions surround a round table laid for the signature afternoon tea, with a tiered stand and teapot. A woven globe pendant hangs overhead, and folding doors open to the veranda, pool and gardens beyond. [below 1200px - best available]", "src": "images/Mandapa/0101 - Mandapa - Library - afternoon tea setting with framed deity painting.jpg", "source": "https://prestburytravel.co.uk/hotels/8374/mandapa-a-ritz-carlton-reserve", "dimensions": "900x600", "size": 251255}, {"number": "0103", "file": "0103 - Amanoi - Amanoi Ocean Pool Villa - living room opening to sea view terrace.jpg", "resort": "Amanoi", "space": "Amanoi Ocean Pool Villa", "description": "Daytime living room photographed from inside looking straight out to the sea, so the furniture reads as a layered foreground to the view. A grey upholstered sofa with rounded cushions sits left, paired with low slung timber armchairs with dark seat pads around a round pedestal coffee table holding a fruit bowl. Narrow side tables carry books and a small lantern. Red cylindrical lanterns hang either side of full height folding doors that open completely onto a terrace with two further armchairs and a table, demonstrating the seamless indoor outdoor plan, pale neutral textiles and dark timber contrast used throughout the villa.", "src": "images/Amanoi/0103 - Amanoi - Amanoi Ocean Pool Villa - living room opening to sea view terrace.jpg", "source": "https://www.aman.com/resorts/amanoi/accommodation/pavilions-villas/amanoi-ocean-pool-villa", "dimensions": "2560x1580", "size": 632650}, {"number": "0110", "file": "0110 - Amanoi - The Restaurant - dining room with white linen and black lamps.jpg", "resort": "Amanoi", "space": "The Restaurant", "description": "Wide interior of the main dining room, set for service with rectangular tables dressed in crisp white linen, glassware and folded napkins, surrounded by wooden framed chairs with dark woven backs and cream seats. A cream banquette runs along one side. Behind the tables, tall illuminated timber display cabinets hold large black lacquered urns and vessels, matched by oversized black table lamps with drum shades on side consoles. Dark ceilings, warm backlighting and restrained black, cream and honey timber tones give the formal room its evening mood, a useful template for quiet, layered restaurant lighting and display shelving.", "src": "images/Amanoi/0110 - Amanoi - The Restaurant - dining room with white linen and black lamps.jpg", "source": "https://www.aman.com/resorts/amanoi/dining", "dimensions": "2000x1235", "size": 478574}, {"number": "0112", "file": "0112 - Amanoi - The Restaurant - pavilion interior with lattice screens and columns.jpg", "resort": "Amanoi", "space": "The Restaurant", "description": "Long view through the Central Pavilion interior toward full height latticed timber screens, showing the restaurant lounge area furnished with grouped wooden armchairs, cushioned seats and low tables on a highly polished dark floor that mirrors the columns. Massive round grey columns carry the high pitched timber ceiling, and carved dark figures and a large floral arrangement on plinths provide the only ornament. Warm light glows through the lattice at the far end. The scale lesson is clear: very tall, simple architecture, furniture kept low and sparse, and screens used instead of solid walls to divide the space.", "src": "images/Amanoi/0112 - Amanoi - The Restaurant - pavilion interior with lattice screens and columns.jpg", "source": "https://www.aman.com/resorts/amanoi/dining", "dimensions": "2560x1580", "size": 537736}, {"number": "0116", "file": "0116 - Amanoi - The Bar - long timber bar counter with columns.jpg", "resort": "Amanoi", "space": "The Bar", "description": "Wide evening view along the Bar, centred on a very long, low timber bar counter with a dark top, fronted by a row of tan leather bar chairs. Massive pale columns divide the counter from a lounge area of low sofas and small round tables to the left, all under a high pitched timber ceiling with exposed structure. Warm light glows from latticed timber screens and glass cabinets behind the counter, where a bartender works. The design takeaway is length and repetition: one continuous counter, identical seating, and amber backlighting creating atmosphere without decoration or clutter.", "src": "images/Amanoi/0116 - Amanoi - The Bar - long timber bar counter with columns.jpg", "source": "https://www.aman.com/resorts/amanoi/dining", "dimensions": "2560x1580", "size": 536606}, {"number": "0128", "file": "0128 - Four Seasons Resort Koh Samui - Specialty Villas - Island Residence living and dining room.jpg", "resort": "Four Seasons Resort Koh Samui", "space": "Specialty Villas", "description": "The living and dining room of the one bedroom Island Residence combines polished hardwood floors with a high open ceiling and full height glass doors. Two woven armchairs with cream and patterned cushions face a pale upholstered sofa across paired drum side tables in natural wood, stacked with books and ceramics. Behind, a timber dining table with six woven chairs and turquoise cushions stands ready for indoor meals, lit by daylight from three sides. Tall potted palms, carved details and a muted palette of cream, sand and sea green complete a calm, collected interior. [below 1200px - best available]", "src": "images/Four Seasons Resort Koh Samui/0128 - Four Seasons Resort Koh Samui - Specialty Villas - Island Residence living and dining room.jpg", "source": "https://hurlinghamtravel.co.uk/hotel/four-seasons-resort-koh-samui", "dimensions": "1100x671", "size": 263986}, {"number": "0132", "file": "0132 - Four Seasons Resort Koh Samui - KOH Thai Kitchen - Main dining hall with woven chairs.jpg", "resort": "Four Seasons Resort Koh Samui", "space": "KOH Thai Kitchen", "description": "The main dining hall at KOH Thai Kitchen is a grand open pavilion with a steeply pitched timber ceiling, exposed trusses and slowly turning ceiling fans. Rows of square wooden tables are set with glassware and folded napkins, surrounded by woven rattan armchairs with patterned seat cushions in cream and soft blue. Dark hardwood floors reflect the warm late light, and the open sides frame jungle and sea views between massive round columns. Botanical artworks and low planting complete a room that feels both ceremonial and relaxed, unmistakably southern Thai in spirit.", "src": "images/Four Seasons Resort Koh Samui/0132 - Four Seasons Resort Koh Samui - KOH Thai Kitchen - Main dining hall with woven chairs.jpg", "source": "https://www.fourseasons.com/kohsamui/dining/restaurants/koh/", "dimensions": "2560x1642", "size": 1125546}, {"number": "0136", "file": "0136 - Four Seasons Resort Koh Samui - KOH Bar - Lounge pavilion with rattan armchairs and oversized sofas.jpg", "resort": "Four Seasons Resort Koh Samui", "space": "KOH Bar", "description": "The KOH Bar lounge fills a high timber pavilion with blocky woven rattan armchairs, oversized daybed sofas and low square coffee tables. Cushions mix burnt orange solids with cream and rust geometric patterns, warming the dark hardwood floor and the massive round columns. Rope wrapped beam joints, a woven ceiling, pierced friezes and clusters of woven pendant lights add crafted Thai detail overhead, while folding glass doors open one whole side to the terrace and trees. Staff serve wine and cocktails at the tables, underlining that this is a drinking lounge, not a dining room.", "src": "images/Four Seasons Resort Koh Samui/0136 - Four Seasons Resort Koh Samui - KOH Bar - Lounge pavilion with rattan armchairs and oversized sofas.jpg", "source": "https://www.fourseasons.com/kohsamui/dining/", "dimensions": "2560x1707", "size": 1055413}, {"number": "0138", "file": "0138 - Amanpuri - Pavilion - bedroom with lattice timber headboard wall.jpg", "resort": "Amanpuri", "space": "Pavilion", "description": "A symmetrical pavilion bedroom built around a full height lattice headboard wall of dark stained timber framing lighter wood panels in a strict grid. The low platform king bed in white striped cotton sits on chunky round timber legs, flanked by oval dark wood side tables, black swing arm reading lamps and tall carved wooden paddle sculptures mounted on the cream walls. Polished teak floorboards, a black vase of white orchids and lotus bud dishes complete the restrained palette. To recreate it, pair geometric timber screening with sculptural tribal art, low rounded furniture and warm uplighting.", "src": "images/Amanpuri/0138 - Amanpuri - Pavilion - bedroom with lattice timber headboard wall.jpg", "source": "https://www.aman.com/resorts/amanpuri/gallery", "dimensions": "2560x1582", "size": 306989}, {"number": "0143", "file": "0143 - Amanpuri - Eight-Bedroom Ocean Villa - lounge with leather armchairs and ocean view.jpg", "resort": "Amanpuri", "space": "Eight-Bedroom Ocean Villa", "description": "A grand open lounge under a high timber roof, where rows of polished round columns and diagonal braces frame glass walls looking to the sea. Seating is low and generous: taupe leather armchairs, leather daybeds with bolster arms and a long sofa grouped around oversized dark wood coffee tables on a muted rug. A tripod telescope, a bronze figure sculpture on a stone plinth and a carved wooden orb act as focal objects, with a rubble stone wall behind. To recreate it, use leather in warm greys, very large low tables, ceiling fans and museum scale art against the view.", "src": "images/Amanpuri/0143 - Amanpuri - Eight-Bedroom Ocean Villa - lounge with leather armchairs and ocean view.jpg", "source": "https://www.aman.com/resorts/amanpuri/accommodation/villas", "dimensions": "1600x988", "size": 1543163}, {"number": "0145", "file": "0145 - Amanpuri - Villas - living room with celadon daybeds and pedestal table.jpg", "resort": "Amanpuri", "space": "Villas", "description": "A formal villa living room arranged with strict symmetry around a round burl wood pedestal table with a stepped, stacked base. Pale celadon daybed platforms with Thai triangular cushions face each other across dark stone tiles, fronted by a low lacquered tea tray. Behind, glazed timber doors and lattice screens reveal display cabinets of ceramics and a media room, flanked by Buddha head sculptures on plinths and silvered bamboo armchairs. The timber boarded ceiling and restrained green, brown and cream palette show how to use symmetry, collectable objects and one statement table to anchor a large room.", "src": "images/Amanpuri/0145 - Amanpuri - Villas - living room with celadon daybeds and pedestal table.jpg", "source": "https://www.aman.com/resorts/amanpuri/accommodation/villas", "dimensions": "2560x2560", "size": 1114382}, {"number": "0186", "file": "0186 - Four Seasons Resort Bali at Sayan - Premier Duplex Suite - carved screen headboard wall detail with bedside pendant.jpg", "resort": "Four Seasons Resort Bali at Sayan", "space": "Premier Duplex Suite", "description": "A detail study of the suite headboard wall, where framed teak panels carved with scrolling foliage run floor to ceiling behind the bed, their openwork backed so the pattern reads as shadow and texture. A single fabric shaded cylindrical pendant drops beside the pillow, and the low nightstand is woven cane fronted timber. In a wall niche sits a small stone guardian statue, spotlit like gallery art, while a pale lounge chair with a patterned cushion waits in the corner. The lesson for recreation is layering: carved wood, woven cane, stone sculpture and plain linen in one restrained palette.", "src": "images/Four Seasons Resort Bali at Sayan/0186 - Four Seasons Resort Bali at Sayan - Premier Duplex Suite - carved screen headboard wall detail with bedside pendant.jpg", "source": "https://press.fourseasons.com/sayan/hotel-news/2026/riverside-suites/", "dimensions": "2560x1920", "size": 885109}, {"number": "0187", "file": "0187 - Four Seasons Resort Bali at Sayan - Premier Duplex Suite - mezzanine living room with woven armchairs and valley windows.jpg", "resort": "Four Seasons Resort Bali at Sayan", "space": "Premier Duplex Suite", "description": "The upper living level of the duplex suite pairs a pale grey sofa with low woven rattan armchairs and a green upholstered bench, arranged around the stair rail so the seating group floats above the floor below. A tall floor lamp with a stacked, textured column base and drum shade anchors one corner, and louvered teak shutters frame floor to ceiling windows over the river valley. Beyond glazed doors a dining nook repeats the palette. Recreating it requires furniture kept low and leggy, natural fibre upholstery, dark timber trim throughout, and pattern confined to a few cushions and the woven chair backs.", "src": "images/Four Seasons Resort Bali at Sayan/0187 - Four Seasons Resort Bali at Sayan - Premier Duplex Suite - mezzanine living room with woven armchairs and valley windows.jpg", "source": "https://press.fourseasons.com/sayan/hotel-news/2026/riverside-suites/", "dimensions": "2560x1920", "size": 963596}, {"number": "0188", "file": "0188 - Four Seasons Resort Bali at Sayan - Premier Duplex Suite - window reading corner with louvered shutters and rattan chair.jpg", "resort": "Four Seasons Resort Bali at Sayan", "space": "Premier Duplex Suite", "description": "A corner reading nook wrapped in teak louvered shutters and tall windows, furnished with a pale sofa dressed in oversized green floral cushions and a round swivel chair in bent rattan with floral upholstery. A small dark timber side table carries a sculptural lamp and a vase of white flowers, and the polished timber floor is left bare to show its grain. The design move to copy is the shuttered window wall itself: adjustable louvres replace curtains, controlling light and privacy while adding strong vertical rhythm, and one bold floral textile repeated on chair and cushions ties the whole corner together.", "src": "images/Four Seasons Resort Bali at Sayan/0188 - Four Seasons Resort Bali at Sayan - Premier Duplex Suite - window reading corner with louvered shutters and rattan chair.jpg", "source": "https://press.fourseasons.com/sayan/hotel-news/2026/riverside-suites/", "dimensions": "2560x1920", "size": 1056774}, {"number": "0192", "file": "0192 - Four Seasons Resort Bali at Sayan - One-Bedroom Villa - bedroom opening to terrace dining with statue niche.jpg", "resort": "Four Seasons Resort Bali at Sayan", "space": "One-Bedroom Villa", "description": "A second angle on the villa bedroom showing its full indoor outdoor plan: bed with plum cushions and a woven bench, a stone deity statue set into a lit wall niche, framed Balinese artwork, and a low carved cabinet beneath it. Teak folding louvered doors open to a covered terrace set with a dining table and timber chairs above the valley, while a separate desk sits by shuttered windows. The palette is cream plaster, warm teak and deep plum accents. To copy it, treat the niche statue and artwork as the room art programme and let one accent colour carry cushions and upholstery.", "src": "images/Four Seasons Resort Bali at Sayan/0192 - Four Seasons Resort Bali at Sayan - One-Bedroom Villa - bedroom opening to terrace dining with statue niche.jpg", "source": "https://www.fourseasons.com/sayan/photos-and-videos/", "dimensions": "2560x1568", "size": 893384}, {"number": "0197", "file": "0197 - Four Seasons Resort Bali at Sayan - Sacred River Spa - relaxation lounge with patterned chairs and bamboo screens.jpg", "resort": "Four Seasons Resort Bali at Sayan", "space": "Sacred River Spa", "description": "Inside the spa relaxation lounge, barrel back lounge chairs upholstered in blue grey patterned fabric face each other across small sculptural black side tables, under a pitched ceiling of bamboo and dark rafters. One wall is screened with vertical bamboo poles of varied tone, another is a long honed timber counter with orchids and ceramics, and the floor is large format grey stone tile. A therapist kneels in a tea service ritual at the centre. Recreation notes: pattern belongs on the chair fabric alone, structure stays dark timber and bamboo, and fresh orchids plus handmade ceramics provide the only decoration needed.", "src": "images/Four Seasons Resort Bali at Sayan/0197 - Four Seasons Resort Bali at Sayan - Sacred River Spa - relaxation lounge with patterned chairs and bamboo screens.jpg", "source": "https://press.fourseasons.com/content/fourseasons_pressroom/printView.html?pageToPrint=%2Fcontent%2Ffourseasons_pressroom%2Fen%2Fnews%2Fsayan%2F2024%2Fsacred_river_spa_rel", "dimensions": "2560x1707", "size": 1217560}, {"number": "0215", "file": "0215 - The Datai Langkawi - Canopy Suite - living and dining room with slatted timber cornice.jpg", "resort": "The Datai Langkawi", "space": "Canopy Suite", "description": "Open plan living and dining room in the main building, defined by a continuous slatted timber cornice at ceiling level. Curved barrel armchairs in cream fabric with dark timber side panels face grey sofas dressed with mustard yellow, charcoal and black and white patterned cushions. Two low black oval coffee tables carry glass hurricane candles, and a tall dark timber minibar cabinet with folding doors and warm internal lighting stands on legs against the wall. Beyond, an oval timber dining table with cream upholstered chairs sits under a large pleated white pendant, with torch style floor lamps, mirrored panelling and polished timber floors.", "src": "images/The Datai Langkawi/0215 - The Datai Langkawi - Canopy Suite - living and dining room with slatted timber cornice.jpg", "source": "https://www.thedatai.com/accommodation/the-canopy-collection/canopy-suite/", "dimensions": "2448x1633", "size": 496682}, {"number": "0217", "file": "0217 - The Datai Langkawi - The Datai Suite - dining room with woven chairs and sunburst wall disc.jpg", "resort": "The Datai Langkawi", "space": "The Datai Suite", "description": "Dining and living space divided by round dark timber columns under a coffered timber ceiling panel with cove lighting. Six dining chairs with tightly woven basketweave backs, cream seat pads and loose white cushions surround a round polished timber table with a raised fruit compote. On the white wall hangs a large circular sunburst disc in dark patinated metal, spotlit from above. A timber desk with an orchid and a black ceramic urn separates the dining area from a grey sofa lounge with a low timber coffee table. Torch style floor lamps, textured grey rugs and dark timber floors hold the calm, earthy palette together.", "src": "images/The Datai Langkawi/0217 - The Datai Langkawi - The Datai Suite - dining room with woven chairs and sunburst wall disc.jpg", "source": "https://www.thedatai.com/accommodation/the-canopy-collection/the-datai-suite/", "dimensions": "2448x1633", "size": 511984}, {"number": "0221", "file": "0221 - The Datai Langkawi - One-Bedroom Beach Villa - living pavilion opening to courtyard pool.jpg", "resort": "The Datai Langkawi", "space": "One-Bedroom Beach Villa", "description": "Open sided living pavilion with a high pitched raftered timber ceiling and full height glass doors. In the foreground, a massive single slab timber coffee table on black block legs holds black and gold ceramic vessels and a book, over a grey rug with a raised organic pattern. Cane backed armchairs with deep cream cushions group around it, and a timber dining table with matching woven cane chairs stands by the glass wall. Beyond the sliding doors, sun loungers and an umbrella sit beside the private pool against a wall of rough grey rubble stone, the resort signature boundary treatment.", "src": "images/The Datai Langkawi/0221 - The Datai Langkawi - One-Bedroom Beach Villa - living pavilion opening to courtyard pool.jpg", "source": "https://www.thedatai.com/gallery/", "dimensions": "2560x1708", "size": 1361931}, {"number": "0228", "file": "0228 - The Datai Langkawi - The Dining Room - poolside terrace with curved armchairs.jpg", "resort": "The Datai Langkawi", "space": "The Dining Room", "description": "Terrace seating of the main restaurant under a slatted timber canopy carried on slender angled columns, overlooking the main pool. Square white topped tables on fluted dark timber pedestal bases are set for breakfast with white ceramics and small stone vases of flowers. The chairs are the design focus: curved timber armchairs with wraparound arms and cream upholstered backs and seats, repeated in rows across the pale stone tiles. Cylindrical cream pendants hang from the canopy. Beyond the pool, sun loungers with white umbrellas and a shingled pavilion roof sit against dense rainforest, in a palette of cream, pale stone and warm timber.", "src": "images/The Datai Langkawi/0228 - The Datai Langkawi - The Dining Room - poolside terrace with curved armchairs.jpg", "source": "https://www.thedatai.com/gallery/", "dimensions": "2560x1708", "size": 1025101}, {"number": "0229", "file": "0229 - The Datai Langkawi - The Lobby Lounge - lounge pavilion with sunken seating and bar.jpg", "resort": "The Datai Langkawi", "space": "The Lobby Lounge", "description": "Grand open lounge pavilion under a soaring pitched timber roof with exposed rafters, ceiling fans and warm uplighting along the beams. In the foreground, a sunken seating pit of long cream banquettes is dressed with black and white geometric patterned cushions and deep green and ochre accents, grouped around round hammered metal drum tables with candle votives and low cream swivel lounge chairs. To the left, a long black stone bar with patterned seat stools runs towards a raised deck with a grand piano, armchairs and torch style lamps, all facing the open side and its view over the rainforest canopy to the sea.", "src": "images/The Datai Langkawi/0229 - The Datai Langkawi - The Lobby Lounge - lounge pavilion with sunken seating and bar.jpg", "source": "https://www.thedatai.com/dining/the-lobby-lounge/", "dimensions": "2560x1709", "size": 1035139}, {"number": "0366", "file": "0366 - The Brando - Three Bedroom Villa - living and dining room under pandanus vault.jpg", "resort": "The Brando", "space": "Three Bedroom Villa", "description": "The great room of the three bedroom villa, a double height space under a dramatic woven pandanus vault with exposed timber trusses and ceiling fans. A long marble topped dining table seats eight in textured oatmeal upholstered chairs. A low open timber credenza with ceramic vessels divides dining from the media wall, which is timber panelled with an inset screen. Full height sliding glass and cream curtains open to the pool deck and beach. Recreate with a woven vaulted ceiling as the hero, one long shared dining table, and low horizontal furniture that never competes with the roof.", "src": "images/The Brando/0366 - The Brando - Three Bedroom Villa - living and dining room under pandanus vault.jpg", "source": "https://thebrando.com/accommodations/", "dimensions": "2500x1879", "size": 997170}, {"number": "0389", "file": "0389 - Constance Prince Maurice - Junior Suite Beachfront - bedroom with draped poster bed and X frame bench.jpg", "resort": "Constance Prince Maurice", "space": "Junior Suite Beachfront", "description": "Portrait view of the suite bedroom built around a tall carved dark wood poster bed dressed in white linen, a pleated fabric canopy panel and spice toned cushions, with an X frame upholstered bench at its foot. The pitched ceiling is lined in woven rattan under the thatch, floors are warm varnished timber, and a writing desk with an oval mirror and shell toned ceramics sits to one side. To recreate the look, pair a raised four poster bed with cream silk drapes, a cross leg bench, rattan ceiling cladding and bedside lamps with drum shades.", "src": "images/Constance Prince Maurice/0389 - Constance Prince Maurice - Junior Suite Beachfront - bedroom with draped poster bed and X frame bench.jpg", "source": "https://www.constancehotels.com/en/hotels-resorts/prince-maurice/accommodation/", "dimensions": "1771x2560", "size": 751844}, {"number": "0394", "file": "0394 - Constance Prince Maurice - Villa on Stilts - bedroom with teal cushions and louvred deck doors.jpg", "resort": "Constance Prince Maurice", "space": "Villa on Stilts", "description": "Villa bedroom with a high vaulted ceiling lit by a warm cove, a carved dark wood bed dressed with a brocade style throw and teal cushions over the spice route palette. Louvred timber doors open to the deck, with an armchair, pedestal table and upholstered bench completing the room on polished wood floors. Recreate with teal and sand silk cushions, a patterned throw, shutter doors and a ceiling fan.", "src": "images/Constance Prince Maurice/0394 - Constance Prince Maurice - Villa on Stilts - bedroom with teal cushions and louvred deck doors.jpg", "source": "https://www.constancehotels.com/en/hotels-resorts/prince-maurice/accommodation/", "dimensions": "2560x1709", "size": 716631}, {"number": "0398", "file": "0398 - Constance Prince Maurice - Princely Villa - thatched dining pavilion with stone wall and chandelier.jpg", "resort": "Constance Prince Maurice", "space": "Princely Villa", "description": "The Princely Villa open air dining pavilion, a vast thatched roof on rough timber posts against a dry stone wall, lit by a multi arm chandelier with fabric shades. A long timber dining table set with glassware and a tall floral arrangement faces low grey lounge sofas, with the private pool and sea beyond. Recreate with a stone feature wall, oversized pendant lighting, mixed dining and lounge zones and sand toned upholstery.", "src": "images/Constance Prince Maurice/0398 - Constance Prince Maurice - Princely Villa - thatched dining pavilion with stone wall and chandelier.jpg", "source": "https://www.constancehotels.com/en/hotels-resorts/prince-maurice/accommodation/", "dimensions": "2560x1708", "size": 1035646}, {"number": "0458", "file": "0458 - Alila Ubud - Deluxe Room - twin room with garden terrace and outdoor armchairs.jpg", "resort": "Alila Ubud", "space": "Deluxe Room", "description": "Ground floor Deluxe twin room in the village blocks, its beds dressed in white with gold patterned runners, a tall louvred timber wardrobe and vanity to one side. Glass doors open fully to a private garden terrace where timber armchairs and a side table sit on stone paving against a low stone wall and lawn, the first step in the resort's indoor outdoor living pattern that the villas take further.", "src": "images/Alila Ubud/0458 - Alila Ubud - Deluxe Room - twin room with garden terrace and outdoor armchairs.jpg", "source": "https://www.hyatt.com/alila-hotels-and-resorts/en-US/dpsau-alila-ubud/rooms", "dimensions": "2560x1440", "size": 338493}, {"number": "0466", "file": "0466 - Alila Ubud - Valley Villa - open bedroom with timber desk, rattan chair and draped canopy bed.jpg", "resort": "Alila Ubud", "space": "Valley Villa", "description": "Valley Villa bedroom photographed from behind its dark timber writing desk, which carries twin shaded lamps and a woven rattan chair. Beyond, the bed is hung with sheer white canopy drapes and faces a full wall of glass over the Ayung valley, with a cushioned window seat built in to one side. The woven thatch ceiling and timber floor keep the open plan room warm despite its size.", "src": "images/Alila Ubud/0466 - Alila Ubud - Valley Villa - open bedroom with timber desk, rattan chair and draped canopy bed.jpg", "source": "https://www.hyatt.com/alila-hotels-and-resorts/en-US/dpsau-alila-ubud/rooms", "dimensions": "2560x1440", "size": 446060}, {"number": "0503", "file": "0503 - Amankila - Amankila Suite - terrace at dusk with seating overlooking the ocean.jpg", "resort": "Amankila", "space": "Amankila Suite", "description": "Terrace of the two bedroom Amankila Suite at dusk, furnished as an outdoor living room with two low teak lounge chairs and a central stone table holding candles, all facing the Lombok Strait. A still reflecting pool in the foreground mirrors the furniture and the sunset sky. The recipe is restraint: solid teak frames, plain cushions, one strong horizon line and no ornament beyond candlelight.", "src": "images/Amankila/0503 - Amankila - Amankila Suite - terrace at dusk with seating overlooking the ocean.jpg", "source": "https://www.aman.com/resorts/amankila/accommodation", "dimensions": "2000x1235", "size": 273810}, {"number": "0504", "file": "0504 - Amankila - Garden Suite - terrace with thatched pavilion and tropical landscape views.jpg", "resort": "Amankila", "space": "Garden Suite", "description": "Garden Suite terrace built as a small open bale with a steep alang alang thatched roof on timber posts, set on a stone balustraded terrace above the gardens. Inside the bale a daybed and low table create a shaded sitting room outdoors, while the balustrade and lawn loungers extend the living space toward the sea. Coconut wood and rattan furniture in the suites follows the same pale, natural palette.", "src": "images/Amankila/0504 - Amankila - Garden Suite - terrace with thatched pavilion and tropical landscape views.jpg", "source": "https://www.aman.com/resorts/amankila/accommodation", "dimensions": "2000x1235", "size": 904640}, {"number": "0505", "file": "0505 - Amankila - Indrakila Suite - plunge pool overlooking the coast with sun loungers.jpg", "resort": "Amankila", "space": "Indrakila Suite", "description": "The Indrakila Suite terrace is organised around a long private infinity pool edged in stone, with two white cushioned teak loungers and a side table placed for the coastal view. A raised lounging pavilion stands behind, giving a second, shaded seating layer. Paras stone, timber and white upholstery keep the composition calm and architectural rather than decorative.", "src": "images/Amankila/0505 - Amankila - Indrakila Suite - plunge pool overlooking the coast with sun loungers.jpg", "source": "https://www.aman.com/resorts/amankila/accommodation", "dimensions": "2000x1235", "size": 432750}, {"number": "0506", "file": "0506 - Amankila - Infinity Pool Suite - thatched pavilion and private pool over terraced gardens.jpg", "resort": "Amankila", "space": "Infinity Pool Suite", "description": "Infinity Pool Suite seen from its garden: a thatched, stilted pavilion in the Ed Tuttle beach house manner, with a private aquamarine pool and stone terrace in front. Sun loungers and a parasol furnish the deck simply. The design lesson is the elevation: raising the suite on stilts buys the sea view while the thatch and timber keep it rooted in the hillside.", "src": "images/Amankila/0506 - Amankila - Infinity Pool Suite - thatched pavilion and private pool over terraced gardens.jpg", "source": "https://www.aman.com/resorts/amankila/accommodation", "dimensions": "2560x2557", "size": 1782459}, {"number": "0507", "file": "0507 - Amankila - Kilasari Suite - plunge pool with sun loungers and palm fringed grounds.jpg", "resort": "Amankila", "space": "Kilasari Suite", "description": "Kilasari Suite plunge pool terrace, a long narrow pool in turquoise tile running between palm fringed lawns, with two timber loungers and a cushioned bale at the far end. The suite pavilion sits quietly behind planting. Furniture is limited to loungers, a daybed bale and low tables, all in weathered teak tones that disappear into the garden.", "src": "images/Amankila/0507 - Amankila - Kilasari Suite - plunge pool with sun loungers and palm fringed grounds.jpg", "source": "https://www.aman.com/resorts/amankila/accommodation", "dimensions": "2000x1235", "size": 990732}, {"number": "0508", "file": "0508 - Amankila - Ocean Suite - principal bedroom with four poster bed and seating area.jpg", "resort": "Amankila", "space": "Ocean Suite", "description": "Ocean Suite bedroom arranged on a central axis: a canopied four poster bed in dark timber faces full height doors to the terrace and sea, flanked by low cabinets in coconut shell and pearl inlay, the signature Amankila furniture finish. A woven rug softens the stone floor and a small sitting area sits to one side. High pitched ceilings in woven bamboo complete the beach house envelope.", "src": "images/Amankila/0508 - Amankila - Ocean Suite - principal bedroom with four poster bed and seating area.jpg", "source": "https://www.aman.com/resorts/amankila/accommodation", "dimensions": "2000x1235", "size": 373241}, {"number": "0509", "file": "0509 - Amankila - Pool Suite - courtyard with plunge pool and sunbeds through archway.jpg", "resort": "Amankila", "space": "Pool Suite", "description": "Pool Suite courtyard viewed through a rounded paras stone archway: a private plunge pool with two sunbeds, a shaded lounging bale and the suite pavilion beyond. The arch frames the scene like a picture, a device borrowed from the nearby Ujung water palace that recurs across Amankila. Stone, thatch and white cushions carry the whole composition.", "src": "images/Amankila/0509 - Amankila - Pool Suite - courtyard with plunge pool and sunbeds through archway.jpg", "source": "https://www.aman.com/resorts/amankila/accommodation", "dimensions": "1067x1067", "size": 247184}, {"number": "0510", "file": "0510 - Amankila - Pool Suite - interior with timber columns and floor to ceiling windows.jpg", "resort": "Amankila", "space": "Pool Suite", "description": "Pool Suite interior showing the working half of the suite: a writing desk and chair set between turned timber columns, with the bed just out of frame and garden light entering through tall windows. Coconut wood and rattan furniture, woven ceiling panels and a pale stone floor give the room its quiet, crafted character. Nothing is upholstered heavily; the luxury is in joinery and proportion.", "src": "images/Amankila/0510 - Amankila - Pool Suite - interior with timber columns and floor to ceiling windows.jpg", "source": "https://www.aman.com/resorts/amankila/accommodation", "dimensions": "2000x2000", "size": 724066}, {"number": "0511", "file": "0511 - Amankila - Spa - relaxation alcove with daybed and carved wooden statue.jpg", "resort": "Amankila", "space": "Spa", "description": "Spa relaxation alcove furnished with a deep cream daybed piled with cushions and a small round tray table, set against a warm plaster wall hung with a carved wooden statue. Tall windows open to the garden. It shows how Amankila handles small spaces: one generous piece of furniture, one piece of Balinese art and natural light.", "src": "images/Amankila/0511 - Amankila - Spa - relaxation alcove with daybed and carved wooden statue.jpg", "source": "https://www.aman.com/resorts/amankila/gallery", "dimensions": "760x1000", "size": 581890}, {"number": "0512", "file": "0512 - Amankila - Spa - treatment preparation with aromatic steam on wooden platform.jpg", "resort": "Amankila", "space": "Spa", "description": "A dark, atmospheric spa still life: aromatic steam rises from a carved vessel on a low wooden platform during treatment preparation. The image captures the sensory register of the Massage Pavilion, where treatments use local oils and compresses. As a design note it records the palette of the spa interiors: near black timber, stone and warm candle tones.", "src": "images/Amankila/0512 - Amankila - Spa - treatment preparation with aromatic steam on wooden platform.jpg", "source": "https://www.aman.com/resorts/amankila/wellness", "dimensions": "1067x1067", "size": 108613}, {"number": "0513", "file": "0513 - Amankila - Suite - bedroom with wooden beams and sitting area in natural light.jpg", "resort": "Amankila", "space": "Suite", "description": "Suite bedroom and sitting area under a woven bamboo ceiling carried on dark timber beams. A desk with chair, a cushioned window seat and low coconut shell inlaid cabinets furnish the room, with sliding doors opening to greenery on two sides. The four poster bed stands just out of frame. This is the standard suite formula that made Amankila influential: pavilion first, furniture second, view throughout.", "src": "images/Amankila/0513 - Amankila - Suite - bedroom with wooden beams and sitting area in natural light.jpg", "source": "https://www.aman.com/resorts/amankila/gallery", "dimensions": "1000x1000", "size": 340145}, {"number": "0514", "file": "0514 - Amankila - Suite - principal bedroom with wooden four poster bed and garden views.jpg", "resort": "Amankila", "space": "Suite", "description": "Principal bedroom centred on a wooden four poster bed dressed in white, positioned before a wide window seat and garden doors. A carved timber screen divides the sleeping area from the entrance, and a low patterned rug warms the stone floor. Furnishings in coconut wood and rattan with pearl inlay details keep the room tactile rather than glossy.", "src": "images/Amankila/0514 - Amankila - Suite - principal bedroom with wooden four poster bed and garden views.jpg", "source": "https://www.aman.com/resorts/amankila/gallery", "dimensions": "1500x938", "size": 389036}, {"number": "0515", "file": "0515 - Amankila - Suite Bathroom - bathtub with ocean view.jpg", "resort": "Amankila", "space": "Suite Bathroom", "description": "Suite bathroom built around a deep rectangular soaking tub placed directly before a wide window framing the coastline. Twin vanities and fittings are kept low and plain so the view does the decorating. Stone surfaces, timber shutters and a simple stool complete a bathroom that behaves like another sitting room, a hallmark of the Amankila plan.", "src": "images/Amankila/0515 - Amankila - Suite Bathroom - bathtub with ocean view.jpg", "source": "https://www.aman.com/resorts/amankila/gallery", "dimensions": "1067x1404", "size": 253984}, {"number": "0516", "file": "0516 - Amankila - The Bar - bar counter with wooden ceiling and ocean view windows.jpg", "resort": "Amankila", "space": "The Bar", "description": "The Bar at Amankila: a long timber counter with backlit bottle shelving, fronted by woven rattan bar stools, inside a high pavilion with a woven bamboo ceiling and full width windows to the sea. Warm downlighting pools on the counter. The room demonstrates the resort's material discipline: teak, rattan, bamboo and stone, with brass only in the lighting.", "src": "images/Amankila/0516 - Amankila - The Bar - bar counter with wooden ceiling and ocean view windows.jpg", "source": "https://www.aman.com/resorts/amankila/dining", "dimensions": "1946x2560", "size": 1381826}, {"number": "0517", "file": "0517 - Amankila - The Terrace Restaurant - round dining table with cream linens and classical columns.jpg", "resort": "Amankila", "space": "The Terrace Restaurant", "description": "A set table at The Terrace restaurant: round table in cream linen with a floral centrepiece, surrounded by rattan and timber dining chairs between classical stone columns. The open sided pavilion looks over the gardens to the coast. Tableware is plain white and silver, letting the columned architecture and view carry the formality.", "src": "images/Amankila/0517 - Amankila - The Terrace Restaurant - round dining table with cream linens and classical columns.jpg", "source": "https://www.aman.com/resorts/amankila/dining", "dimensions": "751x988", "size": 935488}, {"number": "0518", "file": "0518 - Amankila - The Terrace Restaurant - timber lined dining pavilion with open sides.jpg", "resort": "Amankila", "space": "The Terrace Restaurant", "description": "The Terrace restaurant in full: a colonnaded, timber lined dining pavilion with a woven bamboo ceiling, rows of linen dressed tables and rattan chairs, open on all sides to the gardens and the Lombok Strait. Waiters' stations in dark timber punctuate the columns. It is the resort's principal room and the clearest expression of Ed Tuttle's colonial Balinese classicism.", "src": "images/Amankila/0518 - Amankila - The Terrace Restaurant - timber lined dining pavilion with open sides.jpg", "source": "https://www.aman.com/resorts/amankila/dining", "dimensions": "1600x988", "size": 1835720}, {"number": "0519", "file": "0519 - Amandari - Amandari Suite - thatched pavilion reflected in still pool at dusk.jpg", "resort": "Amandari", "space": "Amandari Suite", "description": "The Amandari Suite at dusk: a freestanding thatched pavilion in the Peter Muller village manner, its warm interior light reflected in the private infinity pool. Paras stone walls enclose the garden. The suite pairs this pavilion with a separate living bale, and the image shows why the type endures: one perfect roof form, doubled by water.", "src": "images/Amandari/0519 - Amandari - Amandari Suite - thatched pavilion reflected in still pool at dusk.jpg", "source": "https://www.aman.com/resorts/amandari/accommodation", "dimensions": "1000x1000", "size": 844263}, {"number": "0520", "file": "0520 - Amandari - Asmara Suite - plunge pool and tropical garden pavilion.jpg", "resort": "Amandari", "space": "Asmara Suite", "description": "Asmara Suite garden with its private plunge pool in emerald tile, turquoise loungers on the stone deck and the thatched suite pavilion rising behind palms. The pool is small and jewel like, sized for two. Interiors use the resort wide palette of coconut wood, teak and marble, visible in the pavilion's dark timber framing.", "src": "images/Amandari/0520 - Amandari - Asmara Suite - plunge pool and tropical garden pavilion.jpg", "source": "https://www.aman.com/resorts/amandari/accommodation", "dimensions": "2000x1234", "size": 2840887}, {"number": "0521", "file": "0521 - Amandari - Ayung Pool Duplex Villa - emerald tiled pool and traditional pavilion.jpg", "resort": "Amandari", "space": "Ayung Pool Duplex Villa", "description": "Ayung Pool Duplex Villa: a long emerald tiled swimming pool runs before a two storey thatched pavilion, with loungers and a parasol on the terrace. The duplex plan stacks the bedroom above the living space, both opening to the pool garden. Dark timber, paras stone and dense planting give the villa a secluded, house like feel.", "src": "images/Amandari/0521 - Amandari - Ayung Pool Duplex Villa - emerald tiled pool and traditional pavilion.jpg", "source": "https://www.aman.com/resorts/amandari/accommodation", "dimensions": "1946x2560", "size": 807961}, {"number": "0522", "file": "0522 - Amandari - Ayung Suite - plunge pool overlooking rice terraces.jpg", "resort": "Amandari", "space": "Ayung Suite", "description": "Ayung Suite plunge pool terrace, a rectangular pool set in stone paving with the thatched pavilion behind and rice terraces falling away beyond the garden wall. Two loungers and a small bale furnish the deck. The composition is the Amandari standard: paras stone enclosure, water, thatch and a borrowed landscape view.", "src": "images/Amandari/0522 - Amandari - Ayung Suite - plunge pool overlooking rice terraces.jpg", "source": "https://www.aman.com/resorts/amandari/accommodation", "dimensions": "2000x1234", "size": 2807830}, {"number": "0523", "file": "0523 - Amandari - Duplex Pool Suite - living area with wooden pavilion and daybed.jpg", "resort": "Amandari", "space": "Duplex Pool Suite", "description": "Duplex Pool Suite living pavilion: a glass walled, timber framed room opening on three sides to the garden, furnished with a deep cushioned sofa and daybed in cream upholstery, a low coffee table and woven ceiling above. Sliding glass panels let the room behave as either interior or veranda. Coconut wood and teak accents continue the village material palette.", "src": "images/Amandari/0523 - Amandari - Duplex Pool Suite - living area with wooden pavilion and daybed.jpg", "source": "https://www.aman.com/resorts/amandari/accommodation", "dimensions": "1600x988", "size": 2239028}, {"number": "0524", "file": "0524 - Amandari - Duplex Pool Suite - lounge pavilion with built in daybed seating.jpg", "resort": "Amandari", "space": "Duplex Pool Suite", "description": "Second view of the Duplex Pool Suite pavilion, centred on a built in daybed platform with bolster cushions beneath the high thatched ceiling. Timber posts and full height glazing frame the garden on every side. The built in furniture approach, where seating is part of the architecture, is the detail to copy from Amandari's suites.", "src": "images/Amandari/0524 - Amandari - Duplex Pool Suite - lounge pavilion with built in daybed seating.jpg", "source": "https://www.aman.com/resorts/amandari/accommodation", "dimensions": "1067x1067", "size": 1318766}, {"number": "0525", "file": "0525 - Amandari - One-Bedroom Villa - interior with open air pavilion and teak furnishings.jpg", "resort": "Amandari", "space": "One-Bedroom Villa", "description": "One-Bedroom Villa interior combining dining and sitting space in one open pavilion: a round dining table with woven rattan chairs, a daybed and armchairs beyond, all in teak and coconut wood under a woven bamboo ceiling. Glass doors fold away to the garden and pool. The villa shows Amandari's duplex idea at its most domestic, a small house rather than a hotel room.", "src": "images/Amandari/0525 - Amandari - One-Bedroom Villa - interior with open air pavilion and teak furnishings.jpg", "source": "https://www.aman.com/resorts/amandari/accommodation", "dimensions": "900x900", "size": 252046}, {"number": "0526", "file": "0526 - Amandari - Pool Suite - terrace with thatched pavilion and infinity pool.jpg", "resort": "Amandari", "space": "Pool Suite", "description": "Pool Suite terrace with the suite's thatched pavilion, a private infinity pool and two turquoise loungers angled to the view over Ubud's greenery. A parasol bale shades the deck corner. The exterior furniture is kept deliberately simple so the roof form and the pool edge remain the design events.", "src": "images/Amandari/0526 - Amandari - Pool Suite - terrace with thatched pavilion and infinity pool.jpg", "source": "https://www.aman.com/resorts/amandari/accommodation", "dimensions": "889x889", "size": 341468}, {"number": "0527", "file": "0527 - Amandari - Private Dining - stone archway entrance to dining pavilion.jpg", "resort": "Amandari", "space": "Private Dining", "description": "Entrance to Amandari's private dining setting: a moss softened paras stone archway and gateway in the village wall, with a stone lantern beside the path. The gateway itself is the design content here, showing how the resort uses carved stone thresholds, planted walls and lanterns to make arrival at even a dinner feel ceremonial.", "src": "images/Amandari/0527 - Amandari - Private Dining - stone archway entrance to dining pavilion.jpg", "source": "https://www.aman.com/resorts/amandari/dining", "dimensions": "1946x2560", "size": 771623}, {"number": "0528", "file": "0528 - Amandari - Spa - thatched spa pavilion among tropical foliage.jpg", "resort": "Amandari", "space": "Spa", "description": "Amandari's spa pavilion, a small thatched bale almost hidden in dense tropical planting, where treatments are given in the open air. The image records the spa's essential furnishing idea: a massage bed, a therapist's stool and complete enclosure by greenery, with the building reduced to a roof alone.", "src": "images/Amandari/0528 - Amandari - Spa - thatched spa pavilion among tropical foliage.jpg", "source": "https://www.aman.com/resorts/amandari/wellness", "dimensions": "1946x2560", "size": 1315990}, {"number": "0529", "file": "0529 - Amandari - Suite - bedroom with thatched roof and wooden platform bed.jpg", "resort": "Amandari", "space": "Suite", "description": "Suite bedroom under a soaring thatched roof: a low wooden platform bed with white linen sits on polished stone floors, with marble clad walls, a writing desk and armchairs at the edges, and glass doors to the garden on three sides. Batik and woven textiles appear as accents only. It is the purest statement of the Amandari interior: stone, teak, coconut wood and space.", "src": "images/Amandari/0529 - Amandari - Suite - bedroom with thatched roof and wooden platform bed.jpg", "source": "https://www.aman.com/resorts/amandari/gallery", "dimensions": "1440x889", "size": 599676}, {"number": "0530", "file": "0530 - Amandari - The Restaurant - dining pavilion with wooden table overlooking the valley.jpg", "resort": "Amandari", "space": "The Restaurant", "description": "The Restaurant at Amandari: an open pavilion with a high thatched roof where dark wooden tables and chairs are set along the edge for views over the Ayung valley. Table settings are minimal, white linen, glass and a single flower. The room's luxury is its section: a tall roof, a low balustrade and the gorge beyond.", "src": "images/Amandari/0530 - Amandari - The Restaurant - dining pavilion with wooden table overlooking the valley.jpg", "source": "https://www.aman.com/resorts/amandari/dining", "dimensions": "1067x1404", "size": 1987429}, {"number": "0531", "file": "0531 - Amandari - The Restaurant - thatched dining bale in tropical gardens.jpg", "resort": "Amandari", "space": "The Restaurant", "description": "A thatched dining bale in the restaurant gardens, a small open pavilion with a set table surrounded by palms and dense planting. Amandari uses these bales for private and in garden dining. The furnishing is a single table and chairs in dark timber, with the garden itself acting as walls.", "src": "images/Amandari/0531 - Amandari - The Restaurant - thatched dining bale in tropical gardens.jpg", "source": "https://www.aman.com/resorts/amandari/dining", "dimensions": "1080x1350", "size": 452280}, {"number": "0532", "file": "0532 - Amandari - Valley Suite - dining area with wooden beamed ceiling and valley views.jpg", "resort": "Amandari", "space": "Valley Suite", "description": "Valley Suite dining area: a round table and rattan chairs set in the suite's open pavilion under a beamed, woven ceiling, with the bedroom visible behind and valley views through the glass. The suite layers dining, sitting and sleeping in one flowing pavilion divided only by furniture groupings, a plan worth studying for small luxury villas.", "src": "images/Amandari/0532 - Amandari - Valley Suite - dining area with wooden beamed ceiling and valley views.jpg", "source": "https://www.aman.com/resorts/amandari/accommodation", "dimensions": "1000x1000", "size": 1308437}, {"number": "0533", "file": "0533 - Amandari - Valley Suite - wooden pavilion with dining area and bedroom.jpg", "resort": "Amandari", "space": "Valley Suite", "description": "Wide view of a Valley Suite showing the full pavilion: dining table in the foreground, sitting area with armchairs, and the king bed at the far end beneath the high thatched ceiling, all opening to the garden through sliding glass. Paras stone walls guarantee privacy. Coconut wood, teak and marble run throughout, with batik cushions as the single patterned note.", "src": "images/Amandari/0533 - Amandari - Valley Suite - wooden pavilion with dining area and bedroom.jpg", "source": "https://www.aman.com/resorts/amandari/accommodation", "dimensions": "2000x1234", "size": 2900688}, {"number": "0534", "file": "0534 - COMO Shambhala Estate - Bayugita Residence - bathroom with freestanding oval tub.jpg", "resort": "COMO Shambhala Estate", "space": "Bayugita Residence", "description": "Bayugita Residence bathroom: a large oval freestanding tub before floor to ceiling glass onto a private garden, a long double vanity in dark timber and stone, and a glass shower enclosure. Polished stone floors and chrome fittings give it a more contemporary finish than the estate's bedrooms. The garden outlook turns the bathroom into a pavilion of its own.", "src": "images/COMO Shambhala Estate/0534 - COMO Shambhala Estate - Bayugita Residence - bathroom with freestanding oval tub.jpg", "source": "https://www.comohotels.com/bali/como-shambhala-estate/accommodation/bayugita", "dimensions": "2560x1707", "size": 592410}, {"number": "0535", "file": "0535 - COMO Shambhala Estate - Bayugita Residence - bedroom with draped canopy bed.jpg", "resort": "COMO Shambhala Estate", "space": "Bayugita Residence", "description": "Bayugita Residence bedroom: a four poster bed with sheer white drapes in a dark timber pavilion room, with a carved wooden chest at its foot, armchairs and polished hardwood floors reflecting warm light. Bayugita, meaning song of the wind, is built as a traditional Javanese residence, and its interiors keep that antique gravitas with very little added decoration.", "src": "images/COMO Shambhala Estate/0535 - COMO Shambhala Estate - Bayugita Residence - bedroom with draped canopy bed.jpg", "source": "https://www.comohotels.com/bali/como-shambhala-estate/accommodation/bayugita", "dimensions": "2560x1707", "size": 618455}, {"number": "0536", "file": "0536 - COMO Shambhala Estate - Bayugita Residence - living space with sofas under timber pavilion.jpg", "resort": "COMO Shambhala Estate", "space": "Bayugita Residence", "description": "Bayugita living pavilion: two cream sofas with indigo cushions around a heavy timber coffee table, under a high pitched roof on carved columns, open to the jungle valley on two sides. A dining area sits beyond. The furniture is low, deep and upholstered for long stays, a more residential register than the estate's suites.", "src": "images/COMO Shambhala Estate/0536 - COMO Shambhala Estate - Bayugita Residence - living space with sofas under timber pavilion.jpg", "source": "https://www.comohotels.com/bali/como-shambhala-estate/accommodation/bayugita", "dimensions": "2560x1707", "size": 778143}, {"number": "0537", "file": "0537 - COMO Shambhala Estate - COMO Shambhala Spa - massage treatment.jpg", "resort": "COMO Shambhala Estate", "space": "COMO Shambhala Spa", "description": "COMO Shambhala Spa treatment in progress, a close view of a massage in a shaded treatment pavilion. The estate's spa rooms are timber pavilions scattered through the jungle, several with their own vitality pools. This official image records the treatment itself; the spa's built interiors are represented in the collection by the residences' bathing spaces.", "src": "images/COMO Shambhala Estate/0537 - COMO Shambhala Estate - COMO Shambhala Spa - massage treatment.jpg", "source": "https://www.comohotels.com/bali/como-shambhala-estate/wellness", "dimensions": "1052x1224", "size": 124777}, {"number": "0538", "file": "0538 - COMO Shambhala Estate - COMO Shambhala Suite - outdoor shower deck with bamboo towel ladder.jpg", "resort": "COMO Shambhala Estate", "space": "COMO Shambhala Suite", "description": "COMO Shambhala Suite outdoor shower: a rainfall shower mounted on a stone wall pours onto a dark timber deck, with a bamboo ladder holding white towels and a sculpted wooden stool carrying toiletries. The treetop setting above the Ayung gorge makes the shower feel suspended in the canopy. Natural stone, bamboo and dark timber are the whole palette.", "src": "images/COMO Shambhala Estate/0538 - COMO Shambhala Estate - COMO Shambhala Suite - outdoor shower deck with bamboo towel ladder.jpg", "source": "https://www.comohotels.com/bali/como-shambhala-estate/accommodation/suites", "dimensions": "2240x1180", "size": 445150}, {"number": "0539", "file": "0539 - COMO Shambhala Estate - COMO Shambhala Suite - private pool with rock Jacuzzi and loungers.jpg", "resort": "COMO Shambhala Estate", "space": "COMO Shambhala Suite", "description": "The COMO Shambhala Suite's private pool at dusk: a naturalistic pool with a Jacuzzi carved into a great boulder, bamboo spout, stone decking with two loungers and a shaded bale, candles lit along the edge. It is less a swimming pool than a bathing landscape, and the most evocative outdoor space in the COMO set.", "src": "images/COMO Shambhala Estate/0539 - COMO Shambhala Estate - COMO Shambhala Suite - private pool with rock Jacuzzi and loungers.jpg", "source": "https://www.comohotels.com/bali/como-shambhala-estate/accommodation/suites", "dimensions": "2240x1180", "size": 502400}, {"number": "0540", "file": "0540 - COMO Shambhala Estate - COMO Suite at Umabona Residence - canopy bedroom with stone wall.jpg", "resort": "COMO Shambhala Estate", "space": "COMO Suite at Umabona Residence", "description": "COMO Suite at Umabona: a canopy bed with white drapes and an orange silk bedcover, brass table lamp, dark polished floors and carved timber panelling, with an antique cabinet against the wall. Umabona is the estate's royal residence, and this suite has its richest interior: antique furniture, silk and brass against the jungle green outside.", "src": "images/COMO Shambhala Estate/0540 - COMO Shambhala Estate - COMO Suite at Umabona Residence - canopy bedroom with stone wall.jpg", "source": "https://www.comohotels.com/bali/como-shambhala-estate/accommodation/suites", "dimensions": "2240x1180", "size": 330500}, {"number": "0541", "file": "0541 - COMO Shambhala Estate - One-Bedroom Pool Villa - bathroom and dressing room with twin vanities.jpg", "resort": "COMO Shambhala Estate", "space": "One-Bedroom Pool Villa", "description": "One-Bedroom Pool Villa bathroom and dressing room: a long room with twin vanities in dark timber, a central upholstered ottoman, full height mirrors and garden doors at the far end. The dressing room scale, closer to a boutique than a bathroom, is characteristic of the estate's villas. Stone, timber and cream upholstery keep it serene.", "src": "images/COMO Shambhala Estate/0541 - COMO Shambhala Estate - One-Bedroom Pool Villa - bathroom and dressing room with twin vanities.jpg", "source": "https://www.comohotels.com/bali/como-shambhala-estate/accommodation/villas", "dimensions": "2240x1180", "size": 389562}, {"number": "0542", "file": "0542 - COMO Shambhala Estate - One-Bedroom Pool Villa - bedroom with king bed and balcony doors.jpg", "resort": "COMO Shambhala Estate", "space": "One-Bedroom Pool Villa", "description": "One-Bedroom Pool Villa bedroom: a white dressed king bed centred on a carved dark timber wall panel, polished pale floors, and glass doors on both sides opening to the terrace and pool. The symmetrical composition and the carved panel as headboard wall give the room its formal calm.", "src": "images/COMO Shambhala Estate/0542 - COMO Shambhala Estate - One-Bedroom Pool Villa - bedroom with king bed and balcony doors.jpg", "source": "https://www.comohotels.com/bali/como-shambhala-estate/accommodation/villas", "dimensions": "2240x1180", "size": 446456}, {"number": "0543", "file": "0543 - COMO Shambhala Estate - One-Bedroom Pool Villa - living room with long sofas and patterned rug.jpg", "resort": "COMO Shambhala Estate", "space": "One-Bedroom Pool Villa", "description": "One-Bedroom Pool Villa living room: two long cream sofas facing each other across a low central ottoman on a deep red patterned rug, with the pool terrace visible through full height glass. Books and ceramics style the shelves. The twin sofa arrangement makes the room a conversation space rather than a television room, in keeping with the estate's retreat purpose.", "src": "images/COMO Shambhala Estate/0543 - COMO Shambhala Estate - One-Bedroom Pool Villa - living room with long sofas and patterned rug.jpg", "source": "https://www.comohotels.com/bali/como-shambhala-estate/accommodation/villas", "dimensions": "2240x1180", "size": 518638}, {"number": "0544", "file": "0544 - COMO Shambhala Estate - Tejasuara Residence - garden bale with daybed and outdoor Jacuzzi.jpg", "resort": "COMO Shambhala Estate", "space": "Tejasuara Residence", "description": "Tejasuara Residence garden: a thatched bale with a daybed on a timber deck, a sun lounger beside it and a white outdoor Jacuzzi set into the lawn among dense planting. Tejasuara's rooms are lighter in spirit, and its garden bathing corner shows the estate's habit of scattering small luxuries through the grounds.", "src": "images/COMO Shambhala Estate/0544 - COMO Shambhala Estate - Tejasuara Residence - garden bale with daybed and outdoor Jacuzzi.jpg", "source": "https://www.comohotels.com/bali/como-shambhala-estate/accommodation/tejasuara", "dimensions": "2240x1180", "size": 624555}, {"number": "0545", "file": "0545 - COMO Shambhala Estate - Terrace Suite - canopy bedroom with floral bedcover.jpg", "resort": "COMO Shambhala Estate", "space": "Terrace Suite", "description": "Terrace Suite bedroom: a canopy bed with a floral patterned bedcover and batik cushions, armchairs by the window and garden doors to the terrace. The Terrace Suites are the estate's entry rooms, in the main residence buildings, and their interiors are the most hotel like in this set: still timber and textile led, but more compact.", "src": "images/COMO Shambhala Estate/0545 - COMO Shambhala Estate - Terrace Suite - canopy bedroom with floral bedcover.jpg", "source": "https://www.comohotels.com/bali/como-shambhala-estate/accommodation/suites", "dimensions": "2240x1180", "size": 410163}, {"number": "0546", "file": "0546 - COMO Shambhala Estate - Three-Bedroom Pool Villa - bedroom with tapestry wall panel and upholstered bench.jpg", "resort": "COMO Shambhala Estate", "space": "Three-Bedroom Pool Villa", "description": "Three-Bedroom Pool Villa bedroom: a king bed with an upholstered bench at its foot, a large woven tapestry panel hung as the headboard wall, batik cushions and glass doors to the pool terrace. The tapestry does the decorative work of the room, a textile first approach that runs through the estate.", "src": "images/COMO Shambhala Estate/0546 - COMO Shambhala Estate - Three-Bedroom Pool Villa - bedroom with tapestry wall panel and upholstered bench.jpg", "source": "https://www.comohotels.com/bali/como-shambhala-estate/accommodation/villas", "dimensions": "2240x1180", "size": 386021}, {"number": "0547", "file": "0547 - COMO Shambhala Estate - Three-Bedroom Pool Villa - open living pavilion with white sofas.jpg", "resort": "COMO Shambhala Estate", "space": "Three-Bedroom Pool Villa", "description": "Three-Bedroom Pool Villa living pavilion: white sofas and armchairs around a dark timber coffee table in an open sided pavilion, the private pool and loungers immediately beyond. Indoor and outdoor furniture share the same forms, so the pavilion reads as one continuous living space from sofa to pool edge.", "src": "images/COMO Shambhala Estate/0547 - COMO Shambhala Estate - Three-Bedroom Pool Villa - open living pavilion with white sofas.jpg", "source": "https://www.comohotels.com/bali/como-shambhala-estate/accommodation/villas", "dimensions": "2240x1180", "size": 472134}, {"number": "0548", "file": "0548 - COMO Shambhala Estate - Tirta Ening Residence - bathroom with sunken tub and carved doorway.jpg", "resort": "COMO Shambhala Estate", "space": "Tirta Ening Residence", "description": "Tirta Ening Residence bathroom: a sunken rectangular tub in warm stone, reached through a carved timber doorway flanked by hanging lanterns, with a stone vanity and garden light beyond. Tirta Ening means clear water, and the bathroom is its ceremonial core. The carved doorway is among the finest single details in the COMO set.", "src": "images/COMO Shambhala Estate/0548 - COMO Shambhala Estate - Tirta Ening Residence - bathroom with sunken tub and carved doorway.jpg", "source": "https://www.comohotels.com/bali/como-shambhala-estate/accommodation/tirta-ening", "dimensions": "2240x1180", "size": 421936}, {"number": "0549", "file": "0549 - COMO Shambhala Estate - Wanakasa Residence - bedroom suite with canopy bed and lounge seating.jpg", "resort": "COMO Shambhala Estate", "space": "Wanakasa Residence", "description": "Wanakasa Residence bedroom suite: a canopy bed with sheer drapes, a lounge area with a long sofa and ottoman in the same volume, dark timber floors and wraparound garden views. Wanakasa, forest in the mist, sits high in the estate's trees, and the suite's combined sleeping and sitting plan suits its retreat within a retreat character.", "src": "images/COMO Shambhala Estate/0549 - COMO Shambhala Estate - Wanakasa Residence - bedroom suite with canopy bed and lounge seating.jpg", "source": "https://www.comohotels.com/bali/como-shambhala-estate/accommodation/wanakasa", "dimensions": "2240x1180", "size": 289127}, {"number": "0550", "file": "0550 - COMO Shambhala Estate - Wanakasa Residence - dining pavilion with lantern pendants.jpg", "resort": "COMO Shambhala Estate", "space": "Wanakasa Residence", "description": "Wanakasa dining pavilion: a long timber pavilion on carved columns with a dining table beneath hanging lantern pendants, open to the palm canopy and the river gorge. The lanterns, grouped like a small chandelier, are the decorative focus. Dining here is fully outdoors in feeling while remaining a formal room.", "src": "images/COMO Shambhala Estate/0550 - COMO Shambhala Estate - Wanakasa Residence - dining pavilion with lantern pendants.jpg", "source": "https://www.comohotels.com/bali/como-shambhala-estate/accommodation/wanakasa", "dimensions": "2240x1180", "size": 537126}, {"number": "0551", "file": "0551 - COMO Shambhala Estate - Wanakasa Residence - open living pavilion with columns and sofas.jpg", "resort": "COMO Shambhala Estate", "space": "Wanakasa Residence", "description": "Wanakasa living pavilion: cream sofas and armchairs arranged around low tables between massive timber columns, open on all sides to the jungle. The column scale gives the room a temple like gravity unusual in a residence. Upholstery is plain cream and taupe so the structure and the green view dominate.", "src": "images/COMO Shambhala Estate/0551 - COMO Shambhala Estate - Wanakasa Residence - open living pavilion with columns and sofas.jpg", "source": "https://www.comohotels.com/bali/como-shambhala-estate/accommodation/wanakasa", "dimensions": "2240x1180", "size": 344948}, {"number": "0552", "file": "0552 - Amanjiwo - Borobudur Pavilion - bedroom with stone columns and temple views.jpg", "resort": "Amanjiwo", "space": "Borobudur Pavilion", "description": "Borobudur Pavilion bedroom: a king bed in white linen centred between two stone columns, with a carved headboard wall behind and low timber side tables. Coral limestone floors and walls keep the room cool and pale, while batik cushions and a woven throw add the only colour. The pavilion aligns its terrace and plunge pool to Borobudur on the horizon.", "src": "images/Amanjiwo/0552 - Amanjiwo - Borobudur Pavilion - bedroom with stone columns and temple views.jpg", "source": "https://www.aman.com/resorts/amanjiwo/accommodation", "dimensions": "2000x1234", "size": 531501}, {"number": "0553", "file": "0553 - Amanjiwo - Borobudur Pool Pavilion - pool pavilion overlooking reflecting pool with wooden loungers.jpg", "resort": "Amanjiwo", "space": "Borobudur Pool Pavilion", "description": "Borobudur Pool Pavilion terrace: a thatched bale stands over a long reflecting plunge pool, with two wooden loungers at the water's edge and the Menoreh hills beyond. The pool reads as a still mirror rather than a swimming pool, in keeping with the resort's temple quiet. Stone coping and dark timber furniture keep the palette grave and calm.", "src": "images/Amanjiwo/0553 - Amanjiwo - Borobudur Pool Pavilion - pool pavilion overlooking reflecting pool with wooden loungers.jpg", "source": "https://www.aman.com/resorts/amanjiwo/accommodation", "dimensions": "2560x1580", "size": 747656}, {"number": "0554", "file": "0554 - Amanjiwo - Dalem Jiwo Suite - central pavilion and reflecting pool with forested hills.jpg", "resort": "Amanjiwo", "space": "Dalem Jiwo Suite", "description": "Dalem Jiwo Suite, the resort's principal residence, arranged as four pavilions around a central rotunda and a long reflecting pool, with twin bales and loungers along the water. The suite's composition is a small palace court in limestone and thatch. Interiors add a wraparound terrace, private dining for twelve and antique Javanese furniture to the standard Amanjiwo vocabulary.", "src": "images/Amanjiwo/0554 - Amanjiwo - Dalem Jiwo Suite - central pavilion and reflecting pool with forested hills.jpg", "source": "https://www.aman.com/resorts/amanjiwo/accommodation", "dimensions": "1000x1000", "size": 427065}, {"number": "0555", "file": "0555 - Amanjiwo - Garden Pavilion - garden pavilion with thatched roof and wooden seating.jpg", "resort": "Amanjiwo", "space": "Garden Pavilion", "description": "Garden Pavilion bale: a conical thatched roof on four posts shelters wooden armchairs and a daybed at the pool's edge, facing the hills. The bale is the resort's recurring outdoor room, used for afternoon tea, reading and treatments. Its furniture is deliberately rustic in finish against the precision of the main stone buildings.", "src": "images/Amanjiwo/0555 - Amanjiwo - Garden Pavilion - garden pavilion with thatched roof and wooden seating.jpg", "source": "https://www.aman.com/resorts/amanjiwo/accommodation", "dimensions": "1000x1000", "size": 348500}, {"number": "0556", "file": "0556 - Amanjiwo - Menoreh Pool Pavilion - thatched roof pavilion and still plunge pool.jpg", "resort": "Amanjiwo", "space": "Menoreh Pool Pavilion", "description": "Menoreh Pool Pavilion with its private plunge pool and thatched bale, seen across still water with rice fields and palm groves beyond. The pavilion pairs a marble interior with this outdoor room. Note how the pool is set flush in a stone terrace so the bale appears to float at the garden's edge.", "src": "images/Amanjiwo/0556 - Amanjiwo - Menoreh Pool Pavilion - thatched roof pavilion and still plunge pool.jpg", "source": "https://www.aman.com/resorts/amanjiwo/accommodation", "dimensions": "900x900", "size": 297423}, {"number": "0557", "file": "0557 - Amanjiwo - Pavilion Bale - thatched pavilion with seating overlooking valley landscape.jpg", "resort": "Amanjiwo", "space": "Pavilion Bale", "description": "A pavilion bale furnished with two wooden armchairs, a daybed and a low table, positioned for the valley and volcano view. This is Amanjiwo's simplest interior: four posts, a steep thatch roof, three pieces of teak furniture and a landscape. The restraint is the design statement, and it recurs at every pavilion grade.", "src": "images/Amanjiwo/0557 - Amanjiwo - Pavilion Bale - thatched pavilion with seating overlooking valley landscape.jpg", "source": "https://www.aman.com/resorts/amanjiwo/gallery", "dimensions": "1000x1000", "size": 842543}, {"number": "0558", "file": "0558 - Amanjiwo - Pool Club - dining table set beside the pool with flower arrangement.jpg", "resort": "Amanjiwo", "space": "Pool Club", "description": "Pool Club table setting in close view: a polished timber table set with white porcelain, glassware and a bird of paradise arrangement, with the pool surface immediately behind. The Pool Club serves light meals beside the 40 metre pool in a grove of frangipani. The image captures the resort's table dressing at its most minimal and precise.", "src": "images/Amanjiwo/0558 - Amanjiwo - Pool Club - dining table set beside the pool with flower arrangement.jpg", "source": "https://www.aman.com/resorts/amanjiwo/dining", "dimensions": "760x1000", "size": 475744}, {"number": "0559", "file": "0559 - Amanjiwo - Pool Pavilion - two wooden chairs facing plunge pool and distant temples.jpg", "resort": "Amanjiwo", "space": "Pool Pavilion", "description": "Pool Pavilion terrace reduced to essentials: two wooden chairs and a small table facing a private plunge pool, gardens and the distant temple line. A stone lantern marks the steps. The photograph shows Amanjiwo's belief that a view, correctly framed by two chairs, is a complete room.", "src": "images/Amanjiwo/0559 - Amanjiwo - Pool Pavilion - two wooden chairs facing plunge pool and distant temples.jpg", "source": "https://www.aman.com/resorts/amanjiwo/gallery", "dimensions": "760x1000", "size": 730251}, {"number": "0560", "file": "0560 - Amanjiwo - Restaurant - circular dining table beneath golden abstract artwork.jpg", "resort": "Amanjiwo", "space": "Restaurant", "description": "The Restaurant at Amanjiwo: a circular table with woven rattan chairs set before a huge gilded relief artwork that wraps the columned dining room. The gold panel is the room's single decorative gesture, glowing against limestone columns and dark floors. Tables are dressed in white with silver and glass, formal against the temple landscape outside.", "src": "images/Amanjiwo/0560 - Amanjiwo - Restaurant - circular dining table beneath golden abstract artwork.jpg", "source": "https://www.aman.com/resorts/amanjiwo/dining", "dimensions": "760x1000", "size": 826918}, {"number": "0561", "file": "0561 - Amanjiwo - Restaurant Terrace - illuminated terrace at dusk with dining seating.jpg", "resort": "Amanjiwo", "space": "Restaurant Terrace", "description": "The Restaurant Terrace at dusk: a curving, colonnaded stone terrace following the resort's circular plan, lit by rows of candles and lanterns, with dining tables and a central stage for gamelan and dance. The curve of columns echoes Borobudur's terraces. It is the resort's great ceremonial space and the clearest link between its architecture and the monument.", "src": "images/Amanjiwo/0561 - Amanjiwo - Restaurant Terrace - illuminated terrace at dusk with dining seating.jpg", "source": "https://www.aman.com/resorts/amanjiwo/dining", "dimensions": "1000x1000", "size": 390080}, {"number": "0562", "file": "0562 - Amanjiwo - Rotunda - circular colonnaded pavilion with central daybed platform.jpg", "resort": "Amanjiwo", "space": "Rotunda", "description": "The Rotunda, Amanjiwo's central pavilion: a circular colonnade with a domed ceiling, its floor arranged as a great raised daybed platform with cushions, low tables and armchairs, used for drinks, library hours and cultural talks. Limestone columns and a patterned stone floor carry the temple reference. It functions as the resort's living room and its architectural thesis in one space.", "src": "images/Amanjiwo/0562 - Amanjiwo - Rotunda - circular colonnaded pavilion with central daybed platform.jpg", "source": "https://www.aman.com/resorts/amanjiwo/gallery", "dimensions": "2000x1251", "size": 656740}, {"number": "0563", "file": "0563 - Amanjiwo - Spa - spa pavilion with plunge pool and loungers.jpg", "resort": "Amanjiwo", "space": "Spa", "description": "The Spa pavilion: a serene limestone building fronted by a private plunge pool with two black loungers, housing treatment rooms including the Royal Astawana Bath ritual space. Stone, water and stillness define the design. The pavilion shows how Amanjiwo extends its temple architecture to wellness without changing materials.", "src": "images/Amanjiwo/0563 - Amanjiwo - Spa - spa pavilion with plunge pool and loungers.jpg", "source": "https://www.aman.com/resorts/amanjiwo/gallery", "dimensions": "2000x1251", "size": 780543}, {"number": "0564", "file": "0564 - Amanjiwo - Spa - treatment room with draped fabric ceiling and wooden pillars.jpg", "resort": "Amanjiwo", "space": "Spa", "description": "Spa treatment room with a massage bed draped in patterned batik, beneath a tented ceiling of sheer fabric hung from timber pillars. Warm wood panelling and a low side table with flowers complete the room. The draped ceiling softens the stone architecture into something intimate, a contrast the resort uses repeatedly in private spaces.", "src": "images/Amanjiwo/0564 - Amanjiwo - Spa - treatment room with draped fabric ceiling and wooden pillars.jpg", "source": "https://www.aman.com/resorts/amanjiwo/gallery", "dimensions": "2000x1251", "size": 642613}, {"number": "0565", "file": "0565 - Amanjiwo - Suite - principal bedroom with white bed and stone columns.jpg", "resort": "Amanjiwo", "space": "Suite", "description": "Suite bedroom: a four poster bed in white linen set between limestone columns on a raised coral limestone floor, with batik textiles, framed artwork and a wraparound garden terrace beyond the glass. The bed platform and columns give the room a ceremonial, temple like order. Antique and contemporary Javanese pieces mix in the side furniture.", "src": "images/Amanjiwo/0565 - Amanjiwo - Suite - principal bedroom with white bed and stone columns.jpg", "source": "https://www.aman.com/resorts/amanjiwo/gallery", "dimensions": "1000x1000", "size": 669063}, {"number": "0566", "file": "0566 - Amanjiwo - Suite Bathroom - sunken soaking tub with sculptural stone surround.jpg", "resort": "Amanjiwo", "space": "Suite Bathroom", "description": "Suite bathroom garden court: a sunken rectangular soaking tub carved into a stone terrace, backed by a stone wall hung with a circular bronze gong and planters. Outdoor bathing is a signature Amanjiwo ritual. The sculptural gong turns a functional wall into art, and the whole bathroom is open to the sky.", "src": "images/Amanjiwo/0566 - Amanjiwo - Suite Bathroom - sunken soaking tub with sculptural stone surround.jpg", "source": "https://www.aman.com/resorts/amanjiwo/gallery", "dimensions": "1000x1000", "size": 408296}, {"number": "0567", "file": "0567 - Amanjiwo - Swimming Pool - domed pavilion reflected in still pool framed by columns.jpg", "resort": "Amanjiwo", "space": "Swimming Pool", "description": "The 40 metre swimming pool with the domed Rotunda pavilion reflected in its still surface, stone columns and umbrellas along the edge, a staff member crossing with towels. Frangipani and rice field green surround the water. The pool's mirror finish and the dome's reflection are the resort's most composed architectural photograph and a study in symmetry.", "src": "images/Amanjiwo/0567 - Amanjiwo - Swimming Pool - domed pavilion reflected in still pool framed by columns.jpg", "source": "https://www.aman.com/resorts/amanjiwo/gallery", "dimensions": "1000x1000", "size": 417598}, {"number": "0568", "file": "0568 - NIHI Sumba - Chef's Table at Nio - dining counter and set dining area.jpg", "resort": "NIHI Sumba", "space": "Chef's Table at Nio", "description": "Chef's Table at Nio restaurant: a dark timber chef's counter with leather and wood stools, copper pendant lights above and place settings laid for the interactive dinner. Behind the counter the kitchen works in low warm light. The design is moody and crafted, a contrast to NIHI's bright villa interiors, with the counter itself as the room's single strong piece of furniture.", "src": "images/NIHI Sumba/0568 - NIHI Sumba - Chef's Table at Nio - dining counter and set dining area.jpg", "source": "https://nihi.com/sumba/spa/", "dimensions": "1800x1100", "size": 270328}, {"number": "0569", "file": "0569 - NIHI Sumba - Hillrise Villa - bathroom with ocean view.jpg", "resort": "NIHI Sumba", "space": "Hillrise Villa", "description": "Hillrise Villa bathroom: a long timber vanity carrying two carved stone vessel basins, with rolled towels, wooden accessories and a wall of glass opening to a deck and the surf below. The ceiling is woven bamboo. Natural, unfinished materials do all the work: stone, teak, bamboo and light.", "src": "images/NIHI Sumba/0569 - NIHI Sumba - Hillrise Villa - bathroom with ocean view.jpg", "source": "https://nihi.com/sumba/villa/hillrise/", "dimensions": "1800x1200", "size": 719845}, {"number": "0570", "file": "0570 - NIHI Sumba - Hillrise Villa - bedroom with ocean view.jpg", "resort": "NIHI Sumba", "space": "Hillrise Villa", "description": "Hillrise Villa's combined bedroom and living space: a draped canopy bed at the far end, cream sofas and armchairs in the foreground, ikat cushions and throws in rust and indigo, all under a steep thatched roof with exposed trusses. Full width glass faces the ocean. The room shows NIHI's house style at its most complete: monumental roof, soft white upholstery, tribal textiles.", "src": "images/NIHI Sumba/0570 - NIHI Sumba - Hillrise Villa - bedroom with ocean view.jpg", "source": "https://nihi.com/sumba/villa/hillrise/", "dimensions": "1800x1200", "size": 841574}, {"number": "0571", "file": "0571 - NIHI Sumba - Kanatar Villa - bathroom with stone sink and timber details.jpg", "resort": "NIHI Sumba", "space": "Kanatar Villa", "description": "Kanatar Villa bathroom detail: a rough carved stone basin on a timber stand, with wall mounted taps, a bamboo framed mirror, hanging rattan lanterns and towels on a wooden box. A louvred window filters green light. Every fitting looks handmade, which is the point: NIHI's bathrooms are assembled from craft objects rather than sanitaryware catalogues.", "src": "images/NIHI Sumba/0571 - NIHI Sumba - Kanatar Villa - bathroom with stone sink and timber details.jpg", "source": "https://nihi.com/sumba/villa/kanatar/", "dimensions": "1800x1200", "size": 353572}, {"number": "0572", "file": "0572 - NIHI Sumba - Kanatar Villa - canopy bed in sunlit bedroom with woven textiles.jpg", "resort": "NIHI Sumba", "space": "Kanatar Villa", "description": "Kanatar bedroom: a four poster bed with sheer canopy curtains drawn back, dressed with woven Sumbanese textiles, facing armchairs and a garden terrace through tall doors. Exposed roof trusses and polished floors in dark wood set the tone. Ikat cloth appears on the bed and cushions, tying the room to the island's weaving tradition.", "src": "images/NIHI Sumba/0572 - NIHI Sumba - Kanatar Villa - canopy bed in sunlit bedroom with woven textiles.jpg", "source": "https://nihi.com/sumba/villa/kanatar/", "dimensions": "1800x1200", "size": 525472}, {"number": "0573", "file": "0573 - NIHI Sumba - Kanatar Villa - sunlit indoor lounge with rattan sofa.jpg", "resort": "NIHI Sumba", "space": "Kanatar Villa", "description": "Kanatar Villa's indoor lounge: a long cream sofa and rattan armchairs around a timber coffee table, beneath a dark beamed ceiling, with garden planting visible through every opening. Woven cushions and a carved side table add texture. The lounge is the indoor counterpart to the villa's pool bale, same furniture language, more enclosure.", "src": "images/NIHI Sumba/0573 - NIHI Sumba - Kanatar Villa - sunlit indoor lounge with rattan sofa.jpg", "source": "https://nihi.com/sumba/villa/kanatar/", "dimensions": "1800x1200", "size": 576721}, {"number": "0574", "file": "0574 - NIHI Sumba - Kanatar Villa - villa exterior with private pool and balconies.jpg", "resort": "NIHI Sumba", "space": "Kanatar Villa", "description": "Kanatar Villa from the garden: a two storey thatched residence with wraparound balconies and carved timber rails, standing over its private pool in dense planting. The exterior shows NIHI's architecture clearly, a Sumbanese high roofed house rebuilt at luxury scale, with the pool terrace as its forecourt.", "src": "images/NIHI Sumba/0574 - NIHI Sumba - Kanatar Villa - villa exterior with private pool and balconies.jpg", "source": "https://nihi.com/sumba/villa/kanatar/", "dimensions": "1800x1200", "size": 1155155}, {"number": "0575", "file": "0575 - NIHI Sumba - Kasambi Suite - living room with garden outlook.jpg", "resort": "NIHI Sumba", "space": "Kasambi Suite", "description": "Kasambi Suite living area: a writing desk and chair in dark timber, a sofa with green ikat cushions, a ceramic lamp and a low coffee table with flowers, all facing glazed doors to the garden bale and pool. The suite is one of NIHI's smaller units, and the furnishing keeps everything low and light so the room reads larger.", "src": "images/NIHI Sumba/0575 - NIHI Sumba - Kasambi Suite - living room with garden outlook.jpg", "source": "https://nihi.com/sumba/villa/kasambi-suite/", "dimensions": "1800x1200", "size": 736521}, {"number": "0576", "file": "0576 - NIHI Sumba - Kasambi Suite - open bathroom with stone basins and garden outlook.jpg", "resort": "NIHI Sumba", "space": "Kasambi Suite", "description": "Kasambi Suite bathroom: an open air pavilion bathroom with twin carved stone basins on a timber counter, a stone shower area and garden planting growing through the space, pergola shade overhead. This is bathing as garden architecture, with woven baskets and wooden stools as the only accessories.", "src": "images/NIHI Sumba/0576 - NIHI Sumba - Kasambi Suite - open bathroom with stone basins and garden outlook.jpg", "source": "https://nihi.com/sumba/villa/kasambi-suite/", "dimensions": "1800x1200", "size": 759188}, {"number": "0577", "file": "0577 - NIHI Sumba - Mamole Treehouse - suite interior with canopy king bed.jpg", "resort": "NIHI Sumba", "space": "Mamole Treehouse", "description": "Inside the Mamole Tree House: a round room wrapped around the living tree, with a canopy king bed in white linen and sheer drapes, two armchairs, woven lampshades and bamboo and rattan wall panels. Windows open on every side to the canopy and the sea beyond. The circular plan and the tree trunk as centrepiece make it the most distinctive interior at NIHI.", "src": "images/NIHI Sumba/0577 - NIHI Sumba - Mamole Treehouse - suite interior with canopy king bed.jpg", "source": "https://nihi.com/sumba/villa/treehouse/", "dimensions": "1800x1200", "size": 575010}, {"number": "0578", "file": "0578 - NIHI Sumba - Marangga Villa - thatched roof villa with outdoor lounge.jpg", "resort": "NIHI Sumba", "space": "Marangga Villa", "description": "Marangga Villa: a compact thatched villa with an open outdoor lounge under its great roof, a daybed and chairs facing a small private pool and garden gate to the beach. Marangga is NIHI's couples' hideaway, and its furnishing is correspondingly simple: one daybed, one table, complete privacy.", "src": "images/NIHI Sumba/0578 - NIHI Sumba - Marangga Villa - thatched roof villa with outdoor lounge.jpg", "source": "https://nihi.com/sumba/villa/marangga/", "dimensions": "1800x1200", "size": 1168986}, {"number": "0579", "file": "0579 - NIHI Sumba - Nihioka Spa - open air thatched treatment bale with two massage tables.jpg", "resort": "NIHI Sumba", "space": "Nihioka Spa", "description": "Nihioka Spa at sunset: an open air thatched bale on a clifftop deck with two massage tables dressed in purple cloth, a flower arrangement and the ocean horizon beyond the rail. Guests reach Nihioka by trek or horseback, and treatments are given in these bales. As design it is a roof, a deck and two tables, perfected by position.", "src": "images/NIHI Sumba/0579 - NIHI Sumba - Nihioka Spa - open air thatched treatment bale with two massage tables.jpg", "source": "https://nihi.com/sumba/spa/", "dimensions": "1800x1200", "size": 492623}, {"number": "0580", "file": "0580 - NIHI Sumba - Putri Kasambi Villa - bedroom with canopy king bed and indoor lounge.jpg", "resort": "NIHI Sumba", "space": "Putri Kasambi Villa", "description": "Putri Kasambi bedroom: a canopy king bed with sheer drapes and ikat bed runner, a woven lounge chair and sofa at its foot, ceramic lamps and views through to the bathroom and sea. The villa devotes unusual space to this indoor lounge zone within the bedroom, giving it the feel of a private apartment.", "src": "images/NIHI Sumba/0580 - NIHI Sumba - Putri Kasambi Villa - bedroom with canopy king bed and indoor lounge.jpg", "source": "https://nihi.com/sumba/villa/putri-kasambi/", "dimensions": "1800x1200", "size": 555421}, {"number": "0581", "file": "0581 - NIHI Sumba - Putri Kasambi Villa - ocean view bathroom with flower filled soaking tub.jpg", "resort": "NIHI Sumba", "space": "Putri Kasambi Villa", "description": "Putri Kasambi bathroom: a vast open room with twin carved stone basins on a long timber vanity, a dark stone soaking tub filled with flower petals, woven ceiling and a glass wall to the ocean deck. It is one of the great bathrooms of the collection, closer to a bathing hall than a bathroom, and all in stone, teak and woven fibre.", "src": "images/NIHI Sumba/0581 - NIHI Sumba - Putri Kasambi Villa - ocean view bathroom with flower filled soaking tub.jpg", "source": "https://nihi.com/sumba/villa/putri-kasambi/", "dimensions": "1800x1200", "size": 622140}, {"number": "0582", "file": "0582 - NIHI Sumba - Putri Kasambi Villa - outdoor lounge with light blue cushioned seating.jpg", "resort": "NIHI Sumba", "space": "Putri Kasambi Villa", "description": "Putri Kasambi's outdoor lounge deck: long modular sofas and ottomans in pale blue upholstery, lantern tables and a bar counter behind, under the villa's thatched roof with the pool and sea beyond. The blue palette is a deliberate seaside note against NIHI's usual rust and indigo textiles.", "src": "images/NIHI Sumba/0582 - NIHI Sumba - Putri Kasambi Villa - outdoor lounge with light blue cushioned seating.jpg", "source": "https://nihi.com/sumba/villa/putri-kasambi/", "dimensions": "1800x1200", "size": 654750}, {"number": "0583", "file": "0583 - NIHI Sumba - Raja Puncak Villa - bedroom interior.jpg", "resort": "NIHI Sumba", "space": "Raja Puncak Villa", "description": "Raja Puncak bedroom: the estate's largest villa bedroom, with a draped canopy bed, a cream chaise and sofa grouping at its foot, marble and timber floors and house staff crossing in the background, which gives the room its scale. High pitched ceilings and full height openings keep the grand volume airy. Sumbanese artefacts and ikat textiles carry the decoration.", "src": "images/NIHI Sumba/0583 - NIHI Sumba - Raja Puncak Villa - bedroom interior.jpg", "source": "https://nihi.com/sumba/villa/raja-puncak/", "dimensions": "1800x1200", "size": 616823}, {"number": "0584", "file": "0584 - NIHI Sumba - Raja Puncak Villa - living room with ocean outlook.jpg", "resort": "NIHI Sumba", "space": "Raja Puncak Villa", "description": "Raja Puncak living room: a double height thatched hall with cream sofas arranged around a timber coffee table dressed with fruit and books, ceramic table lamps, a woven pendant overhead and a media wall at the far end. Stairs rise to the upper rooms. It is the most conventionally luxurious living room at NIHI, scaled for a family estate rather than a suite.", "src": "images/NIHI Sumba/0584 - NIHI Sumba - Raja Puncak Villa - living room with ocean outlook.jpg", "source": "https://nihi.com/sumba/villa/raja-puncak/", "dimensions": "1800x1200", "size": 657008}, {"number": "0585", "file": "0585 - NIHI Sumba - Villa Rahasia - bedroom interior with king bed.jpg", "resort": "NIHI Sumba", "space": "Villa Rahasia", "description": "Villa Rahasia bedroom at the spa: a king bed wrapped in sheer canopy drapes tied to carved posts, framed by thick bamboo columns and a steep thatched ceiling, with patterned floor tiles and garden doors. Rahasia sits within the Nihioka spa enclave and is used for wellness stays, so its interior is the calmest at NIHI: white linen, bamboo, shadow and green.", "src": "images/NIHI Sumba/0585 - NIHI Sumba - Villa Rahasia - bedroom interior with king bed.jpg", "source": "https://nihi.com/sumba/villa/rahasia/", "dimensions": "1800x1200", "size": 509993}, {"number": "0586", "file": "0586 - Bawah Reserve - Aura Spa - oil back massage treatment.jpg", "resort": "Bawah Reserve", "space": "Aura Spa", "description": "Aura Spa treatment in progress, photographed as a dark close up of an oil back massage. It is the only spa image the official site serves at original size, and it records the spa's register rather than its rooms: low light, natural oils and unhurried ritual. Bawah's spa interiors themselves, bamboo pavilions in the garden, could not be verified from official imagery at collectable quality.", "src": "images/Bawah Reserve/0586 - Bawah Reserve - Aura Spa - oil back massage treatment.jpg", "source": "https://www.bawahreserve.com/stay/", "dimensions": "600x700", "size": 18337}, {"number": "0587", "file": "0587 - Bawah Reserve - Deluxe Pool Villa - bedroom with canopy bed and hand fans opening to living area.jpg", "resort": "Bawah Reserve", "space": "Deluxe Pool Villa", "description": "Deluxe Pool Villa bedroom: a bamboo framed canopy bed with white drapes, opening through wide doors to the villa's living area with sofas beyond. Bamboo poles form the bed frame and the villa's structure alike, an honesty of construction that runs through Bawah. Ceiling hand fans, carved ornaments and woven panels complete the room; the palette is bamboo gold, white and indigo.", "src": "images/Bawah Reserve/0587 - Bawah Reserve - Deluxe Pool Villa - bedroom with canopy bed and hand fans opening to living area.jpg", "source": "https://www.bawahreserve.com/sleep/two-bedroom-deluxe-pool-villa/", "dimensions": "1920x1200", "size": 146152}, {"number": "0588", "file": "0588 - Bawah Reserve - Elang Private Residence - outdoor bath experience.jpg", "resort": "Bawah Reserve", "space": "Elang Private Residence", "description": "Elang Private Residence outdoor bathing: a huge carved stone tub on a jungle deck being filled with petals by a member of staff, a wooden side table with kettle and cup beside it. Elang is Bawah's private residence on its own island edge, and its bathing ritual is staged as theatre in the forest. The tub itself, hewn from a single stone mass, is the furniture piece.", "src": "images/Bawah Reserve/0588 - Bawah Reserve - Elang Private Residence - outdoor bath experience.jpg", "source": "https://www.bawahreserve.com/gallery/", "dimensions": "800x570", "size": 98018}, {"number": "0589", "file": "0589 - Bawah Reserve - Infinity Pool - pool edge with blue sun loungers and lagoon view.jpg", "resort": "Bawah Reserve", "space": "Infinity Pool", "description": "The main Infinity Pool: a dark lined pool running toward the lagoon, with blue cushioned loungers on the timber deck and the Treetops restaurant pavilion at its end. The pool's edge detail and the bleached deck boards show Bawah's beach club register, brighter and more open than the villa interiors.", "src": "images/Bawah Reserve/0589 - Bawah Reserve - Infinity Pool - pool edge with blue sun loungers and lagoon view.jpg", "source": "https://www.bawahreserve.com/stay/", "dimensions": "1920x1200", "size": 237876}, {"number": "0590", "file": "0590 - Bawah Reserve - Infinity Pool Villa - bamboo dining pavilion with pendant lights and lounge.jpg", "resort": "Bawah Reserve", "space": "Infinity Pool Villa", "description": "Infinity Pool Villa dining pavilion: a long open bamboo pavilion with a dining table dressed in blue runners and cushions, large woven rattan pendant lights overhead, and a sofa lounge at the far end. Every structural member is bamboo lashed and pegged. This is the fullest interior view of Bawah's bamboo architecture and its signature pendant lighting together.", "src": "images/Bawah Reserve/0590 - Bawah Reserve - Infinity Pool Villa - bamboo dining pavilion with pendant lights and lounge.jpg", "source": "https://www.bawahreserve.com/sleep/infinity-pool-villa/", "dimensions": "1734x1157", "size": 212635}, {"number": "0591", "file": "0591 - Bawah Reserve - Infinity Pool Villa - villa pavilion across the pool at dusk with lanterns.jpg", "resort": "Bawah Reserve", "space": "Infinity Pool Villa", "description": "Infinity Pool Villa at dusk seen across its pool: the bamboo pavilion glows with lantern light, paper lanterns line the water's edge and the dining terrace is set behind glass doors. The reflection doubles the pavilion in the still pool. It shows the villa as guests experience it in the evening, a lantern lit bamboo house on the water.", "src": "images/Bawah Reserve/0591 - Bawah Reserve - Infinity Pool Villa - villa pavilion across the pool at dusk with lanterns.jpg", "source": "https://www.bawahreserve.com/sleep/infinity-pool-villa/", "dimensions": "1601x903", "size": 330588}, {"number": "0592", "file": "0592 - Bawah Reserve - Overwater Bungalow - bathroom with copper bathtub and round mirrors.jpg", "resort": "Bawah Reserve", "space": "Overwater Bungalow", "description": "Overwater Bungalow bathroom: a freestanding copper bathtub before a full height jungle mural wall, a round brass mirror over the timber vanity and woven screens at the windows. The mural, the copper and the brass make this the most decorated bathroom at Bawah, a small jewel box between lagoon and forest.", "src": "images/Bawah Reserve/0592 - Bawah Reserve - Overwater Bungalow - bathroom with copper bathtub and round mirrors.jpg", "source": "https://www.bawahreserve.com/sleep/overwater-bungalow/", "dimensions": "1440x957", "size": 197017}, {"number": "0593", "file": "0593 - Bawah Reserve - Overwater Bungalow - bungalows over the lagoon with sun decks.jpg", "resort": "Bawah Reserve", "space": "Overwater Bungalow", "description": "The Overwater Bungalows from the lagoon: two thatched bungalows on stilts with wraparound sun decks and steps to the water, jungle rising behind. Bawah built these in the Maldivian typology but in bamboo, timber and thatch, so they read as part of the island rather than imported. Their bathrooms and decks carry the design interest.", "src": "images/Bawah Reserve/0593 - Bawah Reserve - Overwater Bungalow - bungalows over the lagoon with sun decks.jpg", "source": "https://www.bawahreserve.com/sleep/overwater-bungalow/", "dimensions": "1600x900", "size": 150299}, {"number": "0594", "file": "0594 - Bawah Reserve - Tented Beach Suite - bathroom with copper basin and round mirrors.jpg", "resort": "Bawah Reserve", "space": "Tented Beach Suite", "description": "Tented Beach Suite bathroom: twin round copper framed mirrors over a stone and timber vanity, woven rattan screens, a draped curtain to the shower and towels on wooden rails. The tent suites pair their canvas sleeping chambers with these fully built bathrooms, and the copper fittings are Bawah's recurring metal note.", "src": "images/Bawah Reserve/0594 - Bawah Reserve - Tented Beach Suite - bathroom with copper basin and round mirrors.jpg", "source": "https://www.bawahreserve.com/sleep/tented-beach-suite/", "dimensions": "1920x1440", "size": 479399}, {"number": "0595", "file": "0595 - Bawah Reserve - Tented Beach Suite - copper basin with brass tap and running water.jpg", "resort": "Bawah Reserve", "space": "Tented Beach Suite", "description": "Detail of the Tented Beach Suite basin: a hammered copper vessel with a tall brass tap running, against a woven rattan backdrop in warm light. The fittings throughout Bawah are handmade in this spirit, copper and brass left to patina. A small image, but the clearest record of the resort's bathroom hardware.", "src": "images/Bawah Reserve/0595 - Bawah Reserve - Tented Beach Suite - copper basin with brass tap and running water.jpg", "source": "https://www.bawahreserve.com/sleep/tented-beach-suite/", "dimensions": "1908x1273", "size": 93722}, {"number": "0596", "file": "0596 - Bawah Reserve - Tented Beach Suite - sitting area with jellyfish light and arm chairs against bamboo wall.jpg", "resort": "Bawah Reserve", "space": "Tented Beach Suite", "description": "Tented Beach Suite sitting area: a daybed dressed with indigo ikat cushions beneath the suite's signature jellyfish pendant light, two carved armchairs and a bamboo slat wall with garden light filtering through. The tent's canvas, the bamboo and the jellyfish lamp, made from woven fibre, define the suite type. It is the most characterful small interior at Bawah.", "src": "images/Bawah Reserve/0596 - Bawah Reserve - Tented Beach Suite - sitting area with jellyfish light and arm chairs against bamboo wall.jpg", "source": "https://www.bawahreserve.com/sleep/tented-beach-suite/", "dimensions": "1920x1278", "size": 249202}, {"number": "0597", "file": "0597 - Bawah Reserve - Treetops Restaurant - cooked breakfast table setting.jpg", "resort": "Bawah Reserve", "space": "Treetops Restaurant", "description": "Breakfast table at Treetops Restaurant in close view: eggs, greens and coffee on a wooden table with woven placemats, the restaurant's casual morning register. Treetops sits in the canopy by the infinity pool, built of bamboo with open sides. The official site serves this image small; it is included as the only verified Treetops interior scene.", "src": "images/Bawah Reserve/0597 - Bawah Reserve - Treetops Restaurant - cooked breakfast table setting.jpg", "source": "https://www.bawahreserve.com/stay/", "dimensions": "600x700", "size": 98013}, {"number": "0598", "file": "0598 - Bawah Reserve - Two-Bedroom Garden Pool Villa - garden entrance path with bamboo fencing.jpg", "resort": "Bawah Reserve", "space": "Two-Bedroom Garden Pool Villa", "description": "Garden Pool Villa entrance: a sandy garden path through bamboo fencing and tropical planting to the villa gate. Bawah's villas are hidden behind these woven bamboo screens so that arrival is always through garden. The fencing, gates and paths are part of the design language, raw bamboo used as architecture at every scale.", "src": "images/Bawah Reserve/0598 - Bawah Reserve - Two-Bedroom Garden Pool Villa - garden entrance path with bamboo fencing.jpg", "source": "https://www.bawahreserve.com/sleep/two-bedroom-garden-pool-villa/", "dimensions": "1766x1179", "size": 312764}, {"number": "0599", "file": "0599 - Bawah Reserve - Two-Bedroom Garden Pool Villa - pool terrace with sun loungers.jpg", "resort": "Bawah Reserve", "space": "Two-Bedroom Garden Pool Villa", "description": "Two-Bedroom Garden Pool Villa pool terrace: a green mosaic pool wrapped by the bamboo villa pavilions and dense planting, with two blue loungers on the deck. The garden villas trade the lagoon view for total enclosure, and their terraces feel like clearings. Bamboo columns and thatch unify the pavilions around the water.", "src": "images/Bawah Reserve/0599 - Bawah Reserve - Two-Bedroom Garden Pool Villa - pool terrace with sun loungers.jpg", "source": "https://www.bawahreserve.com/sleep/two-bedroom-garden-pool-villa/", "dimensions": "1766x1179", "size": 295222}, {"number": "0600", "file": "0600 - Bawah Reserve - Two-Bedroom Pool Villa - dining lounge with sofa and chess set.jpg", "resort": "Bawah Reserve", "space": "Two-Bedroom Pool Villa", "description": "Two-Bedroom Pool Villa living pavilion: a grey upholstered sofa lounge in the foreground with a chess set on the coffee table, a dining table behind and the pool terrace beyond, all under a high bamboo roof with woven pendants. The open plan single volume, sleeping pavilions aside, is how Bawah houses families: one great bamboo room for living.", "src": "images/Bawah Reserve/0600 - Bawah Reserve - Two-Bedroom Pool Villa - dining lounge with sofa and chess set.jpg", "source": "https://www.bawahreserve.com/sleep/four-bedroom-pool-villa/", "dimensions": "2085x1390", "size": 423159}, {"number": "0601", "file": "0601 - Bawah Reserve - Two-Bedroom Treehouse Lodge - open plan dining and living area viewed from main door.jpg", "resort": "Bawah Reserve", "space": "Two-Bedroom Treehouse Lodge", "description": "Two-Bedroom Treehouse Lodge interior from its doorway: a long open plan living and dining space in bamboo and timber, with a dining table and woven chairs at the far end, glass walls to the jungle and a polished wooden floor. The lodge is raised into the canopy, and the view through it shows the full depth of the single volume plan.", "src": "images/Bawah Reserve/0601 - Bawah Reserve - Two-Bedroom Treehouse Lodge - open plan dining and living area viewed from main door.jpg", "source": "https://www.bawahreserve.com/sleep/two-bedroom-treehouse-lodge/", "dimensions": "1920x1280", "size": 208852}, {"number": "0602", "file": "0602 - Bawah Reserve - Wallace Library - long oak table set for group lunch with rope lights and white rattan chairs.jpg", "resort": "Bawah Reserve", "space": "Wallace Library", "description": "The Wallace Library set for a group lunch: a very long oak table with place settings running its length, white rattan chairs, and a dramatic ceiling installation of coiled rope lights above tall windows to the lagoon. The library doubles as Bawah's private dining room. The rope light sculpture is the resort's boldest single decor gesture and worth the room on its own.", "src": "images/Bawah Reserve/0602 - Bawah Reserve - Wallace Library - long oak table set for group lunch with rope lights and white rattan chairs.jpg", "source": "https://www.bawahreserve.com/stay/", "dimensions": "1440x961", "size": 135375}, {"number": "0603", "file": "0603 - NIHI Rote - Metis Spa - outdoor massage treatment.jpg", "resort": "NIHI Rote", "space": "Metis Spa", "description": "Metis Spa treatment outdoors: a therapist giving a back massage on a table set among planting, with cushioned loungers behind. NIHI Rote's spa works in the open air in the NIHI manner, and this image records the treatment setting rather than a built interior. Natural fibres, timber and garden shade are the whole material palette.", "src": "images/NIHI Rote/0603 - NIHI Rote - Metis Spa - outdoor massage treatment.jpg", "source": "https://nihi.com/rote/wellness/", "dimensions": "1800x1200", "size": 586285}, {"number": "0604", "file": "0604 - NIHI Rote - Metis Spa - treatment bed with ikat cover and lattice screen.jpg", "resort": "NIHI Rote", "space": "Metis Spa", "description": "Metis Spa treatment room detail: a massage bed dressed with a red Sumbanese ikat cover and white towels, a woven tray with rolled towels and oils beside it, bamboo lattice screens filtering the light. The ikat bed cover is the design signature, bringing the island's textile tradition directly into the spa.", "src": "images/NIHI Rote/0604 - NIHI Rote - Metis Spa - treatment bed with ikat cover and lattice screen.jpg", "source": "https://nihi.com/rote/wellness/", "dimensions": "1800x1200", "size": 524142}, {"number": "0605", "file": "0605 - NIHI Rote - Ume Bo'a Beach - bathroom interior.jpg", "resort": "NIHI Rote", "space": "Ume Bo'a Beach", "description": "Ume Bo'a Beach bathroom: a black stone soaking tub filled with petals stands on the deck before open doors to the beach garden, with a carved stone basin, timber vanity and a patterned robe hanging ready. The bathroom opens completely to the outdoors, so bathing faces the sea path and palms. Stone, timber and thatch keep it in the resort's single material family.", "src": "images/NIHI Rote/0605 - NIHI Rote - Ume Bo'a Beach - bathroom interior.jpg", "source": "https://nihi.com/rote/villa/ume-boa-beach/", "dimensions": "1800x1200", "size": 690370}, {"number": "0606", "file": "0606 - NIHI Rote - Ume Bo'a Beach - beachfront lounge deck at dusk.jpg", "resort": "NIHI Rote", "space": "Ume Bo'a Beach", "description": "Ume Bo'a Beach lounge deck at dusk: an open timber pavilion with daybeds, low tables and an umbrella, facing the sunset over the beach from the villa's raised deck. This deck is the villa's outdoor living room, used from breakfast to sundowners. Dark timber, cream cushions and thatch continue the NIHI palette in a lighter, beach house register.", "src": "images/NIHI Rote/0606 - NIHI Rote - Ume Bo'a Beach - beachfront lounge deck at dusk.jpg", "source": "https://nihi.com/rote/villa/ume-boa-beach/", "dimensions": "1800x1200", "size": 648619}, {"number": "0607", "file": "0607 - NIHI Rote - Ume Bo'a Beach - main bedroom with king bed.jpg", "resort": "NIHI Rote", "space": "Ume Bo'a Beach", "description": "Ume Bo'a Beach main bedroom: a king bed with sheer canopy drapes and a grey upholstered bench, set in a cream walled room with timber ceiling beams, bedside lamps and garden doors. The Rote interiors are paler than Sumba's, more plaster and light timber, with ikat kept to cushions and throws.", "src": "images/NIHI Rote/0607 - NIHI Rote - Ume Bo'a Beach - main bedroom with king bed.jpg", "source": "https://nihi.com/rote/villa/ume-boa-beach/", "dimensions": "1800x1200", "size": 555459}, {"number": "0608", "file": "0608 - NIHI Rote - Ume Bo'a Beach - plunge pool with beachfront view.jpg", "resort": "NIHI Rote", "space": "Ume Bo'a Beach", "description": "Ume Bo'a Beach plunge pool at sunset: a long narrow pool on the deck edge aligned to the sinking sun, cabana beds with drapes at one end and palms silhouetted against an orange sky. The pool is positioned as a viewing instrument for the sunset, with the lounge deck arranged around it.", "src": "images/NIHI Rote/0608 - NIHI Rote - Ume Bo'a Beach - plunge pool with beachfront view.jpg", "source": "https://nihi.com/rote/villa/ume-boa-beach/", "dimensions": "1800x1200", "size": 784815}, {"number": "0609", "file": "0609 - NIHI Rote - Ume Bo'a Garden - garden plunge pool.jpg", "resort": "NIHI Rote", "space": "Ume Bo'a Garden", "description": "Ume Bo'a Garden plunge pool, portrait view: a guest in the stone edged pool with the villa's steep thatched roof and garden planting behind. The garden villas sit one row back from the beach, trading the direct view for deeper shade and privacy. Pool coping in dark stone matches the beach villas.", "src": "images/NIHI Rote/0609 - NIHI Rote - Ume Bo'a Garden - garden plunge pool.jpg", "source": "https://nihi.com/rote/villa/ume-boa-garden/", "dimensions": "1000x1500", "size": 444687}, {"number": "0610", "file": "0610 - NIHI Rote - Ume Bo'a Garden - private swimming pool and deck.jpg", "resort": "NIHI Rote", "space": "Ume Bo'a Garden", "description": "Ume Bo'a Garden from its garden: a long private swimming pool with a draped cabana, sun loungers and the villa pavilion at the far end, lawns and palms around. The garden villa's outdoor room is the most spacious of the Rote types, with the pool garden functioning as a private resort in itself.", "src": "images/NIHI Rote/0610 - NIHI Rote - Ume Bo'a Garden - private swimming pool and deck.jpg", "source": "https://nihi.com/rote/villa/ume-boa-garden/", "dimensions": "1800x1200", "size": 766061}, {"number": "0611", "file": "0611 - NIHI Rote - Ume Leo Beach - bedroom interior.jpg", "resort": "NIHI Rote", "space": "Ume Leo Beach", "description": "Ume Leo Beach bedroom: a king bed with patterned cushions being turned down by a member of staff, sheer curtains and glass doors to the pool garden. Light timber panelling and cream plaster give the room its calm, with woven textiles as accent. The two bedroom layout places this room for the beach view.", "src": "images/NIHI Rote/0611 - NIHI Rote - Ume Leo Beach - bedroom interior.jpg", "source": "https://nihi.com/rote/villa/ume-leo-beach/", "dimensions": "1800x1200", "size": 560919}, {"number": "0612", "file": "0612 - NIHI Rote - Ume Leo Beach - living room with sofa and shelved alcoves.jpg", "resort": "NIHI Rote", "space": "Ume Leo Beach", "description": "Ume Leo Beach living room: a cream sofa with batik cushions before a coffee table with flowers, flanked by built in timber shelving alcoves displaying ceramics and books, and carved doors. The built in joinery, unusual in beach resorts, gives the room a collected, residential character that suits Rote's longer stays.", "src": "images/NIHI Rote/0612 - NIHI Rote - Ume Leo Beach - living room with sofa and shelved alcoves.jpg", "source": "https://nihi.com/rote/villa/ume-leo-beach/", "dimensions": "1800x1200", "size": 613194}, {"number": "0613", "file": "0613 - NIHI Rote - Ume Leo Beach - private pool and open pavilion.jpg", "resort": "NIHI Rote", "space": "Ume Leo Beach", "description": "Ume Leo Beach from above: the private pool and open pavilion set in lawns between the villa and the turquoise sea. The aerial view shows the planning clearly, pavilion, pool, garden, beach, each layer stepping toward the water. Loungers and a shade bale furnish the pool terrace.", "src": "images/NIHI Rote/0613 - NIHI Rote - Ume Leo Beach - private pool and open pavilion.jpg", "source": "https://nihi.com/rote/villa/ume-leo-beach/", "dimensions": "1800x1200", "size": 724901}, {"number": "0614", "file": "0614 - NIHI Rote - Ume Leo Garden - bedroom interior.jpg", "resort": "NIHI Rote", "space": "Ume Leo Garden", "description": "Ume Leo Garden bedroom: a draped canopy king bed with a bench at its foot, timber floors, a desk and armchair by the window and warm wall panelling. The garden rooms at Rote are the most enclosed and shaded, and their interiors lean into timber warmth rather than the beach villas' brightness.", "src": "images/NIHI Rote/0614 - NIHI Rote - Ume Leo Garden - bedroom interior.jpg", "source": "https://nihi.com/rote/villa/ume-leo-garden/", "dimensions": "1800x1200", "size": 739014}, {"number": "0615", "file": "0615 - NIHI Rote - Ume Leo Garden - pool pavilion.jpg", "resort": "NIHI Rote", "space": "Ume Leo Garden", "description": "Ume Leo Garden pool pavilion: a pergola roofed deck with a double daybed in the foreground, dining table and chairs behind, and the private pool glinting beyond the drapes. Timber slat roofing filters the sun into stripes. It is Rote's version of the outdoor living room, softer and more shaded than the beach decks.", "src": "images/NIHI Rote/0615 - NIHI Rote - Ume Leo Garden - pool pavilion.jpg", "source": "https://nihi.com/rote/villa/ume-leo-garden/", "dimensions": "1800x1200", "size": 676413}, {"number": "0616", "file": "0616 - NIHI Rote - Ume Nanaru Beach - bedroom with custom lofted bunk bed.jpg", "resort": "NIHI Rote", "space": "Ume Nanaru Beach", "description": "Ume Nanaru Beach family bedroom: a custom lofted bunk bed built in timber above a king bed, with ladder access and reading lights, in a room with a pitched timber ceiling and fan. The bunk is a bespoke piece of joinery designed for families, and the cleverest single furniture item in the Rote collection.", "src": "images/NIHI Rote/0616 - NIHI Rote - Ume Nanaru Beach - bedroom with custom lofted bunk bed.jpg", "source": "https://nihi.com/rote/villa/ume-nanaru-beach/", "dimensions": "1000x1500", "size": 584050}, {"number": "0617", "file": "0617 - NIHI Rote - Ume Nanaru Beach - ground floor living room with sofas.jpg", "resort": "NIHI Rote", "space": "Ume Nanaru Beach", "description": "Ume Nanaru Beach ground floor living room: a double height space with cream sofas and batik cushions around a timber coffee table, a desk area behind and warm timber wall panelling under a high pitched ceiling. Nanaru is Rote's largest villa type, and this room is its social centre, sized for two families.", "src": "images/NIHI Rote/0617 - NIHI Rote - Ume Nanaru Beach - ground floor living room with sofas.jpg", "source": "https://nihi.com/rote/villa/ume-nanaru-beach/", "dimensions": "1800x1200", "size": 570455}, {"number": "0618", "file": "0618 - NIHI Rote - Ume Nanaru Beach - outdoor bathtub with ocean view.jpg", "resort": "NIHI Rote", "space": "Ume Nanaru Beach", "description": "Ume Nanaru Beach outdoor bath: a great black stone bathtub on a bamboo screened deck, rolled towels on a wooden stool beside it, with greenery and a glimpse of sea beyond the rail. The tub's scale and its deck setting make bathing an event. Bamboo cladding and dark stone keep the palette grounded.", "src": "images/NIHI Rote/0618 - NIHI Rote - Ume Nanaru Beach - outdoor bathtub with ocean view.jpg", "source": "https://nihi.com/rote/villa/ume-nanaru-beach/", "dimensions": "1800x1200", "size": 765599}, {"number": "0619", "file": "0619 - NIHI Rote - Ume Nanaru Garden - bedroom interior.jpg", "resort": "NIHI Rote", "space": "Ume Nanaru Garden", "description": "Ume Nanaru Garden bedroom suite: a living area with a cream sofa and coffee table in the foreground flows into the canopy bedded sleeping area behind, separated by sheer drapes on timber posts. The suite plan, sitting room and bedroom in one volume, mirrors the Sumba villa arrangement in Rote's paler palette.", "src": "images/NIHI Rote/0619 - NIHI Rote - Ume Nanaru Garden - bedroom interior.jpg", "source": "https://nihi.com/rote/villa/ume-nanaru-garden/", "dimensions": "1800x1200", "size": 499733}, {"number": "0620", "file": "0620 - Amanpulo - Hillside Casita - bedroom with arched timber headboard and rattan chairs.jpg", "resort": "Amanpulo", "space": "Hillside Casita", "description": "Hillside Casita bedroom with a wide platform bed framed by an arched rattan and timber headboard, dressed in plain white linen. Rattan armchairs with cream cushions sit by the picture windows, and a low timber dresser runs along the wall under warm lamp light. Dark hardwood floors and a pitched timber ceiling give the room the feel of a refined bahay kubo. The formula to copy is a statement woven headboard, white bedding, and rattan seating kept low and broad.", "src": "images/Amanpulo/0620 - Amanpulo - Hillside Casita - bedroom with arched timber headboard and rattan chairs.jpg", "source": "https://www.aman.com/resorts/amanpulo/accommodation/casitas/hillside-casita", "dimensions": "2560x1582", "size": 584654}, {"number": "0621", "file": "0621 - Amanpulo - Deluxe Hillside Casita - sitting room with daybed and rattan chairs facing the sea.jpg", "resort": "Amanpulo", "space": "Deluxe Hillside Casita", "description": "Sitting room of the Deluxe Hillside Casita, arranged with a long cushioned daybed and two woven rattan armchairs around a small round table, all facing floor to ceiling windows over the sea. Timber framing, a coffered style ceiling with concealed lighting and dark polished floors hold the room together. The palette is honey wood, cream and white. It shows how Aman furnishes a view room: almost nothing that competes with the window.", "src": "images/Amanpulo/0621 - Amanpulo - Deluxe Hillside Casita - sitting room with daybed and rattan chairs facing the sea.jpg", "source": "https://www.aman.com/resorts/amanpulo/accommodation/casitas/deluxe-hillside-casita", "dimensions": "2000x1235", "size": 522377}, {"number": "0622", "file": "0622 - Amanpulo - Beach Casita - bedroom opening to timber deck with window daybed.jpg", "resort": "Amanpulo", "space": "Beach Casita", "description": "Beach Casita photographed from its deck through wide sliding doors, with the bedroom beyond dressed in white and a built in window daybed piled with cushions along the glass. Timber decking flows straight into the room's hardwood floor, blurring inside and out. Planting presses close on both sides. This is the casita plan in one image: deck, glass wall, daybed, bed, in a single line to the sea.", "src": "images/Amanpulo/0622 - Amanpulo - Beach Casita - bedroom opening to timber deck with window daybed.jpg", "source": "https://www.aman.com/resorts/amanpulo/accommodation/casitas/beach-casita", "dimensions": "2024x1271", "size": 2822183}, {"number": "0623", "file": "0623 - Amanpulo - Casita - bedroom with writing desk and sea view windows.jpg", "resort": "Amanpulo", "space": "Casita", "description": "Casita bedroom corner with a writing desk and rattan chair placed before windows looking to the sea, the bed just entering the frame in white linen. A long low cabinet runs beneath the windows and the floors are dark polished hardwood. Aman does not caption gallery images by casita type, so this is recorded at casita level. Note the working desk given the best position in the room, a consistent Amanpulo habit.", "src": "images/Amanpulo/0623 - Amanpulo - Casita - bedroom with writing desk and sea view windows.jpg", "source": "https://www.aman.com/resorts/amanpulo/gallery", "dimensions": "2024x1271", "size": 1839063}, {"number": "0624", "file": "0624 - Amanpulo - Four Bedroom Villa - living and dining room with rattan chairs and daybed.jpg", "resort": "Amanpulo", "space": "Four Bedroom Villa", "description": "The living pavilion of a Four Bedroom Villa, a long room of dining and sitting zones under a pitched timber ceiling. A daybed in dark wood with cream cushions anchors one end, rattan dining chairs surround the table, and full height windows open to the garden on both sides. The furniture is all natural fibre and dark hardwood, scaled generously for group living. It is the villa version of the casita language, stretched to entertaining size.", "src": "images/Amanpulo/0624 - Amanpulo - Four Bedroom Villa - living and dining room with rattan chairs and daybed.jpg", "source": "https://www.aman.com/resorts/amanpulo/accommodation/villas", "dimensions": "2560x1576", "size": 762372}, {"number": "0625", "file": "0625 - Amanpulo - Aman Spa - twin treatment beds in open pavilion with sea view.jpg", "resort": "Amanpulo", "space": "Aman Spa", "description": "Spa treatment pavilion with two massage beds dressed in white, set side by side on a timber deck behind sheer curtains that open to a view over the island canopy to the sea. A small side table holds treatment oils. The structure is a simple pergola in dark timber. For a home spa reference, this is the essential arrangement: paired beds, gauze, wood, and a horizon.", "src": "images/Amanpulo/0625 - Amanpulo - Aman Spa - twin treatment beds in open pavilion with sea view.jpg", "source": "https://www.aman.com/resorts/amanpulo/gallery", "dimensions": "2560x1580", "size": 604163}, {"number": "0626", "file": "0626 - Amanpulo - Nama - restaurant interior with dark timber tables and sea view.jpg", "resort": "Amanpulo", "space": "Nama", "description": "Nama, the Japanese restaurant, photographed at dusk: dark timber tables and chairs with cream cushions set in a glass walled room, the sea darkening beyond. Joinery is square and heavy, lighting low and warm, and table settings are minimal with small ceramic pieces. The room is the most enclosed of the resort's restaurants and the most furniture led. Copy the contrast of blackened wood against a blue evening view.", "src": "images/Amanpulo/0626 - Amanpulo - Nama - restaurant interior with dark timber tables and sea view.jpg", "source": "https://www.aman.com/resorts/amanpulo/dining/nama-lagoon-club", "dimensions": "2000x1235", "size": 388078}, {"number": "0627", "file": "0627 - Amanpulo - Clubhouse Restaurant - terrace dining with white linen under the pavilion.jpg", "resort": "Amanpulo", "space": "Clubhouse Restaurant", "description": "The Clubhouse Restaurant terrace at lunch, with tables dressed in white cloths and dark timber chairs under the deep pitched roof of the clubhouse pavilion. A stone wall and clipped hedge separate the terrace from the garden, and bougainvillea adds the only bright colour. Service is formal but the architecture is pure island pavilion. It records the resort's most traditional dining setting.", "src": "images/Amanpulo/0627 - Amanpulo - Clubhouse Restaurant - terrace dining with white linen under the pavilion.jpg", "source": "https://www.aman.com/resorts/amanpulo/dining/clubhouse-restaurant", "dimensions": "2000x1234", "size": 2248652}, {"number": "0628", "file": "0628 - Amanpulo - Beach Club - terrace tables at dusk with lanterns.jpg", "resort": "Amanpulo", "space": "Beach Club", "description": "Beach Club terrace at sunset, with two timber tables set for dinner under the trees at the sand's edge, lit by glass lanterns as the sky turns pink over the water. Chairs are simple slatted timber. There is no building in frame; the restaurant is a clearing, a tree canopy and lamplight. A useful reference for outdoor dining kept to furniture and light alone.", "src": "images/Amanpulo/0628 - Amanpulo - Beach Club - terrace tables at dusk with lanterns.jpg", "source": "https://www.aman.com/resorts/amanpulo/dining/beach-club", "dimensions": "2000x1235", "size": 338087}, {"number": "0629", "file": "0629 - Amanpulo - Lagoon Club - beachfront dining pavilion with timber tables.jpg", "resort": "Amanpulo", "space": "Lagoon Club", "description": "The Lagoon Club, an open pavilion on the sand with folding timber doors pushed back and rows of square dining tables and slatted chairs facing the lagoon. The roof structure is exposed dark wood and the floor is pale stone. In daylight the room is all horizontals: sea, sand, table line. It is the daytime counterpart to the Beach Club's evening mood.", "src": "images/Amanpulo/0629 - Amanpulo - Lagoon Club - beachfront dining pavilion with timber tables.jpg", "source": "https://www.aman.com/resorts/amanpulo/dining/lagoon-club", "dimensions": "2000x1234", "size": 2548676}, {"number": "0630", "file": "0630 - Amanpulo - Restaurant - dining room with rattan chairs and glass doors to pool garden.jpg", "resort": "Amanpulo", "space": "Restaurant", "description": "A resort dining room with rattan armchairs and white cushioned seats around tables set with glassware, in a timber framed room whose glazed doors open to a pool garden bright with bougainvillea. The mood is garden room rather than pavilion: enclosed, shaded and green on every side. Aman does not caption gallery images by venue, so this is recorded simply as a restaurant interior. The woven chair with a loose white cushion is the repeatable piece.", "src": "images/Amanpulo/0630 - Amanpulo - Restaurant - dining room with rattan chairs and glass doors to pool garden.jpg", "source": "https://www.aman.com/resorts/amanpulo/gallery", "dimensions": "2024x1271", "size": 2246337}, {"number": "0631", "file": "0631 - Amanpulo - Aman Spa - pilates studio with timber reformers and garden windows.jpg", "resort": "Amanpulo", "space": "Aman Spa", "description": "Pilates studio inside the spa complex, with two timber framed reformer machines on the polished hardwood floor facing full height windows over the garden. Woven wall panels and a timber slatted ceiling keep the room in the same material family as the casitas. It is a working room rather than a styled one, kept because it completes the spa's interior set alongside the treatment pavilion.", "src": "images/Amanpulo/0631 - Amanpulo - Aman Spa - pilates studio with timber reformers and garden windows.jpg", "source": "https://www.aman.com/resorts/amanpulo/gallery", "dimensions": "2560x1580", "size": 736787}, {"number": "0632", "file": "0632 - Amanpulo - Deluxe Hillside Casita - bathroom with twin stone basins and egg shaped tub.jpg", "resort": "Amanpulo", "space": "Deluxe Hillside Casita", "description": "Casita bathroom with a long timber vanity carrying two carved stone vessel basins beneath a wide mirror, and an egg shaped freestanding tub set on the dark hardwood floor. A rattan chair and woven baskets sit by the louvred window wall, and the pitched ceiling is lined in timber with a woven fan light. The fittings are plain and sculptural, stone and wood doing the work of ornament. It is the bathroom that completes the casita set, found on the official Deluxe Hillside Casita page.", "src": "images/Amanpulo/0632 - Amanpulo - Deluxe Hillside Casita - bathroom with twin stone basins and egg shaped tub.jpg", "source": "https://www.aman.com/resorts/amanpulo/accommodation/casitas/deluxe-hillside-casita", "dimensions": "2560x1576", "size": 697061}, {"number": "0633", "file": "0633 - Nay Palad Hideaway - Coral Villa - arched entry hall with woven globe pendants.jpg", "resort": "Nay Palad Hideaway", "space": "Coral Villa", "description": "Entry hall of the Coral Villa, a tall arched space lined in woven rattan panelling with three spherical woven pendants hanging over a polished timber floor. Low credenzas in dark wood with woven fronts line both walls, holding glassware and a ceramic bowl, and glazed doors at the end open to the deck and garden. The architecture is the decor here: woven surfaces, arch, and filtered light. Converted from the official AVIF original to JPEG at quality 95 because the staging tools cannot read AVIF.", "src": "images/Nay Palad Hideaway/0633 - Nay Palad Hideaway - Coral Villa - arched entry hall with woven globe pendants.jpg", "source": "https://www.naypaladhideaway.com/", "dimensions": "1443x2002", "size": 1558324}, {"number": "0634", "file": "0634 - Nay Palad Hideaway - Coral Villa - bedroom with draped canopy bed and daybed.jpg", "resort": "Nay Palad Hideaway", "space": "Coral Villa", "description": "Coral Villa bedroom with a four poster bed draped in sheer white canopy fabric, dressed in white linen, and a long daybed along the window wall. Floors are warm polished timber and the ceiling follows the steep thatch pitch. A round woven rug softens the centre of the room. The look to copy is the soft white textile envelope set against dark wood and thatch.", "src": "images/Nay Palad Hideaway/0634 - Nay Palad Hideaway - Coral Villa - bedroom with draped canopy bed and daybed.jpg", "source": "https://www.naypaladhideaway.com/", "dimensions": "2002x1216", "size": 661567}, {"number": "0635", "file": "0635 - Nay Palad Hideaway - Coral Villa - bedroom with carved timber wall and woven egg chair.jpg", "resort": "Nay Palad Hideaway", "space": "Coral Villa", "description": "Second Coral Villa bedroom, backed by a full height carved and woven timber feature wall in pale wood. A woven hanging egg chair sits by the folding glass doors, and the bed is dressed in layered white and cream textiles with a bench at its foot. Louvred panels and a mezzanine rail show the villa's two level plan. The carved wall is the single investment piece; everything else stays plain.", "src": "images/Nay Palad Hideaway/0635 - Nay Palad Hideaway - Coral Villa - bedroom with carved timber wall and woven egg chair.jpg", "source": "https://www.naypaladhideaway.com/", "dimensions": "2000x1332", "size": 924803}, {"number": "0636", "file": "0636 - Nay Palad Hideaway - Coral Villa - mezzanine lounge under arched bamboo vault.jpg", "resort": "Nay Palad Hideaway", "space": "Coral Villa", "description": "The Coral Villa's mezzanine living lounge under a dramatic arched bamboo and rattan vault, furnished with two long curved sofas in pale upholstery facing each other over a round coffee table with a tropical arrangement. Woven pendants hang from the apex and a bed is glimpsed at the far end. This is Dedon style indoor outdoor furniture used as architecture scale furnishing. The vaulted woven ceiling is the resort's signature interior.", "src": "images/Nay Palad Hideaway/0636 - Nay Palad Hideaway - Coral Villa - mezzanine lounge under arched bamboo vault.jpg", "source": "https://www.naypaladhideaway.com/", "dimensions": "2002x1236", "size": 1089512}, {"number": "0637", "file": "0637 - Nay Palad Hideaway - Coral Villa - terrace lounge with woven sofas by the pool.jpg", "resort": "Nay Palad Hideaway", "space": "Coral Villa", "description": "Coral Villa terrace lounge under a woven shade canopy, with deep woven sofas and armchairs in grey and white arranged around a low round table beside the private pool. Timber decking, a thatched cabana and dense planting complete the enclosure. All furniture is woven outdoor construction from the Dedon palette. It shows how the villas treat the terrace as a second living room.", "src": "images/Nay Palad Hideaway/0637 - Nay Palad Hideaway - Coral Villa - terrace lounge with woven sofas by the pool.jpg", "source": "https://www.naypaladhideaway.com/", "dimensions": "2000x1234", "size": 1255703}, {"number": "0638", "file": "0638 - Nay Palad Hideaway - Coral Villa - bathroom with double vanity and woven baskets.jpg", "resort": "Nay Palad Hideaway", "space": "Coral Villa", "description": "Coral Villa bathroom, a long room with a dark timber double vanity, woven basket stools and storage baskets, and a pebble textured wall panel. Louvred windows and an open doorway to a walled garden shower keep it bright and ventilated. Floors are polished timber with a woven runner. Woven storage used openly, instead of cupboards, is the detail to take away.", "src": "images/Nay Palad Hideaway/0638 - Nay Palad Hideaway - Coral Villa - bathroom with double vanity and woven baskets.jpg", "source": "https://www.naypaladhideaway.com/", "dimensions": "2002x1335", "size": 1199266}, {"number": "0639", "file": "0639 - Nay Palad Hideaway - Garden View Villa - bedroom with sheer canopy drapes and garden doors.jpg", "resort": "Nay Palad Hideaway", "space": "Garden View Villa", "description": "Garden View Villa bedroom with the bed wrapped in sheer white drapes that fall from the ceiling frame, opening through glazed doors to the garden. A large potted plant in a woven basket stands by the window and the timber floor is left bare. The room is mostly textile and light. It demonstrates the hideaway's soft, barefoot version of a canopy bed.", "src": "images/Nay Palad Hideaway/0639 - Nay Palad Hideaway - Garden View Villa - bedroom with sheer canopy drapes and garden doors.jpg", "source": "https://www.naypaladhideaway.com/", "dimensions": "2002x1354", "size": 785591}, {"number": "0640", "file": "0640 - Nay Palad Hideaway - Garden View Villa - bedroom under arched woven vault with round rug.jpg", "resort": "Nay Palad Hideaway", "space": "Garden View Villa", "description": "Garden View Villa bedroom under an arched woven ceiling, with a woven panel headboard wall, white dressed bed and a large round woven rug over the timber floor. Armchairs and a side table sit by the curtained window wall, and a small elephant figure stands as a playful accent. The arched woven shell makes the architecture feel handmade at every surface.", "src": "images/Nay Palad Hideaway/0640 - Nay Palad Hideaway - Garden View Villa - bedroom under arched woven vault with round rug.jpg", "source": "https://www.naypaladhideaway.com/", "dimensions": "2002x1310", "size": 1095676}, {"number": "0641", "file": "0641 - Nay Palad Hideaway - Ocean View Villa - veranda with suspended woven daybed and sea view.jpg", "resort": "Nay Palad Hideaway", "space": "Ocean View Villa", "description": "Ocean View Villa veranda, a deep thatched pavilion deck holding a suspended woven daybed, the Dedon Nestrest form, hanging from the rafters, with woven lounge chairs and a leaf shaped floor cushion nearby. The sea shows through the planting at the deck edge. Timber decking and thatch keep the structure rustic while the furniture is sculptural. The hanging daybed is the piece this resort is known for.", "src": "images/Nay Palad Hideaway/0641 - Nay Palad Hideaway - Ocean View Villa - veranda with suspended woven daybed and sea view.jpg", "source": "https://www.naypaladhideaway.com/", "dimensions": "2000x1196", "size": 965094}, {"number": "0642", "file": "0642 - Nay Palad Hideaway - Ocean View Villa - bedroom with tall draped canopy and bench.jpg", "resort": "Nay Palad Hideaway", "space": "Ocean View Villa", "description": "Ocean View Villa bedroom with a tall four poster bed dressed in white and hung with full sheer drapes tied at the posts, a white bench at its foot. A daybed sits in the window bay and a desk with a woven chair occupies the side wall, all on dark polished floors. The scale is grand but the materials stay simple: wood, cotton, rattan. A clear template for a tropical master bedroom.", "src": "images/Nay Palad Hideaway/0642 - Nay Palad Hideaway - Ocean View Villa - bedroom with tall draped canopy and bench.jpg", "source": "https://www.naypaladhideaway.com/", "dimensions": "2002x1270", "size": 668776}, {"number": "0643", "file": "0643 - Nay Palad Hideaway - Ocean View Villa - bathroom vanity with twin vessel basins at louvred window.jpg", "resort": "Nay Palad Hideaway", "space": "Ocean View Villa", "description": "Ocean View Villa bathroom vanity, a long dark timber counter with two white vessel basins, woven basket stools below and wall lanterns either side of a wide louvred window over the garden. A banana leaf in a vase is the single decoration. The room is lit almost entirely by daylight through the louvres. Basket stools as bathroom seating are a Nay Palad signature worth copying.", "src": "images/Nay Palad Hideaway/0643 - Nay Palad Hideaway - Ocean View Villa - bathroom vanity with twin vessel basins at louvred window.jpg", "source": "https://www.naypaladhideaway.com/", "dimensions": "2002x1334", "size": 1011532}, {"number": "0644", "file": "0644 - Nay Palad Hideaway - Ocean View Villa - outdoor shower with woven screen under thatch.jpg", "resort": "Nay Palad Hideaway", "space": "Ocean View Villa", "description": "Outdoor shower of an Ocean View Villa, enclosed by a woven rattan screen under the thatch roof edge, with a timber deck floor still wet from use and planting visible through the weave. A folded towel hangs on the screen. The photograph is portrait format and shows the woven construction up close. It records the resort's woven screens as both privacy device and ornament.", "src": "images/Nay Palad Hideaway/0644 - Nay Palad Hideaway - Ocean View Villa - outdoor shower with woven screen under thatch.jpg", "source": "https://www.naypaladhideaway.com/", "dimensions": "1452x2000", "size": 1629455}, {"number": "0645", "file": "0645 - Nay Palad Hideaway - Perlah Villa - bedroom with canopy bed and patterned cushions.jpg", "resort": "Nay Palad Hideaway", "space": "Perlah Villa", "description": "Perlah Villa master bedroom with a draped canopy bed dressed in white with blue patterned cushions and a grey throw, a chaise at its side and small round timber side tables. Folding doors open to the deck and pool, and the ceiling is a smooth curved shell. Textiles carry more pattern here than elsewhere in the resort, in indigo and grey. It is the most decorated of the villa bedrooms.", "src": "images/Nay Palad Hideaway/0645 - Nay Palad Hideaway - Perlah Villa - bedroom with canopy bed and patterned cushions.jpg", "source": "https://www.naypaladhideaway.com/", "dimensions": "1999x1333", "size": 695200}, {"number": "0646", "file": "0646 - Nay Palad Hideaway - Perlah Villa - circular dressing room with desks and sheer curtains.jpg", "resort": "Nay Palad Hideaway", "space": "Perlah Villa", "description": "The Perlah Villa's circular dressing and sitting room, wrapped in sheer white curtains with a domed ceiling lit by a concealed ring. Two slim writing desks with mirrors face the windows, with woven stools, and a round rug centres the space. Everything is pale: white, cream, light timber. A rare fully round room, furnished minimally so the geometry speaks.", "src": "images/Nay Palad Hideaway/0646 - Nay Palad Hideaway - Perlah Villa - circular dressing room with desks and sheer curtains.jpg", "source": "https://www.naypaladhideaway.com/", "dimensions": "1999x1333", "size": 1010220}, {"number": "0647", "file": "0647 - Nay Palad Hideaway - Perlah Villa - pool terrace with round daybed and drum tables.jpg", "resort": "Nay Palad Hideaway", "space": "Perlah Villa", "description": "Perlah Villa pool terrace under a wide thatched roof, with a large round woven daybed, low drum side tables and cushioned loungers arranged on the timber deck between the villa and its private pool, the sea beyond. The furniture grouping is circular, echoing the daybed. It shows the resort's outdoor rooms at their most generous scale.", "src": "images/Nay Palad Hideaway/0647 - Nay Palad Hideaway - Perlah Villa - pool terrace with round daybed and drum tables.jpg", "source": "https://www.naypaladhideaway.com/", "dimensions": "2000x1096", "size": 1152736}, {"number": "0648", "file": "0648 - Nay Palad Hideaway - Spa - bathroom with sculptural wavy timber vanity and vessel basins.jpg", "resort": "Nay Palad Hideaway", "space": "Spa", "description": "Spa bathroom from the resort's official wellness gallery, centred on a sculptural wave shaped dark timber counter carrying two white vessel basins, with mirrors and a leaf arrangement behind. Sheer curtains diffuse the garden light and small bowls of petals sit on the counter. The vanity is carved as a single flowing form, furniture as sculpture. Converted from the official AVIF original to JPEG at quality 95 because the staging tools cannot read AVIF.", "src": "images/Nay Palad Hideaway/0648 - Nay Palad Hideaway - Spa - bathroom with sculptural wavy timber vanity and vessel basins.jpg", "source": "https://www.naypaladhideaway.com/", "dimensions": "2000x1334", "size": 757251}, {"number": "0649", "file": "0649 - Nay Palad Hideaway - Spa - yoga pavilion with arched bamboo vault over the deck.jpg", "resort": "Nay Palad Hideaway", "space": "Spa", "description": "The yoga pavilion, a long arched bamboo vault open at the far end to palms and the sea, with two practitioners on mats on the timber deck giving scale. The woven arch structure is the same construction language as the villa ceilings, stretched to a hall. Light falls in bands through the weave. Kept as the record of the resort's largest woven interior.", "src": "images/Nay Palad Hideaway/0649 - Nay Palad Hideaway - Spa - yoga pavilion with arched bamboo vault over the deck.jpg", "source": "https://www.naypaladhideaway.com/", "dimensions": "2002x1126", "size": 1126791}, {"number": "0650", "file": "0650 - Four Seasons Resort The Nam Hai - One Bedroom Villa - raised platform bed pavilion with sunken living area.jpg", "resort": "Four Seasons Resort The Nam Hai", "space": "One Bedroom Villa", "description": "The definitive Nam Hai villa view, taken from the sunken living area up to the raised sleeping platform, the local phan reimagined as a ceremonial bed pavilion. Two olive green upholstered armchairs with timber spindle arms flank a round black table set with orchids and a fruit bowl, while stone steps climb on both sides past pleated shade floor lamps. The king bed in crisp white linen sits on the dark timber platform behind sheer drapes that graduate from ivory to amber, under a coffered ceiling with patterned panels and a high pitched roof lined in woven matting. Copy the level change, the symmetry and the ombre sheer as the room divider.", "src": "images/Four Seasons Resort The Nam Hai/0650 - Four Seasons Resort The Nam Hai - One Bedroom Villa - raised platform bed pavilion with sunken living area.jpg", "source": "https://press.fourseasons.com/hoian/hotel-news/2026/10-years-anniversary/", "dimensions": "2560x1589", "size": 671564}, {"number": "0651", "file": "0651 - Four Seasons Resort The Nam Hai - One Bedroom Villa - platform bed with ombre sheer drapes and dark credenza.jpg", "resort": "Four Seasons Resort The Nam Hai", "space": "One Bedroom Villa", "description": "Close view of the platform bed framed by floor length sheer drapes that fade from cream at the top to warm amber at the hem, glowing like the lanterns of Hoi An. In the foreground a long low credenza in ebonised timber with upturned ends carries stacked decorative books and a black vase of green fern, a styling formula worth copying exactly. Behind the white dressed bed, a woven mesh pendant in the shape of a conical hat hangs from the dark coffered ceiling, and a small pleated shade lamp sits at the bedside with an orchid in a metallic vase. Dark stone floors and black structural posts keep the palette grounded against the soft textiles.", "src": "images/Four Seasons Resort The Nam Hai/0651 - Four Seasons Resort The Nam Hai - One Bedroom Villa - platform bed with ombre sheer drapes and dark credenza.jpg", "source": "https://press.fourseasons.com/hoian/hotel-news/2025/redesigned-one-bedroom-and-villas/", "dimensions": "2560x1542", "size": 542788}, {"number": "0652", "file": "0652 - Four Seasons Resort The Nam Hai - One Bedroom Villa - writing desk and daybed behind the bed platform.jpg", "resort": "Four Seasons Resort The Nam Hai", "space": "One Bedroom Villa", "description": "The working side of the bed platform, where a generous writing desk in warm walnut tones with leather fronted drawers and black framing faces back into the room. On it sit a brass singing bowl, a black vase with a fresh fern, stacked books and a single white orchid, showing how the resort layers artisan objects rather than art on walls. Behind the desk, a deep daybed in pale upholstery is dressed with olive cushions, a long leaf pattern bolster and a herringbone throw pillow, lit by the same woven conical hat pendant and sheer ombre drapes seen at the bed. Louvred screens and dark timber posts complete the garden house frame.", "src": "images/Four Seasons Resort The Nam Hai/0652 - Four Seasons Resort The Nam Hai - One Bedroom Villa - writing desk and daybed behind the bed platform.jpg", "source": "https://press.fourseasons.com/hoian/hotel-news/2025/redesigned-one-bedroom-and-villas/", "dimensions": "2560x1620", "size": 654816}, {"number": "0653", "file": "0653 - Four Seasons Resort The Nam Hai - One Bedroom Villa - sunken daybed lounge facing the platform bed.jpg", "resort": "Four Seasons Resort The Nam Hai", "space": "One Bedroom Villa", "description": "Reverse angle of the villa plan, with the sunken lounge in the foreground and the draped bed platform raised beyond it. The lounge is one very wide daybed in oatmeal weave, loaded with cylindrical bolsters and cushions in three prints, a botanical scene with parrots, a grey leaf pattern and plain aqua, around a round black coffee table with a tea set. The platform front is panelled in dark timber with pierced geometric fretwork inserts, and open shelves hold books and a small black bowl. Pleated shade floor lamps mark the steps on each side, and the whole composition sits under a soaring pitched ceiling of woven matting and black beams.", "src": "images/Four Seasons Resort The Nam Hai/0653 - Four Seasons Resort The Nam Hai - One Bedroom Villa - sunken daybed lounge facing the platform bed.jpg", "source": "https://www.fourseasons.com/hoian/villa-residence-rentals/", "dimensions": "2560x1707", "size": 812786}, {"number": "0654", "file": "0654 - Four Seasons Resort The Nam Hai - One Bedroom Villa - bathroom with freestanding bath and marble vanities.jpg", "resort": "Four Seasons Resort The Nam Hai", "space": "One Bedroom Villa", "description": "Villa bathroom arranged symmetrically around a freestanding oval soaking bath in white, placed before a full wall of louvred folding screens that filter garden light into stripes. Twin vanity units in dark stained timber with marble tops and undermount basins face each other across a pale patterned tile floor, each with an arched black framed mirror, a tall glass tube wall light and a textured stone vase of white orchids. A floor standing chrome bath filler and a black candle stand flank the bath, and the curved slatted timber ceiling treatment gives the room its distinctive cocoon shape. The recipe is dark cabinetry, white stone, black metal and one orchid per vanity.", "src": "images/Four Seasons Resort The Nam Hai/0654 - Four Seasons Resort The Nam Hai - One Bedroom Villa - bathroom with freestanding bath and marble vanities.jpg", "source": "https://www.fourseasons.com/hoian/accommodations/villas/one-bedroom-villa/", "dimensions": "2560x1625", "size": 851438}, {"number": "0655", "file": "0655 - Four Seasons Resort The Nam Hai - Pool Villa - bedroom with pitched timber roof and lattice screens.jpg", "resort": "Four Seasons Resort The Nam Hai", "space": "Pool Villa", "description": "Pool Villa bedroom photographed from beside the bed, showing the full height of the pitched roof with its woven lining, black rafters and ceiling fan. The bed in white linen with embroidered pillows rests against a low dark headboard wall, with a pleated dark shade table lamp and a potted white orchid on the nightstand. Pierced geometric lattice screens in blackened timber divide the sleeping area from the dressing space behind, where a vase of yellow orchids catches the light. Timber venetian blinds cover the tall windows, an abstract painting in slate, black and ochre hangs at the right, and dark stone tiles run underfoot.", "src": "images/Four Seasons Resort The Nam Hai/0655 - Four Seasons Resort The Nam Hai - Pool Villa - bedroom with pitched timber roof and lattice screens.jpg", "source": "https://www.fourseasons.com/hoian/accommodations/pool-villas/one-bedroom-pool-villa/", "dimensions": "2560x1655", "size": 801660}, {"number": "0656", "file": "0656 - Four Seasons Resort The Nam Hai - Pool Villa - living pavilion with tassel chandelier and low sectional.jpg", "resort": "Four Seasons Resort The Nam Hai", "space": "Pool Villa", "description": "Separate living pavilion of a Pool Villa, a high pitched room lined in woven matting and organised around an oversized circular chandelier hung with hundreds of white tassels and beads. Seating is low and sprawling, a buttoned sectional in warm oatmeal with bolster cushions and blue grey patterned pillows, paired with round marble topped drum tables, a woven pouffe and cane backed armchairs in a sharp yellow green. A dark timber console with stone and brass objects runs along the slatted wall, and glass doors open straight to the private pool, lawn and beach. Warm timber floors and layered round woven rugs soften the scale.", "src": "images/Four Seasons Resort The Nam Hai/0656 - Four Seasons Resort The Nam Hai - Pool Villa - living pavilion with tassel chandelier and low sectional.jpg", "source": "https://press.fourseasons.com/de/hoian/hotel-news/2026/renovation_3/", "dimensions": "2560x1707", "size": 1150534}, {"number": "0657", "file": "0657 - Four Seasons Resort The Nam Hai - Pool Villa - living and dining pavilion with ocean view.jpg", "resort": "Four Seasons Resort The Nam Hai", "space": "Pool Villa", "description": "Second view of the Pool Villa living pavilion in evening light, with the tassel chandelier lit and a dark timber dining table in the foreground set with green upholstered chairs. Low oatmeal sofas and a buttoned chaise group around a black coffee table, a woven globe pouffe and an amber shaded table lamp on a walnut console, while cane armchairs sit by the louvred windows. Through the central glass doors the private pool and the sea are in direct line of sight, which is the planning idea to copy, living furniture aligned on the water axis. Dark wood floors, slatted timber wall panels and stone accents keep the large room intimate.", "src": "images/Four Seasons Resort The Nam Hai/0657 - Four Seasons Resort The Nam Hai - Pool Villa - living and dining pavilion with ocean view.jpg", "source": "https://www.fourseasons.com/hoian/villa-residence-rentals/", "dimensions": "2560x1707", "size": 1089543}, {"number": "0658", "file": "0658 - Four Seasons Resort The Nam Hai - Heart of the Earth Spa - treatment pavilion with sunken bath and daybed.jpg", "resort": "Four Seasons Resort The Nam Hai", "space": "Heart of the Earth Spa", "description": "Spa treatment pavilion interior on the lotus pond, a long calm room in black stained timber and white plaster with slatted ceiling panels and woven roman blinds. In the foreground a wide daybed in ivory upholstery with large oatmeal cushions holds a low timber tray table with a black ceramic teapot, cup and a bowl of red roses. At the far end, a sunken rectangular bath in dark stone is filled with water and red petals, flanked by trays of rolled white towels and treatment vessels, with folding glass doors opening on both sides to the pond. The palette is almost monochrome, black, white and stone, with flowers as the only colour.", "src": "images/Four Seasons Resort The Nam Hai/0658 - Four Seasons Resort The Nam Hai - Heart of the Earth Spa - treatment pavilion with sunken bath and daybed.jpg", "source": "https://www.fourseasons.com/hoian/weddings/honeymoon/", "dimensions": "2560x1704", "size": 555076}, {"number": "0659", "file": "0659 - Four Seasons Resort The Nam Hai - Heart of the Earth Spa - treatment suite with massage table and pond view.jpg", "resort": "Four Seasons Resort The Nam Hai", "space": "Heart of the Earth Spa", "description": "Treatment suite in session, centred on a massage table dressed in white linen with a fluted timber base, positioned so the guest faces the lotus pond through open folding doors. To the left, a travertine topped vanity holds a rectangular stone basin, set against a full height pierced screen panel in a black and bronze geometric pattern, the same fretwork language used in the villas. A tall turned metal candle stand with a glass hurricane stands by the frosted glass door, and pale stone tiles run out to the pond edge. Useful detail for replication, the treatment furniture is kept low and sculptural so the water view stays uninterrupted.", "src": "images/Four Seasons Resort The Nam Hai/0659 - Four Seasons Resort The Nam Hai - Heart of the Earth Spa - treatment suite with massage table and pond view.jpg", "source": "https://press.fourseasons.com/hoian/hotel-news/2026/return_to_balance_offer/", "dimensions": "2560x1440", "size": 438434}, {"number": "0660", "file": "0660 - Four Seasons Resort The Nam Hai - Cafe Nam Hai - dining room with buffet canopy and cone pendants.jpg", "resort": "Four Seasons Resort The Nam Hai", "space": "Cafe Nam Hai", "description": "Cafe Nam Hai, the resort all day dining room, in dark stained timber with a low plank ceiling and garden windows on two sides. The centrepiece is the buffet counter in stone and aged brass, crowned by a huge rectangular canopy faced in pierced patterned metal that glows from within. Clusters of tall black cone pendants hang over the tables, banquettes are backed in dark woven fretwork panels, and barrel backed armchairs with spindle rails and taupe cushions pull up to dark wood tables set for breakfast. Wall lanterns in black metal and seeded glass repeat the pierced metal theme at smaller scale.", "src": "images/Four Seasons Resort The Nam Hai/0660 - Four Seasons Resort The Nam Hai - Cafe Nam Hai - dining room with buffet canopy and cone pendants.jpg", "source": "https://onlyluxe.com.au/four-seasons-resort-the-nam-hai-hoi-an-accommodation.html", "dimensions": "2560x1440", "size": 267537}, {"number": "0661", "file": "0661 - Four Seasons Resort The Nam Hai - La Sen - terrace dining with woven chairs and green lanterns.jpg", "resort": "Four Seasons Resort The Nam Hai", "space": "La Sen", "description": "La Sen terrace at the pool edge, where curved armchairs in warm timber with woven backs and pale cushions surround black pedestal tables set with green glassware, green ceramic plates and brass vases of white lotus. Folding glass doors and a slatted pergola roof with glass inserts connect the terrace to the interior, and chartreuse silk lanterns hang among the palm trunks outside, the single saturated colour accent of the scheme. Oversized green glazed planters with spiky foliage punctuate the seating rows, and stone paving in large grey slabs keeps the look cool. Patterned grey and white cushions provide the only print.", "src": "images/Four Seasons Resort The Nam Hai/0661 - Four Seasons Resort The Nam Hai - La Sen - terrace dining with woven chairs and green lanterns.jpg", "source": "https://www.fourseasons.com/hoian/dining/restaurants/la-sen/", "dimensions": "2560x1707", "size": 1311319}, {"number": "0662", "file": "0662 - Four Seasons Resort The Nam Hai - La Sen - interior dining room with bead screen and banquette seating.jpg", "resort": "Four Seasons Resort The Nam Hai", "space": "La Sen", "description": "Interior of La Sen showing the transition from terrace to dining room through folding glass doors, with a curved banquette in pale upholstery and teal and watercolour print cushions pulled up to a black turned pedestal table. Woven barrel chairs with timber top rails repeat from the terrace, tables carry the same green glass, green placemats and brass lotus vases, and a dramatic screen of hanging turned beads divides the room at the left. Huge green glazed urns and a terracotta planter act as internal landmarks, and the open kitchen glows behind slatted screens at the back. Ceiling fans and a slatted glass roof keep the room breezy rather than formal.", "src": "images/Four Seasons Resort The Nam Hai/0662 - Four Seasons Resort The Nam Hai - La Sen - interior dining room with bead screen and banquette seating.jpg", "source": "https://press.fourseasons.com/hoian/hotel-news/2025/recent-renovations/", "dimensions": "2560x1707", "size": 1162264}, {"number": "0663", "file": "0663 - Four Seasons Resort The Nam Hai - NAYUU - omakase counter with light timber joinery.jpg", "resort": "Four Seasons Resort The Nam Hai", "space": "NAYUU", "description": "NAYUU, the Japanese omakase restaurant, built almost entirely in pale natural timber, a striking contrast to the dark wood elsewhere in the resort. A long L shaped counter in light ash with a grey granite upstand seats sixteen on curved timber armchairs with blue grey striped upholstery, each place set with a dark placemat, folded white napkin, ceramic cup and chopsticks. Overhead, an elaborate interlocking beam ceiling in the Japanese joinery tradition carries the whole design, while slatted timber screens filter daylight along the garden side. Stone mosaic walls, a blackened steel hood and small ikebana style arrangements in wooden boxes complete the room.", "src": "images/Four Seasons Resort The Nam Hai/0663 - Four Seasons Resort The Nam Hai - NAYUU - omakase counter with light timber joinery.jpg", "source": "https://www.fourseasons.com/hoian/dining/", "dimensions": "2560x1708", "size": 915593}, {"number": "0664", "file": "0664 - Four Seasons Resort The Nam Hai - Sol & Sao - beach bar at dusk with woven pendants and stacked timber counters.jpg", "resort": "Four Seasons Resort The Nam Hai", "space": "Sol & Sao", "description": "Sol and Sao, the beach bar, photographed at dusk under a dense cluster of woven pendants in natural fibre, some plain basket weave and some with a diamond pattern, glowing over the lounge. Bar counters are built from stacked horizontal timber blocks in dark walnut tones with brass trim, and a leaf motif plaster relief covers the wall behind the bar. Seating mixes cord woven swivel chairs with grey patterned cushions, low sofas with blue floral pillows and small round stone topped tables, each with a woven table lantern. Dark stone floors, black posts and an indoor tree in the lounge area keep the beachside room grounded and shaded.", "src": "images/Four Seasons Resort The Nam Hai/0664 - Four Seasons Resort The Nam Hai - Sol & Sao - beach bar at dusk with woven pendants and stacked timber counters.jpg", "source": "https://www.fourseasons.com/hoian/dining/lounges/sol-and-sao/", "dimensions": "2560x1707", "size": 999479}, {"number": "0665", "file": "0665 - Four Seasons Resort The Nam Hai - The Bar - bar lounge with ring chandelier and cane back chairs.jpg", "resort": "Four Seasons Resort The Nam Hai", "space": "The Bar", "description": "The Bar, the resort central lounge bar, a tall pitched roof pavilion in dark timber and woven ceiling lining, lit by a grand circular chandelier hung with dozens of small glass lanterns. Round granite topped pedestal tables are ringed by curved cane back armchairs in dark stained wood with spindle bases, and taller cane bar stools line the window counters. The central bar in black stone and granite holds a wheeled drinks trolley in dark wood and brass, and wall lanterns echo the chandelier at smaller scale. Louvred windows and garden views on all sides make it a daytime lounge as much as an evening bar.", "src": "images/Four Seasons Resort The Nam Hai/0665 - Four Seasons Resort The Nam Hai - The Bar - bar lounge with ring chandelier and cane back chairs.jpg", "source": "https://www.lvtravel.vn/es/hotels/four-seasons-resort-the-nam-hai-h444.html", "dimensions": "2560x1708", "size": 1169068}, {"number": "0666", "file": "0666 - Four Seasons Resort The Nam Hai - Cooking Academy - cooking studio with patterned tiles and rattan chairs.jpg", "resort": "Four Seasons Resort The Nam Hai", "space": "Cooking Academy", "description": "The Nam Hai Cooking Academy, a teaching kitchen organised around a long dark stone topped table seating eight on bent rattan chairs with cane backs and rust coloured seat pads, over a traditional patterned cement tile rug in rust, cream and charcoal. The cooking counters and splashbacks are faced in blue and white geometric patterned tiles, open black shelving displays baskets, bowls and produce, and a vast woven hood hangs over the main range. Oversized cylindrical pendants in dark woven mesh with exposed bulbs provide the lighting, and folding doors open the studio to the herb garden. A strong reference for mixing patterned tile, black joinery and natural cane.", "src": "images/Four Seasons Resort The Nam Hai/0666 - Four Seasons Resort The Nam Hai - Cooking Academy - cooking studio with patterned tiles and rattan chairs.jpg", "source": "https://www.fourseasons.com/hoian/dining/", "dimensions": "2560x1583", "size": 1176804}, {"number": "0667", "file": "0667 - Six Senses Con Dao - Ocean Front Villa - bedroom view to pool terrace and television console.jpg", "resort": "Six Senses Con Dao", "space": "Ocean Front Villa", "description": "Bedroom photographed from the bed toward a wall of sliding glass, so the eye travels past a low teak television console to the private infinity pool, sun loungers and the sea beyond. Walls and ceiling are lined in warm horizontal reclaimed teak boards, and a sheer white mosquito net is gathered in soft swags from bamboo poles overhead, the signature softening layer in every villa. The palette is deliberately quiet, bleached timber, white cotton and pale stone flooring, letting the turquoise water supply the only strong colour. Copy the recipe of one timber tone used everywhere, gauze instead of curtains, and furniture kept low so the view is never interrupted.", "src": "images/Six Senses Con Dao/0667 - Six Senses Con Dao - Ocean Front Villa - bedroom view to pool terrace and television console.jpg", "source": "https://www.sixsensescondao.com/vn//villa/", "dimensions": "2560x1707", "size": 447461}, {"number": "0668", "file": "0668 - Six Senses Con Dao - Ocean View Residence - bedroom with draped canopy and pool doors.jpg", "resort": "Six Senses Con Dao", "space": "Ocean View Residence", "description": "Residence bedroom wrapped in honey toned teak panelling, with a vaulted timber ceiling and full height folding doors opening to the pool terrace and ocean. The bed corner is veiled by a sheer white canopy tied back in loose knots, its fabric pooling softly against the wood. Joinery is built in and flush, with woven panel inserts and simple ironmongery, so the room reads as a crafted timber box rather than a furnished space. A single yellow cushion provides the accent note against white linen and pale upholstery.", "src": "images/Six Senses Con Dao/0668 - Six Senses Con Dao - Ocean View Residence - bedroom with draped canopy and pool doors.jpg", "source": "https://www.sixsenses.com/en/hotels-resorts/asia-the-pacific/vietnam/con-dao/accommodation/", "dimensions": "2560x1707", "size": 554717}, {"number": "0669", "file": "0669 - Six Senses Con Dao - Ocean View Three-Bedroom Pool Villa - king bedroom with desk console and daybed.jpg", "resort": "Six Senses Con Dao", "space": "Ocean View Three-Bedroom Pool Villa", "description": "King bedroom arranged behind a long timber desk console that doubles as a headboard, carrying two tall cylindrical parchment lamps, glass water bottles and tumblers. The white dressed bed sits under a theatrical canopy of white gauze draped in swags from suspended bamboo poles, with a black ceiling fan above. Along the glass wall, a built in daybed carries cushions in cream, butter yellow and dusty pink, beside a stacked round timber side table. Wardrobes in dark teak with woven cane style panels line the inner wall, and sliding doors open to the infinity pool and bay view.", "src": "images/Six Senses Con Dao/0669 - Six Senses Con Dao - Ocean View Three-Bedroom Pool Villa - king bedroom with desk console and daybed.jpg", "source": "https://www.sixsenses.com/en/hotels-resorts/asia-the-pacific/vietnam/con-dao/accommodation/", "dimensions": "2560x1708", "size": 498171}, {"number": "0670", "file": "0670 - Six Senses Con Dao - Beachfront Three-Bedroom Pool Villa - king bedroom with woven lamps and chess daybed.jpg", "resort": "Six Senses Con Dao", "space": "Beachfront Three-Bedroom Pool Villa", "description": "Beachfront bedroom looking across the foot of a crisp white bed to a window daybed dressed in cream, blush and sand cushions, with a chess set laid out on a timber tray. Two oversized cylindrical lamps woven from natural fibre stand on the low headboard console, their texture echoed in the woven ceiling panels above. Gauze drapes in gathered swags from a bamboo and rope frame soften the teak lined walls and plank ceiling. Full height sliders frame the beach, pool edge and headland, making the seascape the room artwork.", "src": "images/Six Senses Con Dao/0670 - Six Senses Con Dao - Beachfront Three-Bedroom Pool Villa - king bedroom with woven lamps and chess daybed.jpg", "source": "https://www.sixsenses.com/en/hotels-resorts/asia-the-pacific/vietnam/con-dao/accommodation/", "dimensions": "2560x1708", "size": 623343}, {"number": "0671", "file": "0671 - Six Senses Con Dao - Ocean Front Residence - living room with banquette and ocean doors.jpg", "resort": "Six Senses Con Dao", "space": "Ocean Front Residence", "description": "Residence living room in pale washed teak, with a plank ceiling, dark ceiling fan and small brass pendant lights dotted overhead. A built in banquette along the right wall carries a row of cushions in rust, ochre and cream, facing a low timber media console and wall mounted screen. Folding glass doors centre the composition on two timber sun loungers, the infinity pool and the island dotted sea. The scheme is restrained and textural, plain upholstery, one row of saturated cushions and nothing on the walls but timber.", "src": "images/Six Senses Con Dao/0671 - Six Senses Con Dao - Ocean Front Residence - living room with banquette and ocean doors.jpg", "source": "https://www.sixsenses.com/en/hotels-resorts/asia-the-pacific/vietnam/con-dao/accommodation/", "dimensions": "2560x1707", "size": 579274}, {"number": "0672", "file": "0672 - Six Senses Con Dao - Beachfront Deluxe Pool Villa - interior daybed lounge with green cushions.jpg", "resort": "Six Senses Con Dao", "space": "Beachfront Deluxe Pool Villa", "description": "Villa interior lounge centred on a deep built in daybed dressed in white with fresh green cushions, set against teak plank walls beneath a draped white gauze canopy. Sliding doors open directly to the pool terrace, where two adjustable timber loungers face the sea and a woven fence screens the garden for privacy. A small round timber tray table with a tea set sits beside the daybed, and pale polished floors reflect the daylight. The mood is barefoot and uncluttered, with green used as the single accent against timber and white.", "src": "images/Six Senses Con Dao/0672 - Six Senses Con Dao - Beachfront Deluxe Pool Villa - interior daybed lounge with green cushions.jpg", "source": "https://www.sixsenses.com/en/hotels-resorts/asia-the-pacific/vietnam/con-dao/accommodation/", "dimensions": "2560x1708", "size": 473403}, {"number": "0673", "file": "0673 - Six Senses Con Dao - Ocean View Four-Bedroom Pool Villa - dining room with woven cloud pendant.jpg", "resort": "Six Senses Con Dao", "space": "Ocean View Four-Bedroom Pool Villa", "description": "Villa dining room dominated by a huge cloud shaped pendant woven from golden rattan, hung low over a timber dining table set with glassware, ceramics and purple toned linens. Teak chairs with woven backs surround the table, while plank walls and ceiling in mixed timber tones enclose the space like a cabin. Small black and brass spot pendants supplement the main light, and folding doors at the far end open to the pool terrace and sea. It shows how one oversized handmade light fitting can carry an otherwise simple room.", "src": "images/Six Senses Con Dao/0673 - Six Senses Con Dao - Ocean View Four-Bedroom Pool Villa - dining room with woven cloud pendant.jpg", "source": "https://www.sixsenses.com/en/hotels-resorts/asia-the-pacific/vietnam/con-dao/accommodation/", "dimensions": "1600x1067", "size": 249395}, {"number": "0674", "file": "0674 - Six Senses Con Dao - Pool Villa Bathroom - open plan bathroom with oval tub and daybed.jpg", "resort": "Six Senses Con Dao", "space": "Pool Villa Bathroom", "description": "Open plan villa bathroom viewed along its length, with a smooth oval soaking tub in the foreground surrounded by candles and amber glass amenities bottles. To the left, a floating timber vanity carries twin basins beneath cylindrical wall lights and hanging white towels, while woven cane fronted wardrobes close the right wall. At the far end, a raised daybed with two vivid green cushions sits before louvred windows and a garden door, blurring bathroom and lounge. Every surface is teak, board, cane or stone, a masterclass in a single material palette.", "src": "images/Six Senses Con Dao/0674 - Six Senses Con Dao - Pool Villa Bathroom - open plan bathroom with oval tub and daybed.jpg", "source": "https://www.sixsenses.com/en/hotels-resorts/asia-the-pacific/vietnam/con-dao/accommodation/", "dimensions": "2560x1707", "size": 611127}, {"number": "0675", "file": "0675 - Six Senses Con Dao - Ocean View Duplex Pool Villa - bathroom with round tub and ocean window.jpg", "resort": "Six Senses Con Dao", "space": "Ocean View Duplex Pool Villa", "description": "Duplex villa bathroom wrapped in dark stained teak boards, its wide picture window opened fully to the private pool and the blue sea beyond. A round freestanding tub sits in the foreground, paired with a long timber vanity carrying two dark vessel basins, a framed mirror and cylindrical parchment sconces. White towels hang from a rail beside the window, and a woven screen gives privacy without blocking light. The design lesson is the window treated as a wall of scenery, with fixtures kept low and horizontal so nothing competes.", "src": "images/Six Senses Con Dao/0675 - Six Senses Con Dao - Ocean View Duplex Pool Villa - bathroom with round tub and ocean window.jpg", "source": "https://www.sixsenses.com/en/hotels-resorts/asia-the-pacific/vietnam/con-dao/accommodation/", "dimensions": "2521x1599", "size": 550099}, {"number": "0676", "file": "0676 - Six Senses Con Dao - Six Senses Spa - couple suite treatment room with green tile wall.jpg", "resort": "Six Senses Con Dao", "space": "Six Senses Spa", "description": "Spa couple suite with two massage beds dressed in white linen and lime green cushions, set against a full wall of small deep green glazed tiles. The ceiling is a woven palm style finish in a warm natural tone, and tall sliding doors open to a private garden and stream view. Cylindrical wall sconces in white give soft vertical accents, and a small timber tray with treatment bowls rests between the beds. Green tile, white linen and woven ceiling are the three moves to copy from this room.", "src": "images/Six Senses Con Dao/0676 - Six Senses Con Dao - Six Senses Spa - couple suite treatment room with green tile wall.jpg", "source": "https://www.sixsenses.com/en/hotels-resorts/asia-the-pacific/vietnam/con-dao/wellness-spa/", "dimensions": "2560x1708", "size": 924013}, {"number": "0677", "file": "0677 - Six Senses Con Dao - Six Senses Spa - reception and welcome lounge with shell pendants.jpg", "resort": "Six Senses Con Dao", "space": "Six Senses Spa", "description": "Spa reception and welcome lounge, a long timber hall lit by a spectacular ceiling installation of shell like pendants, glass orbs and woven rattan ribbons swirling overhead. Seating is arranged in relaxed groups of cane lounge chairs, curved rattan sofas and pale upholstered armchairs with sage and mint cushions, on circular green woven rugs over bleached plank floors. A ribbed timber retail counter and low round coffee tables carry jars, plants and treatment products, while glass doors open to boardwalks and jungle planting. It is maximalist only at ceiling level, calm and natural everywhere else.", "src": "images/Six Senses Con Dao/0677 - Six Senses Con Dao - Six Senses Spa - reception and welcome lounge with shell pendants.jpg", "source": "https://www.sixsenses.com/en/hotels-resorts/asia-the-pacific/vietnam/con-dao/wellness-spa/", "dimensions": "2560x1708", "size": 1152883}, {"number": "0678", "file": "0678 - Six Senses Con Dao - Six Senses Spa - ayurvedic treatment room with suspended bronze vessel.jpg", "resort": "Six Senses Con Dao", "space": "Six Senses Spa", "description": "Ayurvedic treatment room in pale horizontal teak boards, centred on a single white dressed massage bed with a dark timber stand suspending a polished bronze shirodhara vessel above its head end. A small tray with folded towels, a bowl and greenery styles the bed, and floor to ceiling windows on two sides bring in the garden and stream. The ceiling is woven natural fibre, and a potted plant on the window sill is the only decoration. Restraint is the point, one beautiful ritual object in an empty, light filled timber room.", "src": "images/Six Senses Con Dao/0678 - Six Senses Con Dao - Six Senses Spa - ayurvedic treatment room with suspended bronze vessel.jpg", "source": "https://www.sixsenses.com/en/hotels-resorts/asia-the-pacific/vietnam/con-dao/wellness-spa/", "dimensions": "2560x1708", "size": 847627}, {"number": "0679", "file": "0679 - Six Senses Con Dao - Six Senses Spa - alchemy bar with green tiles and open shelving.jpg", "resort": "Six Senses Con Dao", "space": "Six Senses Spa", "description": "The spa Alchemy Bar, where guests blend their own scrubs and oils, fronted by a counter backed with deep green glazed tiles and open timber shelves holding glass jars, bottles, bowls and potted herbs. Sculptural pendants shaped like golden leaves hang from the woven ceiling, echoing the spa reception installation. Staff and guests gather around the work counter with mortars and ingredients laid out, giving the space a working apothecary feel rather than a retail one. Copy the open shelving, labelled jars and plants for an authentic workshop look.", "src": "images/Six Senses Con Dao/0679 - Six Senses Con Dao - Six Senses Spa - alchemy bar with green tiles and open shelving.jpg", "source": "https://www.sixsenses.com/en/hotels-resorts/asia-the-pacific/vietnam/con-dao/wellness-spa/", "dimensions": "2560x1708", "size": 900913}, {"number": "0680", "file": "0680 - Six Senses Con Dao - By the Beach Restaurant - breakfast buffet with woven globe pendants.jpg", "resort": "Six Senses Con Dao", "space": "By the Beach Restaurant", "description": "Breakfast buffet at By the Beach, arranged along a curved stone topped counter with wooden risers, glass storage jars, ceramic bowls and platters garnished with carved fruit. Above hang a cluster of enormous globe pendants woven from tangled natural vine, the defining decor gesture of the restaurant. Whitewashed textured walls, a reclaimed timber door and a framed chalkboard menu complete the backdrop, while full height glass opens to the terrace and the sea. The styling mixes market abundance with careful natural materials.", "src": "images/Six Senses Con Dao/0680 - Six Senses Con Dao - By the Beach Restaurant - breakfast buffet with woven globe pendants.jpg", "source": "https://www.sixsensescondao.com/dining/", "dimensions": "2560x1708", "size": 770814}, {"number": "0681", "file": "0681 - Six Senses Con Dao - Vietnamese by the Market - restaurant interior with chalkboard and carved panels.jpg", "resort": "Six Senses Con Dao", "space": "Vietnamese by the Market", "description": "Interior of Vietnamese by the Market, its walls built from mismatched antique carved teak door panels in differing tones, exactly the reclaimed panel construction the resort is known for. Simple timber tables are set with white bowls and small potted greens, paired with slatted timber chairs carrying green seat cushions. A large framed chalkboard lettered Vietnamese Kitchen hangs above the open counter, where glass jars and stacked crockery line the shelves, and woven bell pendants light each table. Rustic, local and deliberately unpolished, it is the fishing village theme at its most literal.", "src": "images/Six Senses Con Dao/0681 - Six Senses Con Dao - Vietnamese by the Market - restaurant interior with chalkboard and carved panels.jpg", "source": "https://www.sixsensescondao.com/dining/", "dimensions": "2560x1708", "size": 719077}, {"number": "0682", "file": "0682 - Six Senses Con Dao - Elephant Bar - bar pavilion at dusk with swing seating.jpg", "resort": "Six Senses Con Dao", "space": "Elephant Bar", "description": "Elephant Bar at dusk, an open timber pavilion glowing amber against the blue evening sky, its facade clad in antique carved teak panels. Along the deck runs the bar signature seating, a long row of swing seats and banquette cushions in cream, lime and orange, facing the bar counter inside. Low lanterns edge the deck, pendant lights warm the timber soffit, and the Lo Voi mountain silhouette closes the background. The image captures the bar as architecture and atmosphere in one frame.", "src": "images/Six Senses Con Dao/0682 - Six Senses Con Dao - Elephant Bar - bar pavilion at dusk with swing seating.jpg", "source": "https://www.sixsensescondao.com/dining/", "dimensions": "2560x1707", "size": 711526}, {"number": "0683", "file": "0683 - Six Senses Con Dao - Elephant Bar - timber bar counter with orange cushioned stools.jpg", "resort": "Six Senses Con Dao", "space": "Elephant Bar", "description": "Elephant Bar interior looking along a massive bar counter built from reclaimed teak panels, with louvred and fielded panel fronts in varied aged tones. High timber stools with cream seat pads and loose burnt orange cushions line both sides of the counter, and open shelves on the panelled back wall display bottles and glassware. Driftwood pieces, log sections and ceramics style the counter top, while the open sides frame trees, beach and sea. Heavy timber, one hot accent colour and found natural objects define the look.", "src": "images/Six Senses Con Dao/0683 - Six Senses Con Dao - Elephant Bar - timber bar counter with orange cushioned stools.jpg", "source": "https://www.sixsensescondao.com/dining/", "dimensions": "2560x1708", "size": 920846}, {"number": "0684", "file": "0684 - Six Senses Con Dao - Welcome Sala - arrival lounge with green and orange cushions.jpg", "resort": "Six Senses Con Dao", "space": "Welcome Sala", "description": "The Welcome Sala arrival pavilion, furnished as an outdoor living room with low timber framed sofas carrying deep lime green seat cushions and oversized scatter cushions in orange, cream and green stripes. A huge round drum coffee table in polished timber anchors the group, where a host serves welcome drinks to seated guests. White painted brick, bamboo slat screens and a plank ceiling with a black fan form the shell, open to the surrounding jungle planting. It sets the resort palette on arrival, natural timber, white masonry and saturated citrus accents.", "src": "images/Six Senses Con Dao/0684 - Six Senses Con Dao - Welcome Sala - arrival lounge with green and orange cushions.jpg", "source": "https://www.sixsensescondao.com", "dimensions": "2560x1708", "size": 752964}, {"number": "0685", "file": "0685 - Six Senses Krabey Island - Ocean Pool Villa - bedroom with daybed and canopy net.jpg", "resort": "Six Senses Krabey Island", "space": "Ocean Pool Villa", "description": "Wide bedroom and sitting room combined in one long pavilion space, with a timber framed daybed sofa at the centre dressed in white upholstery and cushions in coral pink, blush and pale blue. The king bed behind it carries crisp white linen under a sheer white canopy net suspended from a bamboo frame, against a full wall of vertical timber panelling with twin wall lamps. A round pedestal coffee table with a woven cane drum base, a dark framed lounge chair and a timber media cabinet complete the furniture set, all on pale oak boards with a flatweave rug in blue grey. Full height glazing and sliding doors run the length of the room, opening the interior to the trees and the sea beyond.", "src": "images/Six Senses Krabey Island/0685 - Six Senses Krabey Island - Ocean Pool Villa - bedroom with daybed and canopy net.jpg", "source": "https://www.sixsenses.com/en/hotels-resorts/asia-the-pacific/cambodia/krabey-island/accommodation/ocean-pool-villa/", "dimensions": "2560x1708", "size": 780072}, {"number": "0686", "file": "0686 - Six Senses Krabey Island - Ocean Pool Villa Suite - bedroom with deer mural and deck view.jpg", "resort": "Six Senses Krabey Island", "space": "Ocean Pool Villa Suite", "description": "Closer bedroom view built around a decorative wall panel in deep bronze brown, hand finished with a gold line mural of deer and foliage beside the bed. The bed is dressed in white linen with a grey upholstered bench at its foot, and a gathered sheer canopy drapes overhead from the ceiling. Pale timber floors and a small woven rug keep the palette light against the dark mural panel. Sliding glass doors fill the end wall and open to the sundeck, plunge pool and loungers, so the mural and canopy are always read against green canopy and sea.", "src": "images/Six Senses Krabey Island/0686 - Six Senses Krabey Island - Ocean Pool Villa Suite - bedroom with deer mural and deck view.jpg", "source": "https://flightbridge.com/directory/hotel/vdsv/six-senses-krabey-island/5948784/10577/true", "dimensions": "2048x1366", "size": 707319}, {"number": "0687", "file": "0687 - Six Senses Krabey Island - Hideaway Pool Villa Suite - living room with rattan wardrobe.jpg", "resort": "Six Senses Krabey Island", "space": "Hideaway Pool Villa Suite", "description": "Living room arranged as a calm sitting space between louvred timber shutters and full height glass. A low sofa in pale upholstery carries cushions in powder blue and blush pink, facing a tall double door wardrobe cabinet faced entirely in woven rattan, the signature storage piece of the villas. A black pedestal coffee table with a fruit bowl, a small timber side console with ceramics and a flatweave rug in teal blue complete the scheme. Through the open plan doorway the bedroom and its canopy bed are visible, and glass doors open to a deck daybed, showing how living, sleeping and terrace work as one suite. [below 1200px - best available]", "src": "images/Six Senses Krabey Island/0687 - Six Senses Krabey Island - Hideaway Pool Villa Suite - living room with rattan wardrobe.jpg", "source": "https://www.kiwicollection.com:443/hotel-detail/six-senses-krabey-island", "dimensions": "1024x576", "size": 119958}, {"number": "0688", "file": "0688 - Six Senses Krabey Island - Oceanfront Two-Bedroom Pool Villa - upstairs living area with sea view.jpg", "resort": "Six Senses Krabey Island", "space": "Oceanfront Two-Bedroom Pool Villa", "description": "Upstairs living area of the two bedroom villa, furnished with two facing sofas in pale upholstery and cushions in coral, pink and powder blue around a round timber coffee table with a woven cane drum base and a fruit arrangement. A black framed lounge chair, a floor lamp with a cream shade and a small desk console with a woven rattan cabinet sit against timber panelled walls decorated with a single dark carved wall piece. A blue grey flatweave rug anchors the seating on pale timber boards. Full height sliding glass opens to the deck and the sea, and an open doorway gives a glimpse of the freestanding oval tub in the bathroom beyond.", "src": "images/Six Senses Krabey Island/0688 - Six Senses Krabey Island - Oceanfront Two-Bedroom Pool Villa - upstairs living area with sea view.jpg", "source": "https://www.samraseaplane.com/partners/six-senses-krabey-island", "dimensions": "1800x1201", "size": 485076}, {"number": "0689", "file": "0689 - Six Senses Krabey Island - Ocean Pool Villa Suite - bathroom with round soaking tub.jpg", "resort": "Six Senses Krabey Island", "space": "Ocean Pool Villa Suite", "description": "Bathroom centred on a round freestanding soaking tub in white, set on dark stone flooring in front of a full height window wall to the jungle. Behind it, a dark charcoal stone vanity wall carries a round mirror flanked by sculptural shell like wall lights above a timber washstand with a white vessel basin. An upholstered bench in pale blue sits in front of the vanity, and a timber ladder rail holds folded white towels against vertical timber slat panelling. A woven pendant and warm timber throughout keep the dark stone scheme soft and residential rather than clinical.", "src": "images/Six Senses Krabey Island/0689 - Six Senses Krabey Island - Ocean Pool Villa Suite - bathroom with round soaking tub.jpg", "source": "https://www.scottdunn.com/cambodia/hotels/six-senses-krabey-island", "dimensions": "1920x772", "size": 144409}, {"number": "0690", "file": "0690 - Six Senses Krabey Island - AHA Restaurant - dining room with lattice wall and banquettes.jpg", "resort": "Six Senses Krabey Island", "space": "AHA Restaurant", "description": "Long all day dining room run as a single gallery between full height glass to the pool and sea on one side and a full length banquette on the other. The banquette wall is faced in a deep timber lattice screen with circular carved medallions, and the bench seating is dressed with cushions in cream, sand and pale yellow. Square dark topped tables are paired with curved rattan armchairs with tan cushions, and oversized white fabric drum pendants hang in a row from the beamed ceiling. Pale timber floors and the repeated lattice rhythm give the large room a crafted, residential scale.", "src": "images/Six Senses Krabey Island/0690 - Six Senses Krabey Island - AHA Restaurant - dining room with lattice wall and banquettes.jpg", "source": "https://www.sixsenses.com/en/hotels-resorts/asia-the-pacific/cambodia/krabey-island/dining/aha-restaurant/", "dimensions": "2560x1708", "size": 774975}, {"number": "0691", "file": "0691 - Six Senses Krabey Island - Tree Restaurant - evening dining room with woven ceiling.jpg", "resort": "Six Senses Krabey Island", "space": "Tree Restaurant", "description": "Evening view of the Tree dining room, where a dense woven ceiling canopy in natural fibre spreads over massive round timber columns. Clusters of turned timber teardrop pendants hang at different heights, lit warm against the blue dusk through the glass walls and the trees outside. A central banquette in teal upholstery with pale cushions is paired with pedestal timber tables and woven rattan chairs, while smaller candlelit tables line the windows. Woven baskets on a side table and lanterns at the columns keep the decor handmade and low key, letting texture do the work.", "src": "images/Six Senses Krabey Island/0691 - Six Senses Krabey Island - Tree Restaurant - evening dining room with woven ceiling.jpg", "source": "https://www.sixsenses.com/en/hotels-resorts/asia-the-pacific/cambodia/krabey-island/dining/tree-restaurant/", "dimensions": "2560x1708", "size": 1024507}, {"number": "0692", "file": "0692 - Six Senses Krabey Island - Tree Restaurant - show kitchen with carved stone relief.jpg", "resort": "Six Senses Krabey Island", "space": "Tree Restaurant", "description": "Second view of Tree, arranged around the open show kitchen, whose counter is fronted in dark stone and backed by shelving and hanging rails under a run of small pendants. One whole wall is a large carved stone relief panel with figurative Khmer style carving, lit from a skylight strip above, and a cluster of glossy turned timber teardrop pendants hangs over the main table. A long timber dining table is set for six with spindle back timber chairs with teal seat cushions. Dark stone, carved relief and polished timber give this end of the restaurant a more gallery like character than the woven ceiling room.", "src": "images/Six Senses Krabey Island/0692 - Six Senses Krabey Island - Tree Restaurant - show kitchen with carved stone relief.jpg", "source": "https://www.sixsenses.com/en/hotels-resorts/asia-the-pacific/cambodia/krabey-island/dining/tree-restaurant/", "dimensions": "2560x1724", "size": 942041}, {"number": "0693", "file": "0693 - Six Senses Krabey Island - Sunset Bar - bar counter at sunset with fish mobiles.jpg", "resort": "Six Senses Krabey Island", "space": "Sunset Bar", "description": "Straight on view of the Sunset Bar at dusk, centred on a long island bar counter with a dark stone top and a softly lit stone front, with backlit bottle shelving glowing behind it. Flat woven fish mobiles are suspended across the timber boarded ceiling, a direct reference to the island fishing village inspiration. Low daybeds and lounge chairs with teal cushions flank the bar on polished stone tiles, and open sides frame the sunset over the Gulf of Thailand. The palette is dark timber, warm stone and backlit amber, designed for the hour of day in the photograph.", "src": "images/Six Senses Krabey Island/0693 - Six Senses Krabey Island - Sunset Bar - bar counter at sunset with fish mobiles.jpg", "source": "https://www.sixsenses.com/en/hotels-resorts/asia-the-pacific/cambodia/krabey-island/dining/", "dimensions": "2560x1708", "size": 758780}, {"number": "0694", "file": "0694 - Six Senses Krabey Island - Sunset Bar - lounge seating with leaf mobiles.jpg", "resort": "Six Senses Krabey Island", "space": "Sunset Bar", "description": "Lounge end of the Sunset Bar, where timber framed armchairs with cream seats and vivid turquoise cushions are grouped around a round timber coffee table beside the open sea edge. Overhead, a large mobile of white leaf shaped woven pieces fills the timber ceiling, with a circular Sunset Bar sign at its centre, and woven lantern floor lights glow along the room. The long bar runs into the distance past stone tiled floors and timber columns, with candles lining the low wall to the water. Turquoise textiles against dark timber and stone are the bar signature accent colour.", "src": "images/Six Senses Krabey Island/0694 - Six Senses Krabey Island - Sunset Bar - lounge seating with leaf mobiles.jpg", "source": "https://www.sixsenses.com/en/hotels-resorts/asia-the-pacific/cambodia/krabey-island/dining/", "dimensions": "2560x1708", "size": 924773}, {"number": "0695", "file": "0695 - Six Senses Krabey Island - Six Senses Spa - treatment room with sea view.jpg", "resort": "Six Senses Krabey Island", "space": "Six Senses Spa", "description": "Double treatment room set high in the spa, with two massage beds dressed in natural linen throws and rolled towels, placed side by side on a dark polished timber floor. The whole end wall is glass, framing the sea and islands, with a small timber X frame side table and a tall arrangement of dried grasses between the beds. Woven blinds are drawn up at the side windows, and in the foreground a dark ceramic oil burner and treatment tray sit on a timber ledge. Exposed rafters, ceiling fans and plain linen keep the room elemental, with the view as the only decoration.", "src": "images/Six Senses Krabey Island/0695 - Six Senses Krabey Island - Six Senses Spa - treatment room with sea view.jpg", "source": "https://www.sixsenses.com/en/hotels-resorts/asia-the-pacific/cambodia/krabey-island/wellness-spa/", "dimensions": "2560x1707", "size": 669316}, {"number": "0696", "file": "0696 - Six Senses Krabey Island - Six Senses Spa - hydrotherapy pools in dark stone.jpg", "resort": "Six Senses Krabey Island", "space": "Six Senses Spa", "description": "Hydrotherapy suite built entirely in dark grey stone, with a sequence of still plunge pools at different levels connected by broad stone steps and stainless steel handrails. Tall narrow windows and a glazed side wall bring in shafts of daylight and views of planting, which reflect in the black water. Stone slab walls, a plain white ceiling and the absence of any applied decoration make the space read as a carved stone chamber. A glimpse of timber shelving with towels at the far end is the only warm note in a deliberately monastic palette.", "src": "images/Six Senses Krabey Island/0696 - Six Senses Krabey Island - Six Senses Spa - hydrotherapy pools in dark stone.jpg", "source": "https://www.sixsenses.com/en/hotels-resorts/asia-the-pacific/cambodia/krabey-island/gallery/", "dimensions": "2560x1708", "size": 863167}, {"number": "0697", "file": "0697 - Six Senses Krabey Island - Six Senses Spa - Alchemy Bar workshop table.jpg", "resort": "Six Senses Krabey Island", "space": "Six Senses Spa", "description": "The Alchemy Bar workshop room, centred on one very long solid timber communal table with slab legs, set with bowls, bottles and fresh ingredients for blending sessions. Upholstered stools with round pale seats and a low grey banquette with triangular cushions provide the seating, and open timber shelving along the walls holds rows of jars, bottles and glassware like a pantry. A cluster of pendants made from stacked turned timber pieces with white glass shades hangs over the table. Chalkboards, timber and glass storage keep the room feeling like a working apothecary rather than a bar.", "src": "images/Six Senses Krabey Island/0697 - Six Senses Krabey Island - Six Senses Spa - Alchemy Bar workshop table.jpg", "source": "https://flightbridge.com/directory/hotel/vdsv/six-senses-krabey-island/5948784/10577/true", "dimensions": "2048x1366", "size": 439553}, {"number": "0698", "file": "0698 - Six Senses Krabey Island - Six Senses Spa - reception with boat shaped desk.jpg", "resort": "Six Senses Krabey Island", "space": "Six Senses Spa", "description": "Spa reception dominated by a boat shaped reception desk in rich polished timber, its hull form a reference to local fishing boats. The room is divided by hanging screens and shelving strung with stacked turned timber beads on dark rods, which repeat as a motif across the whole space. A curved lounge chair in pale blue grey with a turquoise cushion, a drum side table in timber and a table lamp furnish the waiting corner, with candles in glass hurricanes on the stone floor. Grey stone flooring and glass to the gardens keep the sculptural timber pieces as the focus.", "src": "images/Six Senses Krabey Island/0698 - Six Senses Krabey Island - Six Senses Spa - reception with boat shaped desk.jpg", "source": "https://flightbridge.com/directory/hotel/vdsv/six-senses-krabey-island/5948784/10577/true", "dimensions": "2048x1366", "size": 580521}, {"number": "0699", "file": "0699 - Six Senses Krabey Island - Lobby - lounge with woven cocoon chairs.jpg", "resort": "Six Senses Krabey Island", "space": "Lobby", "description": "Main lobby lounge furnished with high backed woven cane cocoon chairs with pale cushions and turquoise pillows, arranged on a circular turquoise rug around low timber and stone tables. A low open bookcase in timber forms a room divider, filled with books and objects, and a cluster of large black woven basket pendants hangs from the timber ceiling. Timber framed armchairs with cream upholstery, stone tiled floors and open sides to the terrace, umbrellas and the sea complete the fisherman house inspired scheme. The mix of cane, blackened woven lighting and one saturated rug colour is the lobby recipe to copy.", "src": "images/Six Senses Krabey Island/0699 - Six Senses Krabey Island - Lobby - lounge with woven cocoon chairs.jpg", "source": "https://flightbridge.com/directory/hotel/vdsv/six-senses-krabey-island/5948784/10577/true", "dimensions": "2048x1366", "size": 848125}, {"number": "0700", "file": "0700 - Six Senses Krabey Island - Arrival Pavilion - rattan sofa terrace over the water.jpg", "resort": "Six Senses Krabey Island", "space": "Arrival Pavilion", "description": "Covered arrival terrace sitting directly over the water, furnished with a curved rattan sofa dressed in turquoise seat cushions and a row of blue and white pillows. Three open weave rattan drum stools with white round seat pads and a small oval timber coffee table complete the group, on large grey stone tiles under a timber boarded ceiling. A cluster of round organic framed mirrors decorates the stone wall, tall dark ceramic vases stand in the corner and a glazed balustrade keeps the sea view uninterrupted. Turquoise, natural rattan and grey stone set the colour story guests meet on arrival.", "src": "images/Six Senses Krabey Island/0700 - Six Senses Krabey Island - Arrival Pavilion - rattan sofa terrace over the water.jpg", "source": "https://www.lemispa.com/en/blog/studio-din-six-senses-krabey-island/", "dimensions": "1240x827", "size": 307609}, {"number": "0701", "file": "0701 - Zannier Hotels Phum Baitang - Terrace Villa - bedroom with grey sofa and timber wardrobe wall.jpg", "resort": "Zannier Hotels Phum Baitang", "space": "Terrace Villa", "description": "Terrace Villa bedroom in reclaimed timber, with a loose covered grey sofa at the foot of the bed facing the room and a full wall of planked wardrobe doors behind. The bed is dressed in white linen with grey cushions, and a dark wooden armchair stands by the window. Exposed roof timbers and wide floorboards give the room its structure. The arrangement to note is the sofa used as a room divider in a single open space.", "src": "images/Zannier Hotels Phum Baitang/0701 - Zannier Hotels Phum Baitang - Terrace Villa - bedroom with grey sofa and timber wardrobe wall.jpg", "source": "https://www.zannierhotels.com/phumbaitang", "dimensions": "2560x1707", "size": 770220}, {"number": "0702", "file": "0702 - Zannier Hotels Phum Baitang - Terrace Villa - living room with bench coffee table and veranda doors.jpg", "resort": "Zannier Hotels Phum Baitang", "space": "Terrace Villa", "description": "Living area of a Terrace Villa, photographed from behind a long bench style coffee table in weathered timber holding books and a small vase. A grey upholstered sofa faces it, with a side table and armchair near folding doors that open to the veranda and garden. Sheer curtains filter the light and a woven rug warms the dark floorboards. It shows the villa's calm formula: grey textiles, raw wood, and garden on every side.", "src": "images/Zannier Hotels Phum Baitang/0702 - Zannier Hotels Phum Baitang - Terrace Villa - living room with bench coffee table and veranda doors.jpg", "source": "https://www.zannierhotels.com/phumbaitang", "dimensions": "1718x844", "size": 410529}, {"number": "0703", "file": "0703 - Zannier Hotels Phum Baitang - Pool Villa - bedroom with rust coloured sofa and dark timber.jpg", "resort": "Zannier Hotels Phum Baitang", "space": "Pool Villa", "description": "Pool Villa bedroom with a rust coloured loose covered sofa placed across the middle of the room, facing the white dressed bed, an arrangement that splits sleeping and sitting zones. Walls are a mix of dark reclaimed timber panelling and pale plaster, with shuttered windows and a doorway to the bathroom wing. A low timber coffee table carries books and a pineapple. The single saturated textile colour against dark wood is the takeaway.", "src": "images/Zannier Hotels Phum Baitang/0703 - Zannier Hotels Phum Baitang - Pool Villa - bedroom with rust coloured sofa and dark timber.jpg", "source": "https://www.zannierhotels.com/phumbaitang", "dimensions": "2560x1707", "size": 595930}, {"number": "0704", "file": "0704 - Zannier Hotels Phum Baitang - Pool Villa - terrace with thatched daybed pavilion and plunge pool.jpg", "resort": "Zannier Hotels Phum Baitang", "space": "Pool Villa", "description": "Private terrace of a Pool Villa with a thatched roof daybed pavilion on a raised timber deck, dressed with grey cushions, beside the plunge pool. The villa's shingle clad wall and steps down from the bedroom frame one side, with dense planting screening the rest. A stone vessel sits at the deck edge. It records how the villas push living outdoors: a roofed bed, water, and complete privacy from planting.", "src": "images/Zannier Hotels Phum Baitang/0704 - Zannier Hotels Phum Baitang - Pool Villa - terrace with thatched daybed pavilion and plunge pool.jpg", "source": "https://www.zannierhotels.com/phumbaitang", "dimensions": "2560x1707", "size": 1491770}, {"number": "0705", "file": "0705 - Zannier Hotels Phum Baitang - Hang Bay Restaurant - dining hall with timber shelving and round tables.jpg", "resort": "Zannier Hotels Phum Baitang", "space": "Hang Bay Restaurant", "description": "Hang Bay restaurant, a long timber lined dining hall where round tables with white cloths and leather chairs run down one side and tall open shelving filled with ceramics, baskets and a standing figure sculpture fills the other. The pitched roof is exposed timber with small spotlights. Everything is brown, cream and clay coloured. The shelving wall used as both storage and gallery is the idea to take from this room.", "src": "images/Zannier Hotels Phum Baitang/0705 - Zannier Hotels Phum Baitang - Hang Bay Restaurant - dining hall with timber shelving and round tables.jpg", "source": "https://www.zannierhotels.com/phumbaitang", "dimensions": "2560x1707", "size": 817583}, {"number": "0706", "file": "0706 - Zannier Hotels Phum Baitang - Bay Phsar Restaurant - terrace dining at sunset over the pool.jpg", "resort": "Zannier Hotels Phum Baitang", "space": "Bay Phsar Restaurant", "description": "Terrace of the Bay Phsar poolside restaurant at sunset, with rattan chairs and timber tables set under a deep thatched roof, looking across the pool to rice fields and palm trees. A large woven pendant hangs above and place settings are kept simple with woven placemats. The light does the decorating. It is a model for open air dining: heavy shade, woven furniture, and a long view.", "src": "images/Zannier Hotels Phum Baitang/0706 - Zannier Hotels Phum Baitang - Bay Phsar Restaurant - terrace dining at sunset over the pool.jpg", "source": "https://www.zannierhotels.com/phumbaitang", "dimensions": "2560x1707", "size": 1524741}, {"number": "0707", "file": "0707 - Zannier Hotels Phum Baitang - Main Bar - bar lounge with slipcovered armchairs and trunk table.jpg", "resort": "Zannier Hotels Phum Baitang", "space": "Main Bar", "description": "The Main Bar, set in a century old farmhouse, with cream slipcovered armchairs and a carved wooden chair with an orange cushion arranged around a coffee table made from an old trunk and timber slab. Behind, the bar counter and bottle shelves sit under a glass pitched roof section, with bar stools in a row. Floors are wide dark boards. The mix of antique Khmer pieces and plain upholstery is exactly the Phum Baitang style.", "src": "images/Zannier Hotels Phum Baitang/0707 - Zannier Hotels Phum Baitang - Main Bar - bar lounge with slipcovered armchairs and trunk table.jpg", "source": "https://www.zannierhotels.com/phumbaitang", "dimensions": "2560x1707", "size": 795119}, {"number": "0708", "file": "0708 - Zannier Hotels Phum Baitang - Main Bar - rustic lounge with leather sofa and timber shelves.jpg", "resort": "Zannier Hotels Phum Baitang", "space": "Main Bar", "description": "A corner of the Main Bar lounge with a worn leather sofa piled with cushions, facing timber shelves built into the wall and stacked with ceramics and old objects. Sunlight falls through a window opening to the garden, raking across the rough plaster and wood. Colours are leather tan, grey and blackened timber. It reads as a collector's sitting room rather than a hotel bar, which is the effect to aim for.", "src": "images/Zannier Hotels Phum Baitang/0708 - Zannier Hotels Phum Baitang - Main Bar - rustic lounge with leather sofa and timber shelves.jpg", "source": "https://www.zannierhotels.com/phumbaitang", "dimensions": "1618x1080", "size": 300930}, {"number": "0709", "file": "0709 - Zannier Hotels Phum Baitang - Main Bar - antique chest detail with stoneware vase.jpg", "resort": "Zannier Hotels Phum Baitang", "space": "Main Bar", "description": "Detail of an antique carved chest in the Main Bar, topped with a tall crackle glazed stoneware vase and a lidded bronze vessel, set against louvred timber doors and a marble veined pillar. The chest's painted panels and worn edges show genuine age, used here as decor rather than restoration. A small study in the resort's antique led styling: one important old piece, two vessels, nothing else.", "src": "images/Zannier Hotels Phum Baitang/0709 - Zannier Hotels Phum Baitang - Main Bar - antique chest detail with stoneware vase.jpg", "source": "https://www.zannierhotels.com/phumbaitang", "dimensions": "2560x1707", "size": 597884}, {"number": "0710", "file": "0710 - Zannier Hotels Phum Baitang - Spa Temple - stone walled hall with antique table and floating shelves.jpg", "resort": "Zannier Hotels Phum Baitang", "space": "Spa Temple", "description": "The Spa Temple reception hall, a stone block walled room with floating timber shelves holding trailing plants and small vessels, arranged symmetrically around a doorway. In the centre stands a huge antique timber table with carved legs, flanked by two slipcovered armchairs in natural linen. The floor is grey stone tile. It demonstrates spa design through mass and shadow: heavy stone, one monumental table, soft chairs.", "src": "images/Zannier Hotels Phum Baitang/0710 - Zannier Hotels Phum Baitang - Spa Temple - stone walled hall with antique table and floating shelves.jpg", "source": "https://www.zannierhotels.com/phumbaitang", "dimensions": "2560x1707", "size": 858632}, {"number": "0711", "file": "0711 - Zannier Hotels Phum Baitang - Spa Temple - lounge with stone Buddha head and cushioned armchairs.jpg", "resort": "Zannier Hotels Phum Baitang", "space": "Spa Temple", "description": "Spa lounge corner with two cushioned armchairs in pale upholstery facing each other across a dark round side table, and a weathered stone Buddha head on the shelf between them under trailing greenery. Light is low and warm against grey plaster. The room sells calm through a single piece of Khmer sculpture and comfortable, plain seating. An easy formula to reproduce faithfully.", "src": "images/Zannier Hotels Phum Baitang/0711 - Zannier Hotels Phum Baitang - Spa Temple - lounge with stone Buddha head and cushioned armchairs.jpg", "source": "https://www.zannierhotels.com/phumbaitang", "dimensions": "2560x1707", "size": 318862}, {"number": "0712", "file": "0712 - Zannier Hotels Phum Baitang - Bay Phsar Pool Bar - thatched pavilion with rattan seating by the pool.jpg", "resort": "Zannier Hotels Phum Baitang", "space": "Bay Phsar Pool Bar", "description": "The Bay Phsar pool bar pavilion, a wide thatched roof on timber posts sheltering rows of rattan lounge chairs and tables beside the main pool. The bar structure is open on all sides with planting growing up to the deck edge. Furniture is uniformly woven, in honey tones against green. It shows how the resort furnishes large shared spaces entirely in natural fibre without monotony.", "src": "images/Zannier Hotels Phum Baitang/0712 - Zannier Hotels Phum Baitang - Bay Phsar Pool Bar - thatched pavilion with rattan seating by the pool.jpg", "source": "https://www.zannierhotels.com/phumbaitang", "dimensions": "2560x1707", "size": 1133295}, {"number": "0713", "file": "0713 - Zannier Hotels Phum Baitang - Terrace Villa - bathroom with oval stone tub and twin stone basins.jpg", "resort": "Zannier Hotels Phum Baitang", "space": "Terrace Villa", "description": "Villa bathroom photographed from the doorway, perfectly symmetrical: an oval stone soaking tub centred before a lattice screened window, flanked by twin stone trough basins on open timber vanity stands with folded grey towels below. Tall woven pendants hang beside the mirrors and the floor is dark stained boards with woven runners. It is the full Phum Baitang bathroom recipe in one frame. Image sourced from a luxury travel partner gallery because the resort's own media library publishes no bathroom photograph. [below 1200px - best available]", "src": "images/Zannier Hotels Phum Baitang/0713 - Zannier Hotels Phum Baitang - Terrace Villa - bathroom with oval stone tub and twin stone basins.jpg", "source": "https://cazloyd.com/cambodia/hotels/zannier-phum-baitang-siem-reap/", "dimensions": "882x659", "size": 104950}, {"number": "0714", "file": "0714 - Zannier Hotels Bai San Ho - Grand Bay Pool Villa - bedroom with paper lantern sconces and dark wall disc.jpg", "resort": "Zannier Hotels Bai San Ho", "space": "Grand Bay Pool Villa", "description": "Master bedroom of the Grand Bay Pool Villa, modelled on the Ede longhouse, with a low timber bed dressed in undyed natural linen against rammed earth walls. A square paper lantern sconce glows beside the bed and a large round blackened tray hangs as wall art, the room's single strong decorative gesture. Dark stained wood, woven matting and earthen plaster keep the palette deep and quiet. To recreate the look, pair a platform bed and plain linen with one oversized dark wall piece and warm, low lighting.", "src": "images/Zannier Hotels Bai San Ho/0714 - Zannier Hotels Bai San Ho - Grand Bay Pool Villa - bedroom with paper lantern sconces and dark wall disc.jpg", "source": "https://www.zannierhotels.com/hotels/bai-san-ho/", "dimensions": "2560x1707", "size": 559362}, {"number": "0715", "file": "0715 - Zannier Hotels Bai San Ho - Grand Bay Pool Villa - open kitchen with stoneware jars and carved wall plate.jpg", "resort": "Zannier Hotels Bai San Ho", "space": "Grand Bay Pool Villa", "description": "The villa's open kitchen corner, where a modern inset hob and steel tap sit in a reclaimed timber counter so the room still reads as a traditional house. Behind, a dark antique sideboard carries celadon stoneware jars and a small lamp, and a large carved circular wall plate hangs on the limewashed earth wall. A simple wooden dining table stands to the side. The lesson is layering: contemporary fittings kept visually quiet, with ceramics and one carved piece supplying the character.", "src": "images/Zannier Hotels Bai San Ho/0715 - Zannier Hotels Bai San Ho - Grand Bay Pool Villa - open kitchen with stoneware jars and carved wall plate.jpg", "source": "https://www.zannierhotels.com/hotels/bai-san-ho/", "dimensions": "2560x1708", "size": 616226}, {"number": "0716", "file": "0716 - Zannier Hotels Bai San Ho - Grand Bay Pool Villa - bathroom with black freestanding tub and long vanity.jpg", "resort": "Zannier Hotels Bai San Ho", "space": "Grand Bay Pool Villa", "description": "Bathroom in dark, moody tones with a black oval freestanding tub centred on the room and a long low vanity in dark timber with inset basins. Woven rattan pendants hang in a row above the mirror, casting patterned light on the rammed earth walls. A woven stool and folded rust red towels add the only colour. The recipe is restraint: one sculptural tub, honest materials, and textiles in a single earthy accent.", "src": "images/Zannier Hotels Bai San Ho/0716 - Zannier Hotels Bai San Ho - Grand Bay Pool Villa - bathroom with black freestanding tub and long vanity.jpg", "source": "https://www.zannierhotels.com/hotels/bai-san-ho/", "dimensions": "2560x1708", "size": 495317}, {"number": "0717", "file": "0717 - Zannier Hotels Bai San Ho - Beach Pool Villa - canopy bed bedroom with draped mosquito net.jpg", "resort": "Zannier Hotels Bai San Ho", "space": "Beach Pool Villa", "description": "Wide bedroom view in the Cham inspired Beach Pool Villa, centred on a four poster bed draped with a sheer white canopy net and dressed in pale linen with a teal throw. Woven rattan pendants hang either side, and open doorways lead through to a dressing area and bathroom beyond. Timber floors, a woven ceiling and limewashed walls keep the room soft and shaded. Recreate it with a simple poster frame, gauze drapes and layered natural fibre lighting.", "src": "images/Zannier Hotels Bai San Ho/0717 - Zannier Hotels Bai San Ho - Beach Pool Villa - canopy bed bedroom with draped mosquito net.jpg", "source": "https://www.zannierhotels.com/hotels/bai-san-ho/", "dimensions": "2560x1708", "size": 748821}, {"number": "0718", "file": "0718 - Zannier Hotels Bai San Ho - Beach Pool Villa - living room with daybed sofa and woven wall discs.jpg", "resort": "Zannier Hotels Bai San Ho", "space": "Beach Pool Villa", "description": "Living area arranged around a deep daybed sofa in grey green upholstery with cream and woven cushions, set against a wall hung with a cluster of round woven basket trays. Behind, the canopy bed is glimpsed through sheer drapes, showing the villa's open plan flow. A small bench with woven pillows and a vase of dried grasses complete the corner. The decorative system is woven wall pieces used as art, a signature Zannier move worth copying.", "src": "images/Zannier Hotels Bai San Ho/0718 - Zannier Hotels Bai San Ho - Beach Pool Villa - living room with daybed sofa and woven wall discs.jpg", "source": "https://www.zannierhotels.com/hotels/bai-san-ho/", "dimensions": "2560x1708", "size": 799611}, {"number": "0719", "file": "0719 - Zannier Hotels Bai San Ho - Beach Pool Villa - writing desk with rattan chair and barred window.jpg", "resort": "Zannier Hotels Bai San Ho", "space": "Beach Pool Villa", "description": "A quiet work corner with a plain reclaimed timber desk and a woven rattan campaign style chair, lit by a small table lamp with a pleated shade. The window is screened with vertical timber bars in the traditional manner, filtering the garden light. A low coffee table in the foreground holds green ceramic stools used as accents. The mood is monastic and useful: solid wood, one woven chair, and pattern only from light and shadow.", "src": "images/Zannier Hotels Bai San Ho/0719 - Zannier Hotels Bai San Ho - Beach Pool Villa - writing desk with rattan chair and barred window.jpg", "source": "https://www.zannierhotels.com/hotels/bai-san-ho/", "dimensions": "2560x1707", "size": 542534}, {"number": "0720", "file": "0720 - Zannier Hotels Bai San Ho - Beach Pool Villa - bathroom with oval tub and timber vanity desk.jpg", "resort": "Zannier Hotels Bai San Ho", "space": "Beach Pool Villa", "description": "Bathroom combining a white oval freestanding tub with a writing desk style vanity in dark wood, complete with stool and table lamp, so the room feels furnished rather than fitted. A tall window with a woven blind looks onto planting, and woven baskets serve as storage and laundry pieces. Warm plaster walls and timber floors run through from the bedroom. For recreation, treat the bathroom as a room: desk vanity, lamp light, and baskets instead of built in cabinetry.", "src": "images/Zannier Hotels Bai San Ho/0720 - Zannier Hotels Bai San Ho - Beach Pool Villa - bathroom with oval tub and timber vanity desk.jpg", "source": "https://www.zannierhotels.com/hotels/bai-san-ho/", "dimensions": "2560x1708", "size": 634067}, {"number": "0721", "file": "0721 - Zannier Hotels Bai San Ho - Hill Pool Villa - bedroom with rattan lounge chair and woven drum table.jpg", "resort": "Zannier Hotels Bai San Ho", "space": "Hill Pool Villa", "description": "Bedroom of a Hill Pool Villa in the Rade longhouse style, with a dressed king bed, a curved rattan lounge chair and a round woven drum side table holding a fruit bowl. Box lantern wall sconces in paper and timber give the room its gentle light, and a doorway frames a view through to the bathroom. Floors are dark woven matting over timber. The scheme to copy is a neutral bed, one sculptural woven chair and a woven table as the complete furniture set.", "src": "images/Zannier Hotels Bai San Ho/0721 - Zannier Hotels Bai San Ho - Hill Pool Villa - bedroom with rattan lounge chair and woven drum table.jpg", "source": "https://www.zannierhotels.com/hotels/bai-san-ho/", "dimensions": "2560x1708", "size": 703653}, {"number": "0722", "file": "0722 - Zannier Hotels Bai San Ho - Hill Pool Villa - bathroom with black tub and garden window.jpg", "resort": "Zannier Hotels Bai San Ho", "space": "Hill Pool Villa", "description": "Bathroom with a black freestanding tub placed before a full height window onto dense green planting, so bathing faces the garden. A long vanity in dark timber carries twin basins, with tall woven pendants above and rust red towels folded on the rail. The ceiling is dark stained, the walls earthen plaster. It shows the resort's bathroom formula at its best: dark, private, and opened completely to greenery on one side.", "src": "images/Zannier Hotels Bai San Ho/0722 - Zannier Hotels Bai San Ho - Hill Pool Villa - bathroom with black tub and garden window.jpg", "source": "https://www.zannierhotels.com/hotels/bai-san-ho/", "dimensions": "2560x1708", "size": 769843}, {"number": "0723", "file": "0723 - Zannier Hotels Bai San Ho - Paddy Field Villa - bedroom with window seat daybed and garden view.jpg", "resort": "Zannier Hotels Bai San Ho", "space": "Paddy Field Villa", "description": "Bedroom in a fisherman's stilt house style Paddy Field Villa, with a long built in window seat daybed piled with cream and rust cushions beneath a wide picture window. The bed is dressed in a faded teal woven throw, and a rattan chair and small round table stand beside it. Walls are deep indigo grey limewash and the ceiling is woven matting. Copy the built in daybed under the window; it is the piece that makes the room.", "src": "images/Zannier Hotels Bai San Ho/0723 - Zannier Hotels Bai San Ho - Paddy Field Villa - bedroom with window seat daybed and garden view.jpg", "source": "https://www.zannierhotels.com/hotels/bai-san-ho/", "dimensions": "2560x1707", "size": 1037075}, {"number": "0724", "file": "0724 - Zannier Hotels Bai San Ho - Paddy Field Villa - bedroom detail with bench and woven headboard.jpg", "resort": "Zannier Hotels Bai San Ho", "space": "Paddy Field Villa", "description": "Detail view of a Paddy Field Villa bedroom showing a woven panel headboard, a rustic timber bench with folded cushions at the wall, and an open fronted wardrobe niche with shelves lit from within. A small stool side table holds a clock radio and books beside a woven shade pendant. Everything is handmade in appearance: rough timber, woven fibre, plain cotton. It is a useful study in how much atmosphere texture alone can carry.", "src": "images/Zannier Hotels Bai San Ho/0724 - Zannier Hotels Bai San Ho - Paddy Field Villa - bedroom detail with bench and woven headboard.jpg", "source": "https://www.zannierhotels.com/hotels/bai-san-ho/", "dimensions": "2560x1707", "size": 752337}, {"number": "0725", "file": "0725 - Zannier Hotels Bai San Ho - Paddy Field Villa - bathroom with stone tub at garden window.jpg", "resort": "Zannier Hotels Bai San Ho", "space": "Paddy Field Villa", "description": "Bathroom photographed through the doorway, framing a solid stone freestanding tub set before a window with a woven blind and a view of tropical planting. A red towel hangs over the tub edge as the single colour note. Timber panelling and warm plaster surround it. The composition shows the resort's habit of placing the tub as a piece of furniture in front of the view rather than against a wall.", "src": "images/Zannier Hotels Bai San Ho/0725 - Zannier Hotels Bai San Ho - Paddy Field Villa - bathroom with stone tub at garden window.jpg", "source": "https://www.zannierhotels.com/hotels/bai-san-ho/", "dimensions": "2560x1707", "size": 698986}, {"number": "0726", "file": "0726 - Zannier Hotels Bai San Ho - Hoa Sen Spa - arched window hall with earthenware urn.jpg", "resort": "Zannier Hotels Bai San Ho", "space": "Hoa Sen Spa", "description": "Interior of the Hoa Sen Spa, a soaring earth toned hall with twin arched windows filled with bamboo planting and a single huge earthenware urn placed between them as sculpture. The walls are smooth terracotta plaster, lit by concealed uplights that wash the curves. There is almost no furniture; architecture and one pot do all the work. A powerful reference for spa design built on proportion and material rather than equipment.", "src": "images/Zannier Hotels Bai San Ho/0726 - Zannier Hotels Bai San Ho - Hoa Sen Spa - arched window hall with earthenware urn.jpg", "source": "https://www.zannierhotels.com/hotels/bai-san-ho/", "dimensions": "2560x1732", "size": 627442}, {"number": "0727", "file": "0727 - Zannier Hotels Bai San Ho - Hoa Sen Spa - spiral staircase in terracotta plaster.jpg", "resort": "Zannier Hotels Bai San Ho", "space": "Hoa Sen Spa", "description": "Looking down the spa's spiral staircase, a continuous sweep of terracotta plaster steps curling around a central well with a small green ceramic disc set into the floor below. A therapist carrying a treatment tray descends the curve, giving scale. The stair is pure vernacular modernism: local plaster, no balustrade ornament, form following the circle. It documents how the resort handles circulation spaces as designed moments.", "src": "images/Zannier Hotels Bai San Ho/0727 - Zannier Hotels Bai San Ho - Hoa Sen Spa - spiral staircase in terracotta plaster.jpg", "source": "https://www.zannierhotels.com/hotels/bai-san-ho/", "dimensions": "2560x1707", "size": 494196}, {"number": "0728", "file": "0728 - Zannier Hotels Bai San Ho - Lang Chai Restaurant - beachfront dining terrace with rattan chairs.jpg", "resort": "Zannier Hotels Bai San Ho", "space": "Lang Chai Restaurant", "description": "The beachfront Lang Chai restaurant at dusk, where round timber tables are set with woven rattan chairs under a huge woven pendant, looking straight out to the sea. Woven screens divide the terrace and the structure is dark stained timber throughout. Settings are simple: cloth napkins, glasses, and the view. Recreate the mood with oversized woven lighting, rattan seating and an unobstructed horizon line.", "src": "images/Zannier Hotels Bai San Ho/0728 - Zannier Hotels Bai San Ho - Lang Chai Restaurant - beachfront dining terrace with rattan chairs.jpg", "source": "https://www.zannierhotels.com/hotels/bai-san-ho/", "dimensions": "1731x1155", "size": 482801}, {"number": "0729", "file": "0729 - Zannier Hotels Bai San Ho - Nha O Restaurant - dining room with peacock rattan chairs.jpg", "resort": "Zannier Hotels Bai San Ho", "space": "Nha O Restaurant", "description": "The main Nha O restaurant, a high timber roofed hall filled with peacock style rattan armchairs around small round tables dressed with blue patterned ceramics. Tall windows line both sides and brass pendants hang from the coffered ceiling. The far wall is a glazed screen framing the hills. It is the resort's most formal room, yet the furniture is entirely woven and wooden, showing how rattan can carry a grand dining space.", "src": "images/Zannier Hotels Bai San Ho/0729 - Zannier Hotels Bai San Ho - Nha O Restaurant - dining room with peacock rattan chairs.jpg", "source": "https://www.zannierhotels.com/hotels/bai-san-ho/", "dimensions": "2560x1707", "size": 752009}, {"number": "0730", "file": "0730 - Zannier Hotels Bai San Ho - Ham Bar - bar interior with cane stools at dusk.jpg", "resort": "Zannier Hotels Bai San Ho", "space": "Ham Bar", "description": "Evening view of the Ham Bar, a dark timber room with a row of cane backed bar stools at the counter, small round tables with woven chairs in front, and globe pendants reflected in the window wall opening to the night garden. Bottles are displayed on open shelves behind the bar. The palette is tobacco, amber and black. A compact lesson in making a bar feel intimate with cane, low light and timber.", "src": "images/Zannier Hotels Bai San Ho/0730 - Zannier Hotels Bai San Ho - Ham Bar - bar interior with cane stools at dusk.jpg", "source": "https://www.zannierhotels.com/hotels/bai-san-ho/", "dimensions": "2560x1707", "size": 822587}, {"number": "0731", "file": "0731 - Zannier Hotels Bai San Ho - Reception - entrance hall with studded timber door and pottery urns.jpg", "resort": "Zannier Hotels Bai San Ho", "space": "Reception", "description": "The resort entrance, where a massive studded reclaimed timber door stands open into a hall floored with patterned tiles and furnished with oversized earthenware urns and dried grasses. Shelves with small ceramics line the warm brown wall. The arrival sets the whole design language in one view: antique timber, handmade pottery, and nothing glossy. Worth copying as an entrance formula for a house in this style.", "src": "images/Zannier Hotels Bai San Ho/0731 - Zannier Hotels Bai San Ho - Reception - entrance hall with studded timber door and pottery urns.jpg", "source": "https://www.zannierhotels.com/hotels/bai-san-ho/", "dimensions": "2560x1708", "size": 729379}, {"number": "0732", "file": "0732 - Keemala - Clay Pool Cottages - canopy bedroom.jpg", "resort": "Keemala", "space": "Clay Pool Cottages", "description": "The bedroom is built around a low timber platform bed dressed in plain white linen and layered with black and white geometric patterned cushions that carry the clan motif work of the resort. Sheer taupe canopy drapes are tied back from the four posts and fall in soft folds to the dark stone floor, where a cream rug with a bold blue geometric motif anchors the bed. Full height glass on both sides opens the room to rainforest planting and a glimpse of the private pool, while the headboard wall is panelled in dark stained timber with a woven screen set into it. To recreate the look, pair a chunky low timber bed frame with gauze canopy curtains, charcoal drapes, and a single strong geometric textile pattern repeated on cushions and rug.", "src": "images/Keemala/0732 - Keemala - Clay Pool Cottages - canopy bedroom.jpg", "source": "https://www.keemala.com/villa/clay-pool-cottages/", "dimensions": "1440x720", "size": 371303}, {"number": "0733", "file": "0733 - Keemala - Clay Pool Cottages - black stone tub bathroom.jpg", "resort": "Keemala", "space": "Clay Pool Cottages", "description": "The bathroom is viewed through open dark timber doors and centres on a matte black oval freestanding tub set on a floor of irregular black, white and grey stone mosaic in a crazy paving pattern. Behind the tub a screen of vertical bamboo slats is carved and pierced with a swirling organic pattern that filters light and acts as the room artwork. Walls are finished in rough textured clay toned plaster, with carved stone relief panels and woven shade wall sconces flanking the doorway, and a woven rattan pendant hangs above the tub. Recreation notes: keep every surface matte and hand worked, use one sculptural black tub as the only smooth form, and let bamboo, stone mosaic and textured plaster supply all of the pattern.", "src": "images/Keemala/0733 - Keemala - Clay Pool Cottages - black stone tub bathroom.jpg", "source": "https://www.keemala.com/villa/clay-pool-cottages/", "dimensions": "1440x864", "size": 520552}, {"number": "0734", "file": "0734 - Keemala - Clay Pool Cottages - thatched cottage and private pool.jpg", "resort": "Keemala", "space": "Clay Pool Cottages", "description": "The cottage sits elevated in dense rainforest under a steep double layered thatch roof with a soft, uneven silhouette that reads as part of the tree canopy. A timber balcony runs across the glazed front of the cottage and holds a pair of loungers, and beside it a rectangular private pool in pale stone with turquoise water steps down the hillside. Construction is dark timber framing with woven and thatch surfaces throughout, and the planting grows right up to the structure on every side. For recreation, the lesson is the exterior palette: raw thatch, weathered dark wood, pale stone pool coping and layered tropical green, with no painted colour anywhere.", "src": "images/Keemala/0734 - Keemala - Clay Pool Cottages - thatched cottage and private pool.jpg", "source": "https://www.keemala.com/villa/clay-pool-cottages/", "dimensions": "1440x768", "size": 820689}, {"number": "0735", "file": "0735 - Keemala - Tent Pool Villas - canopy bedroom opening to pool.jpg", "resort": "Keemala", "space": "Tent Pool Villas", "description": "The bedroom pairs a low platform bed in white linen with a draped canopy of sheer taupe fabric gathered from the ceiling, giving the fixed room the softness of a tent interior. Cushions in an indigo and white circular pattern sit against woven rattan bedhead panels, and a cream rug painted with large blue crescent motifs lies on the polished timber floor. Sliding glass walls open one whole side to the private pool and terrace, and a dark timber panelled unit houses the television opposite the bed. To recreate it, combine safari camp cues, draped gauze, dark wood joinery and a flat woven rug with one graphic motif, with tailored white bedding.", "src": "images/Keemala/0735 - Keemala - Tent Pool Villas - canopy bedroom opening to pool.jpg", "source": "https://www.keemala.com/villa/tent-pool-villas/", "dimensions": "1440x720", "size": 394717}, {"number": "0736", "file": "0736 - Keemala - Tent Pool Villas - barrel vanity bathroom with sea view.jpg", "resort": "Keemala", "space": "Tent Pool Villas", "description": "The bathroom is a study in travel inspired furniture, led by a vanity built like a timber barrel with dark metal bands and a round mirror in a timber frame above it. Open timber shelving holds rolled white towels and toiletries beside the vanity, and walls and floor are clad in a bold mosaic of irregular dark and pale stone shards. A matte black oval freestanding tub sits on a timber plinth in front of floor to ceiling glass with views across the forest to the sea, under a slatted timber ceiling. Recreation notes: the barrel vanity is the signature piece, supported by stone shard mosaic, black sanitaryware and warm slatted wood overhead.", "src": "images/Keemala/0736 - Keemala - Tent Pool Villas - barrel vanity bathroom with sea view.jpg", "source": "https://www.keemala.com/villa/tent-pool-villas/", "dimensions": "1440x720", "size": 453663}, {"number": "0737", "file": "0737 - Keemala - Tree Pool Houses - round daybed living level.jpg", "resort": "Keemala", "space": "Tree Pool Houses", "description": "The lower living level is furnished around a very large circular daybed upholstered in oatmeal fabric, dressed with black and white patterned cushions and set on a dark timber base. A woven rattan scoop chair and a live edge timber table sit in the foreground, and a black woven cocoon chair hangs from the ceiling on the terrace beyond the sliding glass wall. Dark timber ceilings and floors, full height glazing and a private infinity pool looking over forested hills complete the room, with an indigo upholstered chair adding the single colour accent at the rear. To recreate it, use one oversized round daybed as the anchor, keep joinery dark and horizontal, and hang one sculptural seat in the view line.", "src": "images/Keemala/0737 - Keemala - Tree Pool Houses - round daybed living level.jpg", "source": "https://www.keemala.com/villa/tree-pool-houses/", "dimensions": "1440x720", "size": 521068}, {"number": "0738", "file": "0738 - Keemala - Tree Pool Houses - upper canopy bedroom.jpg", "resort": "Keemala", "space": "Tree Pool Houses", "description": "The upper bedroom wraps its bed in sheer cream canopy drapes that fall from above the headboard to pool on the dark polished timber floor, a direct reference to furniture suspended in the trees. The bed is dressed in white linen with stacked cushions in black and white tribal geometric weaves, and a small tray with a coconut and flower offering sits on the bed as styling. One wall is fully glazed with the curved bamboo shell of the house visible outside, and bedside lamps have natural woven shades on rustic timber bases. Recreation notes: dark wood everywhere, one pale draped bed as the focal point, and pattern confined to cushion textiles.", "src": "images/Keemala/0738 - Keemala - Tree Pool Houses - upper canopy bedroom.jpg", "source": "https://www.keemala.com/villa/tree-pool-houses/", "dimensions": "1440x720", "size": 353088}, {"number": "0739", "file": "0739 - Keemala - Tree Pool Houses - pod exterior with plunge pool.jpg", "resort": "Keemala", "space": "Tree Pool Houses", "description": "The house is a teardrop shaped pod wrapped in a cage of bent bamboo and metal ribs that taper to a point at the top, giving the two storey villa the look of a hanging lantern or seed pod in the canopy. Glass fronts both levels, with a small balcony and hanging chair on the upper floor, and a circular plunge pool is set into a stone clad drum at the base of the pod. The surrounding rainforest grows close on all sides and is the only backdrop. For recreation of the style, the transferable elements are the ribbed woven shell, the round pool geometry, stone cladding in grey tones and furniture silhouettes that follow curves rather than straight lines.", "src": "images/Keemala/0739 - Keemala - Tree Pool Houses - pod exterior with plunge pool.jpg", "source": "https://www.keemala.com/villa/tree-pool-houses/", "dimensions": "2560x2560", "size": 1802736}, {"number": "0740", "file": "0740 - Keemala - Bird's Nest Pool Villas - living room with live edge table.jpg", "resort": "Keemala", "space": "Bird's Nest Pool Villas", "description": "The living area is arranged along a long live edge timber table with carved detail, set between a grey upholstered sofa dressed with indigo and white circular patterned cushions and the glazed wall to the pool terrace. At the far end of the open plan room the bed is enclosed in a domed sheer canopy that reads as a nest within the room, and through the glass another woven nest villa and the private lap pool are visible. Walls are panelled in dark vertical timber, the pitched ceiling is lined with woven material, and floors are polished dark wood. To recreate it, combine one very long rustic timber table, a single dome canopy over the bed, and indigo circular motifs as the repeating textile pattern.", "src": "images/Keemala/0740 - Keemala - Bird's Nest Pool Villas - living room with live edge table.jpg", "source": "https://www.keemala.com/villa/birds-nest-pool-villas/", "dimensions": "1440x720", "size": 431033}, {"number": "0741", "file": "0741 - Keemala - Bird's Nest Pool Villas - canopy bedroom with circular rug.jpg", "resort": "Keemala", "space": "Bird's Nest Pool Villas", "description": "The bedroom centres on a wide bed in crisp white linen with sheer white canopy drapes sweeping down from the vaulted ceiling and cushions in an indigo and white concentric circle pattern. A flat woven rug in cream with a large blue circular medallion motif lies on the dark timber floor at the foot of the bed. The ceiling follows the curve of the nest shell and is lined in woven panels with exposed dark ribs, while full height glass opens to the terrace and forest. A tailored lounge chair with matching patterned cushions sits in an alcove at the rear. Recreation notes: keep the palette to white, indigo and dark wood, and repeat one circular motif across cushions and rug at large scale.", "src": "images/Keemala/0741 - Keemala - Bird's Nest Pool Villas - canopy bedroom with circular rug.jpg", "source": "https://www.keemala.com/villa/birds-nest-pool-villas/", "dimensions": "1440x720", "size": 376111}, {"number": "0742", "file": "0742 - Keemala - Bird's Nest Pool Villas - stone tub bathroom.jpg", "resort": "Keemala", "space": "Bird's Nest Pool Villas", "description": "The bathroom places a rough hewn stone freestanding tub in front of glass doors that open to the pool terrace, so bathing faces the forest view. A stone vessel basin sits on a dark timber vanity beneath a large framed mirror on the timber panelled wall, and the floor is a mosaic of irregular pale and grey stone pieces. A circular open shower is defined by a curved metal rail with a heavy dark curtain, and two orange woven globe pendants provide the only warm colour accent. To recreate it, use carved stone for both tub and basin, keep metalwork in dark bronze tones, and let the stone mosaic floor carry the texture.", "src": "images/Keemala/0742 - Keemala - Bird's Nest Pool Villas - stone tub bathroom.jpg", "source": "https://www.keemala.com/villa/birds-nest-pool-villas/", "dimensions": "1440x750", "size": 461935}, {"number": "0743", "file": "0743 - Keemala - Bird's Nest Pool Villas - woven nest exterior at dusk.jpg", "resort": "Keemala", "space": "Bird's Nest Pool Villas", "description": "At dusk the villa shows its signature woven lattice shell, an interlaced free form mesh that wraps the whole structure like a giant nest perched on stilts in the rainforest. The private lap pool projects from the deck toward the trees and its supporting shell is clad in the same patterned mosaic lattice, so pool and villa read as one woven object. Warm light glows from the glazed interior, and two red loungers on the deck provide the single saturated colour note against the green and grey palette. For recreation, the key moves are the woven screen as both cladding and privacy device, the projecting pool, and lighting kept warm and low.", "src": "images/Keemala/0743 - Keemala - Bird's Nest Pool Villas - woven nest exterior at dusk.jpg", "source": "https://www.keemala.com/villa/birds-nest-pool-villas/", "dimensions": "2560x2560", "size": 1175780}, {"number": "0744", "file": "0744 - Keemala - Mala Spa - reception with carved ceiling dome.jpg", "resort": "Keemala", "space": "Mala Spa", "description": "The spa reception is crowned by an enormous circular ceiling dome carved with dense concentric pattern in a warm copper toned timber, which acts as the room chandelier and artwork in one. Below it an oval medallion of turquoise mosaic is set into the pale floor, echoing the dome above. Ladder style open shelving in dark timber displays treatment products along the walls, a carved timber reception desk sits at the rear, and a window bench with a teal cushion and black and white patterned pillows runs along the louvered glass wall. To recreate it, build the room around one oversized carved ceiling feature, then keep furniture low, open and made of dark wood and woven fibre.", "src": "images/Keemala/0744 - Keemala - Mala Spa - reception with carved ceiling dome.jpg", "source": "https://www.keemala.com/wellness-mala-spa/", "dimensions": "2560x1703", "size": 1180987}, {"number": "0745", "file": "0745 - Keemala - Mala Spa - treatment room with peacock mosaic mural.jpg", "resort": "Keemala", "space": "Mala Spa", "description": "The treatment room holds two massage beds side by side, dressed in natural linen covers with woven throws banded in deep purple across the foot. The curved rear wall is finished in deep teal and carries a large mosaic mural of a peacock in a flowering tree with small red boats below, the signature artwork of the room. A circular coved ceiling ring with a wire frame chandelier casts warm light over the beds, and a stone vessel basin on a dark timber vanity with a framed mirror serves the corner. Recreation notes: one mural wall, beds kept plain and low, dark stone floors, and all colour drawn from the artwork itself.", "src": "images/Keemala/0745 - Keemala - Mala Spa - treatment room with peacock mosaic mural.jpg", "source": "https://www.keemala.com/wellness-mala-spa/", "dimensions": "2560x1703", "size": 901779}, {"number": "0746", "file": "0746 - Keemala - Mala Restaurant - main dining room with rattan chairs.jpg", "resort": "Keemala", "space": "Mala Restaurant", "description": "The main dining room is lined with rattan dining chairs that have patterned woven backs and deep blue seat pads, grouped around solid timber tables on a dark plank floor. Ceiling, beams and columns are entirely clad in timber carved and printed with a swirling circular pattern, so the architecture itself supplies the decoration. Floor to ceiling glass opens one side to a terrace with red umbrellas and views over the forested hills, and a buffet counter runs along the rear wall. To recreate it, commit to one carved pattern across every hard surface, then keep tableware, glass and linen plain and natural.", "src": "images/Keemala/0746 - Keemala - Mala Restaurant - main dining room with rattan chairs.jpg", "source": "https://www.keemala.com/cuisine-restaurant/", "dimensions": "2560x1703", "size": 1081202}, {"number": "0747", "file": "0747 - Keemala - Mala Restaurant - banquette corner with swirl patterned walls.jpg", "resort": "Keemala", "space": "Mala Restaurant", "description": "This evening corner of the restaurant wraps a dark leather banquette with walls covered floor to ceiling in a bold gold and black circular swirl pattern, repeated on the upholstered backs of the dining chairs. Live edge timber tables are set with glassware, candles and folded napkins, and cushions in black and white circular patterns soften the banquette. Woven rattan lattice chairs with curved backs complete the setting, and the lighting is low and warm, glinting off the patterned walls. Recreation notes: the swirl pattern must appear on walls and chair backs together, with leather, cane and raw timber as the material base.", "src": "images/Keemala/0747 - Keemala - Mala Restaurant - banquette corner with swirl patterned walls.jpg", "source": "https://www.keemala.com/cuisine-restaurant/", "dimensions": "2560x1708", "size": 1225590}, {"number": "0748", "file": "0748 - Keemala - Mala Bar - copper bar counter and terrace.jpg", "resort": "Keemala", "space": "Mala Bar", "description": "The bar is fronted by a counter clad in hammered copper toned metal with a black stone top, backed by open timber shelves of bottles set against the same swirling patterned wall used in the restaurant. Rows of hanging pendants with exposed bulbs in wire and glass shades light the counter, where dark timber bar stools are placed for guests. The bar opens fully to a terrace with red umbrellas and rattan seating overlooking the forested hills, so the room works as an inside outside space. One staff member is serving a seated guest in the photograph. To recreate it, use one metallic counter front as the focal piece, open bottle shelving, and industrial style pendant lighting over the bar.", "src": "images/Keemala/0748 - Keemala - Mala Bar - copper bar counter and terrace.jpg", "source": "https://www.keemala.com/cuisine-restaurant/", "dimensions": "2560x1705", "size": 1081822}, {"number": "0749", "file": "0749 - Keemala - Lobby - lounge with louvered screens and daybeds.jpg", "resort": "Keemala", "space": "Lobby", "description": "The lobby lounge is a long room enclosed by floor to ceiling louvered screens that filter the daylight into stripes across the furniture and floor. Long low timber daybeds with rust red seat cushions and black and white patterned pillows line the window wall, facing woven chairs and tables in blue patterned fabric in the centre of the room. The ceiling is a dense woven timber lattice, and a very large rug in deep blue, turquoise and gold pattern covers most of the dark floor. To recreate it, layer louvered screening, low horizontal daybed seating, one oversized patterned rug and woven ceiling texture, keeping all furniture below window sill height.", "src": "images/Keemala/0749 - Keemala - Lobby - lounge with louvered screens and daybeds.jpg", "source": "https://www.keemala.com/gallery/", "dimensions": "1200x800", "size": 632778}, {"number": "0750", "file": "0750 - Phulay Bay a Ritz-Carlton Reserve - Reserve Pavilion - bedroom with Lanna painted doors and bolster sofa.jpg", "resort": "Phulay Bay, a Ritz-Carlton Reserve", "space": "Reserve Pavilion", "description": "A barrel vaulted white ceiling spans an oversized bed dressed in plain white linen on a pale terrazzo platform, with a low upholstered sofa built across its foot. The sofa carries two huge cylindrical bolster cushions with pleated ends and round timber centre discs, a signature Phulay Bay motif. Behind the bed, tall folding doors are hand painted in the Lanna style with serene figures in rust, ochre and indigo, and oversized cylindrical white lamps stand on stone plinths at each side. A small oval white table on turned timber legs sits in front, linen curtains soften one wall, and a deep purple painted wall in the adjoining dressing space gives the otherwise pale room its rich accent.", "src": "images/Phulay Bay a Ritz-Carlton Reserve/0750 - Phulay Bay a Ritz-Carlton Reserve - Reserve Pavilion - bedroom with Lanna painted doors and bolster sofa.jpg", "source": "https://www.ritzcarlton.com/en/hotels/kbvrz-phulay-bay-a-ritz-carlton-reserve/photos/", "dimensions": "2560x1707", "size": 520448}, {"number": "0751", "file": "0751 - Phulay Bay a Ritz-Carlton Reserve - Reserve Pavilion - bathroom with oval terrazzo tub and painted panels.jpg", "resort": "Phulay Bay, a Ritz-Carlton Reserve", "space": "Reserve Pavilion", "description": "A vast oval freestanding tub in speckled pale terrazzo fills the centre of the bathroom, ringed by a dark polished timber rail with brass grab handles and a traditional cross handle filler with a hand shower. Tall hand painted Lanna panels of women in striped silk sarongs frame the room on every side, turning the bathing space into a gallery. Beyond an arched opening, twin fluted lotus form basins sit before a pierced dark timber screen, with a deep purple wall glowing behind the fretwork. Floors and low walls are finished in the same warm terrazzo, keeping the palette calm against the vivid painted figures.", "src": "images/Phulay Bay a Ritz-Carlton Reserve/0751 - Phulay Bay a Ritz-Carlton Reserve - Reserve Pavilion - bathroom with oval terrazzo tub and painted panels.jpg", "source": "https://www.ritzcarlton.com/en/hotels/kbvrz-phulay-bay-a-ritz-carlton-reserve/photos/", "dimensions": "2560x1707", "size": 601443}, {"number": "0752", "file": "0752 - Phulay Bay a Ritz-Carlton Reserve - Reserve Pool Villa Sea View - bedroom with Lanna panels and garden doors.jpg", "resort": "Phulay Bay, a Ritz-Carlton Reserve", "space": "Reserve Pool Villa Sea View", "description": "The same grand bedroom formula is seen here in warmer reds, with an oversized white dressed bed, a foot sofa with cylindrical bolsters, and tall cylindrical lamps on terrazzo plinths. Folding doors hand painted with Lanna villagers in russet and terracotta tones line the wall behind the bed, reflected in a large arched mirror panel. To the right, full height timber and glass doors with a pierced carved valance open to a private garden, hung with long natural linen curtains. A quilted triangular Thai cushion rests at the head of the bed, and small bronze figures and turned wood vessels provide the quiet decorative layer.", "src": "images/Phulay Bay a Ritz-Carlton Reserve/0752 - Phulay Bay a Ritz-Carlton Reserve - Reserve Pool Villa Sea View - bedroom with Lanna panels and garden doors.jpg", "source": "https://www.ritzcarlton.com/en/hotels/kbvrz-phulay-bay-a-ritz-carlton-reserve/photos/", "dimensions": "2560x1707", "size": 592501}, {"number": "0753", "file": "0753 - Phulay Bay a Ritz-Carlton Reserve - Reserve Pool Villa Sea View - veranda daybed with curved timber screens and sea view.jpg", "resort": "Phulay Bay, a Ritz-Carlton Reserve", "space": "Reserve Pool Villa Sea View", "description": "From the foot of the bed the view runs through a wide arched opening to a shaded veranda and the Andaman Sea beyond. The veranda holds a broad built in daybed with a taupe mattress and two sculptural curved slatted timber headboards, each paired with a round ended bolster cushion. Dark timber posts and a shingled roof frame the terrace, with ceiling fans above and small bronze praying figures on the stone ledges at each side. Inside, the edge of the upholstered foot sofa, an oval white side table and tied back linen curtains show how completely the bedroom opens to outdoor living and the private pool in front of the daybed.", "src": "images/Phulay Bay a Ritz-Carlton Reserve/0753 - Phulay Bay a Ritz-Carlton Reserve - Reserve Pool Villa Sea View - veranda daybed with curved timber screens and sea view.jpg", "source": "https://www.ritzcarlton.com/en/hotels/kbvrz-phulay-bay-a-ritz-carlton-reserve/photos/", "dimensions": "2560x1707", "size": 620626}, {"number": "0754", "file": "0754 - Phulay Bay a Ritz-Carlton Reserve - Reserve Pool Villa - bathroom with petal filled double tub and courtyard basins.jpg", "resort": "Phulay Bay, a Ritz-Carlton Reserve", "space": "Reserve Pool Villa", "description": "A theatrical bathroom in deep crimson and burgundy, centred on an enormous double lobed terrazzo tub filled with floating flower petals and edged with a dark timber rim and brass fittings. Slender dark metal tray tables on splayed legs stand at each side of the tub. At the far end, twin fluted stone basins face a courtyard through a wide opening crowned by two tiers of pierced dark timber fretwork, with palm trunks and a terraced garden court visible outside. A hand painted panel of a dancing Lanna figure in a striped sarong covers one wall section, and mirrored panels multiply the candlelit warmth of the room.", "src": "images/Phulay Bay a Ritz-Carlton Reserve/0754 - Phulay Bay a Ritz-Carlton Reserve - Reserve Pool Villa - bathroom with petal filled double tub and courtyard basins.jpg", "source": "https://www.ritzcarlton.com/en/hotels/kbvrz-phulay-bay-a-ritz-carlton-reserve/photos/", "dimensions": "2560x1707", "size": 612819}, {"number": "0755", "file": "0755 - Phulay Bay a Ritz-Carlton Reserve - Ocean Pavilion - bedroom with painted doors and foot sofa.jpg", "resort": "Phulay Bay, a Ritz-Carlton Reserve", "space": "Ocean Pavilion", "description": "A bright barrel vaulted bedroom with the oversized bed placed across the room, white linen bedding, and the low upholstered foot sofa with its pair of cylindrical bolster cushions and timber centre discs. Hand painted folding doors in red, indigo and olive show cropped details of Lanna dress and textiles, and through them a quatrefoil bathroom niche is visible, giving the room its layered Moorish Thai character. Tall drum lamps stand on terrazzo plinths, a brass dome shaded table lamp sits by the terrace doors, and heavy dark timber doors open to palm planting outside. The effect is serene and monumental at once, with every surface either pale stone, white textile or rich painted colour.", "src": "images/Phulay Bay a Ritz-Carlton Reserve/0755 - Phulay Bay a Ritz-Carlton Reserve - Ocean Pavilion - bedroom with painted doors and foot sofa.jpg", "source": "https://www.ritzcarlton.com/en/hotels/kbvrz-phulay-bay-a-ritz-carlton-reserve/photos/", "dimensions": "2560x1707", "size": 557441}, {"number": "0756", "file": "0756 - Phulay Bay a Ritz-Carlton Reserve - Ocean Pavilion - bathroom with twin fluted basins and quatrefoil niche.jpg", "resort": "Phulay Bay, a Ritz-Carlton Reserve", "space": "Ocean Pavilion", "description": "Twin lotus fluted basins in speckled stone stand on a sculptural quatrefoil edged terrazzo island, served by tall polished chrome gooseneck taps with cross handles. Behind them, a huge quatrefoil cut out in the stone wall frames a softly lit niche, the Moorish quatrefoil being a recurring motif across the resort. Painted door panels in red striped textile patterns flank the vanity, a full height mirror in a dark timber frame leans into the composition, and small quatrefoil wall apertures pierce the side wall. A low brass tray table with a vase of purple orchids is the single decorative accent in an otherwise architectural room.", "src": "images/Phulay Bay a Ritz-Carlton Reserve/0756 - Phulay Bay a Ritz-Carlton Reserve - Ocean Pavilion - bathroom with twin fluted basins and quatrefoil niche.jpg", "source": "https://www.ritzcarlton.com/en/hotels/kbvrz-phulay-bay-a-ritz-carlton-reserve/photos/", "dimensions": "2560x1707", "size": 595752}, {"number": "0757", "file": "0757 - Phulay Bay a Ritz-Carlton Reserve - Beach Villa Ocean View - bedroom with red arches and timber daybed.jpg", "resort": "Phulay Bay, a Ritz-Carlton Reserve", "space": "Beach Villa Ocean View", "description": "A high vaulted bedroom under an exposed boarded roof, organised by sweeping undulating arches painted in graduated coral and crimson around the windows and doorways. Along the garden side runs a long timber daybed with a slatted back rail, a pale mattress and loose cushions in burnt orange linen. The main bed is simply dressed in white with a plain upholstered headboard beneath a large arched mirror in a gilt edged frame. A pair of gold lacquered wardrobe doors fills one arched niche, a round tray top side table stands on a dark pedestal base, and a woven natural fibre rug covers the centre of the stone floor.", "src": "images/Phulay Bay a Ritz-Carlton Reserve/0757 - Phulay Bay a Ritz-Carlton Reserve - Beach Villa Ocean View - bedroom with red arches and timber daybed.jpg", "source": "https://www.ritzcarlton.com/en/hotels/kbvrz-phulay-bay-a-ritz-carlton-reserve/photos/", "dimensions": "2560x1707", "size": 606532}, {"number": "0758", "file": "0758 - Phulay Bay a Ritz-Carlton Reserve - Beach Villa Ocean View - bathroom with magenta walls and freestanding tub.jpg", "resort": "Phulay Bay, a Ritz-Carlton Reserve", "space": "Beach Villa Ocean View", "description": "Saturated magenta walls and arches contrast with pale stone in this long bathroom, where a sleek white freestanding oval tub sits before a full height garden window planted with palms and bamboo. At the near end, fluted lotus form stone basins repeat the resort motif, lit by tall cylindrical wall shades. A hand painted door panel shows a Lanna woman among tropical leaves in purple, green and striped red silk. Blackened metal tripod side tables hold rolled towels, a small gilt topped table stands by an arched mirror, and large format stone tiles run across the floor, with light timber wardrobe joinery visible along the dressing passage.", "src": "images/Phulay Bay a Ritz-Carlton Reserve/0758 - Phulay Bay a Ritz-Carlton Reserve - Beach Villa Ocean View - bathroom with magenta walls and freestanding tub.jpg", "source": "https://www.ritzcarlton.com/en/hotels/kbvrz-phulay-bay-a-ritz-carlton-reserve/photos/", "dimensions": "2560x1707", "size": 592193}, {"number": "0759", "file": "0759 - Phulay Bay a Ritz-Carlton Reserve - Royal Beach Villa - bedroom with circular timber headboard and hanging lanterns.jpg", "resort": "Phulay Bay, a Ritz-Carlton Reserve", "space": "Royal Beach Villa", "description": "The Royal Beach Villa bedroom is dominated by a monumental polished timber headboard wall pierced by a huge circular keyhole opening, through which a vaulted passage and a vase of magenta orchids are framed. The oversized bed, dressed in ivory linen with bolster cushions at head and foot, extends into a wide upholstered daybed platform across its foot, scattered with small square cushions. Two blackened metal Moroccan style hanging lanterns with pierced star patterns flank the bed on chains. Painted timber panels, dark framed glass doors to the garden, and the signature deep purple courtyard wall visible outside complete this most dramatic of the villa interiors.", "src": "images/Phulay Bay a Ritz-Carlton Reserve/0759 - Phulay Bay a Ritz-Carlton Reserve - Royal Beach Villa - bedroom with circular timber headboard and hanging lanterns.jpg", "source": "https://www.ritzcarlton.com/en/hotels/kbvrz-phulay-bay-a-ritz-carlton-reserve/photos/", "dimensions": "2560x1707", "size": 535159}, {"number": "0760", "file": "0760 - Phulay Bay a Ritz-Carlton Reserve - Royal Beach Villa - bathroom with sunken tub in quatrefoil stone alcove.jpg", "resort": "Phulay Bay, a Ritz-Carlton Reserve", "space": "Royal Beach Villa", "description": "A sunken oval bathing pool is carved into a pale terrazzo alcove formed by overlapping quatrefoil and circular stone cut outs, so the bather sits inside a piece of abstract sculpture. Ribbed quatrefoil window screens filter soft light into the alcove, and smaller quatrefoil apertures pierce the side walls. Traditional chrome cross handle fittings with a telephone style hand shower serve the tub, and a round turned timber tray table holds rolled white towels beside it. Painted panels in muted sepia tones edge the frame, keeping the focus on the extraordinary stone geometry that defines the Royal Beach Villa bathroom.", "src": "images/Phulay Bay a Ritz-Carlton Reserve/0760 - Phulay Bay a Ritz-Carlton Reserve - Royal Beach Villa - bathroom with sunken tub in quatrefoil stone alcove.jpg", "source": "https://www.ritzcarlton.com/en/hotels/kbvrz-phulay-bay-a-ritz-carlton-reserve/photos/", "dimensions": "2560x1920", "size": 626492}, {"number": "0761", "file": "0761 - Phulay Bay a Ritz-Carlton Reserve - Sala Srichan Welcome Pavilion - interior with timber columns gong and candle wall.jpg", "resort": "Phulay Bay, a Ritz-Carlton Reserve", "space": "Sala Srichan Welcome Pavilion", "description": "Inside the Sala Srichan welcome pavilion, a forest of massive round timber columns with bulbous turned bases supports a soaring lattice roof of timber slats and glass tiles that floods the hall with patterned light. The open sided pavilion has no reception desk; instead a freestanding timber frame holds two bronze gongs that are sounded to greet arriving guests. Beyond the columns, the reflecting pool stretches toward the resort hedge wall in deep purple, studded with rows of small candle niches. Polished timber floors, the dark bronze of the gongs and the warm grain of the columns give the arrival space the gravity of a temple hall.", "src": "images/Phulay Bay a Ritz-Carlton Reserve/0761 - Phulay Bay a Ritz-Carlton Reserve - Sala Srichan Welcome Pavilion - interior with timber columns gong and candle wall.jpg", "source": "https://www.ritzcarlton.com/en/hotels/kbvrz-phulay-bay-a-ritz-carlton-reserve/photos/", "dimensions": "1921x2560", "size": 1168350}, {"number": "0762", "file": "0762 - Phulay Bay a Ritz-Carlton Reserve - Jampoon - dining room with timber beams banquette and coral chairs.jpg", "resort": "Phulay Bay, a Ritz-Carlton Reserve", "space": "Jampoon", "description": "A double height dining pavilion of massive dark timber beams and columns, with a long built in banquette in off white upholstery and embroidered botanical cushions running along a ribbed timber screen wall. Dining tables have glossy black tops on sculptural ribbed hourglass pedestals, paired with high backed armchairs in coral pink and cream upholstery with ebonised frames. Oversized red lacquer lidded urns crown the screen wall, a tall turned and ribbed floor vase holds white orchids, and cylindrical ribbed pendants hang over the sea facing tables. A bronze gong decorates the far wall, and full height glazing opens the room to the garden and the Andaman Sea.", "src": "images/Phulay Bay a Ritz-Carlton Reserve/0762 - Phulay Bay a Ritz-Carlton Reserve - Jampoon - dining room with timber beams banquette and coral chairs.jpg", "source": "https://www.ritzcarlton.com/en/hotels/kbvrz-phulay-bay-a-ritz-carlton-reserve/photos/", "dimensions": "2560x1707", "size": 862175}, {"number": "0763", "file": "0763 - Phulay Bay a Ritz-Carlton Reserve - Sri Trang - dining room with turquoise chairs and gong wall.jpg", "resort": "Phulay Bay, a Ritz-Carlton Reserve", "space": "Sri Trang", "description": "Sri Trang at night is intimate and dark, with square black tables dressed with natural linen runners, woven placemats, stoneware cups and candlelight. The dining chairs are fully upholstered in vivid turquoise fabric with dark timber arm frames, the single strong colour in the room. The end wall carries a dramatic installation of hammered metal gongs in gold, silver, bronze and blackened finishes, arranged as overlapping discs of many sizes. Small carved figurines stand on the side ledges, and floor to ceiling windows on both sides open to the dark tropical garden, keeping the focus on the glowing gong wall and the table settings.", "src": "images/Phulay Bay a Ritz-Carlton Reserve/0763 - Phulay Bay a Ritz-Carlton Reserve - Sri Trang - dining room with turquoise chairs and gong wall.jpg", "source": "https://www.ritzcarlton.com/en/hotels/kbvrz-phulay-bay-a-ritz-carlton-reserve/photos/", "dimensions": "2510x1412", "size": 405370}, {"number": "0764", "file": "0764 - Phulay Bay a Ritz-Carlton Reserve - Lae Lay - dining room with slatted timber chairs and sea view.jpg", "resort": "Phulay Bay, a Ritz-Carlton Reserve", "space": "Lae Lay", "description": "Lae Lay is a calm sea facing dining room in warm mid tone timber, with square pedestal tables and slatted back dining chairs with pale upholstered seat pads. The pitched shingle roof is visible through a glazed gable, hung with pierced metal Moroccan lanterns in aged bronze and verdigris finishes on long chains. Hand painted Lanna panels of women in striped sarongs frame the view on both sides, acting as decorative door leaves between the dining room and the terrace. Polished timber floors reflect the daylight, blue tinted glassware accents each setting, and the limestone islands of the Andaman Sea close the composition beyond the trees.", "src": "images/Phulay Bay a Ritz-Carlton Reserve/0764 - Phulay Bay a Ritz-Carlton Reserve - Lae Lay - dining room with slatted timber chairs and sea view.jpg", "source": "https://www.ritzcarlton.com/en/hotels/kbvrz-phulay-bay-a-ritz-carlton-reserve/photos/", "dimensions": "2560x1707", "size": 911894}, {"number": "0765", "file": "0765 - Phulay Bay a Ritz-Carlton Reserve - Chomtawan - sunset lounge terrace with thatched pavilion and deck sofas.jpg", "resort": "Phulay Bay, a Ritz-Carlton Reserve", "space": "Chomtawan", "description": "The Chomtawan sunset lounge is an open timber deck under a steep thatched pavilion roof, furnished for slow evening drinks facing the Andaman Sea. Low framed outdoor sofas and armchairs in weathered grey upholstery are grouped around small side tables at the edge of the deck, with two pale stone table lamps glowing under the roof. Dark stained timber posts and diagonal braces carry the thatch, and the deck boards run down toward a still pond that mirrors the orange sunset sky. It is the resort bar terrace in its simplest form, where the furniture is deliberately quiet and the light and seascape do the work.", "src": "images/Phulay Bay a Ritz-Carlton Reserve/0765 - Phulay Bay a Ritz-Carlton Reserve - Chomtawan - sunset lounge terrace with thatched pavilion and deck sofas.jpg", "source": "https://www.ritzcarlton.com/en/hotels/kbvrz-phulay-bay-a-ritz-carlton-reserve/photos/", "dimensions": "2560x1728", "size": 781940}, {"number": "0766", "file": "0766 - Phulay Bay a Ritz-Carlton Reserve - The Spa at Phulay Bay - treatment room with twin beds and bamboo screens.jpg", "resort": "Phulay Bay, a Ritz-Carlton Reserve", "space": "The Spa at Phulay Bay", "description": "A private couples treatment room in dark stained timber, with two massage beds dressed in cream linen with woven gold runners, rolled towels, orchid petals and small black lacquer trays with candles. Slate blue upholstered banquettes with olive silk cushions line both sides of the room behind vertical bamboo pole screens. Wide sliding doors open to a private timber deck with two further daybeds, a small plunge pool edge and a lush garden with a Thai garden lantern. The palette of dark wood, cream textile and muted blue grey upholstery is designed to lower the pulse before treatment begins.", "src": "images/Phulay Bay a Ritz-Carlton Reserve/0766 - Phulay Bay a Ritz-Carlton Reserve - The Spa at Phulay Bay - treatment room with twin beds and bamboo screens.jpg", "source": "https://www.ritzcarlton.com/en/hotels/kbvrz-phulay-bay-a-ritz-carlton-reserve/photos/", "dimensions": "2560x1707", "size": 574944}, {"number": "0767", "file": "0767 - Phulay Bay a Ritz-Carlton Reserve - The Spa at Phulay Bay - reception lounge with lattice screens and drum pendants.jpg", "resort": "Phulay Bay, a Ritz-Carlton Reserve", "space": "The Spa at Phulay Bay", "description": "The spa reception is a double height lounge wrapped in blackened geometric lattice screens that filter daylight into fine patterns across the room. A cluster of large cream drum pendants hangs over a seating group of an ochre upholstered sofa, plum coloured armchairs with patterned cushions, a dark timber coffee table and a woven rug. To one side, a full wall of backlit open shelving displays spa retail products in amber lit cubbies, giving the lounge a boutique gallery feel. Tall grasses in a black vase, orchid arrangements and views straight into the tropical garden complete a reception that works as a serene living room rather than a desk.", "src": "images/Phulay Bay a Ritz-Carlton Reserve/0767 - Phulay Bay a Ritz-Carlton Reserve - The Spa at Phulay Bay - reception lounge with lattice screens and drum pendants.jpg", "source": "https://www.ritzcarlton.com/en/hotels/kbvrz-phulay-bay-a-ritz-carlton-reserve/photos/", "dimensions": "2560x1707", "size": 764282}, {"number": "0768", "file": "0768 - Soneva Fushi - 1 Bedroom Villa Suite with Pool - vaulted bedroom with desk and sitting area beyond.jpg", "resort": "Soneva Fushi", "space": "1 Bedroom Villa Suite with Pool", "description": "A long vaulted bedroom under a steep thatched roof with exposed timber trusses, rafters and a central ceiling fan. The king bed in the foreground has a chunky dark timber post frame, crisp white bedding and woven neutral cushions, facing a low whitewashed sitting area with teal cushions at the far glazed wall. To the left a dark timber desk with drawers holds a shaded table lamp and is paired with a sculptural black metal chair with scrollwork back. Canvas roman blinds, whitewashed textured walls, a pale timber cabinet and stone toned flooring complete the barefoot, handcrafted palette, with garden views on three sides.", "src": "images/Soneva Fushi/0768 - Soneva Fushi - 1 Bedroom Villa Suite with Pool - vaulted bedroom with desk and sitting area beyond.jpg", "source": "https://soneva.com/villa/soneva-fushi-1-bedroom-suite-with-pool/", "dimensions": "1920x1280", "size": 492635}, {"number": "0769", "file": "0769 - Soneva Fushi - 1 Bedroom Crusoe with Pool - upstairs bedroom under woven thatch ceiling.jpg", "resort": "Soneva Fushi", "space": "1 Bedroom Crusoe with Pool", "description": "An intimate upstairs bedroom tucked under a sloping woven thatch ceiling with dark timber battens and a deep stained tie beam. The low bed is dressed simply in white linen with two woven geometric cushions in warm neutrals, flanked by timber table lamps with natural parchment toned shades. Whitewashed walls, a small timber framed window with a rolled bamboo blind and a rustic stick balustrade reinforce the castaway character. The restrained furniture and natural fibres keep the focus on texture, shadow and the hand built roof above.", "src": "images/Soneva Fushi/0769 - Soneva Fushi - 1 Bedroom Crusoe with Pool - upstairs bedroom under woven thatch ceiling.jpg", "source": "https://soneva.com/villa/soneva-fushi-1-bedroom-crusoe-with-pool/", "dimensions": "1920x1280", "size": 284773}, {"number": "0770", "file": "0770 - Soneva Fushi - 2 Bedroom Crusoe Residence with Pool Villa 44 - bedroom with orange daybed and patchwork trunk.jpg", "resort": "Soneva Fushi", "space": "2 Bedroom Crusoe Residence with Pool Villa 44", "description": "A bright bedroom draped with sheer white mosquito netting gathered above the bed, with white bedding in the foreground and garden doors opening to planting on the left. At the foot of the bed sits a patchwork timber trunk chest with metal handles, a signature storage piece that also hides technology in these villas. Beyond it a curved daybed carries vivid orange cushions, matched by the orange seat pad of a woven back desk chair at a long pale timber desk with drawers. Timber framed glazing, thatch and pole rafters overhead and pale stone tiles keep the strong colour accents grounded in natural material.", "src": "images/Soneva Fushi/0770 - Soneva Fushi - 2 Bedroom Crusoe Residence with Pool Villa 44 - bedroom with orange daybed and patchwork trunk.jpg", "source": "https://soneva.com/villa/soneva-fushi-2-bedroom-crusoe-residence-with-pool-villa-44/", "dimensions": "1799x1199", "size": 410041}, {"number": "0771", "file": "0771 - Soneva Fushi - 2 Bedroom Crusoe Residence with Pool Villa 44 - open air bathroom with twin metal bowl basins.jpg", "resort": "Soneva Fushi", "space": "2 Bedroom Crusoe Residence with Pool Villa 44", "description": "An open air garden bathroom centred on a solid pale timber vanity with a single drawer, open towel shelves below and carved fish details at the sides. Two hammered metal bowl basins sit on the top with tall curved taps, below twin mirrors framed in rough natural branches and lit by glowing cylindrical pendants. Behind, a shallow water garden with stone stepping pads, stone tiled walls and dense tropical planting wraps the space, with white towels on a ladder rail reflected in the mirrors. The scheme mixes raw timber, metal, stone and water for a bathing room that is furniture led rather than fitted.", "src": "images/Soneva Fushi/0771 - Soneva Fushi - 2 Bedroom Crusoe Residence with Pool Villa 44 - open air bathroom with twin metal bowl basins.jpg", "source": "https://soneva.com/villa/soneva-fushi-2-bedroom-crusoe-residence-with-pool-villa-44/", "dimensions": "2048x1365", "size": 671327}, {"number": "0772", "file": "0772 - Soneva Fushi - 9 Bedroom Estate Villa 11 - bedroom with louvred doors to palm balcony.jpg", "resort": "Soneva Fushi", "space": "9 Bedroom Estate Villa 11", "description": "A calm bedroom detail with a white dressed bed in the foreground, a glass panel headboard detail and an articulated bedside lamp with a natural shade on a small timber side table. Tall dark timber doors fill the far wall, combining louvres, glazing and full height glass panels that open to a stick railed balcony framed by palm fronds. Cylindrical wall lights with warm natural shades punctuate the whitewashed undulating walls, and canvas blinds sit above the doors. The contrast of dark timber, white plaster and green foliage is the estate villa language in miniature.", "src": "images/Soneva Fushi/0772 - Soneva Fushi - 9 Bedroom Estate Villa 11 - bedroom with louvred doors to palm balcony.jpg", "source": "https://soneva.com/villa/soneva-fushi-9-bedroom-estate-villa-11/", "dimensions": "2048x1366", "size": 484779}, {"number": "0773", "file": "0773 - Soneva Fushi - 9 Bedroom Estate Villa 11 - bathroom with timber encased bath under blinds.jpg", "resort": "Soneva Fushi", "space": "9 Bedroom Estate Villa 11", "description": "A bathroom built around a long oval bath fully encased in warm timber with a broad timber surround and a curved end, set beneath a full width window wall. Fine timber venetian blinds filter the jungle view and cast striped light across the dark timber floor, while a cylindrical wall light glows beside a smaller side window. Exposed pole rafters and thatch show in the ceiling above whitewashed walls, and simple chrome bath fittings keep the focus on wood grain and light. It reads as a piece of joinery furniture scaled to the room rather than a standard fitted bath.", "src": "images/Soneva Fushi/0773 - Soneva Fushi - 9 Bedroom Estate Villa 11 - bathroom with timber encased bath under blinds.jpg", "source": "https://soneva.com/villa/soneva-fushi-9-bedroom-estate-villa-11/", "dimensions": "1366x2048", "size": 534062}, {"number": "0774", "file": "0774 - Soneva Fushi - 9 Bedroom Estate Villa 11 - corner desk with branch form chair and terrace daybed.jpg", "resort": "Soneva Fushi", "space": "9 Bedroom Estate Villa 11", "description": "A corner study formed by a continuous pale timber desk wrapping two glazed walls, with drawer pedestals, dark round pulls and a desk lamp with a conical natural shade. The chair is made from irregular branch timber with a woven looking back detail and a pale seat cushion, reinforcing the hand made quality of the villa furniture. Canvas blinds roll above the windows, cylindrical pendants hang by the sliding door, and through the glass a terrace daybed with white cushioning and a timber table sit under thatch and pole rafters. Jungle planting fills every view, so the work space feels embedded in the canopy.", "src": "images/Soneva Fushi/0774 - Soneva Fushi - 9 Bedroom Estate Villa 11 - corner desk with branch form chair and terrace daybed.jpg", "source": "https://soneva.com/villa/soneva-fushi-9-bedroom-estate-villa-11/", "dimensions": "1366x2048", "size": 514640}, {"number": "0775", "file": "0775 - Soneva Fushi - 9 Bedroom Estate Villa 11 - open dining pavilion with woven back chairs.jpg", "resort": "Soneva Fushi", "space": "9 Bedroom Estate Villa 11", "description": "An open dining pavilion on a wide timber deck, with a very long dark plank dining table seating twelve on high backed timber chairs with woven strap backs, pale seat pads and round mustard cushions. The ceiling is lined with tightly packed timber discs on pole beams, with leaf bladed ceiling fans and a suspended driftwood style centrepiece above the table. Woven hanging pod chairs swing at both sides of the pavilion, and beyond the posts the pool, thatched pavilions and the main residence complete the estate setting. A simple seed filled timber trough serves as the only table decor, keeping the look natural and unadorned.", "src": "images/Soneva Fushi/0775 - Soneva Fushi - 9 Bedroom Estate Villa 11 - open dining pavilion with woven back chairs.jpg", "source": "https://soneva.com/villa/soneva-fushi-9-bedroom-estate-villa-11/", "dimensions": "2048x1143", "size": 593187}, {"number": "0776", "file": "0776 - Soneva Fushi - 9 Bedroom Estate Villa 11 - terrace lounge with low timber daybed.jpg", "resort": "Soneva Fushi", "space": "9 Bedroom Estate Villa 11", "description": "A shaded terrace lounge seen through natural pole posts, centred on a low timber framed daybed with a thick white mattress and two large off white cushions. A plain timber side table stands beside it on wide plank flooring, under a thatched roof carried on rounded pole rafters with a small ceiling fan. A cylindrical natural shade wall light, glass doors with a small fish shaped key tag and a stick balustrade open the space to dense green planting. The furniture is deliberately low, heavy and simple, letting texture and dappled light provide the decoration.", "src": "images/Soneva Fushi/0776 - Soneva Fushi - 9 Bedroom Estate Villa 11 - terrace lounge with low timber daybed.jpg", "source": "https://soneva.com/villa/soneva-fushi-9-bedroom-estate-villa-11/", "dimensions": "1366x2048", "size": 564808}, {"number": "0777", "file": "0777 - Soneva Fushi - 3 Bedroom Beach Villa with Pool Villa 9 - bedroom with magenta window daybed and green trunk.jpg", "resort": "Soneva Fushi", "space": "3 Bedroom Beach Villa with Pool Villa 9", "description": "A spacious high ceilinged bedroom with a thatched vault on pole rafters, a leaf bladed fan and white mosquito netting draped from a timber rail above the white dressed bed. To the right a built in window daybed carries a magenta mattress with magenta and green cushions, the strongest colour statement in the set, facing garden and sea glimpses through timber framed doors. At the centre stands a vivid green trunk cabinet with dark edging, used as both storage and a visual anchor on the rich dark timber floor. A small timber desk with a green chair, a woven floor mat and canvas blinds complete a playful but still natural scheme.", "src": "images/Soneva Fushi/0777 - Soneva Fushi - 3 Bedroom Beach Villa with Pool Villa 9 - bedroom with magenta window daybed and green trunk.jpg", "source": "https://soneva.com/villa/soneva-fushi-3-bedroom-beach-villa-with-pool-villa-9/", "dimensions": "1800x1200", "size": 2122778}, {"number": "0778", "file": "0778 - Soneva Fushi - 3 Bedroom Beach Villa with Pool Villa 9 - open air bathroom with sunken oval bath and stone tiles.jpg", "resort": "Soneva Fushi", "space": "3 Bedroom Beach Villa with Pool Villa 9", "description": "An open air bathroom courtyard enclosed by high curved walls in variegated green and earth stone tiles, with matching stone tiles under shallow water across the floor. At the centre a white oval bath is sunk into a raised stone rim, with chrome fittings and a small timber tray of bottles, reached by round stone stepping pads. The thatched bathroom pavilion behind holds the vanity in shadow, framed by whitewashed curved walls and a timber post. Sand, planting pockets and a small stone vessel in the foreground soften the hard surfaces and keep the bathing space feeling like a private garden room.", "src": "images/Soneva Fushi/0778 - Soneva Fushi - 3 Bedroom Beach Villa with Pool Villa 9 - open air bathroom with sunken oval bath and stone tiles.jpg", "source": "https://soneva.com/villa/soneva-fushi-3-bedroom-beach-villa-with-pool-villa-9/", "dimensions": "1800x1200", "size": 2993760}, {"number": "0779", "file": "0779 - Soneva Fushi - 3 Bedroom Beach Villa with Pool Villa 9 - upper terrace lounge with log framed sofas.jpg", "resort": "Soneva Fushi", "space": "3 Bedroom Beach Villa with Pool Villa 9", "description": "An upper terrace lounge under thatch on pole rafters, furnished with two facing sofas built from massive rounded logs with thick pale mattresses and loose off white cushions. Between them a square timber coffee table on a trunk base holds a single small coconut bowl as decor. Timber decking, cylindrical wall lights, glass and stick balustrades and a ceiling fan complete the pavilion, which looks over loungers and a parasol on the sand to the lagoon. The scale of the log frames is the design feature, giving simple seating a sculptural, castaway presence.", "src": "images/Soneva Fushi/0779 - Soneva Fushi - 3 Bedroom Beach Villa with Pool Villa 9 - upper terrace lounge with log framed sofas.jpg", "source": "https://soneva.com/villa/soneva-fushi-3-bedroom-beach-villa-with-pool-villa-9/", "dimensions": "1800x1200", "size": 3259625}, {"number": "0780", "file": "0780 - Soneva Fushi - Fresh in the Garden - treetop dining deck with curved green banquettes at dusk.jpg", "resort": "Soneva Fushi", "space": "Fresh in the Garden", "description": "A treetop dining deck at dusk reached by a long timber walkway lined with glass hurricane candles, leading to a curved dining platform suspended in the jungle canopy. Built in curved banquettes with green cushions wrap two timber tables set for a group dinner, lit by cylindrical pendants hung from branch supports and by candlelight on the tables. Natural timber rails follow the curve of the platform, and dense foliage closes in on all sides so the furniture appears to float in the trees. It is the clearest expression of the resort dining idea, simple timber and cushion construction made dramatic by height, light and setting.", "src": "images/Soneva Fushi/0780 - Soneva Fushi - Fresh in the Garden - treetop dining deck with curved green banquettes at dusk.jpg", "source": "https://soneva.com/dining/fresh-in-the-garden/", "dimensions": "1024x682", "size": 179107}, {"number": "0781", "file": "0781 - Soneva Fushi - Mihiree Mithaa - sand floor table with timber chairs and green cushions.jpg", "resort": "Soneva Fushi", "space": "Mihiree Mithaa", "description": "A small outdoor dining setting on sand in front of dense green planting, with a plain square timber table and matching timber ladder back chairs with dark green seat cushions. The table is laid for breakfast with fruit plates, glasses, white cups and folded napkins, and a server in white is placing a glass, which gives scale to the simple furniture. A carved timber torch stands in the planting behind, one of the few decorative elements. The image captures the all day restaurant in its most informal mode, toes in the sand seating with no table linen and no ornament beyond the food and foliage.", "src": "images/Soneva Fushi/0781 - Soneva Fushi - Mihiree Mithaa - sand floor table with timber chairs and green cushions.jpg", "source": "https://soneva.com/dining/mihiree-mithaa/", "dimensions": "1024x683", "size": 254232}, {"number": "0782", "file": "0782 - Soneva Fushi - By the Bar - curved timber bar with yellow cushioned seating.jpg", "resort": "Soneva Fushi", "space": "By the Bar", "description": "The interior of the beach bar under a thatched pavilion on rough timber posts, centred on a broad curved bar counter in polished warm timber. Built in seating along the counter is piled with large mustard yellow cushions, matching the drinks being poured and giving the space its colour accent. Above the bar a curved glass shelf carries bottles, while glass hurricane lanterns with white candles and sand bases line the counter alongside rows of glassware and lidded jars. Bamboo screening, natural shade wall lights and open sides to palms and beach keep the bar firmly in the barefoot, natural material language of the island.", "src": "images/Soneva Fushi/0782 - Soneva Fushi - By the Bar - curved timber bar with yellow cushioned seating.jpg", "source": "https://soneva.com/dining/by-the-bar/", "dimensions": "2048x1366", "size": 253723}, {"number": "0783", "file": "0783 - Soneva Kiri - Sunset Ocean View Pool Reserve - living room with green daybed sofa and round woven rug.jpg", "resort": "Soneva Kiri", "space": "Sunset Ocean View Pool Reserve", "description": "Vaulted living hall lined in woven bamboo and pale timber boards, with a pitched ceiling carried on round pole columns. A long low daybed sofa upholstered in mint green cotton runs along the window wall, its loose cushions graded from green to turquoise, facing a honey timber media wall with open cubby shelving, cupboards below and the television set into the middle. A small square coffee table holds a chess set, and a large round flatweave rug in concentric rings of blue anchors the polished board floor. Canvas roman blinds, a sculptural white petal pendant and a ceiling fan complete the barefoot, craft led scheme.", "src": "images/Soneva Kiri/0783 - Soneva Kiri - Sunset Ocean View Pool Reserve - living room with green daybed sofa and round woven rug.jpg", "source": "https://lvhglobal.com/thailand/soneva-kiri-five-bedroom-sunset-ocean-view-reserve", "dimensions": "1366x768", "size": 187697}, {"number": "0784", "file": "0784 - Soneva Kiri - Bayview Pool Reserve - living pavilion with games tables and green corner sofa.jpg", "resort": "Soneva Kiri", "space": "Bayview Pool Reserve", "description": "Evening view of the reserve living pavilion in warm dark timber, its steep pitched roof lit by a large crumpled parchment pendant. A corner banquette in vivid green cotton wraps around a low timber coffee table, while the opposite side of the room is given to play, with a chess table in the foreground and a desk with two leather and timber campaign chairs near the doors. Full height glazed doors with cream canvas blinds open to a railed deck and the thatched roofs of the pavilions below. The lesson is zoning without walls: one big volume, furniture grouped by activity, colour used only in the soft furnishings.", "src": "images/Soneva Kiri/0784 - Soneva Kiri - Bayview Pool Reserve - living pavilion with games tables and green corner sofa.jpg", "source": "https://lvhglobal.com/thailand/soneva-kiri-four-bedroom-bayview-reserve", "dimensions": "1366x768", "size": 217410}, {"number": "0785", "file": "0785 - Soneva Kiri - Beach Pool Reserve - TV lounge with green sectional and slatted coffee table.jpg", "resort": "Soneva Kiri", "space": "Beach Pool Reserve", "description": "Intimate television lounge wrapped in pale bamboo panelling, planned around a generous L shaped sectional and a matching daybed, all upholstered in lime green cotton with deep loose back cushions. The centrepiece is a chunky low coffee table in dark timber with a slatted glass inset top. A wall mounted screen sits above a long run of panelled timber cupboards, and cylindrical bamboo wall lights flank the folding glazed doors, which open on two sides to dense palm planting. Cream canvas blinds soften the light, keeping the palette to green, straw and honey wood.", "src": "images/Soneva Kiri/0785 - Soneva Kiri - Beach Pool Reserve - TV lounge with green sectional and slatted coffee table.jpg", "source": "https://lvhglobal.com/thailand/soneva-kiri-three-bedroom-beach-reserve", "dimensions": "1366x768", "size": 163433}, {"number": "0786", "file": "0786 - Soneva Kiri - Bayview Pool Reserve - canopy bedroom with orange daybed and stacked trunks.jpg", "resort": "Soneva Kiri", "space": "Bayview Pool Reserve", "description": "Master bedroom photographed from behind the bed, looking through swagged white mosquito netting to a window daybed dressed in burnt orange cushions and the curving pool and garden beyond. The king bed in crisp white linen sits against a wide dark timber headboard wall with integrated side tables, one holding a glass water bottle and tumbler on a leather coaster. To the right, a stack of three vintage style trunks with studs and patterned banding serves as both storage and sculpture. Ochre canvas blinds, woven wall panels and a bamboo lined ceiling keep the room warm and shaded.", "src": "images/Soneva Kiri/0786 - Soneva Kiri - Bayview Pool Reserve - canopy bedroom with orange daybed and stacked trunks.jpg", "source": "https://lvhglobal.com/thailand/soneva-kiri-four-bedroom-bayview-reserve", "dimensions": "1366x768", "size": 149845}, {"number": "0787", "file": "0787 - Soneva Kiri - Beach Pool Reserve - canopy bedroom with vintage trunk stack at bed foot.jpg", "resort": "Soneva Kiri", "space": "Beach Pool Reserve", "description": "Bright bedroom with the bed centred on full height folding doors to the pool deck, the white sheer canopy draped in soft swags from a ceiling rail. White bed linen is kept completely plain so the furniture carries the character: a taupe upholstered headboard wall with inset cupboard panels, timber nightstands with drawer pulls in the form of trunk handles, and a conical parchment bedside lamp. At the foot of the bed, three stacked travelling trunks in leather, canvas and studded patterned finishes act as a bench and storage, the signature Soneva device for hiding technology and clutter in plain sight.", "src": "images/Soneva Kiri/0787 - Soneva Kiri - Beach Pool Reserve - canopy bedroom with vintage trunk stack at bed foot.jpg", "source": "https://lvhglobal.com/thailand/soneva-kiri-five-bedroom-beach-reserve", "dimensions": "1366x768", "size": 142252}, {"number": "0788", "file": "0788 - Soneva Kiri - Bayview Pool Reserve - family bedroom with rustic pole bunk beds.jpg", "resort": "Soneva Kiri", "space": "Bayview Pool Reserve", "description": "Family bedroom lined floor to ceiling in golden woven bamboo, with a polished dark board floor. On one side a low platform double bed in white linen, on the other a bunk bed built entirely from lashed round poles with a ladder end, its rustic frame left deliberately rough against the refined room. Between them, an open shelving bay with folded white towels and glass bottles is flanked by two panelled timber doors. A single conical wall sconce gives the only decoration. A useful model for a children sharing room that still feels designed rather than themed.", "src": "images/Soneva Kiri/0788 - Soneva Kiri - Bayview Pool Reserve - family bedroom with rustic pole bunk beds.jpg", "source": "https://lvhglobal.com/thailand/soneva-kiri-four-bedroom-bayview-reserve", "dimensions": "1366x768", "size": 180197}, {"number": "0789", "file": "0789 - Soneva Kiri - Sunset Ocean View Pool Reserve - dressing bathroom with leather front vanity and metal bowl basins.jpg", "resort": "Soneva Kiri", "space": "Sunset Ocean View Pool Reserve", "description": "Long dressing bathroom under a pitched bamboo ceiling, organised as two dark stained vanity dressers with leather fronted drawers and ring pulls, each topped with a hammered metal bowl basin and exposed pipework taps beneath a wide mirror. Cylindrical paper pendants hang from sculptural branch mounts, and bamboo ladder rails hold white towels beside a woven laundry basket. An orange cushioned bench runs along the louvred window wall, and louvred doors open to a small deck. The mix of campaign furniture details, raw metal and woven bamboo is the house bathroom language in full.", "src": "images/Soneva Kiri/0789 - Soneva Kiri - Sunset Ocean View Pool Reserve - dressing bathroom with leather front vanity and metal bowl basins.jpg", "source": "https://lvhglobal.com/thailand/soneva-kiri-five-bedroom-sunset-ocean-view-reserve", "dimensions": "1366x768", "size": 230876}, {"number": "0790", "file": "0790 - Soneva Kiri - Beach Pool Reserve - outdoor bathroom with bamboo walls and stone shower.jpg", "resort": "Soneva Kiri", "space": "Beach Pool Reserve", "description": "Open air bathroom walled in vertical bamboo in two tones, pale split cane to the left and golden whole poles screening the right. A green glass vessel basin floats on a chrome and glass shelf beneath a mirror framed to reveal the planting behind it, with frosted glass tumblers and folded towels set out beside it. The shower stands open against a curved wall of variegated stone tiles with a handheld fitting, and a bamboo ladder towel rail and a solid log stool provide the only furniture. Decking underfoot and tree canopy overhead make the room feel grown rather than built.", "src": "images/Soneva Kiri/0790 - Soneva Kiri - Beach Pool Reserve - outdoor bathroom with bamboo walls and stone shower.jpg", "source": "https://lvhglobal.com/thailand/soneva-kiri-three-bedroom-beach-reserve", "dimensions": "1366x768", "size": 277858}, {"number": "0791", "file": "0791 - Soneva Kiri - Sunset Ocean View Pool Reserve - dining pavilion with long plank table and leather director chairs.jpg", "resort": "Soneva Kiri", "space": "Sunset Ocean View Pool Reserve", "description": "Covered dining pavilion on a wide board deck, its bamboo lined ceiling carried on massive round timber posts. A very long plank top dining table in dark stained wood seats ten on folding director chairs in tan leather with aluminium banded arms, a matched set that reads as safari campaign furniture refined for a house. Above the table a branch form pendant carries small conical shades, echoed by paper cylinder lanterns on the posts. A dark sideboard with glassware stands against the glazed wall to the villa interior, and the pool and green daybeds are visible beyond the deck edge.", "src": "images/Soneva Kiri/0791 - Soneva Kiri - Sunset Ocean View Pool Reserve - dining pavilion with long plank table and leather director chairs.jpg", "source": "https://lvhglobal.com/thailand/soneva-kiri-five-bedroom-sunset-ocean-view-reserve", "dimensions": "1366x768", "size": 235600}, {"number": "0792", "file": "0792 - Soneva Kiri - Beach Pool Reserve - garden pavilion with woven daybed and outdoor bath.jpg", "resort": "Soneva Kiri", "space": "Beach Pool Reserve", "description": "Circular garden pavilion with a radiating patterned timber floor and a cream canvas canopy roof on bamboo poles, enclosed by a dry stacked stone wall and bamboo fencing within dense planting. At its centre sits a low platform daybed with a thick cream mattress and bolster pillow on a base of woven natural fibre, with a bamboo ladder rail hung with white towels behind it and an outdoor soaking tub set into the decking to one side. Stone cylinder lights on the posts finish the composition. It shows how Soneva turns a bathroom garden into a furnished outdoor room.", "src": "images/Soneva Kiri/0792 - Soneva Kiri - Beach Pool Reserve - garden pavilion with woven daybed and outdoor bath.jpg", "source": "https://lvhglobal.com/thailand/soneva-kiri-five-bedroom-beach-reserve", "dimensions": "1366x768", "size": 240367}, {"number": "0793", "file": "0793 - Soneva Kiri - Soneva Kiri Spa - treatment room with twin beds and garden windows.jpg", "resort": "Soneva Kiri", "space": "Soneva Kiri Spa", "description": "Couples treatment room in the spa, furnished with two massage beds dressed in plain cream linen, a dark bronze singing bowl placed on the near bed as the single ornament. The end wall is a full run of timber framed glazed doors looking into dense tropical planting, so the garden acts as the artwork, with a canvas valance softening the top light. A small timber cabinet with drawers holds bowls and treatment vessels to one side. Nothing is upholstered or decorated beyond the linen and wood, which is precisely the calm, low stimulus palette a treatment room needs.", "src": "images/Soneva Kiri/0793 - Soneva Kiri - Soneva Kiri Spa - treatment room with twin beds and garden windows.jpg", "source": "https://scramblyn.com/2021/06/16/review-phenomenal-soneva-kiri-thailand/", "dimensions": "1000x667", "size": 214500}, {"number": "0794", "file": "0794 - Soneva Kiri - Soneva Kiri Spa - reception and retail lounge with log tables and teal daybeds.jpg", "resort": "Soneva Kiri", "space": "Soneva Kiri Spa", "description": "Spa reception and retail lounge inside a round bamboo lined pavilion with a canvas ceiling and ceiling fan. Two daybeds in teal cotton flank the entrance, each fronted by a coffee table hewn from stacked dark logs displaying treatment oils and testers. At the centre, a timber reception desk is paired with chairs upholstered in the same teal, and woven bags, hats and textiles are merchandised on a bamboo ladder display and rustic stump tables. The retail is integrated into the lounge furniture rather than shelved, keeping the room residential in feel.", "src": "images/Soneva Kiri/0794 - Soneva Kiri - Soneva Kiri Spa - reception and retail lounge with log tables and teal daybeds.jpg", "source": "https://scramblyn.com/2021/06/16/review-phenomenal-soneva-kiri-thailand/", "dimensions": "1000x667", "size": 245919}, {"number": "0795", "file": "0795 - Soneva Kiri - The View - terrace dining deck at dusk with sea view.jpg", "resort": "Soneva Kiri", "space": "The View", "description": "Dinner service on the wide timber deck of The View, photographed at dusk with the sea and headland behind. Simple square timber tables are set with linen, glassware and small lamps, surrounded by low backed timber chairs with green seat pads, and guests are served by staff in muted uniforms so the room stays visually quiet. Torch flames on the deck rail and the deep blue evening light do the decorating. For a designer the takeaway is restraint: durable plank furniture, one accent colour in the pads, and the horizon as the only focal point.", "src": "images/Soneva Kiri/0795 - Soneva Kiri - The View - terrace dining deck at dusk with sea view.jpg", "source": "https://scramblyn.com/2021/06/16/review-phenomenal-soneva-kiri-thailand/", "dimensions": "1000x667", "size": 238861}, {"number": "0796", "file": "0796 - Soneva Kiri - Benz - candlelit long table on stilt deck over the mangroves.jpg", "resort": "Soneva Kiri", "space": "Benz", "description": "Night view along the communal style long table at Benz, the Thai restaurant built on stilts among the mangroves and reached by boat. A single run of timber table is dressed with folded napkin sculptures, plates and a central line of hurricane candles, flanked by plain timber chairs with green cushions, all on a railed deck over still dark water with the tree line silhouetted at last light. No other lighting competes with the candles. The image captures the restaurant format to copy: one long table, ritual candlelight, and architecture reduced to posts, rails and decking.", "src": "images/Soneva Kiri/0796 - Soneva Kiri - Benz - candlelit long table on stilt deck over the mangroves.jpg", "source": "https://scramblyn.com/2021/06/16/review-phenomenal-soneva-kiri-thailand/", "dimensions": "1000x667", "size": 132668}, {"number": "0797", "file": "0797 - Soneva Kiri - The Bar - timber slab bar counter with leather stools.jpg", "resort": "Soneva Kiri", "space": "The Bar", "description": "The main bar under a cream canvas canopy on round timber posts, centred on a very thick single slab timber counter with a live, uneven front edge. A row of swivel stools with round tan leather seats and curved timber backs lines the guest side, and back bar shelving in matching timber holds bottles and glassware beneath hanging woven pendants. A fabric wrapped column and woven fencing screen the pool planting behind. The design relies on the scale and grain of one piece of wood rather than on fittings or signage.", "src": "images/Soneva Kiri/0797 - Soneva Kiri - The Bar - timber slab bar counter with leather stools.jpg", "source": "https://scramblyn.com/2021/06/16/review-phenomenal-soneva-kiri-thailand/", "dimensions": "1000x667", "size": 233366}, {"number": "0798", "file": "0798 - Soneva Kiri - Observatory - telescope dome on timber tower with wraparound deck.jpg", "resort": "Soneva Kiri", "space": "Observatory", "description": "The resort observatory, a silver telescope dome set on a two storey tower built entirely of weathered timber, with a wraparound railed viewing deck, external stair and bamboo fencing at its base. The structure uses the same pole, plank and thatch vocabulary as the villas, so a highly technical facility reads as another garden pavilion. Below the dome, a glazed room with a canvas shade houses the astronomer sessions that precede stargazing on the deck. It is included for its furniture lesson in disguise: consistent materials can carry even the most specialised room type.", "src": "images/Soneva Kiri/0798 - Soneva Kiri - Observatory - telescope dome on timber tower with wraparound deck.jpg", "source": "https://scramblyn.com/2021/06/16/review-phenomenal-soneva-kiri-thailand/", "dimensions": "1000x667", "size": 271073}, {"number": "0799", "file": "0799 - Soneva Kiri - The Den - bamboo interior with woven pod chairs and ramp.jpg", "resort": "Soneva Kiri", "space": "The Den", "description": "Interior of The Den, the children activity pavilion, a soaring bamboo vault built like the inside of a woven basket. A curving ramp with bamboo balustrades climbs through the space past large spherical woven rattan pod chairs suspended and set at floor level, with low tables, colourful bunting and children artwork pinned to the woven walls. Every structural member is bamboo or rattan, lashed and bent rather than jointed, and daylight filters through the weave. It is the most fully realised bamboo interior in the resort and a reference for playful, all natural construction at large scale.", "src": "images/Soneva Kiri/0799 - Soneva Kiri - The Den - bamboo interior with woven pod chairs and ramp.jpg", "source": "https://scramblyn.com/2021/06/16/review-phenomenal-soneva-kiri-thailand/", "dimensions": "1000x667", "size": 325712}, {"number": "0800", "file": "0800 - Soneva Kiri - Reception and Library Pavilion - curved timber desk and spiral stair.jpg", "resort": "Soneva Kiri", "space": "Reception and Library Pavilion", "description": "Ground floor of the reception and library pavilion, dominated by a sweeping spiral stair in pale timber that wraps a central pole column. In front of it stands a large oval reception desk in bleached, grain forward timber, styled with a tall black textured table lamp, framed notices on small easels and a black woven leather director chair for guests. Woven armchairs and a small round table sit by the glazed doors to the deck, and a carved rustic console with driftwood pieces lines the far wall. Wide board floors and exposed beams keep the welcome space calm and craft based.", "src": "images/Soneva Kiri/0800 - Soneva Kiri - Reception and Library Pavilion - curved timber desk and spiral stair.jpg", "source": "https://scramblyn.com/2021/06/16/review-phenomenal-soneva-kiri-thailand/", "dimensions": "1000x667", "size": 243657}, {"number": "0801", "file": "0801 - Gili Lankanfushi - Villa Suite Bedroom - king bed lagoon view.jpg", "resort": "Gili Lankanfushi", "space": "Villa Suite Bedroom", "description": "A spacious king bedroom under a steep thatched vault with exposed timber rafters and woven palm ceiling panels. The low platform bed is built from warm reclaimed wood and dressed in crisp white linen with a sheer white mosquito canopy gathered overhead. At the foot sits a wide upholstered daybed in natural oatmeal fabric with loose cushions and a curved wooden reading tray. A simple timber desk and chair face full height lagoon windows, woven natural fibre matting softens the dark polished floorboards, and small details such as a fish form bedside lamp and a turned wood fruit bowl keep the scheme rustic and handcrafted.", "src": "images/Gili Lankanfushi/0801 - Gili Lankanfushi - Villa Suite Bedroom - king bed lagoon view.jpg", "source": "https://gili-lankanfushi.com/maldives-luxury-resort/overwater-villa-suite/", "dimensions": "1920x1280", "size": 391768}, {"number": "0802", "file": "0802 - Gili Lankanfushi - Villa Suite Living Room - open air daybeds.jpg", "resort": "Gili Lankanfushi", "space": "Villa Suite Living Room", "description": "An open air living space that flows straight onto a broad timber sun deck above the lagoon. A deep daybed in cream upholstery is layered with cushions in soft aqua, stone and pale patterned cotton, paired with a low round wooden coffee table and a small bentwood tray table. Timber posts, a thatched roof with rolled canvas blinds and a rocking chair in light wood give the room its castaway character. Beyond the glass balustrade the deck continues with cushioned loungers, a catamaran net and a large white parasol, all in weathered natural timber tones.", "src": "images/Gili Lankanfushi/0802 - Gili Lankanfushi - Villa Suite Living Room - open air daybeds.jpg", "source": "https://gili-lankanfushi.com/maldives-luxury-resort/overwater-villa-suite/", "dimensions": "1920x1280", "size": 467145}, {"number": "0803", "file": "0803 - Gili Lankanfushi - Crusoe Residence Living Room - sofas and dining.jpg", "resort": "Gili Lankanfushi", "space": "Crusoe Residence Living Room", "description": "A long air conditioned living room with a high thatched ceiling, dark polished floorboards and a full wall of folding glass doors opening to the deck. Two generous daybeds in cream fabric are set back to back on low timber bases, dressed with blue grey cushions in subtle geometric weaves. A narrow wooden bench table holds a drinks tray, while a large cylindrical woven pendant hangs overhead. Organic decor includes a sculptural piece of natural root or coral form mounted on the white wall, and outside the doors a netted overwater hammock and cushioned deck seating extend the living space over the lagoon.", "src": "images/Gili Lankanfushi/0803 - Gili Lankanfushi - Crusoe Residence Living Room - sofas and dining.jpg", "source": "https://gili-lankanfushi.com/maldives-luxury-resort/sunset-crusoe-residence", "dimensions": "1920x1281", "size": 475982}, {"number": "0804", "file": "0804 - Gili Lankanfushi - Open Air Bathroom - freestanding tub.jpg", "resort": "Gili Lankanfushi", "space": "Open Air Bathroom", "description": "A semi open air bathroom centred on a smooth oval freestanding soaking tub in white stone, raised on a timber platform facing the ocean. Twin vanity units in chunky natural wood with dark stone tops carry hammered metal vessel basins, starfish motif details and tall woven framed mirrors. Warm cylindrical wall lights glow either side of the mirrors, while a bamboo ladder holds folded white towels. The woven palm ceiling, exposed beams and dark stained floorboards continue the villa material palette, and a glass walled shower opens at the side with direct lagoon views.", "src": "images/Gili Lankanfushi/0804 - Gili Lankanfushi - Open Air Bathroom - freestanding tub.jpg", "source": "https://gili-lankanfushi.com/maldives-luxury-resort/sunset-crusoe-residence", "dimensions": "1920x1280", "size": 477992}, {"number": "0805", "file": "0805 - Gili Lankanfushi - Rooftop Terrace - upstairs dining table.jpg", "resort": "Gili Lankanfushi", "space": "Rooftop Terrace", "description": "An upstairs outdoor dining terrace in silvered weathered timber, set with a round slatted wooden table for four. Lattice back dining chairs with tan seat pads surround the table, which is laid with cream placemats, deep blue folded napkins, brown ceramic plates and blue tinted glassware. A thatched parasol on timber posts shades a cushioned bench seat behind, and louvred timber screens and simple stick balustrades enclose the deck. The furniture is deliberately raw and sun bleached, letting the turquoise lagoon beyond provide the colour.", "src": "images/Gili Lankanfushi/0805 - Gili Lankanfushi - Rooftop Terrace - upstairs dining table.jpg", "source": "https://gili-lankanfushi.com/maldives-luxury-resort/overwater-villa-suite/", "dimensions": "1920x1280", "size": 488890}, {"number": "0806", "file": "0806 - Gili Lankanfushi - Residence with Pool - poolside lunch deck.jpg", "resort": "Gili Lankanfushi", "space": "Residence with Pool", "description": "A private pool deck dining setting where a round weathered timber table sits at the edge of an infinity pool that merges visually with the lagoon. Woven lattice back chairs in grey washed wood with tan cushions are set with cream placemats, deep blue napkins and pale ceramic plates. Behind the table, timber sun loungers with rolled white towels rest under a single white parasol. The restrained palette of bleached wood, stone coping and deep blue textiles is a clear template for the resort outdoor furniture language.", "src": "images/Gili Lankanfushi/0806 - Gili Lankanfushi - Residence with Pool - poolside lunch deck.jpg", "source": "https://gili-lankanfushi.com/maldives-luxury-resort/residence-with-pool/", "dimensions": "1920x1280", "size": 348079}, {"number": "0807", "file": "0807 - Gili Lankanfushi - Residence with Pool - infinity pool deck.jpg", "resort": "Gili Lankanfushi", "space": "Residence with Pool", "description": "A wide view of the residence infinity pool laid in deep turquoise mosaic tile with pale stone coping, set into a broad deck of silver grey weathered planks. At the far corner a pair of low timber loungers with cream cushions sits beneath a white canvas parasol beside the lagoon steps. A narrow bed of dark pebbles inset in the stone surround is the only decorative detail. The image is useful for deck material, pool finish and outdoor furniture placement rather than for interior styling.", "src": "images/Gili Lankanfushi/0807 - Gili Lankanfushi - Residence with Pool - infinity pool deck.jpg", "source": "https://gili-lankanfushi.com/maldives-luxury-resort/residence-with-pool/", "dimensions": "1920x1280", "size": 322200}, {"number": "0808", "file": "0808 - Gili Lankanfushi - Residence Living Room - lounge daybeds.jpg", "resort": "Gili Lankanfushi", "space": "Residence Living Room", "description": "An enclosed living room that opens completely to the sun deck through folding timber and glass doors topped with cream canvas valances. Two cream upholstered daybeds carry pale grey cushions with fine white geometric pattern, and a low rectangular wooden coffee table holds a fruit bowl and glasses. A light wood rocking chair sits by the doors, and the dark polished floor contrasts with the pale thatch and timber ceiling above. Outside, cushioned loungers, a catamaran net and a white parasol continue the same relaxed, natural scheme over the water.", "src": "images/Gili Lankanfushi/0808 - Gili Lankanfushi - Residence Living Room - lounge daybeds.jpg", "source": "https://gili-lankanfushi.com/maldives-luxury-resort/overwater-villa-suite/", "dimensions": "1920x1280", "size": 489287}, {"number": "0809", "file": "0809 - Gili Lankanfushi - Kashiveli - breakfast area.jpg", "resort": "Gili Lankanfushi", "space": "Kashiveli", "description": "The Kashiveli breakfast buffet arranged on a curved island counter in pale whitewashed wood under a soaring thatched roof. Tropical fruit is piled in rustic wooden crates and woven bowls, with turned wood serving bowls and stacked ceramic dishes ready for service. Massive natural tree trunk columns support the roof, white textured plaster walls carry a large neutral woven wall hanging, and slender white pendant lights hang overhead. Through to the open kitchen, backlit shelves display rows of ceramic vessels in warm cream tones, reinforcing the organic, market style presentation.", "src": "images/Gili Lankanfushi/0809 - Gili Lankanfushi - Kashiveli - breakfast area.jpg", "source": "https://gili-lankanfushi.com/dine/kashiveli/", "dimensions": "1500x1000", "size": 294597}, {"number": "0810", "file": "0810 - Gili Lankanfushi - Kashiveli - beach breakfast.jpg", "resort": "Gili Lankanfushi", "space": "Kashiveli", "description": "Breakfast for two set on the sand in front of Kashiveli, with a simple square timber table and two wooden armchairs fitted with pale blue seat cushions and fabric back panels. The table carries woven trays, ceramic cups, a brown teapot and glasses of coloured juice, all kept intentionally simple against the white sand. Palm shade, the lagoon and the thatched overwater buildings frame the setting. The chairs show the resort standard outdoor dining chair in natural wood with soft blue upholstery, a key furniture reference.", "src": "images/Gili Lankanfushi/0810 - Gili Lankanfushi - Kashiveli - beach breakfast.jpg", "source": "https://gili-lankanfushi.com/dine/kashiveli/", "dimensions": "1920x1280", "size": 238377}, {"number": "0811", "file": "0811 - Gili Lankanfushi - By the Sea - Japanese restaurant interior.jpg", "resort": "Gili Lankanfushi", "space": "By the Sea", "description": "A private dining booth at By the Sea formed by two high backed banquettes in solid natural timber, upholstered in deep navy fabric. Plump navy cushions are mixed with cream pillows and black accent cushions bearing white circular Japanese inspired motifs. Between the banquettes an oval ended wooden table is set with indigo placemats, folded navy napkins and small ceramic cups around a candle lantern. Woven palm ceiling panels, timber posts, fabric cylinder wall lights and black wall fans complete the intimate, oriental accented interior above the beach and lagoon.", "src": "images/Gili Lankanfushi/0811 - Gili Lankanfushi - By the Sea - Japanese restaurant interior.jpg", "source": "https://gili-lankanfushi.com/dine/by-the-sea/", "dimensions": "1920x1280", "size": 361951}, {"number": "0812", "file": "0812 - Gili Lankanfushi - Over Water Bar - lounge chairs and root tables.jpg", "resort": "Gili Lankanfushi", "space": "Over Water Bar", "description": "The main lounge interior of the Over Water Bar, a vast thatched pavilion with radiating timber rafters over an orange toned woven ceiling. Groups of low lounge chairs in pale natural branch wood are upholstered in vivid turquoise cushions, arranged around glass topped coffee tables whose bases are sculptural pieces of natural tree root. A roped off glass floor opening reveals the lagoon below, and dark curved bar counters line the far side. Bamboo cylinder pendants, ceiling fans and wide polished timber floorboards finish the bold, rustic scheme.", "src": "images/Gili Lankanfushi/0812 - Gili Lankanfushi - Over Water Bar - lounge chairs and root tables.jpg", "source": "https://gili-lankanfushi.com/dine/overwater-bar/", "dimensions": "1920x1280", "size": 461551}, {"number": "0813", "file": "0813 - Gili Lankanfushi - Over Water Bar - sunset deck.jpg", "resort": "Gili Lankanfushi", "space": "Over Water Bar", "description": "The sunset deck extending from the Over Water Bar on timber piles over the lagoon, furnished as an outdoor lounge. Low timber loungers and curved banquette seating carry deep turquoise cushions that echo the colour of the water. Potted green plants in rustic containers soften the deck edges, and a simple timber boardwalk links the deck back to the thatched bar building. The furniture is low, horizontal and weather resistant, designed to keep sightlines open toward the sunset horizon.", "src": "images/Gili Lankanfushi/0813 - Gili Lankanfushi - Over Water Bar - sunset deck.jpg", "source": "https://gili-lankanfushi.com/dine/overwater-bar/", "dimensions": "1920x1279", "size": 314286}, {"number": "0814", "file": "0814 - Gili Lankanfushi - Wine Cellar - underground cellar table.jpg", "resort": "Gili Lankanfushi", "space": "Wine Cellar", "description": "The underground gourmet cellar, a curved room lined floor to ceiling with vertical planks of reclaimed timber in varied brown tones. At its centre a single massive natural tree trunk forms the tasting table, fitted with small round glass side tables at each place. Tan leather dining chairs with light wood frames surround it, beneath a branching pendant of exposed bulbs on twisted cords and organic shaped ceiling lights. Wine is stored in angled timber racks, box shelves and wooden crates, with oversized display bottles standing on the terracotta tiled floor.", "src": "images/Gili Lankanfushi/0814 - Gili Lankanfushi - Wine Cellar - underground cellar table.jpg", "source": "https://gili-lankanfushi.com/dine/kashiveli/", "dimensions": "1920x1281", "size": 397611}, {"number": "0815", "file": "0815 - Gili Lankanfushi - Meera Spa - treatment room.jpg", "resort": "Gili Lankanfushi", "space": "Meera Spa", "description": "A couples treatment room at Meera Spa with two massage beds dressed in white linen and slate blue runners, each holding a woven rattan tray with wooden treatment boxes. Dark stained cabinets with small starfish motif handles flank the room, topped with candles, singing bowls and a mottled blue glass vessel. Polished dark floorboards, a thatched vaulted ceiling and taupe roman blinds frame panoramic lagoon windows on three sides. Through the glass doors an outdoor soaking tub sits on a timber deck, and a glass floor panel between the beds looks down to the water.", "src": "images/Gili Lankanfushi/0815 - Gili Lankanfushi - Meera Spa - treatment room.jpg", "source": "https://gili-lankanfushi.com/wellness/meera-spa-in-maldives/", "dimensions": "1920x1280", "size": 323951}, {"number": "0816", "file": "0816 - Gili Lankanfushi - Meera Spa - tea service on relaxation deck.jpg", "resort": "Gili Lankanfushi", "space": "Meera Spa", "description": "A close detail of the spa relaxation ritual, with a celadon ceramic tea set decorated with a white coral motif arranged on a wooden tray. The tray rests on a slatted teak side table set between curved timber loungers piled with vivid turquoise cushions, positioned at the lagoon edge. Sliced citrus fruit and small bowls of nuts accompany the tea, showing how the spa layers colour through textiles and tableware against natural wood. This is a styling and decor detail rather than a full room view, valuable for recreating the spa palette.", "src": "images/Gili Lankanfushi/0816 - Gili Lankanfushi - Meera Spa - tea service on relaxation deck.jpg", "source": "https://gili-lankanfushi.com/wellness/meera-spa-in-maldives/", "dimensions": "2560x1707", "size": 375184}, {"number": "0817", "file": "0817 - Gili Lankanfushi - Meera Spa - outdoor jacuzzi lagoon view.jpg", "resort": "Gili Lankanfushi", "space": "Meera Spa", "description": "The outdoor jacuzzi terrace attached to the Meera Spa treatment rooms, where a large rectangular white spa bath is built into a surround of rich dark timber cladding. Pale blue and white cushions are stacked on a bench behind a slatted timber privacy screen, and a small white dish of strawberries with two glasses of sparkling wine is set on the timber ledge. The restrained combination of white sanitaryware, warm wood and soft blue textiles against the open lagoon is the defining spa terrace formula.", "src": "images/Gili Lankanfushi/0817 - Gili Lankanfushi - Meera Spa - outdoor jacuzzi lagoon view.jpg", "source": "https://gili-lankanfushi.com/wellness/meera-spa-in-maldives/", "dimensions": "1920x1280", "size": 163529}, {"number": "0818", "file": "0818 - Anantara Maia Seychelles Villas - Villa Bedroom - Premier Beach Pool Villa king bedroom.jpg", "resort": "Anantara Maia Seychelles Villas", "space": "Villa Bedroom", "description": "A canopy king bed in crisp white linen with pale sage cushions anchors the room, its sheer white drapes gathered from a circular timber crown above a vertical slatted dark wood headboard wall. A low timber daybed with grey bolster cushions sits at the foot of the bed, facing a woven rattan lounge chair and ottoman with white cushions. Polished dark timber floors, slatted wood screens and lattice panels, built in desks and window seats, small framed monochrome artworks, cylindrical wall lights and recessed wall niches holding small bowls complete the warm, layered Bill Bensley interior.", "src": "images/Anantara Maia Seychelles Villas/0818 - Anantara Maia Seychelles Villas - Villa Bedroom - Premier Beach Pool Villa king bedroom.jpg", "source": "https://www.anantara.com/en/maia-seychelles/gallery", "dimensions": "1920x1037", "size": 1855498}, {"number": "0819", "file": "0819 - Anantara Maia Seychelles Villas - Villa Bedroom - Premier Beach Pool Villa bedroom second view.jpg", "resort": "Anantara Maia Seychelles Villas", "space": "Villa Bedroom", "description": "The reverse view of the canopy bedroom shows built in window seats with white pads and sage bolster cushions set under linen Roman blinds and tall slatted timber screens. A woven rattan armchair and matching ottoman sit beside a dark wood table lamp with a natural fabric shade, on polished timber flooring with a pale woven rug. Framed monochrome prints in carved timber frames, tropical flower arrangements in dark vases, and small illuminated wall niches with ceramic bowls provide the art and decor accents against cream walls and rich wood panelling.", "src": "images/Anantara Maia Seychelles Villas/0819 - Anantara Maia Seychelles Villas - Villa Bedroom - Premier Beach Pool Villa bedroom second view.jpg", "source": "https://www.anantara.com/en/maia-seychelles/gallery", "dimensions": "1920x1037", "size": 1818648}, {"number": "0820", "file": "0820 - Anantara Maia Seychelles Villas - Villa Bedroom - Ocean View Pool Villa view from bedroom.jpg", "resort": "Anantara Maia Seychelles Villas", "space": "Villa Bedroom", "description": "A wide opening wall of sheer curtains and dark timber framing leads from the bedroom to a timber deck terrace with two folding lounge chairs with pale cushions overlooking the turquoise ocean. Inside, a foot of bed daybed with grey bolsters, a woven rattan chair with white and rust cushions, a small dark side table with a drum shade lamp, and slatted timber wall panels create a calm sitting area. A framed print, a vase of tropical flowers, and a glimpse through an open slatted door to a stone vessel basin in the bathroom link the sleeping, living and bathing pavilions.", "src": "images/Anantara Maia Seychelles Villas/0820 - Anantara Maia Seychelles Villas - Villa Bedroom - Ocean View Pool Villa view from bedroom.jpg", "source": "https://www.anantara.com/en/maia-seychelles/gallery", "dimensions": "1920x1037", "size": 1826229}, {"number": "0821", "file": "0821 - Anantara Maia Seychelles Villas - Villa Bedroom - Premier Beach Pool Villa view from bedroom.jpg", "resort": "Anantara Maia Seychelles Villas", "space": "Villa Bedroom", "description": "From the foot of the white dressed bed and its grey bolster daybed, sliding doors open fully to a private plunge pool, timber deck and palm garden with the sea beyond, furnished with two timber deck chairs with teal cushions and a small round side table. A woven rattan armchair with white and sage cushions sits by a timber media console and flat screen set into slatted wood panelling, beneath a small framed print in a carved bead frame. Cream walls, sheer curtains, polished timber floors and the open bathroom doorway with a stone basin reinforce the indoor outdoor pavilion layout.", "src": "images/Anantara Maia Seychelles Villas/0821 - Anantara Maia Seychelles Villas - Villa Bedroom - Premier Beach Pool Villa view from bedroom.jpg", "source": "https://www.anantara.com/en/maia-seychelles/gallery", "dimensions": "1920x1037", "size": 2088945}, {"number": "0822", "file": "0822 - Anantara Maia Seychelles Villas - Bathroom - One Bedroom Villa stone rain shower.jpg", "resort": "Anantara Maia Seychelles Villas", "space": "Bathroom", "description": "A tall, narrow rain shower is lined floor to ceiling in small, irregular stone mosaic tiles in warm brown, rust and grey tones, giving a hand laid, textured surface. A large round ceiling mounted rain head in aged brass tone metal and a matching hand shower on a slide rail serve the space, with toiletries set into a tiled wall niche. Frosted glass brings in soft garden light, rolled white towels rest on a dark stool, and a small frangipani arrangement adds a single natural decor note.", "src": "images/Anantara Maia Seychelles Villas/0822 - Anantara Maia Seychelles Villas - Bathroom - One Bedroom Villa stone rain shower.jpg", "source": "https://www.anantara.com/en/maia-seychelles/gallery", "dimensions": "1920x1037", "size": 1686502}, {"number": "0823", "file": "0823 - Anantara Maia Seychelles Villas - Bathroom - Ocean View Pool Villa sunken bath.jpg", "resort": "Anantara Maia Seychelles Villas", "space": "Bathroom", "description": "The signature outdoor sunken bath is a wide rectangular stone lined tub filled with foam, set into a stone surround with dark metal taps and three small bowls along its ocean facing edge. Dark timber and frosted glass doors frame the view, with a thatched roof fringe above, timber louvres to one side, and the villa infinity pool and palm canopy leading to the sea beyond. Rolled white towels on a small red pedestal stand provide the one vivid colour accent in an otherwise stone, timber and white palette.", "src": "images/Anantara Maia Seychelles Villas/0823 - Anantara Maia Seychelles Villas - Bathroom - Ocean View Pool Villa sunken bath.jpg", "source": "https://www.anantara.com/en/maia-seychelles/gallery", "dimensions": "1920x1037", "size": 2554583}, {"number": "0824", "file": "0824 - Anantara Maia Seychelles Villas - Bathroom - Premier Beach Pool Villa outdoor bath.jpg", "resort": "Anantara Maia Seychelles Villas", "space": "Bathroom", "description": "Under a thatched pavilion roof on heavy dark timber posts, the rectangular sunken foam bath sits in a stone surround with blue mosaic tile channels of water running around it toward the private pool. Dark metal bath fittings, rolled white towels on a dark red stand, and small bowls on the bath edge are the functional decor. To the left, timber sun loungers with teal pads and an orange rolled towel face the pool, while lawn, palms and a distant lounger frame the beach garden setting.", "src": "images/Anantara Maia Seychelles Villas/0824 - Anantara Maia Seychelles Villas - Bathroom - Premier Beach Pool Villa outdoor bath.jpg", "source": "https://www.anantara.com/en/maia-seychelles/gallery", "dimensions": "1920x1037", "size": 2332033}, {"number": "0825", "file": "0825 - Anantara Maia Seychelles Villas - Bathroom - Premier Ocean View Pool Villa outdoor bath.jpg", "resort": "Anantara Maia Seychelles Villas", "space": "Bathroom", "description": "Seen from outside, the thatched bath pavilion shelters the sunken white bath between polished dark timber posts, with timber louvred screens behind and rolled towels and small bowls on its stone edge. In the foreground, two adjustable timber sun loungers with deep red cushions and orange bolster towels sit in the shallow blue mosaic tiled infinity pool that runs to a black metal railing above the bay. The image records how the bathing pavilion, pool furniture and loungers work as one outdoor room.", "src": "images/Anantara Maia Seychelles Villas/0825 - Anantara Maia Seychelles Villas - Bathroom - Premier Ocean View Pool Villa outdoor bath.jpg", "source": "https://www.anantara.com/en/maia-seychelles/gallery", "dimensions": "1920x1037", "size": 2680610}, {"number": "0826", "file": "0826 - Anantara Maia Seychelles Villas - Spa - Anantara Spa couple pavilion.jpg", "resort": "Anantara Maia Seychelles Villas", "space": "Spa", "description": "Two timber massage beds with white covers, lime green throws, rolled white towels and small trays of treatment bottles face a garden deck inside an open thatched pavilion with tied back cream curtains. At the far end, a low timber bench with a leaf patterned cushion is flanked by two large turned wood pedestal urns, one holding rolled towels and one a vase of red tropical flowers, with copper tone foot bowls on a white mat before it. Dark timber decking, thatch, and dense fan palm planting form the entire enclosure, with no hard walls.", "src": "images/Anantara Maia Seychelles Villas/0826 - Anantara Maia Seychelles Villas - Spa - Anantara Spa couple pavilion.jpg", "source": "https://www.anantara.com/en/maia-seychelles/gallery", "dimensions": "1920x1037", "size": 2819496}, {"number": "0827", "file": "0827 - Anantara Maia Seychelles Villas - Spa - Anantara Spa outdoor pavilion.jpg", "resort": "Anantara Maia Seychelles Villas", "space": "Spa", "description": "An aerial view shows a single massage bed with a lime green throw and a low timber daybed with green cushion and grey bolsters set on a broad dark timber deck hidden in dense palm and fern planting beside thatched spa roofs. A turned wood urn stands by the treatment bed as the only decor object. The image is valuable for the spa layout, showing how each open air treatment deck is cut into the forest garden for complete privacy rather than arranged as an indoor spa suite.", "src": "images/Anantara Maia Seychelles Villas/0827 - Anantara Maia Seychelles Villas - Spa - Anantara Spa outdoor pavilion.jpg", "source": "https://www.anantara.com/en/maia-seychelles/gallery", "dimensions": "1920x800", "size": 1709381}, {"number": "0828", "file": "0828 - Anantara Maia Seychelles Villas - Spa - Anantara Spa signature massage pavilion.jpg", "resort": "Anantara Maia Seychelles Villas", "space": "Spa", "description": "A close view of a massage in progress on a white towel covered treatment bed on a pale timber deck, with a sheer white curtain at the edge of the open pavilion and fan palms filling the background. The simplicity is the design point, a plain timber bed, white cotton towelling and no visible furniture or ornament beyond the planting. It confirms the treatment setting shown wider in the couple pavilion and outdoor deck images.", "src": "images/Anantara Maia Seychelles Villas/0828 - Anantara Maia Seychelles Villas - Spa - Anantara Spa signature massage pavilion.jpg", "source": "https://www.anantara.com/en/maia-seychelles/gallery", "dimensions": "1920x1037", "size": 2257466}, {"number": "0829", "file": "0829 - Anantara Maia Seychelles Villas - Restaurant - Tec Tec Restaurant interior.jpg", "resort": "Anantara Maia Seychelles Villas", "space": "Restaurant", "description": "Tec Tec at dusk is a high, open sided pavilion with a steeply pitched woven thatch ceiling on sculptural dark timber trusses and heavy wood columns, lit by small recessed spotlights. Square tables are dressed in white cloths with glass candle hurricanes, wine glasses and folded napkins, surrounded by tall backed timber dining chairs with woven panels and mustard yellow seat cushions. Polished timber floors reflect the candlelight, a side alcove holds a console with a shell ornament and tropical flowers, and open sides frame the pool, garden and sea.", "src": "images/Anantara Maia Seychelles Villas/0829 - Anantara Maia Seychelles Villas - Restaurant - Tec Tec Restaurant interior.jpg", "source": "https://www.anantara.com/en/maia-seychelles/gallery", "dimensions": "1920x1037", "size": 186421}, {"number": "0830", "file": "0830 - Anantara Maia Seychelles Villas - Pool - Aerial main pool and thatched pavilions.jpg", "resort": "Anantara Maia Seychelles Villas", "space": "Pool", "description": "An aerial view maps the main freeform blue pool and its surrounding pavilion furniture, with red sun umbrellas over circular red loungers on pale paving, dark stone pool pillars, and stepped entries into the water. Around it stand the steep conical and pitched thatched roofs of the restaurant and bar pavilions in grey brown thatch, set in dense palm planting above the sand beach. Colour is carried almost entirely by the red outdoor textiles and umbrellas against blue water, green planting and natural thatch and stone.", "src": "images/Anantara Maia Seychelles Villas/0830 - Anantara Maia Seychelles Villas - Pool - Aerial main pool and thatched pavilions.jpg", "source": "https://www.anantara.com/en/maia-seychelles/gallery", "dimensions": "1920x1037", "size": 363254}, {"number": "0831", "file": "0831 - Anantara Maia Seychelles Villas - Villa Dining - In villa dining setting.jpg", "resort": "Anantara Maia Seychelles Villas", "space": "Villa Dining", "description": "A breakfast for two is set on a glass topped timber dining table with slatted wood edging, on a timber deck terrace under a thatched gazebo post, overlooking the infinity pool edge and the open ocean. Two slatted timber armchairs with pale grey seat cushions face each other across woven placemats, ceramic plates, juice glasses and small preserve jars. A large dark urn planter with green planting and the timber and black metal railing complete this example of the villa gazebo dining furniture.", "src": "images/Anantara Maia Seychelles Villas/0831 - Anantara Maia Seychelles Villas - Villa Dining - In villa dining setting.jpg", "source": "https://www.anantara.com/en/maia-seychelles/gallery", "dimensions": "1920x1037", "size": 292960}, {"number": "0832", "file": "0832 - Anantara Maia Seychelles Villas - Villa Pool Terrace - Premier Ocean View Villa at sunset.jpg", "resort": "Anantara Maia Seychelles Villas", "space": "Villa Gazebo and Pool Terrace", "description": "At sunset the villa living pavilion glows under its steep thatched roof, showing an oversized timber daybed with deep red mattress cushions and cream bolsters, lit by two tall cylindrical woven lamps. A small timber dining table and slatted chairs stand on the deck by a stone based column and timber bar counter, in front of slatted wood screens and a framed mirror. The blue mosaic tiled private infinity pool with submerged steps runs along the deck edge, linking bedroom, gazebo living area and terrace as separate thatched pavilions.", "src": "images/Anantara Maia Seychelles Villas/0832 - Anantara Maia Seychelles Villas - Villa Pool Terrace - Premier Ocean View Villa at sunset.jpg", "source": "https://www.anantara.com/en/maia-seychelles/gallery", "dimensions": "1920x1037", "size": 1997764}, {"number": "0833", "file": "0833 - Anantara Maia Seychelles Villas - Bar - Sunset Pool Bar.jpg", "resort": "Anantara Maia Seychelles Villas", "space": "Bar", "description": "The Sunset Pool Bar is a circular open pavilion with a conical thatched roof carried on tall columns wrapped in teal and gold geometric patterned fabric, set on rounded dark stone bases over a curved timber deck. Timber bar stools with red cushions line the dark wood bar counter, and matching red upholstered armchairs with small woven side tables and a candle lantern form a lounge grouping facing the sunset over the water. Dense palm planting closes the back of the deck. Note, below 1200 pixels, best available official image of the bar.", "src": "images/Anantara Maia Seychelles Villas/0833 - Anantara Maia Seychelles Villas - Bar - Sunset Pool Bar.jpg", "source": "https://www.anantara.com/en/maia-seychelles/dining", "dimensions": "960x519", "size": 130894}, {"number": "0834", "file": "0834 - Anantara Maia Seychelles Villas - Restaurant - Wine cellar.jpg", "resort": "Anantara Maia Seychelles Villas", "space": "Wine Cellar", "description": "The wine cellar dining room is lined in rich polished timber, with a full height bottle rack of small square compartments and diagonal display bins, open shelves holding decanters, and a highly figured timber floor. A single glass topped timber dining table is set for a private tasting, with timber framed chairs with pale cushions, one draped with a teal and white striped throw. Framed certificates hang on the wood panelling and dark fabric screens soften one wall. Note, below 1200 pixels, best available official image of the wine cellar.", "src": "images/Anantara Maia Seychelles Villas/0834 - Anantara Maia Seychelles Villas - Restaurant - Wine cellar.jpg", "source": "https://www.anantara.com/en/maia-seychelles/dining", "dimensions": "880x620", "size": 109298}, {"number": "0835", "file": "0835 - North Island - Villa North Island - handcrafted bedroom with ocean view.jpg", "resort": "North Island", "space": "Villa North Island Bedroom", "description": "The Villa North Island bedroom is a calm, pavilion like sleeping space built around a locally handcrafted bed dressed in soft white and stone coloured linens. Chunky Banuas hardwood columns and takamaka framing give the room its sculptural structure, while the high thatched ceiling keeps the volume airy and shaded. Low timber furniture, woven textures and restrained neutral textiles let the ocean view carry the colour. The mood is barefoot and handmade rather than polished, with every surface showing natural grain and craft.", "src": "images/North Island/0835 - North Island - Villa North Island - handcrafted bedroom with ocean view.jpg", "source": "https://north-island.com/accommodation/", "dimensions": "1966x1311", "size": 1365768}, {"number": "0836", "file": "0836 - North Island - Villa North Island - bathroom with stone and timber vanity.jpg", "resort": "North Island", "space": "Villa North Island Bathroom", "description": "The Villa North Island bathroom reads as a private bathhouse in stone, timber and glass, generous in scale and open to light and air. A large vanity area anchors the room, paired with substantial mirrors and warm wood cabinetry that echo the villa joinery. Natural stone and smooth plaster surfaces contrast with the softness of cotton towels and woven accessories. The palette stays chalk, sand and granite grey, keeping the focus on texture and ritual.", "src": "images/North Island/0836 - North Island - Villa North Island - bathroom with stone and timber vanity.jpg", "source": "https://north-island.com/accommodation/", "dimensions": "1966x1311", "size": 1830418}, {"number": "0837", "file": "0837 - North Island - Villa North Island - study room with desk and lounge seating.jpg", "resort": "North Island", "space": "Villa North Island Study Room", "description": "The separate study in Villa North Island doubles as a quiet second living and family room, furnished with a writing desk, relaxed lounge seating and low timber tables. Takamaka and rosewood tones warm the space, while pale upholstery and natural fibre rugs soften the stone and deck flooring. Shelving and simple decor keep the room practical without breaking the island calm. Large openings frame greenery and sea glimpses, so work and reading happen inside the landscape.", "src": "images/North Island/0837 - North Island - Villa North Island - study room with desk and lounge seating.jpg", "source": "https://north-island.com/accommodation/", "dimensions": "1966x1311", "size": 1581121}, {"number": "0838", "file": "0838 - North Island - Villa North Island - bedroom view across deck to ocean.jpg", "resort": "North Island", "space": "Villa North Island Bedroom", "description": "This second bedroom view shows the Villa North Island sleeping pavilion opening across broad timber decking toward the ocean. The bed is simply dressed in white linen with layered neutral throws, flanked by handcrafted bedside pieces in weathered wood. Sliding screens and curtains in natural fabrics mediate light and privacy without closing the room down. Stone, thatch and casuarina furniture keep the composition grounded in island materials.", "src": "images/North Island/0838 - North Island - Villa North Island - bedroom view across deck to ocean.jpg", "source": "https://north-island.com/accommodation/", "dimensions": "1966x1311", "size": 1770236}, {"number": "0839", "file": "0839 - North Island - Villa North Island - open sala lounge with thatched roof.jpg", "resort": "North Island", "space": "Villa North Island Sala", "description": "The secluded sala at Villa North Island is an open sided lounge pavilion under a steep ylang ylang thatch roof, furnished for slow hours between swims. Deep, low sofas and armchairs in pale, loose fabrics gather around timber coffee tables on the deck. Takamaka posts and root like pergola details give the structure its organic, handmade character. Cushions in sage, sand and aqua pick up the colours of garden and sea without competing with them.", "src": "images/North Island/0839 - North Island - Villa North Island - open sala lounge with thatched roof.jpg", "source": "https://north-island.com/accommodation/", "dimensions": "2300x1533", "size": 5013302}, {"number": "0840", "file": "0840 - North Island - Villa North Island - terrace fire pit with outdoor seating.jpg", "resort": "North Island", "space": "Villa North Island Terrace Fire Pit", "description": "The elevated terrace and fire pit at Villa North Island form an outdoor living room arranged across timber decks above the beach. Built in seating and loose lounge chairs in weather resistant natural fabrics circle the fire for evening gathering. Granite boulders, takamaka rails and thatch edges blend the terrace into the granitic slope behind it. The furnishing is deliberately low and horizontal, preserving the endless ocean view as the main artwork.", "src": "images/North Island/0840 - North Island - Villa North Island - terrace fire pit with outdoor seating.jpg", "source": "https://north-island.com/accommodation/", "dimensions": "2300x1533", "size": 3619781}, {"number": "0841", "file": "0841 - North Island - Beachfront Villa Bedroom - four poster bed and timber columns.jpg", "resort": "North Island", "space": "Beachfront Villa Bedroom", "description": "The Beachfront Villa bedroom centres on a handcrafted four poster bed framed by chunky hardwood uprights and dressed in crisp white linen with soft neutral layering. Retractable sliding doors dissolve the wall to the deck, so the bed faces garden and sunrise over East Beach. Bedside furniture in takamaka and casuarina shows visible handwork, matched with woven and cotton textiles in sand and chalk tones. A small lounge corner completes a bedroom that feels like a furnished pavilion rather than a closed room.", "src": "images/North Island/0841 - North Island - Beachfront Villa Bedroom - four poster bed and timber columns.jpg", "source": "https://north-island.com/accommodation/", "dimensions": "2300x1534", "size": 3231556}, {"number": "0842", "file": "0842 - North Island - Beachfront Villa Living Room - open lounge to deck and ocean.jpg", "resort": "North Island", "space": "Beachfront Villa Living Room", "description": "This Beachfront Villa living view shows the open lounge flowing directly onto the wooden deck and private garden beyond. Generous sofas and armchairs in pale, tactile fabrics are grouped loosely around low timber tables, encouraging barefoot, unstructured living. The thatched roof, takamaka structure and stone details provide texture overhead and underfoot. Decor is minimal and natural, with shells, woven pieces and soft cushions in sage, coral and turquoise accents.", "src": "images/North Island/0842 - North Island - Beachfront Villa Living Room - open lounge to deck and ocean.jpg", "source": "https://north-island.com/accommodation/", "dimensions": "2300x1533", "size": 3544091}, {"number": "0843", "file": "0843 - North Island - Beachfront Villa Living Room - second lounge view with sofa.jpg", "resort": "North Island", "space": "Beachfront Villa Living Room", "description": "A second angle on the Beachfront Villa lounge reveals the depth of the open plan living space and its second seating group. A long, comfortable sofa in natural cotton faces outward, paired with handcrafted casuarina side tables and chairs shaped on the island. Light filters through screens and thatch, playing across weathered wood, cork and sandstone surfaces. The scheme by LIFE interiors layers rock, silk, velvet and shell in quiet, sun faded tones.", "src": "images/North Island/0843 - North Island - Beachfront Villa Living Room - second lounge view with sofa.jpg", "source": "https://north-island.com/accommodation/", "dimensions": "2300x1533", "size": 3865564}, {"number": "0844", "file": "0844 - North Island - Beachfront Villa Bathroom - sunken bath and outdoor shower.jpg", "resort": "North Island", "space": "Beachfront Villa Bathroom", "description": "The Beachfront Villa bathroom is a spacious bathhouse with a sunken marble bath as its centrepiece, set among stone, timber and glass. Twin vanity areas with large mirrors and warm wood joinery give the room a crafted, residential feel. Indoor and outdoor showers extend the bathing ritual into the garden air, screened by beachrock and planting. Textiles stay simple and absorbent in white and sand, letting the material palette do the decorative work.", "src": "images/North Island/0844 - North Island - Beachfront Villa Bathroom - sunken bath and outdoor shower.jpg", "source": "https://north-island.com/accommodation/", "dimensions": "2300x1534", "size": 4631519}, {"number": "0845", "file": "0845 - North Island - Beachfront Villa Sala and Pool - shaded sala beside plunge pool.jpg", "resort": "North Island", "space": "Beachfront Villa Sala and Pool", "description": "The covered sala beside the private plunge pool is the Beachfront Villa outdoor room, furnished with a comfortable couch, loungers and a dining table for shaded hours. Sandstone hanging drinks tables and takamaka structure details show the architects hands on philosophy in miniature. Pale cushions and natural fibre textiles soften the timber deck and stone pool edge. Granite, thatch and tropical planting wrap the pool, so furniture and landscape read as one composition.", "src": "images/North Island/0845 - North Island - Beachfront Villa Sala and Pool - shaded sala beside plunge pool.jpg", "source": "https://north-island.com/accommodation/", "dimensions": "2400x1600", "size": 4287048}, {"number": "0846", "file": "0846 - North Island - Piazza Restaurant - interior dining with timber and thatch.jpg", "resort": "North Island", "space": "Piazza Restaurant", "description": "The Piazza dining interior gathers tables beneath soaring thatch and exposed takamaka trusses, in the restored heart of the island. Dining chairs and tables in dark, hand finished timber contrast with pale stone walls and soft, neutral table linens. Mother of pearl and copper lighting details add a gentle lustre above the settings. The room balances ceremony and ease, formal enough for tasting menus yet unmistakably built from island stone, wood and grass.", "src": "images/North Island/0846 - North Island - Piazza Restaurant - interior dining with timber and thatch.jpg", "source": "https://north-island.com/dining-and-cuisine/", "dimensions": "2300x1534", "size": 4579562}, {"number": "0847", "file": "0847 - North Island - Piazza Restaurant - chefs table dining setting.jpg", "resort": "North Island", "space": "Piazza Restaurant", "description": "The chefs table setting at the Piazza shows close, convivial dining arranged on a substantial timber table with simple, elegant place settings. Stone walls, thatch overhead and handcrafted serving pieces keep the experience rooted in the island building tradition. Textiles are restrained, natural cotton and linen in chalk and sand, so food and craft carry the colour. Low lighting and woven, shell and wood decor complete an intimate room within the larger restaurant.", "src": "images/North Island/0847 - North Island - Piazza Restaurant - chefs table dining setting.jpg", "source": "https://north-island.com/dining-and-cuisine/", "dimensions": "2300x1534", "size": 4890361}, {"number": "0848", "file": "0848 - North Island - Piazza Restaurant - wine cellar interior with stone walls.jpg", "resort": "North Island", "space": "Piazza Restaurant Wine Cellar", "description": "The Piazza wine cellar is a cool, stone walled interior where bottles rest in timber racking built into the granite and coral masonry. A tasting table and simple stools in dark wood furnish the centre of the room for private pours and pairings. The material palette is deliberately elemental, rough stone, smooth timber and glass, lit warmly against the cellar shade. It extends the restaurant language of handmade, local construction into a quiet, enclosed retreat.", "src": "images/North Island/0848 - North Island - Piazza Restaurant - wine cellar interior with stone walls.jpg", "source": "https://north-island.com/dining-and-cuisine/", "dimensions": "2300x1533", "size": 3465341}, {"number": "0849", "file": "0849 - North Island - West Beach Bar - open bar lounge on the beach.jpg", "resort": "North Island", "space": "West Beach Bar", "description": "The West Beach Bar, also known as the Sunset Bar, is an open lounge pavilion set at the edge of the sand for evening drinks. Its celebrated bar stools are made from takamaka stumps shaped on site, paired with low lounge seating in weathered timber and pale cushions. Thatch, granite and driftwood like details keep the bar continuous with the villas and Piazza. As the sun sets, the furniture grouping turns the beach itself into the room, with the ocean as backdrop.", "src": "images/North Island/0849 - North Island - West Beach Bar - open bar lounge on the beach.jpg", "source": "https://north-island.com/dining-and-cuisine/", "dimensions": "2300x1536", "size": 3406741}, {"number": "0850", "file": "0850 - North Island - Spa - couples treatment room with ocean view.jpg", "resort": "North Island", "space": "Spa", "description": "The spa treatment room is an open, timber framed pavilion where twin massage beds are dressed in soft aqua and sage linens facing the ocean. Between the beds, a solid wood cabinet carries a sculptural coral piece on a tray of blue glass, a signature natural decor moment. Sheer curtains in pale fabric soften the openings, while handcrafted loungers and side tables in weathered wood furnish the deck beyond. Takamaka structure, stone flooring and sea light give the room its calm, elemental character.", "src": "images/North Island/0850 - North Island - Spa - couples treatment room with ocean view.jpg", "source": "https://north-island.com/experience-the-island/", "dimensions": "2300x1724", "size": 2717670}, {"number": "0851", "file": "0851 - North Island - Pool Pavilion - main pool with ocean view.jpg", "resort": "North Island", "space": "Pool Pavilion", "description": "The main rim flow pool curves along a broad timber deck above East Beach, edged with granite boulders that anchor it into the hillside. At the far end, cushioned daybeds and a shade umbrella form a small, furnished pool pavilion for lounging between swims. Stone planters, low timber benches and palm planting soften the deck without cluttering the view. The furnishing is sparse by design, letting water, rock, wood and ocean carry the scene.", "src": "images/North Island/0851 - North Island - Pool Pavilion - main pool with ocean view.jpg", "source": "https://north-island.com/", "dimensions": "2300x1450", "size": 4732937}, {"number": "0852", "file": "0852 - North Island - Library - reading room with bookshelves and armchairs.jpg", "resort": "North Island", "space": "Library", "description": "The library occupies a restored coral stone building, its whitewashed rubble walls and arched openings framing views straight onto the beach. Inside, loose covered sofas and armchairs in stone coloured linen gather on natural fibre rugs around round metal and timber coffee tables, with deep green silk cushions as the single colour accent. A glazed bookcase filled with books lines one wall, while timber desks and dining height tables at the far end serve study and games. Exposed takamaka trusses and woven thatch overhead complete a room where furniture, books and island history share one calm, shaded volume.", "src": "images/North Island/0852 - North Island - Library - reading room with bookshelves and armchairs.jpg", "source": "https://www.travelplusstyle.com/hotels/north-island", "dimensions": "1880x1208", "size": 2247117}, {"number": "0853", "file": "0853 - Kisawa Sanctuary - Residence Bedroom - king bed with olive green curtains.jpg", "resort": "Kisawa Sanctuary", "space": "Residence Bedroom", "description": "A serene king bedroom framed by floor length olive green curtains and woven grass sliding panels, with a tall upholstered headboard, crisp white bedding and a woven bench at the foot of the bed. Cane backed carved wood lounge chairs, stone side tables with small brass lamps and a low ochre daybed show the bespoke, individually furnished character of each residence. The barrel vaulted ceiling is lined in a jute like weave, and flat woven rugs in sand and soft check patterns layer over warm timber floors.", "src": "images/Kisawa Sanctuary/0853 - Kisawa Sanctuary - Residence Bedroom - king bed with olive green curtains.jpg", "source": "https://kisawasanctuary.com/bungalows/", "dimensions": "2000x1333", "size": 556537}, {"number": "0854", "file": "0854 - Kisawa Sanctuary - Residence Bedroom - bedroom opening to living room.jpg", "resort": "Kisawa Sanctuary", "space": "Residence Bedroom", "description": "A wide view from the king bedroom through a deep timber opening into the adjoining living room, linking the two halves of the bungalow in one calm enfilade. In the bedroom, a carved dark wood figure stands beside the bed, cane chairs sit on checked woven rugs and a woven bench holds a straw hat, while beyond, a cream sofa, low stone tables and a branching white pendant light furnish the living space. Timber doors inlaid with coloured glass triangles, olive curtains and woven ceiling linings carry the pan African craft language through both rooms.", "src": "images/Kisawa Sanctuary/0854 - Kisawa Sanctuary - Residence Bedroom - bedroom opening to living room.jpg", "source": "https://kisawasanctuary.com/bungalows/", "dimensions": "2000x1333", "size": 458337}, {"number": "0855", "file": "0855 - Kisawa Sanctuary - Residence Bedroom - ochre daybed and carved figure.jpg", "resort": "Kisawa Sanctuary", "space": "Residence Bedroom", "description": "From the foot of the bed, an ochre upholstered daybed on a solid timber frame anchors the bedroom, with a tall carved wooden bust on a plinth marking the threshold to the living room. Beyond the opening, cognac leather tub chairs, low block stools with woven cushions and a pale stone coffee table sit beneath a white cone pendant cluster. Woven grass ceiling panels, thatch fringed verandas and full height sliding doors dissolve the boundary between the interior and the sand and sea outside.", "src": "images/Kisawa Sanctuary/0855 - Kisawa Sanctuary - Residence Bedroom - ochre daybed and carved figure.jpg", "source": "https://kisawasanctuary.com/bungalows/", "dimensions": "1605x1065", "size": 539683}, {"number": "0856", "file": "0856 - Kisawa Sanctuary - Residence Living Room - stone tables and carved stool detail.jpg", "resort": "Kisawa Sanctuary", "space": "Residence Living Room", "description": "A close designer study of the living room layering: freeform travertine like stone coffee tables hold a red glass bottle, small ceramic vessels, miniature wooden figures and a green dish, beside a dark carved stool with a sculpted face supporting a large terracotta vase. A cream linen sofa, block timber stools with striped cushions and a bold checked flatweave rug complete the composition. Woven grass screens behind show how texture, rather than pattern alone, builds the Kisawa interior.", "src": "images/Kisawa Sanctuary/0856 - Kisawa Sanctuary - Residence Living Room - stone tables and carved stool detail.jpg", "source": "https://kisawasanctuary.com/bungalows/", "dimensions": "2000x1333", "size": 561511}, {"number": "0857", "file": "0857 - Kisawa Sanctuary - Residence Living Room - cream sofa and leather tub chairs.jpg", "resort": "Kisawa Sanctuary", "space": "Residence Living Room", "description": "The principal living room in full: a long cream linen sofa and two cognac leather tub chairs arranged on a checked woven rug around organic stone coffee tables dressed with terracotta and red glass vessels. A writing desk with a brass lamp runs along one wall, olive green curtains frame the sliding doors, and a white multi cone chandelier hangs from the woven grass lined vaulted ceiling. Carved wooden stools, figures and ceramics sourced across Africa give the room its collected, pan African character.", "src": "images/Kisawa Sanctuary/0857 - Kisawa Sanctuary - Residence Living Room - cream sofa and leather tub chairs.jpg", "source": "https://studionjf.com/work/furniture/", "dimensions": "1500x1000", "size": 327598}, {"number": "0858", "file": "0858 - Kisawa Sanctuary - Residence Bathroom - shower opening to sand deck.jpg", "resort": "Kisawa Sanctuary", "space": "Residence Bathroom", "description": "The bathroom shower area opens through full height timber and glass doors to the private deck and sand beyond, with brass shower fittings, a small stone stool holding bathing amenities and a white towel on the wall. Two dark carved high back chairs with pierced geometric backs and a small carved side table furnish the threshold, a signature Kisawa pairing of useful furniture and sculptural African craft. Woven fencing, rope rails and the thatch fringe of the roof keep even this most private space rooted in island materials.", "src": "images/Kisawa Sanctuary/0858 - Kisawa Sanctuary - Residence Bathroom - shower opening to sand deck.jpg", "source": "https://kisawasanctuary.com/bungalows/", "dimensions": "2000x1333", "size": 734320}, {"number": "0859", "file": "0859 - Kisawa Sanctuary - Residence Bathroom - sculpted stone bathtub with sea view.jpg", "resort": "Kisawa Sanctuary", "space": "Residence Bathroom", "description": "A sculptural, undulating bathtub in pale 3D printed sand composite sits before an open doorway framing the turquoise sea, with brass floor mounted taps and a small stone side table for amenities. Two dark carved wooden armchairs with pierced backs and a matching carved table with a vase of dried grasses furnish the bathroom as a living space, not a utility room. Rope railed decking, woven ceiling lining and thatch fringe connect the bath to the dune landscape outside.", "src": "images/Kisawa Sanctuary/0859 - Kisawa Sanctuary - Residence Bathroom - sculpted stone bathtub with sea view.jpg", "source": "https://kisawasanctuary.com/bungalows/", "dimensions": "1613x1075", "size": 701811}, {"number": "0860", "file": "0860 - Kisawa Sanctuary - Residence Bathroom - undulating vanity and woven baskets.jpg", "resort": "Kisawa Sanctuary", "space": "Residence Bathroom", "description": "A portrait view of the bathroom vanity: a long, wave fronted stone washstand with an integrated basin, a tall mirror and paired white cone wall lights, reflecting the sculpted bathtub and the sea beyond. Two large woven grass baskets in gourd forms sit on the timber floor beneath the vanity, echoing the woven vessels used throughout the sanctuary. Warm plaster walls, rope wrapped ceiling beams and small wooden trays of amenities keep the palette sandy, tactile and calm.", "src": "images/Kisawa Sanctuary/0860 - Kisawa Sanctuary - Residence Bathroom - undulating vanity and woven baskets.jpg", "source": "https://kisawasanctuary.com/bungalows/", "dimensions": "883x1300", "size": 281745}, {"number": "0861", "file": "0861 - Kisawa Sanctuary - Outdoor Day Area - thatched dining pavilion and pool deck.jpg", "resort": "Kisawa Sanctuary", "space": "Outdoor Day Area", "description": "The private outdoor day area: a vast oval timber dining table with woven seat dining chairs under a deep thatched pavilion, dressed with dark wooden bowls, amber glass and tall vases of foliage. Beyond, woven loungers and white umbrellas line the deck around the private pool, with the ocean as backdrop. The thatch, made from local grasses by island thatchers, and the woven furniture show the outdoor rooms furnished to the same standard as the interiors.", "src": "images/Kisawa Sanctuary/0861 - Kisawa Sanctuary - Outdoor Day Area - thatched dining pavilion and pool deck.jpg", "source": "https://kisawasanctuary.com/bungalows/", "dimensions": "1575x1036", "size": 972710}, {"number": "0862", "file": "0862 - Kisawa Sanctuary - Outdoor Pool Deck - infinity pool with woven loungers.jpg", "resort": "Kisawa Sanctuary", "space": "Outdoor Pool Deck", "description": "A curved private infinity pool melts into the dune edge, its timber deck furnished with two folding woven loungers, a small side table and amber drinking glasses. A low woven fence and rope posts trace the sand boundary, and coastal planting frames the turquoise ocean view. The scene captures the Kisawa approach to outdoor furniture: light timber frames, woven grass seats and nothing that competes with the landscape.", "src": "images/Kisawa Sanctuary/0862 - Kisawa Sanctuary - Outdoor Pool Deck - infinity pool with woven loungers.jpg", "source": "https://kisawasanctuary.com/bungalows/", "dimensions": "1600x1067", "size": 756727}, {"number": "0863", "file": "0863 - Kisawa Sanctuary - Outdoor Deck - oceanfront dining under thatch.jpg", "resort": "Kisawa Sanctuary", "space": "Outdoor Deck", "description": "Beneath the sweeping fringe of a thatched roof, a long oval timber dining table and woven grid back chairs sit on a pale terrace directly above the ocean. A terracotta vase with citrus branches, a clear glass vessel and dark wooden bowls dress the table simply. The heavy timber roof post, layered thatch and woven chair seats demonstrate the traditional weaving, thatching and carpentry techniques, in jambir and sambiri type hardwoods, that define the residences.", "src": "images/Kisawa Sanctuary/0863 - Kisawa Sanctuary - Outdoor Deck - oceanfront dining under thatch.jpg", "source": "https://studionjf.com/work/furniture/", "dimensions": "2000x1363", "size": 947903}, {"number": "0864", "file": "0864 - Kisawa Sanctuary - Main Terrace Restaurant - woven chairs and curved counter.jpg", "resort": "Kisawa Sanctuary", "space": "Main Terrace Restaurant", "description": "Inside the Main Terrace restaurant, rows of dining chairs with circular woven grass backs and seats surround dark timber tables beneath a soaring arched ceiling of exposed timber ribs. Oversized brass framed lantern pendants hang above, and a long curved service counter with fluted timber front and stone top runs along the back wall. Patterned lounge chairs in the foreground and a black ceramic vessel on a side counter add the layered, residential feel Kisawa calls its extended living room.", "src": "images/Kisawa Sanctuary/0864 - Kisawa Sanctuary - Main Terrace Restaurant - woven chairs and curved counter.jpg", "source": "https://kisawasanctuary.com/", "dimensions": "1075x1521", "size": 574153}, {"number": "0865", "file": "0865 - Kisawa Sanctuary - Main Terrace Bar and Lounge - curved bar with patterned lounge chairs.jpg", "resort": "Kisawa Sanctuary", "space": "Main Terrace Bar and Lounge", "description": "The Main Terrace bar and lounge, captioned by Studio NJF as the Restaurant Main Terrace Interior: a curved, fluted timber bar with round porthole windows to the sea behind it, fronted by low bar stools. Groups of timber lounge chairs with cream patterned upholstery sit on woven grass rugs, beneath brass lantern pendants and the arched ribbed ceiling. A carved wooden figure and ceramics on the bar, plus a vast potted palm, carry the pan African decor into the public rooms.", "src": "images/Kisawa Sanctuary/0865 - Kisawa Sanctuary - Main Terrace Bar and Lounge - curved bar with patterned lounge chairs.jpg", "source": "https://studionjf.com/work/architectural-design/", "dimensions": "1046x1500", "size": 338644}, {"number": "0866", "file": "0866 - Kisawa Sanctuary - Main Terrace Wine Room - live edge tasting table and wine wall.jpg", "resort": "Kisawa Sanctuary", "space": "Main Terrace Wine Room", "description": "The wine room off the Main Terrace: a dramatic live edge timber tasting table set with glasses and boards, surrounded by chairs with woven circular backs, before a full wall of light timber wine cabinets and racks. A dark timber door pierced with three large circular windows glows with daylight, and woven baskets and ceramic vessels line the top of the cabinetry. The room shows Kisawa dressing even its cellar spaces with the same woven, carved and ceramic vocabulary as the residences.", "src": "images/Kisawa Sanctuary/0866 - Kisawa Sanctuary - Main Terrace Wine Room - live edge tasting table and wine wall.jpg", "source": "https://kisawasanctuary.com/culinary/", "dimensions": "1200x1186", "size": 565869}, {"number": "0867", "file": "0867 - Kisawa Sanctuary - Baracca Restaurant - beachfront table with louvred doors.jpg", "resort": "Kisawa Sanctuary", "space": "Baracca Restaurant", "description": "A quiet corner of Baracca, the Mozambican restaurant, captioned by Studio NJF as the Baracca interior: a simple dark timber table and four matching chairs on a woven grass mat, set for dinner before tall louvred timber doors. A woven pendant shade hangs above, and through the open doorway the thatch fringe, white sand and sea are visible. The restraint of the setting puts the craft of the timber, weaving and thatch entirely in focus.", "src": "images/Kisawa Sanctuary/0867 - Kisawa Sanctuary - Baracca Restaurant - beachfront table with louvred doors.jpg", "source": "https://studionjf.com/work/furniture/", "dimensions": "1050x1466", "size": 444076}, {"number": "0868", "file": "0868 - Kisawa Sanctuary - Baracca Bar - thatched bar glowing at dusk.jpg", "resort": "Kisawa Sanctuary", "space": "Baracca Bar", "description": "Baracca at dusk, its steep thatched gable glowing amber through coloured glass panels above an open fronted bar lined with bottles and timber counters. Woven chairs and small tables spill onto the sand terrace, and a lantern lit woven path leads through the dunes to the entrance. The image captures the playful, barefoot character of the sunset facing bar, built from thatch, timber and woven screens like the rest of the sanctuary.", "src": "images/Kisawa Sanctuary/0868 - Kisawa Sanctuary - Baracca Bar - thatched bar glowing at dusk.jpg", "source": "https://kisawasanctuary.com/", "dimensions": "1900x1384", "size": 470027}, {"number": "0869", "file": "0869 - Kisawa Sanctuary - Natural Wellness Center - treatment room under thatched dome.jpg", "resort": "Kisawa Sanctuary", "space": "Natural Wellness Center", "description": "A treatment room in the Natural Wellness Center, its white draped massage table set on a broad striped woven rug beneath a soaring conical thatched dome carried on massive timber poles. Three large woven storage vessels with geometric patterning line the curved plaster wall beside a door pierced with circular openings, and brass singing bowls are arranged on the floor for sound healing. Cream boucle armchairs and a small carved side table complete a room where woven grass, thatch and timber do all the decorative work.", "src": "images/Kisawa Sanctuary/0869 - Kisawa Sanctuary - Natural Wellness Center - treatment room under thatched dome.jpg", "source": "https://kisawasanctuary.com/", "dimensions": "1600x1650", "size": 589477}, {"number": "0870", "file": "0870 - Kisawa Sanctuary - Natural Wellness Center - Iyashi Dome infrared treatment room.jpg", "resort": "Kisawa Sanctuary", "space": "Natural Wellness Center", "description": "The Iyashi Dome room in the Natural Wellness Center: the arched white infrared dome bed faces a draped treatment table across a striped woven rug, under a conical thatched ceiling on heavy timber rafters. Sheer curtains soften two tall doors that open to the thatched domes outside, and a boucle armchair, a large woven planter and a small rope wrapped side table furnish the space. It shows the wellness interiors using the same natural fibre palette as the residences, even around high technology equipment.", "src": "images/Kisawa Sanctuary/0870 - Kisawa Sanctuary - Natural Wellness Center - Iyashi Dome infrared treatment room.jpg", "source": "https://kisawasanctuary.com/wellness/", "dimensions": "1600x2039", "size": 570918}, {"number": "0871", "file": "0871 - Miavana by Time + Tide - Villa Bedroom - Canopy bed with turquoise ombre curtains.jpg", "resort": "Miavana by Time + Tide", "space": "Villa Bedroom", "description": "A canopy bed dressed in crisp white linen sits under a sheer white canopy, with a straw hat resting on the cover as a quiet castaway note. Hand dyed curtains fall in an ombre of deep aqua to pale turquoise beside floor to ceiling glass, echoing the illuminated ocean outside. A low white lounge chair, a small desk with a woven seat chair, woven floor matting and pale timber decking boards keep the room airy, while Malagasy wood and bamboo lined ceilings warm the minimalist steel framed structure.", "src": "images/Miavana by Time + Tide/0871 - Miavana by Time + Tide - Villa Bedroom - Canopy bed with turquoise ombre curtains.jpg", "source": "https://miavana.com/gallery/", "dimensions": "1800x1200", "size": 295728}, {"number": "0872", "file": "0872 - Miavana by Time + Tide - Villa Bedroom - Dusk view across bed to private deck.jpg", "resort": "Miavana by Time + Tide", "space": "Villa Bedroom", "description": "At dusk the bedroom opens through retractable glass to a private deck, pool and palm garden, so the sleeping space reads as part of the landscape. The bed faces the view across a long woven runner, flanked by a cream lounge chair and a substantial Malagasy wood desk and headboard unit. Oversized globe pendants and small paper lamps glow against slatted timber screens and hand dyed turquoise curtains. The mood is desert modernism softened by tropical textiles and warm evening light.", "src": "images/Miavana by Time + Tide/0872 - Miavana by Time + Tide - Villa Bedroom - Dusk view across bed to private deck.jpg", "source": "https://miavana.com/gallery/", "dimensions": "2560x1440", "size": 404516}, {"number": "0873", "file": "0873 - Miavana by Time + Tide - Villa Bedroom - Curved glass wall and globe pendant.jpg", "resort": "Miavana by Time + Tide", "space": "Villa Bedroom", "description": "A sweeping curved wall of glass wraps this bedroom, framing palms and sea from the white dressed bed. A vast spherical paper pendant hangs over the bed, balancing the fine lines of the bamboo lined ceiling and pale boarded floor. In the sitting zone a white lounge chair and a low slung timber chair with woven detailing face the view, keeping furniture low and unhurried. Hand dyed turquoise curtains and white sail like canopy fabric soften the architecture throughout.", "src": "images/Miavana by Time + Tide/0873 - Miavana by Time + Tide - Villa Bedroom - Curved glass wall and globe pendant.jpg", "source": "https://miavana.com/gallery/", "dimensions": "1800x1200", "size": 302951}, {"number": "0874", "file": "0874 - Miavana by Time + Tide - Study and Dressing Area - Open wardrobe shelving beside canopy bed.jpg", "resort": "Miavana by Time + Tide", "space": "Study and Dressing Area", "description": "Open timber wardrobe shelving lines one wall of the bedroom, with hanging space, folded storage and a dressing table visible beyond the bed, showing how dressing is integrated rather than hidden. The canopy bed is built into a solid Malagasy wood headboard unit with globe lamps at each side. Through the glass, a vanity with a round mirror and turquoise detailing links the dressing zone to the bathroom. Raffia and bamboo ceiling linings and pale decking floors unify the whole suite.", "src": "images/Miavana by Time + Tide/0874 - Miavana by Time + Tide - Study and Dressing Area - Open wardrobe shelving beside canopy bed.jpg", "source": "https://miavana.com/gallery/", "dimensions": "1800x1200", "size": 291105}, {"number": "0875", "file": "0875 - Miavana by Time + Tide - Study and Dressing Area - Curved study room with daybeds and desk.jpg", "resort": "Miavana by Time + Tide", "space": "Study and Dressing Area", "description": "This curved secondary room, the villa study that can convert to a childrens bedroom, is furnished with two white daybeds piled with turquoise cushions under sheer canopy drapes. A round natural fibre rug anchors a small white desk and midcentury style timber chairs at the centre of the pale boarded floor. Slatted Malagasy wood walls, a woven bamboo ceiling and hand dyed turquoise curtains create a cocooning, handcrafted feel. It is a useful study in flexible luxury, where a workspace, reading room and guest sleeping share one calm palette.", "src": "images/Miavana by Time + Tide/0875 - Miavana by Time + Tide - Study and Dressing Area - Curved study room with daybeds and desk.jpg", "source": "https://miavana.com/gallery/", "dimensions": "1800x1200", "size": 316156}, {"number": "0876", "file": "0876 - Miavana by Time + Tide - Villa Living Room - Curved turquoise sofa and wicker chairs.jpg", "resort": "Miavana by Time + Tide", "space": "Villa Living Room", "description": "A large curved sofa upholstered in vivid turquoise dominates the living room, paired with a matching ottoman and a low timber tray table displaying shells. Blackened wicker lounge chairs and a patterned woven rug add contrast against the slatted timber walls and dark wood ceiling. Beyond the open glass wall, the private pool, striped turquoise pouffe and dining terrace extend the living space outdoors. Bespoke midcentury forms, nautical shell decor and the signature turquoise palette define the Miavana living style.", "src": "images/Miavana by Time + Tide/0876 - Miavana by Time + Tide - Villa Living Room - Curved turquoise sofa and wicker chairs.jpg", "source": "https://miavana.com/gallery/", "dimensions": "2560x1457", "size": 485030}, {"number": "0877", "file": "0877 - Miavana by Time + Tide - Villa Living Room - Open plan dining table and kitchenette bar.jpg", "resort": "Miavana by Time + Tide", "space": "Villa Living Room", "description": "The open plan living pavilion combines a long oval dining table on a hand dyed turquoise rug with a kitchenette bar faced in stacked timber blocks. Cane backed timber dining chairs, a spherical pendant and ceiling fans sit under a bamboo lined ceiling that runs uninterrupted to the terrace. Hand hewn stone and vertical Malagasy wood slats clad the walls, while turquoise chairs on the deck repeat the interior accent colour. It shows the villa as a single flowing entertaining space rather than separate formal rooms.", "src": "images/Miavana by Time + Tide/0877 - Miavana by Time + Tide - Villa Living Room - Open plan dining table and kitchenette bar.jpg", "source": "https://miavana.com/gallery/", "dimensions": "1800x1200", "size": 362085}, {"number": "0878", "file": "0878 - Miavana by Time + Tide - Villa Bathroom - Long vanity counter and sunken bath.jpg", "resort": "Miavana by Time + Tide", "space": "Villa Bathroom", "description": "A long white vanity counter on angled timber legs runs through the bathroom, carrying a vessel basin, brass toned bottles and a large round mirror on a slatted wood wall. In the foreground a sunken bath is set into the pale deck, with the canopy bed visible through the open plan suite beyond. Hand dyed turquoise glass panels and curtains separate zones without closing them off. The design pairs crisp white sanitaryware with warm Malagasy woods and woven ceiling linings.", "src": "images/Miavana by Time + Tide/0878 - Miavana by Time + Tide - Villa Bathroom - Long vanity counter and sunken bath.jpg", "source": "https://miavana.com/gallery/", "dimensions": "1800x1200", "size": 304404}, {"number": "0879", "file": "0879 - Miavana by Time + Tide - Villa Bathroom - Sunken square bath facing the beach.jpg", "resort": "Miavana by Time + Tide", "space": "Villa Bathroom", "description": "A deep square sunken bath sits in a white plinth at the centre of the bathroom, positioned to face palms, beach and sea through full height glass. A small timber stool, woven bath mat and amber glass bottles are the only accessories, keeping the scene deliberately spare. Slatted Malagasy wood walls and a bamboo lined ceiling enclose the space in warm natural texture. This is bathing as a viewing ritual, with the indoor stone and timber bathroom opening directly to the outdoors.", "src": "images/Miavana by Time + Tide/0879 - Miavana by Time + Tide - Villa Bathroom - Sunken square bath facing the beach.jpg", "source": "https://miavana.com/gallery/", "dimensions": "1800x1200", "size": 238586}, {"number": "0880", "file": "0880 - Miavana by Time + Tide - Outdoor Deck - Oval private pool and sun loungers.jpg", "resort": "Miavana by Time + Tide", "space": "Outdoor Deck", "description": "A white oval plunge pool is inset into the pale timber deck directly in front of the villa, with turquoise cushioned loungers and a white parasol arranged beside it. Striped turquoise pouffes and low deck chairs carry the interior accent colour outdoors, while the glass frontage reveals hand dyed curtains within. Palm planting and lawn soften the deck edges and the sea closes the view. The deck works as an outdoor living room, furnished rather than simply landscaped.", "src": "images/Miavana by Time + Tide/0880 - Miavana by Time + Tide - Outdoor Deck - Oval private pool and sun loungers.jpg", "source": "https://miavana.com/gallery/", "dimensions": "1800x1200", "size": 283936}, {"number": "0881", "file": "0881 - Miavana by Time + Tide - Spa - Outdoor massage treatment on beach deck.jpg", "resort": "Miavana by Time + Tide", "space": "Spa", "description": "Two treatment beds dressed in white linen and folded plaid blankets are set on a pale timber deck facing the beach for an open air massage. Miavana has no separate spa building, and the official wellness approach treats the whole island as the spa, with treatments given in the villa or a chosen setting. Natural fibres, bare timber and the sound of the ocean replace a conventional treatment room interior. For a designer, the lesson is in the portable, textile led treatment setup rather than fixed spa furniture.", "src": "images/Miavana by Time + Tide/0881 - Miavana by Time + Tide - Spa - Outdoor massage treatment on beach deck.jpg", "source": "https://miavana.com/gallery/", "dimensions": "1800x1200", "size": 115355}, {"number": "0882", "file": "0882 - Miavana by Time + Tide - Piazza Central Area - Evening pavilion beside the infinity pool.jpg", "resort": "Miavana by Time + Tide", "space": "Piazza Central Area", "description": "At night the Piazza pavilion glows behind the infinity pool, its open sided restaurant and lounge framed by white columns and a timber lined roof. Hand hewn stone walls in pale seashell tones form the turreted buildings behind, while a broad timber deck with a sculptural propeller decor piece leads the eye along the water. Lounge chairs and dining tables are arranged loosely under the pavilion, keeping the central area social and unhurried. It is the clearest view of the Piazza as the stone built heart of the island.", "src": "images/Miavana by Time + Tide/0882 - Miavana by Time + Tide - Piazza Central Area - Evening pavilion beside the infinity pool.jpg", "source": "https://miavana.com/gallery/", "dimensions": "2560x1707", "size": 440069}, {"number": "0883", "file": "0883 - Miavana by Time + Tide - Piazza Central Area - Wine cellar tasting room La Cave.jpg", "resort": "Miavana by Time + Tide", "space": "Piazza Central Area", "description": "The circular wine cellar, known as La Cave, is lined floor to ceiling with timber bottle racking set against curved hand hewn stone walls. A long Malagasy wood tasting table carries bottles, glasses and a model ship, lit by a single large globe pendant. Four circular glass skylights in the cellar ceiling are a noted Piazza feature, bringing daylight into the stone room. The cellar shows the resort at its most crafted, combining storage, tasting and display in one curved interior.", "src": "images/Miavana by Time + Tide/0883 - Miavana by Time + Tide - Piazza Central Area - Wine cellar tasting room La Cave.jpg", "source": "https://miavana.com/gallery/", "dimensions": "1800x1200", "size": 257676}, {"number": "0884", "file": "0884 - Miavana by Time + Tide - Lounge - Infinity pool with stone turret and draped cabanas.jpg", "resort": "Miavana by Time + Tide", "space": "Lounge", "description": "The Piazza infinity pool curves toward the sea beside a round hand hewn stone turret, with white draped cabanas sheltering loungers at its edge. Pale timber decking and low coastal planting keep the foreground quiet so the turquoise water carries the colour. Gauzy white curtains echo the sail canvas screens used inside the villas. As a lounge space it is furnished for long, shaded pauses between swims rather than formal seating.", "src": "images/Miavana by Time + Tide/0884 - Miavana by Time + Tide - Lounge - Infinity pool with stone turret and draped cabanas.jpg", "source": "https://miavana.com/gallery/", "dimensions": "1800x1200", "size": 297058}, {"number": "0885", "file": "0885 - Miavana by Time + Tide - Lounge - Cabinet de Curiosities collection room.jpg", "resort": "Miavana by Time + Tide", "space": "Lounge", "description": "The Cabinet de Curiosities is a thatched, timber beamed collection room where framed natural history prints, a vast butterfly display and artefacts under glass domes cover turquoise painted walls. Rattan lounge chairs with white cushions, round marble topped tables and long Malagasy wood display tables furnish it as a lounge as much as a museum. A ships wheel, globe and woven pendants add a nautical, exploratory layer of decor. It is the richest source at Miavana for art, objects and display ideas.", "src": "images/Miavana by Time + Tide/0885 - Miavana by Time + Tide - Lounge - Cabinet de Curiosities collection room.jpg", "source": "https://miavana.com/gallery/", "dimensions": "1800x1200", "size": 261539}, {"number": "0886", "file": "0886 - Miavana by Time + Tide - Bar - Toulou Bar stone counter and rattan chairs.jpg", "resort": "Miavana by Time + Tide", "space": "Bar", "description": "Toulou Bar is built from wonky hand hewn stone walls and a stone faced counter, with hand axed rosewood shelves holding bottles against the sea view. Rattan and cane lounge chairs with white cushions, low round tables and a woven rug furnish the shaded terrace under a bamboo lined ceiling. Turquoise ceramics and cushions provide the single accent colour against stone, cane and timber. Upstairs and downstairs seating in the same stone tower gives the bar panoramic views over the Piazza and beach.", "src": "images/Miavana by Time + Tide/0886 - Miavana by Time + Tide - Bar - Toulou Bar stone counter and rattan chairs.jpg", "source": "https://miavana.com/gallery/", "dimensions": "1800x1200", "size": 291143}, {"number": "0887", "file": "0887 - Miavana by Time + Tide - Restaurant and Dining Pavilion - Sunset dining deck with sunken circular lounge.jpg", "resort": "Miavana by Time + Tide", "space": "Restaurant and Dining Pavilion", "description": "An outdoor dining table dressed in white linen stands on the Piazza deck at sunset beside a sunken circular lounge sofa upholstered in pale turquoise. Timber dining chairs with woven seats, stone paving inlaid with a subtle pattern and broad timber decking define the restaurant terrace. Palms frame the sea view and no walls interrupt the open air setting. It captures Miavana dining as pavilion living, where furniture is low, circular and oriented to the horizon.", "src": "images/Miavana by Time + Tide/0887 - Miavana by Time + Tide - Restaurant and Dining Pavilion - Sunset dining deck with sunken circular lounge.jpg", "source": "https://miavana.com/gallery/", "dimensions": "1800x1200", "size": 202523}, {"number": "0888", "file": "0888 - Miavana by Time + Tide - Restaurant and Dining Pavilion - Silvio restaurant sandy floor with hammock chairs.jpg", "resort": "Miavana by Time + Tide", "space": "Restaurant and Dining Pavilion", "description": "Silvio restaurant sits on a sandy floor under a suspended palm leaf woven roof, exactly as the official design account describes, with ocean facing hammocks in bright striped textiles at its centre. Hand hewn stone walls, simple timber dining tables and woven seat chairs keep the room barefoot and informal, while the Piazza moat pool wraps around the sand island. Colour comes from the hammock fabrics and the turquoise water rather than from ornament. It is a distinctive model for relaxed restaurant design built from local, natural materials.", "src": "images/Miavana by Time + Tide/0888 - Miavana by Time + Tide - Restaurant and Dining Pavilion - Silvio restaurant sandy floor with hammock chairs.jpg", "source": "https://miavana.com/island-inspired-design/", "dimensions": "1800x1200", "size": 266948}, {"number": "0889", "file": "0889 - Le Taha'a by Pearl Resorts - Overwater Suite - king bedroom with carved wardrobes.jpg", "resort": "Le Taha'a by Pearl Resorts", "space": "Overwater Suite", "description": "A wide king bedroom under a high pitched ceiling lined in woven pandanus, with warm timber floors and a low platform bed framed in light wood. At the foot of the bed a glass panel set into the floor looks down to the lagoon, a signature overwater detail. Behind the bed, full height wardrobe doors carry hand carved Polynesian motifs, flanked by woven rattan wall covering and a framed painting in hot orange tones by a Polynesian artist. A timber framed daybed with turquoise patterned cushions sits to one side, and the white bedding is dressed with a turquoise tapa pattern runner and scattered flowers.", "src": "images/Le Taha'a by Pearl Resorts/0889 - Le Taha'a by Pearl Resorts - Overwater Suite - king bedroom with carved wardrobes.jpg", "source": "https://www.letahaa.com/en/tahaa-overwater-suite-room.html", "dimensions": "2048x1365", "size": 1815653}, {"number": "0890", "file": "0890 - Le Taha'a by Pearl Resorts - Overwater Suite Bathroom - canoe shaped bathtub and vessel sinks.jpg", "resort": "Le Taha'a by Pearl Resorts", "space": "Overwater Suite Bathroom", "description": "A generous bathroom centred on a deep oval bathtub clad in horizontal timber boards, its hull like form echoing a Polynesian canoe, which the resort confirms is the deliberate reference for its overwater suite tubs. Twin white vessel basins sit on curved timber counters carried on pedestals wrapped in woven coconut nape rope. Sliding timber panels are incised with a double hulled canoe and wave motifs, and the vaulted ceiling is lined in woven matting. Stone toned floor tiles, timber framed mirrors and folded white towels keep the palette natural and calm.", "src": "images/Le Taha'a by Pearl Resorts/0890 - Le Taha'a by Pearl Resorts - Overwater Suite Bathroom - canoe shaped bathtub and vessel sinks.jpg", "source": "https://www.letahaa.com/en/tahaa-overwater-suite-room.html", "dimensions": "2048x1365", "size": 1680226}, {"number": "0891", "file": "0891 - Le Taha'a by Pearl Resorts - Premium Overwater Suite - curved desk behind king bed.jpg", "resort": "Le Taha'a by Pearl Resorts", "space": "Premium Overwater Suite", "description": "The suite is planned around a curved timber desk and shelving unit that stands directly behind the king bed, so the sleeping area doubles as a writing and dressing space. Polished timber floors run under a woven pandanus ceiling, and the doors at each side are lashed with dark X pattern bindings in the manner of traditional canoe lashing. Table lamps with pale shades sit on the desk, sheer curtains soften the glass wall to the deck, and through the opening at the far end the lagoon and the island of Taha'a close the view.", "src": "images/Le Taha'a by Pearl Resorts/0891 - Le Taha'a by Pearl Resorts - Premium Overwater Suite - curved desk behind king bed.jpg", "source": "https://www.letahaa.com/en/tahaa-premium-overwater-suite.html", "dimensions": "2500x1666", "size": 1999742}, {"number": "0892", "file": "0892 - Le Taha'a by Pearl Resorts - Overwater Suite Terrace - sun lounger deck over lagoon.jpg", "resort": "Le Taha'a by Pearl Resorts", "space": "Overwater Suite Terrace", "description": "A private timber deck over the lagoon furnished with a single low white sun lounger, shaded by the deep overhang of the pandanus thatch roof. Dark timber railings keep the horizon open toward the motu and its palm grove. The decking boards, thatch fringe and simple contemporary lounger show how the resort pairs traditional Polynesian building materials with restrained modern outdoor furniture.", "src": "images/Le Taha'a by Pearl Resorts/0892 - Le Taha'a by Pearl Resorts - Overwater Suite Terrace - sun lounger deck over lagoon.jpg", "source": "https://www.letahaa.com/en/sunset-overwater-suite.html", "dimensions": "2048x1365", "size": 1848981}, {"number": "0893", "file": "0893 - Le Taha'a by Pearl Resorts - Pool Beach Villa - king bedroom with carved canoe door.jpg", "resort": "Le Taha'a by Pearl Resorts", "space": "Pool Beach Villa", "description": "A beach villa bedroom with a low dark timber platform bed dressed in white linen, a turquoise tapa pattern runner and cushions, and flower petals spelling a welcome across the cover. Above the bed hangs a large colourful painting of Polynesian figures, one of the original artworks the resort commissions from local artists. A sliding door beside the bed is carved with a sailing canoe, and a woven pandanus ceiling, timber dresser and black shaded bedside lamps complete the warm, crafted interior.", "src": "images/Le Taha'a by Pearl Resorts/0893 - Le Taha'a by Pearl Resorts - Pool Beach Villa - king bedroom with carved canoe door.jpg", "source": "https://www.letahaa.com/en/pool-beach-villa.html", "dimensions": "2500x1667", "size": 1879442}, {"number": "0894", "file": "0894 - Le Taha'a by Pearl Resorts - Pool Beach Villa Living Area - white sofa and woven blinds.jpg", "resort": "Le Taha'a by Pearl Resorts", "space": "Pool Beach Villa Living Area", "description": "A separate living room with a long white sofa scattered with turquoise patterned cushions, facing a low live edge timber coffee table on a blue green rug. Woven blinds filter the windows, and a woven wall panel sits between timber posts under the pandanus lined ceiling. Sliding glass doors open to a shaded terrace with outdoor dining, so the room works as an indoor outdoor salon. A sculptural black lamp on a timber cabinet adds a contemporary note.", "src": "images/Le Taha'a by Pearl Resorts/0894 - Le Taha'a by Pearl Resorts - Pool Beach Villa Living Area - white sofa and woven blinds.jpg", "source": "https://www.letahaa.com/en/pool-beach-villa.html", "dimensions": "2048x1365", "size": 2197585}, {"number": "0895", "file": "0895 - Le Taha'a by Pearl Resorts - Pool Beach Villa Bathroom - twin vessel sinks and outdoor shower.jpg", "resort": "Le Taha'a by Pearl Resorts", "space": "Pool Beach Villa Bathroom", "description": "A bathroom that opens almost completely to a private garden court, with twin white vessel basins on semicircle timber counters carried on woven rope pedestals. Grey stone panels banded with timber line the walls, and full height glass doors slide back to a stone walled outdoor shower area paved in stone slabs. Pandanus thatch shades the opening, towels are embroidered with the resort monogram, and the whole room is built from the stone, coral toned and timber materials used across the resort.", "src": "images/Le Taha'a by Pearl Resorts/0895 - Le Taha'a by Pearl Resorts - Pool Beach Villa Bathroom - twin vessel sinks and outdoor shower.jpg", "source": "https://www.letahaa.com/en/pool-beach-villa.html", "dimensions": "2500x1666", "size": 979596}, {"number": "0896", "file": "0896 - Le Taha'a by Pearl Resorts - Pool Beach Villa Terrace - thatched gazebo and plunge pool.jpg", "resort": "Le Taha'a by Pearl Resorts", "space": "Pool Beach Villa Terrace", "description": "The villa garden terrace is arranged as outdoor rooms: a thatched gazebo on thick timber posts shelters a cushioned day sofa and low table, while a small dining set sits in front of the villa doors beside the plunge pool. Dry stone walls enclose the garden for privacy, and the decking is laid in pale timber boards. Pandanus thatch, volcanic stone and tropical planting give the furnished outdoor living space the same crafted character as the interiors.", "src": "images/Le Taha'a by Pearl Resorts/0896 - Le Taha'a by Pearl Resorts - Pool Beach Villa Terrace - thatched gazebo and plunge pool.jpg", "source": "https://www.letahaa.com/en/pool-beach-villa.html", "dimensions": "1800x1199", "size": 820594}, {"number": "0897", "file": "0897 - Le Taha'a by Pearl Resorts - Premium Pool Beach Villa - carved canoe sliding door detail.jpg", "resort": "Le Taha'a by Pearl Resorts", "space": "Premium Pool Beach Villa", "description": "A close view of a sliding door panel incised with a Polynesian double hulled sailing canoe, its sails filled with fine geometric patterning in the style of Marquesan tapa cloth. The panel is framed in warm timber and slides across a doorway where double doors beyond carry carved X lashings and dark metal handles. This single detail explains the resort's design language: navigation imagery, hand worked timber and tapa pattern applied to everyday architectural elements.", "src": "images/Le Taha'a by Pearl Resorts/0897 - Le Taha'a by Pearl Resorts - Premium Pool Beach Villa - carved canoe sliding door detail.jpg", "source": "https://www.letahaa.com/en/premium-pool-beach-villa.html", "dimensions": "2560x1707", "size": 618624}, {"number": "0898", "file": "0898 - Le Taha'a by Pearl Resorts - Royal Beach Villa - outdoor stone bathtub in garden.jpg", "resort": "Le Taha'a by Pearl Resorts", "space": "Royal Beach Villa", "description": "A freestanding outdoor bathtub hewn from a single stone toned block, set on dark pebbles in a walled tropical garden and scattered with flower petals. The rough outer surface contrasts with the smooth dark interior, and a simple chrome filler stands at one end. Dry stone walls, palm planting and sand underfoot make the bath a piece of garden sculpture as much as a bathroom fixture, a signature feature of the beach villas.", "src": "images/Le Taha'a by Pearl Resorts/0898 - Le Taha'a by Pearl Resorts - Royal Beach Villa - outdoor stone bathtub in garden.jpg", "source": "https://www.letahaa.com/en/royal-beach-villa.html", "dimensions": "2048x1366", "size": 3293367}, {"number": "0899", "file": "0899 - Le Taha'a by Pearl Resorts - Royal Beach Villa Living Area - barrel chairs and navigation paintings.jpg", "resort": "Le Taha'a by Pearl Resorts", "space": "Royal Beach Villa Living Area", "description": "A grand living space under a soaring woven ceiling carried on exposed dark timber trusses, with two white barrel armchairs and yellow cushions arranged on a pale blue rug in the foreground. Large framed paintings of Polynesian navigation under night skies hang on both walls; the resort notes these works were created exclusively for the Royal Villas by Haumani Stanley. Beyond, a carved timber screen frames the bedroom, and polished timber floors and a long console table keep the furnishing calm against the dramatic architecture.", "src": "images/Le Taha'a by Pearl Resorts/0899 - Le Taha'a by Pearl Resorts - Royal Beach Villa Living Area - barrel chairs and navigation paintings.jpg", "source": "https://www.letahaa.com/en/royal-beach-villa.html", "dimensions": "2300x1532", "size": 926724}, {"number": "0900", "file": "0900 - Le Taha'a by Pearl Resorts - Hawaiki Nui Restaurant - treetop dining hall with stone pillars.jpg", "resort": "Le Taha'a by Pearl Resorts", "space": "Hawaiki Nui Restaurant", "description": "The main restaurant is a long treetop dining hall under a steep pandanus thatch roof, its ridge hung with a large woven pendant light. Rough stone pillars divide the room, and rows of timber tables with white cloths and slatted timber chairs run down both sides above the lagoon view. Dark tiled and timber floors, ceiling fans and open sides give the formal table settings a breezy, elevated treehouse character.", "src": "images/Le Taha'a by Pearl Resorts/0900 - Le Taha'a by Pearl Resorts - Hawaiki Nui Restaurant - treetop dining hall with stone pillars.jpg", "source": "https://www.letahaa.com/en/gastronomy.html", "dimensions": "1500x2250", "size": 1567948}, {"number": "0901", "file": "0901 - Le Taha'a by Pearl Resorts - Titiraina Restaurant - open dining room with branch posts.jpg", "resort": "Le Taha'a by Pearl Resorts", "space": "Titiraina Restaurant", "description": "A beachside dining room under a vast woven pandanus canopy carried on natural branch posts that fork like trees through the space. Timber tables are set with woven placemats and paired with slatted chairs with blue cushions, and a host stand at the entrance carries the Titiraina name beneath a large colourful painting of Polynesian women. A stone clad counter, timber deck floor and tropical flower arrangements complete the relaxed feet in the sand restaurant.", "src": "images/Le Taha'a by Pearl Resorts/0901 - Le Taha'a by Pearl Resorts - Titiraina Restaurant - open dining room with branch posts.jpg", "source": "https://www.letahaa.com/en/gastronomy.html", "dimensions": "2560x1707", "size": 1092636}, {"number": "0902", "file": "0902 - Le Taha'a by Pearl Resorts - Tipairua Restaurant - round gourmet dining room at night.jpg", "resort": "Le Taha'a by Pearl Resorts", "space": "Tipairua Restaurant", "description": "The gourmet restaurant is a small round dining room photographed at night, with white clothed tables and timber chairs set around a central polished timber counter. A starburst chandelier hangs from the apex of the conical thatched ceiling, and sheer white curtains dress the openings between dark timber posts. The scale is deliberately intimate, matching the resort's description of a handful of tables, with candlelit settings and warm uplighting on the woodwork.", "src": "images/Le Taha'a by Pearl Resorts/0902 - Le Taha'a by Pearl Resorts - Tipairua Restaurant - round gourmet dining room at night.jpg", "source": "https://www.letahaa.com/en/gastronomy.html", "dimensions": "2560x1707", "size": 647690}, {"number": "0903", "file": "0903 - Le Taha'a by Pearl Resorts - Manuia Bar - swim up pool bar.jpg", "resort": "Le Taha'a by Pearl Resorts", "space": "Manuia Bar", "description": "The Manuia pool bar sits under a sweeping circular pandanus thatch roof, its name lettered on the timber bar front. A curved timber counter overlooks the pool, where round submerged stools let guests sit in the water at the bar. Bottles are shelved behind the counter, a tropical flower arrangement dresses the bar, and palms and the lagoon close the backdrop, making this the resort's relaxed daytime drinking spot.", "src": "images/Le Taha'a by Pearl Resorts/0903 - Le Taha'a by Pearl Resorts - Manuia Bar - swim up pool bar.jpg", "source": "https://www.letahaa.com/en/gastronomy.html", "dimensions": "2200x1466", "size": 1842078}, {"number": "0904", "file": "0904 - Le Taha'a by Pearl Resorts - Tiki Bar - bar interior with thatched canopy.jpg", "resort": "Le Taha'a by Pearl Resorts", "space": "Tiki Bar", "description": "An atmospheric evening bar interior with a long timber counter and high stools facing shelves of bottles lit under a fringe of pandanus thatch and a Tiki Bar sign. Low tables and curved timber lounge chairs are arranged on a rust toned rug over polished timber boards, beneath a woven ceiling with dark beams. The lighting is low and warm, picking out carved details and giving the room the feel of a traditional Polynesian gathering house.", "src": "images/Le Taha'a by Pearl Resorts/0904 - Le Taha'a by Pearl Resorts - Tiki Bar - bar interior with thatched canopy.jpg", "source": "https://www.letahaa.com/en/gastronomy.html", "dimensions": "1400x2100", "size": 1628401}, {"number": "0905", "file": "0905 - Le Taha'a by Pearl Resorts - Tavai Spa - thatched pavilions over inland lagoon.jpg", "resort": "Le Taha'a by Pearl Resorts", "space": "Tavai Spa", "description": "The Tavai Spa sits in two small thatched pavilions raised on timber stilts over the resort's still inland lagoon, reached through dense tropical planting. Pandanus thatch roofs, timber walls and a small deck mirror perfectly in the dark water, with palms and flowering trees enclosing the setting. The official spa pages show no treatment room interior, so this exterior view is the verifiable record of the spa's architecture and setting.", "src": "images/Le Taha'a by Pearl Resorts/0905 - Le Taha'a by Pearl Resorts - Tavai Spa - thatched pavilions over inland lagoon.jpg", "source": "https://www.letahaa.com/en/wellness-and-spa.html", "dimensions": "2560x1707", "size": 1259121}, {"number": "0906", "file": "0906 - Le Taha'a by Pearl Resorts - Reception - boathouse entrance with canoe at night.jpg", "resort": "Le Taha'a by Pearl Resorts", "space": "Reception", "description": "The reception at night is shaped like a traditional Polynesian boathouse, its tall hull form roof built in woven bamboo and pandanus rising to a sharp prow. A full size double hulled canoe with a white sail stands at the entrance, exactly as the resort describes, beside a carved tiki figure and dense planting. Warm light spills from the open front where the welcome desk sits, making the building itself the resort's central piece of cultural storytelling.", "src": "images/Le Taha'a by Pearl Resorts/0906 - Le Taha'a by Pearl Resorts - Reception - boathouse entrance with canoe at night.jpg", "source": "https://www.letahaa.com/en/resort.html", "dimensions": "2000x1332", "size": 876472}, {"number": "0907", "file": "0907 - Kona Village, a Rosewood Resort - Hale Bedroom - tree top king boat bed.jpg", "resort": "Kona Village, a Rosewood Resort", "space": "Hale Bedroom", "description": "Tree Top King Hale bedroom designed by NICOLEHOLLIS, centred on the low handmade bed inspired by the hull form of a fishing boat, a reference to the fishing village origins of Kaupulehu. Wire brushed oak floors and Douglas fir tongue and groove walls and ceilings give the room a warm, scraped timber envelope, while woven storage cabinetry, soft neutral linens and layered textiles carrying traditional Hawaiian motifs soften the geometry. The bed faces full height glazing and the furnished lanai beyond, so furniture, art and view are composed on a single axis.", "src": "images/Kona Village a Rosewood Resort/0907 - Kona Village, a Rosewood Resort - Hale Bedroom - tree top king boat bed.jpg", "source": "https://www.rosewoodhotels.com/en/kona-village/accommodation/rooms/tree-top-king-hale", "dimensions": "2000x1500", "size": 372263}, {"number": "0908", "file": "0908 - Kona Village, a Rosewood Resort - Kauhale Bedroom - beach front black sand two beds ocean view.jpg", "resort": "Kona Village, a Rosewood Resort", "space": "Kauhale Bedroom", "description": "Beach Front Black Sand Kauhale bedroom with two dressed beds set under a high pitched thatched ceiling in pale Douglas fir. Built in timber joinery lines both walls, integrating storage, lighting and display into the architecture rather than as applied furniture. White bedding, woven runners and a dark patterned rug introduce the textile layer, and the beds are aligned to a low, wide window that frames the ocean, keeping the palette restrained in the South and North Village tradition of colour drawn from sea and lava.", "src": "images/Kona Village a Rosewood Resort/0908 - Kona Village, a Rosewood Resort - Kauhale Bedroom - beach front black sand two beds ocean view.jpg", "source": "https://www.rosewoodhotels.com/en/kona-village/accommodation/suites/beach-front-black-sand-two-bedroom-kauhale", "dimensions": "2000x1478", "size": 355321}, {"number": "0909", "file": "0909 - Kona Village, a Rosewood Resort - Hale Living Area - beach front living room.jpg", "resort": "Kona Village, a Rosewood Resort", "space": "Hale Living Area", "description": "Beach front hale living room arranged for conversation, with a low sofa, timber armchairs, round coffee tables and a floor lamp grouped on a patterned area rug. Douglas fir panelling and scraped wood floors continue the hale material palette, while cushions and throws in earth and indigo tones carry Hawaiian pattern. Sliding walls open the whole room to the lanai and ocean, demonstrating the indoor outdoor planning that defines the 150 standalone hale, with local artwork and plantings used as quiet focal points.", "src": "images/Kona Village a Rosewood Resort/0909 - Kona Village, a Rosewood Resort - Hale Living Area - beach front living room.jpg", "source": "https://www.rosewoodhotels.com/en/kona-village/accommodation/suites/beach-front-black-sand-two-bedroom-kauhale", "dimensions": "2000x1500", "size": 418687}, {"number": "0910", "file": "0910 - Kona Village, a Rosewood Resort - Kauhale Living Room - ocean front black sand lounge.jpg", "resort": "Kona Village, a Rosewood Resort", "space": "Kauhale Living Room", "description": "Ocean Front Black Sand Kauhale covered living lounge, furnished as an outdoor room with a long upholstered sectional, woven side tables and low timber tables on a shaded deck. A bold graphic woven wall hanging in natural and dark fibres acts as the principal artwork, a direct example of textiles carrying traditional Hawaiian artforms. Weathered timber, basalt toned accents and open sides to the sea show how the kauhale extend living space onto the lanai without losing shelter or privacy.", "src": "images/Kona Village a Rosewood Resort/0910 - Kona Village, a Rosewood Resort - Kauhale Living Room - ocean front black sand lounge.jpg", "source": "https://www.rosewoodhotels.com/en/kona-village/accommodation/suites/ocean-front-black-sand-two-bedroom-kauhale", "dimensions": "2000x1500", "size": 416900}, {"number": "0911", "file": "0911 - Kona Village, a Rosewood Resort - Signature Kauhale Living Room - maheawalu living space.jpg", "resort": "Kona Village, a Rosewood Resort", "space": "Signature Kauhale Living Room", "description": "Maheawalu signature kauhale living room, the most residential interior in the set, with a large L shaped sectional in cream upholstery, rust and indigo cushions, a dark round coffee table and woven occasional tables on a large patterned rug. Open timber shelving displays ceramics, baskets and books as curated decor, and a large framed abstract artwork anchors the wall. Light wire brushed oak, vaulted fir ceilings and full glazing to the terrace keep the generous furniture grouping calm and grounded in the landscape.", "src": "images/Kona Village a Rosewood Resort/0911 - Kona Village, a Rosewood Resort - Signature Kauhale Living Room - maheawalu living space.jpg", "source": "https://www.rosewoodhotels.com/en/kona-village/accommodation/signature-suites/ocean-front-four-bedroom-maheawalu-kauhale", "dimensions": "2000x1500", "size": 584854}, {"number": "0912", "file": "0912 - Kona Village, a Rosewood Resort - Hale Bathroom - ocean front black sand concrete vanity and shower.jpg", "resort": "Kona Village, a Rosewood Resort", "space": "Hale Bathroom", "description": "Ocean Front Black Sand Kauhale bathroom with a long dark concrete vanity and integrated sinks formed to reflect the surrounding lava flows, one of the signature bathroom details of the rebuild. A glass enclosed shower with fine vertical screening, round mirror, timber walls and hanging robes complete the composition. The contrast of blackened concrete and basalt tones against warm Douglas fir and soft white textiles shows the Nicole Hollis method of pairing rugged natural material with refined, handmade fittings.", "src": "images/Kona Village a Rosewood Resort/0912 - Kona Village, a Rosewood Resort - Hale Bathroom - ocean front black sand concrete vanity and shower.jpg", "source": "https://www.rosewoodhotels.com/en/kona-village/accommodation/suites/ocean-front-black-sand-two-bedroom-kauhale", "dimensions": "1244x933", "size": 176763}, {"number": "0913", "file": "0913 - Kona Village, a Rosewood Resort - Hale Bathroom - ohana suite vanity and tub.jpg", "resort": "Kona Village, a Rosewood Resort", "space": "Hale Bathroom", "description": "Ohana Pool Kauhale bathroom with a dark stone topped double vanity, large mirrors, wall sconces and a black ladder towel rail holding white towels, with the edge of a deep soaking tub in the foreground. Pale timber doors and white painted panelling lighten the otherwise moody palette of dark floors and fittings. The room demonstrates the standard hale bathroom language at suite scale, generous circulation, concealed storage in fitted joinery and spa like fixtures in natural materials.", "src": "images/Kona Village a Rosewood Resort/0913 - Kona Village, a Rosewood Resort - Hale Bathroom - ohana suite vanity and tub.jpg", "source": "https://www.rosewoodhotels.com/en/kona-village/accommodation/signature-suites/ohana-pool-four-bedroom-kauhale", "dimensions": "2000x1500", "size": 225481}, {"number": "0914", "file": "0914 - Kona Village, a Rosewood Resort - Hale Bathroom - ocean view soaking tub.jpg", "resort": "Kona Village, a Rosewood Resort", "space": "Hale Bathroom", "description": "Hale bathroom centred on a matte black freestanding oval soaking tub with a timber bath caddy, set before a dark tiled walk in shower. Light timber ceilings and walls, a woven wall piece and glimpsed vanity joinery in the mirror keep the dark fixtures from feeling heavy. Concrete and stone tubs and sinks throughout the hale were formed after the lava flows around the resort, and this image shows that idea at its most sculptural, the tub treated as a piece of furniture in its own right.", "src": "images/Kona Village a Rosewood Resort/0914 - Kona Village, a Rosewood Resort - Hale Bathroom - ocean view soaking tub.jpg", "source": "https://www.rosewoodhotels.com/en/kona-village/accommodation/rooms/tree-top-king-hale", "dimensions": "2000x1500", "size": 359945}, {"number": "0915", "file": "0915 - Kona Village, a Rosewood Resort - Hale Outdoor Shower - ocean view outdoor shower.jpg", "resort": "Kona Village, a Rosewood Resort", "space": "Hale Outdoor Shower", "description": "Private outdoor shower enclosed by horizontal weathered timber fencing and a woven privacy screen, with a simple dark metal rain shower and a low timber bench holding folded towels and amenities. Palms and planting rise above the fence and the thatched eave shades the space, making the shower a furnished outdoor room rather than an add on. Outdoor showers are a defining hale feature, and this view records the material palette of weathered cypress, timber and stone in its purest form.", "src": "images/Kona Village a Rosewood Resort/0915 - Kona Village, a Rosewood Resort - Hale Outdoor Shower - ocean view outdoor shower.jpg", "source": "https://www.rosewoodhotels.com/en/kona-village/overview/gallery", "dimensions": "2000x1500", "size": 557332}, {"number": "0916", "file": "0916 - Kona Village, a Rosewood Resort - Hale Lanai - beach front furnished terrace.jpg", "resort": "Kona Village, a Rosewood Resort", "space": "Hale Lanai", "description": "Beach front hale lanai furnished with two solid timber lounge chairs with dark cushions and a small sculptural timber side table between them, set on a wide deck facing palms, lawn and the ocean. Thatched roofs shade the terrace on both sides, framing the furniture as an outdoor living room. The chunky, low, handcrafted character of the lanai furniture, built for weather and bare feet, is central to recreating the Kona Village style.", "src": "images/Kona Village a Rosewood Resort/0916 - Kona Village, a Rosewood Resort - Hale Lanai - beach front furnished terrace.jpg", "source": "https://www.rosewoodhotels.com/en/kona-village/accommodation", "dimensions": "2000x1500", "size": 548242}, {"number": "0917", "file": "0917 - Kona Village, a Rosewood Resort - Hale Lanai - tree top terrace daybed.jpg", "resort": "Kona Village, a Rosewood Resort", "space": "Hale Lanai", "description": "Tree Top Hale lanai with a generous upholstered daybed dressed in white linen, dark cushions and a loose throw, placed behind fine vertical timber screening that filters light and view. A turned timber side table and woven basket complete the small grouping, with palms and the resort grounds beyond the railing. The daybed lanai is the most repeated furniture idea across hale categories, generous enough for sleeping outdoors and detailed with textiles in Hawaiian patterns.", "src": "images/Kona Village a Rosewood Resort/0917 - Kona Village, a Rosewood Resort - Hale Lanai - tree top terrace daybed.jpg", "source": "https://www.rosewoodhotels.com/en/kona-village/accommodation/rooms/tree-top-king-hale", "dimensions": "2000x1538", "size": 532076}, {"number": "0918", "file": "0918 - Kona Village, a Rosewood Resort - Moana Restaurant - vaulted dining room live edge table.jpg", "resort": "Kona Village, a Rosewood Resort", "space": "Moana Restaurant", "description": "Moana signature restaurant interior under a soaring vaulted thatched ceiling, centred on the vast live edge communal table made from a Hilo grown mahogany tree by Kamuela Hardwoods. Oversized monkey pod tables fill the rest of the room, and overhead a ceiling installation by Native Hawaiian artist Kaili Chun nods to the crab claw sails of voyaging canoes. Warm timber structure, woven screens and open sides to Kahuwai Bay make this the clearest record of the resort public space furniture and art programme.", "src": "images/Kona Village a Rosewood Resort/0918 - Kona Village, a Rosewood Resort - Moana Restaurant - vaulted dining room live edge table.jpg", "source": "https://www.rosewoodhotels.com/en/kona-village/dining/moana-restaurant", "dimensions": "2000x1540", "size": 512665}, {"number": "0919", "file": "0919 - Kona Village, a Rosewood Resort - Moana Restaurant - terrace lounge and dining.jpg", "resort": "Kona Village, a Rosewood Resort", "space": "Moana Restaurant", "description": "Moana terrace lounge and dining area, with deep upholstered sofas, patterned armchairs and low tables arranged on the open deck between palms and the ocean, under the edge of the restaurant roof. The furniture grouping is residential in scale, encouraging guests to move from table to lounge within one space, true to the communal spirit of the original Moana. Natural timber, woven textiles and dark cushions repeat the hale palette at public scale.", "src": "images/Kona Village a Rosewood Resort/0919 - Kona Village, a Rosewood Resort - Moana Restaurant - terrace lounge and dining.jpg", "source": "https://www.rosewoodhotels.com/en/kona-village/dining/moana-restaurant", "dimensions": "2000x1594", "size": 528005}, {"number": "0920", "file": "0920 - Kona Village, a Rosewood Resort - Kahuwai Cookhouse - cookhouse dining.jpg", "resort": "Kona Village, a Rosewood Resort", "space": "Kahuwai Cookhouse", "description": "Kahuwai Cookhouse and Market dining room, an open sided pavilion with rows of light timber tables and canvas and wood director style chairs on a wide board deck. Timber posts, shelving with produce and vessels, and ceiling fans keep the room casual and market like, in deliberate contrast to Moana. The simple, durable, handcrafted furniture and the garden outlook record the paniolo inspired, fire cooking side of the resort food and beverage design.", "src": "images/Kona Village a Rosewood Resort/0920 - Kona Village, a Rosewood Resort - Kahuwai Cookhouse - cookhouse dining.jpg", "source": "https://www.rosewoodhotels.com/en/kona-village/dining/kahuwai-cookhouse-and-market", "dimensions": "2000x1500", "size": 457409}, {"number": "0921", "file": "0921 - Kona Village, a Rosewood Resort - Talk Story Bar - beach bar seating.jpg", "resort": "Kona Village, a Rosewood Resort", "space": "Talk Story Bar", "description": "Talk Story Bar at sunset, returned to its original sandy beach location, a thatched roof open bar with timber stools and low lounge chairs with cushions arranged on the sand among palms facing the ocean. The loose, sociable seating plan and natural materials, thatch, timber and woven fibre, preserve the upbeat character of the original resort bar. This is outdoor bar furniture at its most elemental, designed to be moved, gathered around and used barefoot.", "src": "images/Kona Village a Rosewood Resort/0921 - Kona Village, a Rosewood Resort - Talk Story Bar - beach bar seating.jpg", "source": "https://www.rosewoodhotels.com/en/kona-village/dining/talk-story-bar", "dimensions": "2000x1500", "size": 467289}, {"number": "0922", "file": "0922 - Kona Village, a Rosewood Resort - Shipwreck Bar - schooner bar on the beach.jpg", "resort": "Kona Village, a Rosewood Resort", "space": "Shipwreck Bar", "description": "Shipwreck Bar on the beach at sunset, built from the restored wreck of founder Johnno Jackson schooner New Moon, with its masts and hull form sheltering tables and chairs set directly on the sand. Palms frame the scene and the ocean closes the view, so the bar reads as both furniture and landmark. The restoration of this single object carries the whole design story of the rebuild, salvaged heritage, handcrafted repair and reuse at the centre of communal life.", "src": "images/Kona Village a Rosewood Resort/0922 - Kona Village, a Rosewood Resort - Shipwreck Bar - schooner bar on the beach.jpg", "source": "https://www.rosewoodhotels.com/en/kona-village/dining", "dimensions": "2000x1638", "size": 460358}, {"number": "0923", "file": "0923 - Kona Village, a Rosewood Resort - Asaya Spa - outdoor soaking tub over lava.jpg", "resort": "Kona Village, a Rosewood Resort", "space": "Asaya Spa", "description": "Asaya Spa outdoor soaking tub, a round pale concrete tub set on a timber deck at the edge of the black lava field, with a small timber stool and planted screening. Built into the lava flow and facing the mountains toward Hualalai volcano, Asaya uses the same wood and stone language as the hale but in darker, more rugged tones. The solitary tub against raw lava is the defining wellness image of the property and a study in concrete formed to echo natural flows.", "src": "images/Kona Village a Rosewood Resort/0923 - Kona Village, a Rosewood Resort - Asaya Spa - outdoor soaking tub over lava.jpg", "source": "https://www.rosewoodhotels.com/en/kona-village/wellness/spa", "dimensions": "2000x1438", "size": 303885}, {"number": "0924", "file": "0924 - Kona Village, a Rosewood Resort - Asaya Spa - lava field relaxation pavilion.jpg", "resort": "Kona Village, a Rosewood Resort", "space": "Asaya Spa", "description": "Asaya Spa relaxation pavilion at dusk, an open dark timber structure set in the lava field with low daybeds, cushioned lounge seating, a rectangular plunge pool and lanterns, with shelves of towels and vessels built into the wall. The pavilion shows the spa furniture language, low, horizontal and deeply cushioned, in blackened timber and stone that merge with the lava setting. It serves as the pre and post treatment tranquillity space described in the official spa programme.", "src": "images/Kona Village a Rosewood Resort/0924 - Kona Village, a Rosewood Resort - Asaya Spa - lava field relaxation pavilion.jpg", "source": "https://www.rosewoodhotels.com/en/kona-village/overview/gallery", "dimensions": "2000x1500", "size": 276241}, {"number": "0925", "file": "0925 - Turtle Inn - Seafront Cottages - carved headboard bedroom and living area.jpg", "resort": "Turtle Inn", "space": "Seafront Cottages", "description": "A single open plan room under a soaring palm thatch roof on exposed pole rafters, combining the sleeping and sitting areas in the classic Turtle Inn manner. The king bed carries a deeply carved dark wood headboard backed by a hanging Indonesian ikat textile with a red and black geometric pattern, and a painted and carved Balinese chest in red, green and gold stands at its foot topped with a turtle sculpture. Cream upholstered sofas and an armchair with batik cushions face a long low dark wood coffee table over a flat woven natural fibre rug, while a carved armoire, a shellphone side table with a shaded lamp, and framed botanical artwork complete the room. Polished dark hardwood floors, screened openings to the palms, and ceiling fans reinforce the deliberately rustic Balinese finish designed under architect Made Wijaya.", "src": "images/Turtle Inn/0925 - Turtle Inn - Seafront Cottages - carved headboard bedroom and living area.jpg", "source": "https://thecoppolahideaways.com/turtle-inn/dwelling/seafront-cottages", "dimensions": "2048x1366", "size": 3566773}, {"number": "0926", "file": "0926 - Turtle Inn - Poolside Garden View Cottages - bedroom with carved chest and ikat runner.jpg", "resort": "Turtle Inn", "space": "Poolside Garden View Cottages", "description": "A high vaulted cottage interior with palm thatch and bamboo lined gables, bamboo tie beams, and dark polished hardwood floors. In the foreground the bed is dressed in white with a purple and black ikat runner and an indigo batik cushion, and a long chest with a deeply carved and pierced floral lid sits at its foot. A cream sofa and armchair with batik cushions are arranged around a dark slatted coffee table beneath a Gauguin style painting of Tahitian figures, a house signature. At the left an antique weathered Balinese door stands open within a carved frame, leading to a screened porch with a small dining set, and louvred windows filter the garden light.", "src": "images/Turtle Inn/0926 - Turtle Inn - Poolside Garden View Cottages - bedroom with carved chest and ikat runner.jpg", "source": "https://thecoppolahideaways.com/turtle-inn/dwelling/poolside-garden-view-cottage", "dimensions": "2560x1919", "size": 1034756}, {"number": "0927", "file": "0927 - Turtle Inn - Seafront Villas - canopy bed through carved Balinese doorway.jpg", "resort": "Turtle Inn", "space": "Seafront Villas", "description": "The villa bedroom is seen through a monumental hand carved Balinese doorway whose scrolling floral lintel and jambs frame the whole composition, the single strongest statement of the Coppola hideaway style. Inside, a bamboo framed canopy bed hung with sheer white mosquito netting is dressed in white with a red woven runner and a round medallion batik cushion in gold and black. A carved floral chest stands at the foot of the bed on a flat woven striped rug over dark hardwood floors. To one side a painted low chest holds a shaded lamp and tropical flowers, a woven textile hangs on the wall, and a rustic pole stand holds a straw hat beside the louvred doors.", "src": "images/Turtle Inn/0927 - Turtle Inn - Seafront Villas - canopy bed through carved Balinese doorway.jpg", "source": "https://thecoppolahideaways.com/turtle-inn/dwelling/seafront-villas", "dimensions": "2048x1366", "size": 3048822}, {"number": "0928", "file": "0928 - Turtle Inn - Seafront Villas - living area and carved bedroom doorway.jpg", "resort": "Turtle Inn", "space": "Seafront Villas", "description": "A long living space under a steep thatched roof with bamboo lined walls and warm plank ceilings, looking through to a dining area and the sea beyond the screened porch. In the foreground a richly carved Balinese doorway with a scrolling floral arch opens into the bedroom, where a carved chest, a painted bedside cabinet with a shaded lamp, and a fringed woven wall hanging are visible. The sitting area mixes a cream slipcovered sofa with a woven rattan armchair and batik cushions on dark hardwood floors, lit by a small bamboo chandelier. Louvred shutters, a woven floor runner, and glimpsed porch furniture underline the indoor outdoor Balinese plan.", "src": "images/Turtle Inn/0928 - Turtle Inn - Seafront Villas - living area and carved bedroom doorway.jpg", "source": "https://thecoppolahideaways.com/turtle-inn/dwelling/seafront-villas", "dimensions": "2048x1366", "size": 3566009}, {"number": "0929", "file": "0929 - Turtle Inn - Sofias Beach House - wood panelled bedroom opening to courtyard.jpg", "resort": "Turtle Inn", "space": "Sofia's Beach House", "description": "A bedroom in Sofia's Beach House, the modernist tropical house designed by architect Laurent Deroo, where the Balinese cottage language gives way to flat ceilings and full height wood panelling in warm mid tone timber. A wide sliding opening frames the courtyard deck, palms, and the corrugated guest bungalow beyond, so the garden acts as the room's artwork. Furnishings are spare: a low platform bed in plain white, a woven rattan armchair with a brightly striped Guatemalan style cushion, a simple wood desk with a glass based lamp, and a potted heliconia in a woven basket. Dark hardwood floors and a white ceiling fan keep the palette calm and coastal.", "src": "images/Turtle Inn/0929 - Turtle Inn - Sofias Beach House - wood panelled bedroom opening to courtyard.jpg", "source": "https://thecoppolahideaways.com/turtle-inn/dwelling/sofias-beach-house", "dimensions": "1708x2560", "size": 771506}, {"number": "0930", "file": "0930 - Turtle Inn - Sofias Beach House - dining table with woven globe pendant.jpg", "resort": "Turtle Inn", "space": "Sofia's Beach House", "description": "The open air living and dining room of Sofia's Beach House, centred on a long solid wood table and bench in warm honeyed timber. A large spherical pendant woven from natural fibre hangs low over the table, which is set with a cheese board, a bottle of rose in a rustic ice bucket, glasses, and a coral sculpture on a wood block used as pure decor. Full height timber framed glazing and sliding panels open the room completely to palms and the outdoor dining terrace beyond. The mood is mid century Laurel Canyon meets the Caribbean, distinct from the carved Balinese cottages it adjoins.", "src": "images/Turtle Inn/0930 - Turtle Inn - Sofias Beach House - dining table with woven globe pendant.jpg", "source": "https://thecoppolahideaways.com/turtle-inn/dwelling/sofias-beach-house", "dimensions": "1708x2560", "size": 1090745}, {"number": "0931", "file": "0931 - Turtle Inn - Francis Family Pavilion - living room with carved screens and bamboo walls.jpg", "resort": "Turtle Inn", "space": "Francis' Family Pavilion", "description": "The great living room of Francis' Family Pavilion, the most ornate interior at Turtle Inn, with walls of vertical bamboo, a thatched vault, and two huge antique hand carved wooden screen walls dividing the bedrooms from the living space. A chandelier of pierced bamboo pendants hangs over cream sofas arranged around a carved coffee table draped with a patterned ikat cloth and batik cushions in rust and gold. At the centre a framed painting of goldfish, chosen in the Coppola family spirit, is set into a chevron panelled wood wall beneath carved crestwork, and a stone statue is glimpsed in the bedroom beyond. A tall ladder rises to the loft bedroom, and ceiling fans turn under the natural pole beams.", "src": "images/Turtle Inn/0931 - Turtle Inn - Francis Family Pavilion - living room with carved screens and bamboo walls.jpg", "source": "https://thecoppolahideaways.com/turtle-inn/dwelling/francis-family-pavilion", "dimensions": "2048x1366", "size": 3785299}, {"number": "0932", "file": "0932 - Turtle Inn - Francis Family Pavilion Bathroom - vessel basin and dark tiled walls.jpg", "resort": "Turtle Inn", "space": "Francis' Family Pavilion Bathroom", "description": "An ensuite bathroom in Francis' Family Pavilion lined with small dark green, almost black, square tiles laid in both grid and diamond patterns, the hand painted Thai tile character described in the resort's own fact sheet. A dark glass vessel basin sits on a pale stone topped wood vanity beneath a large oval mirror in a thick timber frame, with a woven rattan amenity basket, rolled white towels, and fresh orchids as styling. Louvred timber shutters, a hanging white bathrobe, dark hardwood floors, and heavy wood framing keep the bathroom inside the same rustic Balinese material palette as the bedrooms.", "src": "images/Turtle Inn/0932 - Turtle Inn - Francis Family Pavilion Bathroom - vessel basin and dark tiled walls.jpg", "source": "https://thecoppolahideaways.com/turtle-inn/dwelling/francis-family-pavilion", "dimensions": "2048x1372", "size": 288210}, {"number": "0933", "file": "0933 - Turtle Inn - Romans Lagoon Bungalow - timber living and dining room.jpg", "resort": "Turtle Inn", "space": "Roman's Lagoon Bungalow", "description": "The living and dining room of Roman's Lagoon Bungalow seen through its opening mirrored wall panel, a feature the resort itself describes for this residence. The room is built almost entirely of warm timber: plank walls, a pitched boarded ceiling, dark floors, and banks of screened windows looking to the lagoon greenery. A long wood dining table with cushioned chairs sits beside a built in daybed with palm print cushions, while boxy armchairs and an ottoman are upholstered in a brown palm tree motif fabric. Tiered corner shelves with lamps and objects, a hanging lantern pendant, and ceiling fans give the bungalow a collected, lived in family character quite different from the carved Balinese cottages.", "src": "images/Turtle Inn/0933 - Turtle Inn - Romans Lagoon Bungalow - timber living and dining room.jpg", "source": "https://thecoppolahideaways.com/turtle-inn/dwelling/romans-lagoon-bungalow", "dimensions": "2048x1366", "size": 2870178}, {"number": "0934", "file": "0934 - Turtle Inn - Mare Restaurant - dining room with barrel back chairs.jpg", "resort": "Turtle Inn", "space": "Mare Restaurant", "description": "The Mare dining room under its towering vaulted thatch roof, the flagship restaurant of Turtle Inn photographed for Beyond Green, the resort's Preferred Hotels sustainability collection. Rows of round and polygonal solid wood tables are set with woven placemats and napkins folded in glasses, surrounded by barrel back wooden chairs with bright blue seat cushions. Dark hardwood floors, heavy timber posts, and a central carved stone pedestal table anchor the space, while a cushioned lounge corner with black and white patterned pillows and a green glass pendant softens the far end. The room opens on all sides to the gardens, keeping the rustic open air Balinese pavilion character.", "src": "images/Turtle Inn/0934 - Turtle Inn - Mare Restaurant - dining room with barrel back chairs.jpg", "source": "https://www.staybeyondgreen.com/hotels/turtle-inn", "dimensions": "2048x1671", "size": 2837000}, {"number": "0935", "file": "0935 - Turtle Inn - Skip White Bar - bar and dining room under vaulted thatch.jpg", "resort": "Turtle Inn", "space": "Skip White Bar", "description": "A wide view across the Mare dining terrace to the Skip White Bar, named for the original owner of the property, photographed for Beyond Green. The bar sits at the far end under the same vast thatched vault, with bottle shelves, barrel front stools, and cross back bar chairs, while the foreground is all dining: long communal wood tables, smaller tables in blue cloths with woven blue runners, and rattan sofas with batik cushions for lounging. Enormous ceramic urns on carved green stands hold heliconia arrangements, and the polished dark floor reflects the warm light under the palm thatch and pole rafters.", "src": "images/Turtle Inn/0935 - Turtle Inn - Skip White Bar - bar and dining room under vaulted thatch.jpg", "source": "https://www.staybeyondgreen.com/hotels/turtle-inn", "dimensions": "2048x1366", "size": 3524753}, {"number": "0936", "file": "0936 - Turtle Inn - Gauguin Grill - bamboo bar with Gauguin paintings and sand floor.jpg", "resort": "Turtle Inn", "space": "Gauguin Grill", "description": "The sandy floored bar and lounge of the Gauguin Grill at night, its front formed from vertical bamboo poles under a black countertop, with plain round wooden bar stools. Walls are woven palm matting in a diamond pattern hung with framed Gauguin reproduction paintings, including the artist's self portrait, a direct nod to the restaurant's name. Two conical woven pendants light the bar, stocked with bottles, pineapples, and tropical flower arrangements. In the foreground, rustic pole framed armchairs with lime green cushions and teal pillows sit on the sand beside a carved root wood side table, with a bright red ice cart adding a single saturated accent.", "src": "images/Turtle Inn/0936 - Turtle Inn - Gauguin Grill - bamboo bar with Gauguin paintings and sand floor.jpg", "source": "https://thecoppolahideaways.com/turtle-inn/dining/gauguin-grill", "dimensions": "2048x1366", "size": 3827942}, {"number": "0937", "file": "0937 - Turtle Inn - Wine Aquarium - glass bottle wall and tasting terrace.jpg", "resort": "Turtle Inn", "space": "Wine Aquarium", "description": "The Wine Aquarium, Turtle Inn's glass encased wine cellar designed by Laurent Deroo, seen from its thatched tasting terrace in the wine garden. More than 1200 bottles lie in horizontal racks behind glass, glowing as a full wall of wine, while a tasting for two is poured at a small table on the gravel below a palm tree that grows through the terrace. The furnished deck mixes a curved wooden bench with patterned cushions, branch formed railings, oversized terracotta pots, and a counter fronted with a carved stone relief panel lit from above, where a small wooden figure stands as decor. Thatch, dark timber, and warm uplighting keep the cellar inside the resort's rustic Balinese world.", "src": "images/Turtle Inn/0937 - Turtle Inn - Wine Aquarium - glass bottle wall and tasting terrace.jpg", "source": "https://thecoppolahideaways.com/turtle-inn/dining/wine-cellar", "dimensions": "2400x1600", "size": 966670}, {"number": "0938", "file": "0938 - Turtle Inn - Sunset Spa - thatched treatment pavilion with massage table.jpg", "resort": "Turtle Inn", "space": "Sunset Spa", "description": "The Sunset Spa treatment pavilion, an open round hut with a steep palm thatch roof crowned by a carved finial, raised on a dark stained wooden deck in dense tropical planting. Inside, sheer white curtains screen a massage table dressed in white linen, ready for the spa's traditional Thai massage treatments, and a green glazed ceramic garden stool holds the treatment oils and a small flower offering. A large terracotta planter, wet deck boards, and the surrounding garden give the space its open air Balinese rice house character, as the resort describes the spa setting. The image is the hero photograph of the official Sunset Spa page.", "src": "images/Turtle Inn/0938 - Turtle Inn - Sunset Spa - thatched treatment pavilion with massage table.jpg", "source": "https://www.thecoppolahideaways.com/turtle-inn/services/sunset-spa", "dimensions": "1600x1200", "size": 2751297}, {"number": "0939", "file": "0939 - Islas Secas - Casita Bedroom - King canopy bed with louvred walls.jpg", "resort": "Islas Secas", "space": "Casita Bedroom", "description": "A spacious casita bedroom built around a reclaimed teak four poster bed dressed in white linen and sheer draped canopy curtains, in the Canal Zone house tradition described for Hart Howerton. Full height louvred timber shutters line both sides and filter jungle light across warm wood floors, a desk and reading chair, and low bedside furniture. The palette stays natural and quiet, with woven textures, a ceiling fan under the high pitched ventilated roof, and garden views kept present from the bed.", "src": "images/Islas Secas/0939 - Islas Secas - Casita Bedroom - King canopy bed with louvred walls.jpg", "source": "https://islassecas.com/panama/", "dimensions": "2560x1707", "size": 771994}, {"number": "0940", "file": "0940 - Islas Secas - Casita Bathroom - Shower and dark wood vanity.jpg", "resort": "Islas Secas", "space": "Casita Bathroom", "description": "A casita bathroom pairing a walk in tiled shower with a long dark wood vanity, framed mirror and louvred window above the robe hooks. White robes hang ready beside woven baskets and potted greenery, giving a residential, plantation house feel rather than a hotel bath. Stone look tile, timber joinery and soft natural light carry the same reclaimed tropical wood language used in the bedrooms.", "src": "images/Islas Secas/0940 - Islas Secas - Casita Bathroom - Shower and dark wood vanity.jpg", "source": "https://islassecas.com/casita/casita-grande/", "dimensions": "1440x605", "size": 186801}, {"number": "0941", "file": "0941 - Islas Secas - Tented Casita Bedroom - Canopy bed open to ocean view.jpg", "resort": "Islas Secas", "space": "Tented Casita Bedroom", "description": "The Tented Casita bedroom opens almost completely to the terrace and ocean, with a draped canopy bed in sage and white linen set on polished dark timber floors. Canvas ceiling, roll up walls and low woven seating keep the structure light, while a desk and day furniture face the view. It is indoor outdoor living in its purest form at Islas Secas, with furniture kept low and unobtrusive so the landscape leads.", "src": "images/Islas Secas/0941 - Islas Secas - Tented Casita Bedroom - Canopy bed open to ocean view.jpg", "source": "https://islassecas.com/casita/tented-casitas/", "dimensions": "1440x710", "size": 152843}, {"number": "0942", "file": "0942 - Islas Secas - Tented Casita Terrace - Armchair and outdoor soaking tub.jpg", "resort": "Islas Secas", "space": "Tented Casita Terrace", "description": "A Tented Casita sitting corner with a cushioned armchair on a round woven rug, a rustic timber side table and open timber doors framing dense jungle. Beyond the chair the private terrace holds a large outdoor soaking tub, one of the signature indulgences of the Tented Casitas. Natural fibres, pale upholstery and raw wood keep the terrace continuous with the bedroom inside.", "src": "images/Islas Secas/0942 - Islas Secas - Tented Casita Terrace - Armchair and outdoor soaking tub.jpg", "source": "https://islassecas.com/casita/tented-casitas/", "dimensions": "850x1044", "size": 138181}, {"number": "0943", "file": "0943 - Islas Secas - Casita Terrace and Plunge Pool - Thatched cabana terrace.jpg", "resort": "Islas Secas", "space": "Casita Terrace and Plunge Pool", "description": "The private casita terrace centres on a plunge pool at the edge of a broad timber deck, shaded by a deep thatched cabana roof on wooden posts. Teak outdoor armchairs, a dining table and cushioned loungers are arranged for outdoor living with ocean views beyond the planting. Simple furniture in natural timber and woven fibre under heavy thatch is the defining outdoor formula of the Islas Secas casitas.", "src": "images/Islas Secas/0943 - Islas Secas - Casita Terrace and Plunge Pool - Thatched cabana terrace.jpg", "source": "https://islassecas.com/casita/casita-grande/", "dimensions": "1440x605", "size": 315981}, {"number": "0944", "file": "0944 - Islas Secas - Casa Cavada Living Room - Symmetrical sofa arrangement.jpg", "resort": "Islas Secas", "space": "Casa Cavada Living Room", "description": "The Casa Cavada sitting room by Studio Tre is arranged symmetrically around a pale sofa with patterned and blush cushions, flanked by matching ceramic table lamps with green glazed bases. Timber armchairs with white cushions, a dark wood coffee table and potted palms complete a formal yet relaxed tropical drawing room. Exposed roof timbers and an arched opening to the garden confirm the indoor outdoor plan and the coral stone and reclaimed teak palette described for the house.", "src": "images/Islas Secas/0944 - Islas Secas - Casa Cavada Living Room - Symmetrical sofa arrangement.jpg", "source": "https://islassecas.com/casita/casa-cavada/", "dimensions": "2560x1236", "size": 652060}, {"number": "0945", "file": "0945 - Islas Secas - Casa Cavada Bedroom - Canopy bed with blue tufted sofa.jpg", "resort": "Islas Secas", "space": "Casa Cavada Bedroom", "description": "A Casa Cavada bedroom with a draped four poster bed, a deep blue tufted sofa at its foot and a woven rattan armchair with indigo upholstery. Louvred shutters, a timber dresser and layered textiles in blue and white give the room a collected, Anglo Indian and Spanish colonial mix consistent with the Studio Tre scheme. Plants, framed work and soft carpet underfoot keep the large room intimate despite its scale.", "src": "images/Islas Secas/0945 - Islas Secas - Casa Cavada Bedroom - Canopy bed with blue tufted sofa.jpg", "source": "https://islassecas.com/casita/casa-cavada/", "dimensions": "2560x1236", "size": 660666}, {"number": "0946", "file": "0946 - Islas Secas - Casa Cavada Bathroom - Carved wood vanity with patterned tile.jpg", "resort": "Islas Secas", "space": "Casa Cavada Bathroom", "description": "A Casa Cavada bathroom built around a hand carved dark wood vanity cabinet with panelled doors, a stone top and a framed mirror. Walls are lined in patterned tile in warm terracotta tones, described for the house as custom tile evocative of indigenous motifs, with wall sconces, folded white towels and trailing greenery as styling. The room shows the craft led, regionally sourced approach that runs through the whole residence.", "src": "images/Islas Secas/0946 - Islas Secas - Casa Cavada Bathroom - Carved wood vanity with patterned tile.jpg", "source": "https://islassecas.com/casita/casa-cavada/", "dimensions": "1192x1302", "size": 225994}, {"number": "0947", "file": "0947 - Islas Secas - Casa Cavada Terrace - Ocean view lounge seating.jpg", "resort": "Islas Secas", "space": "Casa Cavada Terrace", "description": "The main Casa Cavada terrace frames the Pacific between two massive eucalyptus pillars, with low teak framed sofas and armchairs in pale cushions arranged around a solid timber coffee table. The undulating roof that recalls a frigate bird wing or a ray fin shelters the seating while leaving the view completely open. Coral stone and timber underfoot and uninterrupted ocean make this the outdoor living room of the house.", "src": "images/Islas Secas/0947 - Islas Secas - Casa Cavada Terrace - Ocean view lounge seating.jpg", "source": "https://islassecas.com/casita/casa-cavada/", "dimensions": "2560x1236", "size": 494023}, {"number": "0948", "file": "0948 - Islas Secas - Casa Cavada Dining Terrace - Round table under eucalyptus pillars.jpg", "resort": "Islas Secas", "space": "Casa Cavada Dining Terrace", "description": "An outdoor dining setting at Casa Cavada with a round timber table and rattan dining chairs on a circular woven rug, set beneath soaring angled eucalyptus pillars. A woven pendant hangs above the table and the terrace opens to jungle and sea on two sides. Rattan, reclaimed teak tones and natural fibre are exactly the materials Studio Tre layered through the residence, here used for private chef led dining in the open air.", "src": "images/Islas Secas/0948 - Islas Secas - Casa Cavada Dining Terrace - Round table under eucalyptus pillars.jpg", "source": "https://islassecas.com/casita/casa-cavada/", "dimensions": "2560x1236", "size": 748988}, {"number": "0949", "file": "0949 - Islas Secas - Casa Cavada Grotto Lounge - Wicker chairs under frescoed arches.jpg", "resort": "Islas Secas", "space": "Casa Cavada Grotto Lounge", "description": "The lower level grotto lounge at Casa Cavada is formed from lava stone boulders and vaulted arches painted with marine frescoes inspired by indigenous Panamanian cave art, with sea turtles and fish across the ceilings. Wicker lounge chairs with patterned cushions gather around a low dark table on a pale rug, open to the pool and ocean beyond. It is the most distinctive interior in the house, part cave, part poolside bar and lounge.", "src": "images/Islas Secas/0949 - Islas Secas - Casa Cavada Grotto Lounge - Wicker chairs under frescoed arches.jpg", "source": "https://islassecas.com/casita/casa-cavada/", "dimensions": "2560x1236", "size": 549091}, {"number": "0950", "file": "0950 - Islas Secas - Terraza Restaurant - Bamboo cathedral interior with set tables.jpg", "resort": "Islas Secas", "space": "Terraza Restaurant", "description": "Inside Terraza, the bamboo and thatch dining structure built by Simon Velez, with a soaring cathedral like framework of guadua bamboo rising to a pitched thatch roof. Set dining tables with woven and rope chairs sit on a broad timber deck, with buffet stations, lanterns and sheer curtains softening the open sides. Verde marble tones, rope armchairs and handcrafted structure make this the social heart of Islas Secas and its clearest statement of natural material design.", "src": "images/Islas Secas/0950 - Islas Secas - Terraza Restaurant - Bamboo cathedral interior with set tables.jpg", "source": "https://islassecas.com/es/postcards/an-inspired-design-terraza/", "dimensions": "2560x1707", "size": 1112528}, {"number": "0951", "file": "0951 - Islas Secas - Terraza Restaurant - Lounge seating with bamboo columns.jpg", "resort": "Islas Secas", "space": "Terraza Restaurant", "description": "A close view of Terraza lounge seating, with deep sofas in pale upholstery, cushions in aqua, coral and patterned textiles, and woven armchairs grouped around low tables. Bamboo columns and draped curtains divide the dining deck from the beach edge, keeping the space shaded and breezy. The mix of rope, rattan and soft outdoor textiles shows how the restaurant doubles as an all day lounge.", "src": "images/Islas Secas/0951 - Islas Secas - Terraza Restaurant - Lounge seating with bamboo columns.jpg", "source": "https://islassecas.com/gallery/", "dimensions": "2560x1067", "size": 380265}, {"number": "0952", "file": "0952 - Islas Secas - Balboa Bar - Panelled bar with lounge seating.jpg", "resort": "Islas Secas", "space": "Balboa Bar", "description": "The Balboa Bar is a handsome panelled room with a dark wood bar counter and stools, bottle shelving, louvred windows and a relaxed lounge of armchairs and sofas beyond. Historic maps, local artwork and books are displayed through the room, giving it a club like, collected character distinct from the open Terraza. Warm timber, leather tones and shaded light make it the evening counterpart to the beachside restaurant.", "src": "images/Islas Secas/0952 - Islas Secas - Balboa Bar - Panelled bar with lounge seating.jpg", "source": "https://islassecas.com/food-and-drink/", "dimensions": "1440x710", "size": 187011}];
